// ===== Year Utility Helpers (auto-detect from data) =====
function _sortedNumKeys(obj){return Object.keys(obj||{}).map(Number).sort(function(a,b){return a-b;});}
function _yearsFromRows(rows,fallbackObj){var s={};(rows||[]).forEach(function(r){if(r.year)s[r.year]=1;});var y=Object.keys(s).map(Number).sort(function(a,b){return a-b;});return y.length?y:_sortedNumKeys(fallbackObj);}
function _latestYear(obj){var k=_sortedNumKeys(obj);return k.length?k[k.length-1]:2569;}

// Thai month normalizer — maps common variants to canonical 'ม.ค.' form
var _TH_MO_CANON=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
var _TH_MO_MAP=(function(){
  var m={};
  var full=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
  var abbr2=['ม.ค','ก.พ','มี.ค','เม.ย','พ.ค','มิ.ย','ก.ค','ส.ค','ก.ย','ต.ค','พ.ย','ธ.ค'];
  var en=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
  var enFull=['january','february','march','april','may','june','july','august','september','october','november','december'];
  _TH_MO_CANON.forEach(function(c,i){
    m[c]=c;
    m[full[i]]=c;
    m[abbr2[i]]=c;
    m[en[i]]=c;
    m[enFull[i]]=c;
    m[String(i+1)]=c;
    if(i<9) m['0'+String(i+1)]=c;
  });
  return m;
})();
function _normMonth(s){if(!s)return s;var k=String(s).trim().toLowerCase();return _TH_MO_MAP[k]||_TH_MO_MAP[k.replace(/\.$/,'')]||s;}
function _normMonthIdx(s){var c=_normMonth(s);return c?_TH_MO_CANON.indexOf(c):-1;}

function _lsSet(key,val){try{localStorage.setItem(key,typeof val==='string'?val:JSON.stringify(val));}catch(e){if(e.name==='QuotaExceededError'||e.code===22){console.warn('localStorage full, clearing old entries');try{var rm=[];for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);if(/^(ads|ship|cod|supply|influ)/.test(k))rm.push(k);}rm.forEach(function(k){localStorage.removeItem(k);});localStorage.setItem(key,typeof val==='string'?val:JSON.stringify(val));}catch(e2){console.error('localStorage save failed',e2);}}}}
function _lsGet(key){try{return localStorage.getItem(key);}catch(e){return null;}}
function _lsGetJSON(key,fallback){try{var v=localStorage.getItem(key);return v?JSON.parse(v):fallback;}catch(e){return fallback;}}

// ===== Global Performance Helpers =====
window.calcPerf = function(vals) {
  if (!vals || vals.length < 6) return { label: '-', color: '#94a3b8', icon: '', pct: 0, cls: 'neutral' };
  var half = Math.floor(vals.length / 2);
  var early = vals.slice(0, half).filter(function(v){ return v > 0; });
  var late = vals.slice(-half).filter(function(v){ return v > 0; });
  if (early.length === 0 || late.length === 0) return { label: '-', color: '#94a3b8', icon: '', pct: 0, cls: 'neutral' };
  var avgE = early.reduce(function(a,b){ return a+b; },0) / early.length;
  var avgL = late.reduce(function(a,b){ return a+b; },0) / late.length;
  var pct = avgE > 0 ? ((avgL - avgE) / avgE) : 0;
  if (pct > 0.05) return { label: 'ขาขึ้น', color: '#16a34a', icon: '▲', pct: pct, cls: 'up' };
  if (pct < -0.05) return { label: 'ขาลง', color: '#dc2626', icon: '▼', pct: pct, cls: 'down' };
  return { label: 'คงที่', color: '#d97706', icon: '►', pct: pct, cls: 'stable' };
};
window.perfBadgeHTML = function(perf) {
  var bg = perf.cls === 'up' ? '#dcfce7' : perf.cls === 'down' ? '#fee2e2' : perf.cls === 'stable' ? '#fef9c3' : '#f1f5f9';
  if (perf.label === '-') return '<span style="color:#94a3b8">-</span>';
  return '<span style="display:inline-flex;align-items:center;gap:3px;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:600;background:' + bg + ';color:' + perf.color + '">' +
    perf.icon + ' ' + perf.label +
    '<span style="font-weight:400;font-size:10px;opacity:0.8">(' + (perf.pct >= 0 ? '+' : '') + (perf.pct * 100).toFixed(1) + '%)</span></span>';
};
window.perfSearchIcon = function() {
  return '<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:#f1f5f9;color:#3b82f6;font-size:14px;cursor:pointer;transition:background .15s" onmouseover="this.style.background=\'#dbeafe\'" onmouseout="this.style.background=\'#f1f5f9\'">&#128269;</span>';
};

// Strip brand prefix for product display
function _stripBrand(n){
  if(!n) return '';
  return n.replace(/^วรรณวนัช\s*/,'');
}

// Booth upload helpers
    function bthHandleUpload(input, key) {
      var file = input.files[0];
      if (!file) return;
      bthShowUploadStatus(key, file.name);
    }
    function bthHandleDrop(event, key, label) {
      event.preventDefault();
      label.style.background = '';
      var file = event.dataTransfer.files[0];
      if (!file) return;
      bthShowUploadStatus(key, file.name);
    }
    function bthShowUploadStatus(key, filename) {
      var el = document.getElementById('bth-upload-status-' + key);
      if (el) el.innerHTML = '✅ <span style="color:#16a34a;font-weight:700">'+filename+'</span> พร้อมส่งให้ Claude แล้ว';
    }

window.onerror=function(msg,src,line,col,err){
  var box=document.getElementById('_errBox');
  if(!box){box=document.createElement('div');box.id='_errBox';box.style='position:fixed;top:100px;left:50%;transform:translateX(-50%);background:#fee2e2;border:2px solid #dc2626;padding:16px;border-radius:12px;z-index:99999;max-width:700px;font-size:13px;font-family:monospace';document.body.appendChild(box);}
  box.innerHTML+='<b>JS ERROR:</b> '+msg+'<br><small>line '+line+':'+col+'</small><hr>';
  return false;
};

