function renderMapTierKPI(){
  const el=document.getElementById('mapTierKPI');
  if(!el||el.innerHTML) return;
  const TOTAL_MAP_PINS=6164; // total pins in Google My Maps KML
  const counts={A:0,B:0,C:0,D:0}, totals={A:0,B:0,C:0,D:0};
  Object.entries(SALES_MAY).forEach(([k,v])=>{
    if(v>=10000){counts.A++;totals.A+=v;}
    else if(v>=5000){counts.B++;totals.B+=v;}
    else if(v>=1000){counts.C++;totals.C+=v;}
    else{counts.D++;totals.D+=v;}
  });
  const withSales=counts.A+counts.B+counts.C+counts.D;
  counts.R=TOTAL_MAP_PINS-withSales;
  const tiers=[
    {k:'A',label:'🟢 A — ≥ 10,000 บาท',color:'#22c55e',bg:'#f0fdf4',border:'#86efac'},
    {k:'B',label:'🟡 B — 5,000–9,999',color:'#ca8a04',bg:'#fefce8',border:'#fde047'},
    {k:'C',label:'🔵 C — 1,000–4,999',color:'#2563eb',bg:'#eff6ff',border:'#93c5fd'},
    {k:'D',label:'🟠 D — 1–999',color:'#ea580c',bg:'#fff7ed',border:'#fdba74'},
    {k:'R',label:'🔴 ยังไม่มียอด',color:'#dc2626',bg:'#fff1f2',border:'#fca5a5'},
  ];
  el.innerHTML=tiers.map(t=>`
    <div class="kpi-card" style="border-left:4px solid ${t.color};background:${t.bg};border:1px solid ${t.border}">
      <div class="kpi-label" style="color:${t.color};font-weight:600">${t.label}</div>
      <div class="kpi-value" style="color:${t.color}">${(counts[t.k]||0).toLocaleString()} สาขา</div>
      ${totals[t.k]?`<div class="kpi-sub" style="color:${t.color}">฿${totals[t.k].toLocaleString('th-TH')}</div>`:''}
    </div>`).join('');
}

function _mapTierColor(code){
  const a = SALES_MAY[code]||0;
  if(a>=10000) return '#4CAF50';
  if(a>=5000)  return '#FFC107';
  if(a>=1000)  return '#2196F3';
  if(a>0)      return '#FF9800';
  return '#F44336';
}
function _mapTierLabel(code){
  const a = SALES_MAY[code]||0;
  if(a>=10000) return 'A';
  if(a>=5000)  return 'B';
  if(a>=1000)  return 'C';
  if(a>0)      return 'D';
  return '-';
}

let _mapReady=false, _leafletLoaded=false;
async function initWanwanachMap(){
  const btn=document.getElementById('mapLoadBtn');
  const statusEl=document.getElementById('mapStatusText');
  if(btn) btn.style.display='none';
  statusEl.textContent='⏳ กำลังโหลด Leaflet...';

  if(!_leafletLoaded){
    // Load Leaflet CSS
    if(!document.querySelector('#leafletCSS')){
      const lnk=document.createElement('link');
      lnk.id='leafletCSS';lnk.rel='stylesheet';
      lnk.href='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css';
      document.head.appendChild(lnk);
    }
    // Load Leaflet JS
    await new Promise((res,rej)=>{
      const s=document.createElement('script');
      s.src='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js';
      s.onload=res; s.onerror=rej;
      document.head.appendChild(s);
    });
    _leafletLoaded=true;
  }

  if(_mapReady) return;

  statusEl.textContent='⏳ กำลังโหลดข้อมูลแผนที่จาก Google Maps...';
  const mapEl=document.getElementById('wanwanachMap');

  // Init Leaflet map centered on Thailand
  const map=L.map(mapEl,{zoomControl:true}).setView([15.0,101.5],6);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
    attribution:'© <a href="https://www.openstreetmap.org">OpenStreetMap</a>',
    maxZoom:18
  }).addTo(map);

  try{
    const res=await fetch(
      'https://www.google.com/maps/d/kml?mid=1UhE91q_ZFUG_oZzIJzndYUQlfTXEoVs&forcekml=1',
      {credentials:'include',mode:'cors'}
    );
    if(!res.ok) throw new Error('HTTP '+res.status);
    const kmlText=await res.text();
    const parser=new DOMParser();
    const kmlDoc=parser.parseFromString(kmlText,'text/xml');
    const placemarks=Array.from(kmlDoc.querySelectorAll('Placemark'));

    let added=0, byTier={A:0,B:0,C:0,D:0,'-':0};
    placemarks.forEach(pm=>{
      const name=(pm.querySelector('name')||{}).textContent?.trim()||'';
      const coords=(pm.querySelector('coordinates')||{}).textContent?.trim()||'';
      if(!coords) return;
      const parts=coords.split(',');
      const lng=parseFloat(parts[0]), lat=parseFloat(parts[1]);
      if(!lat||!lng||isNaN(lat)||isNaN(lng)) return;

      const color=_mapTierColor(name);
      const tier=_mapTierLabel(name);
      const amt=(SALES_MAY[name]||0).toLocaleString('th-TH');
      byTier[tier]=(byTier[tier]||0)+1;

      L.circleMarker([lat,lng],{
        radius:6, fillColor:color,
        color:'#ffffff', weight:1.5,
        opacity:1, fillOpacity:0.88
      }).addTo(map)
       .bindPopup(`<div style="font-size:13px;min-width:160px">
          <b style="font-size:14px">${name}</b><br>
          <span style="color:#64748b">ยอด พ.ค. 2569:</span>
          <b style="color:#ea580c">฿${amt}</b><br>
          เกรด: <b>${tier==='−'?'ยังไม่มียอด':tier}</b>
        </div>`);
      added++;
    });

    var mapPinEl=document.getElementById('mapPinCount');
    if(mapPinEl) mapPinEl.textContent=
      `สาขาทั้งหมด ${added.toLocaleString()} จุด`;
    statusEl.textContent=
      `✅ โหลดแล้ว ${added.toLocaleString()} สาขา | 🟢A:${byTier.A} 🟡B:${byTier.B} 🔵C:${byTier.C} 🟠D:${byTier.D} 🔴ไม่มียอด:${byTier['-']||0}`;
    _mapReady=true;

  }catch(e){
    statusEl.innerHTML=
      `⚠️ โหลดแผนที่ไม่ได้: ${e.message} — ต้อง<b>เปิดไฟล์ใน Chrome</b> และ<b>ล็อกอิน Google</b> ก่อน &nbsp;|&nbsp; <a href="https://www.google.com/maps/d/viewer?hl=en&mid=1UhE91q_ZFUG_oZzIJzndYUQlfTXEoVs" target="_blank" style="color:#ea580c">เปิดใน Google Maps</a>`;
    if(btn){btn.style.display='';btn.textContent='🔄 ลองใหม่';}
  }
}

