let currentMonth='YTD', selectedPerson=null;
const COLORS12=['#4f46e5','#0891b2','#16a34a','#d97706','#dc2626','#7c3aed','#0d9488','#ea580c','#2563eb','#db2777','#65a30d','#b45309'];
const fmt=n=>n==null?'—':Math.round(n).toLocaleString('th-TH');
const fmtM=n=>(n/1e6).toFixed(2)+' M';
const achCls=p=>p>=80?'green':p>=60?'yellow':'red';
function progFill(pct){const w=Math.min(Math.max(pct,0),100),cls=pct>=80?'high':pct>=60?'mid':'low';return`<div class="prog-wrap"><div class="prog" style="width:80px"><div class="prog-fill ${cls}" style="width:${w}%"></div></div><span class="prog-label">${pct.toFixed(1)}%</span></div>`;}
function rankBadge(i){const c=['r1','r2','r3'][i]||'rn';return`<span class="rank ${c}">${i+1}</span>`;}
// Resolve currentMonth into list of month codes for range mode
function _resolveMonths(){
  if(currentMonth && currentMonth.range){
    const si = MONTHS_12.indexOf(currentMonth.start);
    const ei = MONTHS_12.indexOf(currentMonth.end);
    if(si<0||ei<0) return MONTHS;
    return MONTHS_12.slice(si, ei+1);
  }
  if(currentMonth==='YTD') return MONTHS;
  return [currentMonth];
}

// Sum a src object across a list of month codes
function _sumMonths(src, months){
  const out = {};
  for(const m of months){
    const row = src[m];
    if(!row) continue;
    for(const [k,v] of Object.entries(row)){
      if(!out[k]) out[k]={t:0,a:0};
      out[k].t += (v.t||0);
      out[k].a += (v.a||0);
    }
  }
  return out;
}

function getMonthData(src,m){if(!src)return {};
  if(m==='YTD'){
    const res={};MONTHS.forEach(mo=>Object.entries(src[mo]||{}).forEach(([k,v])=>{if(!res[k])res[k]={t:0,a:0};res[k].t+=v.t;res[k].a+=v.a;}));return res;
  }
  if(m && m.range){
    const si=MONTHS_12.indexOf(m.start),ei=MONTHS_12.indexOf(m.end);
    if(si<0||ei<0) return {};
    const res={};
    MONTHS_12.slice(si,ei+1).forEach(mo=>Object.entries(src[mo]||{}).forEach(([k,v])=>{
      if(!res[k])res[k]={t:0,a:0};res[k].t+=v.t;res[k].a+=v.a;
    }));
    return res;
  }
  return src[m]||{};
}
function getChannelData(m){return getMonthData(CHANNEL_MONTHLY,m);}
function getSalesData(m){
  var mos=_resolveMonths();
  return Object.keys(SALES_MONTHLY).map(n=>{
    var act=0,tgt=0;
    mos.forEach(function(mo){act+=(SALES_MONTHLY[n][mo]||0);tgt+=((SALES_MTH_TARGET[n]&&SALES_MTH_TARGET[n][mo])||0);});
    return {name:n,zone:SALES_MONTHLY[n].zone,target:tgt,actual:act};
  }).sort((a,b)=>b.actual-a.actual);
}
let charts={};
function mkChart(id,cfg){if(typeof Chart==='undefined')return;if(charts[id])charts[id].destroy();const c=document.getElementById(id);if(c)charts[id]=new Chart(c,cfg);}
try{Chart.defaults.color='#64748b';Chart.defaults.borderColor='#e2e8f0';Chart.defaults.font.family="'Segoe UI',Tahoma,sans-serif";
Chart.register({id:'doughnutPercent',afterDraw:function(chart){
  if(chart.config.type!=='doughnut'&&chart.config.type!=='pie')return;
  var meta=chart.getDatasetMeta(0);if(!meta||!meta.data||!meta.data.length)return;
  var ds=chart.data.datasets[0];if(!ds||!ds.data)return;
  var total=ds.data.reduce(function(a,b){return a+(b||0);},0);if(total===0)return;
  var area=chart.chartArea,sz=Math.min(area.width,area.height);
  var fs=Math.max(11,Math.round(sz/22));
  var ctx=chart.ctx;ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.font='bold '+fs+'px "Segoe UI",Tahoma,sans-serif';
  meta.data.forEach(function(arc,i){
    var v=ds.data[i];if(!v)return;var pct=v/total*100;if(pct<4)return;
    var props=arc.getProps(['startAngle','endAngle','innerRadius','outerRadius']);
    var midA=(props.startAngle+props.endAngle)/2;
    var midR=(props.innerRadius+props.outerRadius)/2;
    var x=arc.x+Math.cos(midA)*midR,y=arc.y+Math.sin(midA)*midR;
    var label=pct>=10?Math.round(pct)+'%':pct.toFixed(1)+'%';
    ctx.strokeStyle='rgba(0,0,0,0.45)';ctx.lineWidth=3;ctx.strokeText(label,x,y);
    ctx.fillStyle='#fff';ctx.fillText(label,x,y);
  });ctx.restore();
}});}catch(e){console.warn('Chart.js not ready:',e.message);}
