function renderWfFlow(){
  window._wfFlowRendered=true;
  var box=document.getElementById('wfSteps');
  var html='';
  WF_STEPS.forEach(function(s,i){
    var isLast=i===WF_STEPS.length-1;
    html+='<div class="wf-step">';
    html+='<div class="wf-step-line">';
    html+='<div class="wf-step-dot" style="background:'+s.color+'">'+s.n+'</div>';
    if(!isLast) html+='<div class="wf-step-bar" style="background:'+s.color+'22"></div>';
    html+='</div>';
    html+='<div class="wf-step-card">';
    html+='<div class="wf-step-title">'+s.title+'</div>';
    html+='<div class="wf-step-detail">'+s.detail+'</div>';
    html+='<div class="wf-step-meta">';
    html+='<span class="wf-step-tag" style="background:#f1f5f9;color:#475569">👥 '+s.who+'</span>';
    if(s.days>0) html+='<span class="wf-step-tag" style="background:#dbeafe;color:#1d4ed8">⏱️ '+s.days+' วัน</span>';
    if(s.gate) html+='<span class="wf-step-tag" style="background:#fef2f2;color:#dc2626">🚦 Decision Gate</span>';
    html+='</div></div></div>';
  });
  box.innerHTML=html;

  var labels=WF_STEPS.filter(function(s){return s.days>0}).map(function(s){return s.n+'. '+s.title});
  var vals=WF_STEPS.filter(function(s){return s.days>0}).map(function(s){return s.days});
  var colors=WF_STEPS.filter(function(s){return s.days>0}).map(function(s){return s.color});
  if(window._wfTimeChart) window._wfTimeChart.destroy();
  window._wfTimeChart=mkChart('wfTimelineChart',{type:'bar',data:{labels:labels,datasets:[{label:'Lead Time (วัน)',data:vals,backgroundColor:colors.map(function(c){return c+'cc'}),borderColor:colors,borderWidth:1,borderRadius:6}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{color:'#f1f5f9'},title:{display:true,text:'จำนวนวัน'}},y:{grid:{display:false}}}}});
}

