function renderWfRaci(){
  window._wfRaciRendered=true;
  var cls={R:'raci-r',A:'raci-a',C:'raci-c',I:'raci-i'};
  var tb=document.getElementById('wfRaciBody');
  tb.innerHTML=WF_RACI.map(function(r){
    return '<tr><td style="font-weight:600">'+r.act+'</td>'+r.data.map(function(v){
      return '<td style="text-align:center"><span class="'+cls[v]+'">'+v+'</span></td>';
    }).join('')+'</tr>';
  }).join('');

  var rb=document.getElementById('wfRolesBody');
  rb.innerHTML=WF_ROLES.map(function(r){
    return '<tr><td style="font-weight:600;white-space:nowrap">'+r.dept+'</td><td>'+r.tasks+'</td></tr>';
  }).join('');
}

