function renderWfGate(){
  window._wfGateRendered=true;
  var g=document.getElementById('wfGates');
  g.innerHTML=WF_GATES.map(function(gt){
    return '<div class="wf-gate-card" style="border-left:4px solid '+gt.color+'"><div class="wf-gate-icon">'+gt.icon+'</div><div class="wf-gate-title">'+gt.title+'</div><div class="wf-gate-who">👤 ผู้อนุมัติ: '+gt.who+'</div><div class="wf-gate-criteria">✅ '+gt.criteria+'</div></div>';
  }).join('');

  document.getElementById('wfRedFlagBody').innerHTML=WF_RED_FLAGS.map(function(r){
    return '<tr><td>'+r.problem+'</td><td><span style="background:#fef2f2;color:#dc2626;padding:3px 10px;border-radius:6px;font-weight:700;font-size:12px">'+r.action+'</span></td></tr>';
  }).join('');

  document.getElementById('wfSlaBody').innerHTML=WF_SLA.map(function(s){
    return '<tr><td>'+s.step+'</td><td style="font-weight:700;color:#1d4ed8">'+s.sla+'</td></tr>';
  }).join('');
}

