let _snkCharts={};
function renderSnackIssue(){
  var yr=document.getElementById('snackYearSel').value;
  var ch=document.getElementById('snackChannelSel').value;
  var yearData=SNACK_ISSUE_DATA[yr];
  if(!yearData) return;

  var channels=ch==='all'?['Amazon','Booth','Modern Trade','Online']:[ch];
  var merged=Array.from({length:12},function(_,i){return{month:['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][i],expired:0,mold:0,nodate:0,packaging:0,foreign:0,total:0,amt:0};});

  channels.forEach(function(c){
    var d=yearData[c];
    if(!d)return;
    d.forEach(function(r,i){
      merged[i].expired+=r.expired;
      merged[i].mold+=r.mold;
      merged[i].nodate+=r.nodate;
      merged[i].packaging+=r.packaging;
      merged[i].foreign+=r.foreign;
      merged[i].total+=r.total;
      merged[i].amt+=r.amt;
    });
  });

  var totQty=merged.reduce(function(s,r){return s+r.total;},0);
  var totAmt=merged.reduce(function(s,r){return s+r.amt;},0);
  var totExpired=merged.reduce(function(s,r){return s+r.expired;},0);
  var totMold=merged.reduce(function(s,r){return s+r.mold;},0);
  var totNodate=merged.reduce(function(s,r){return s+r.nodate;},0);
  var totPkg=merged.reduce(function(s,r){return s+r.packaging;},0);
  var totForeign=merged.reduce(function(s,r){return s+r.foreign;},0);
  var worstMonth=merged.reduce(function(a,b){return b.total>a.total?b:a;},{total:0,month:'-'});

  // KPI — use dashboard kpi-card classes
  function _snkKpi(cls,label,value,sub){return '<div class="kpi-card '+cls+'"><div class="kpi-label">'+label+'</div><div class="kpi-value">'+value+'</div><div class="kpi-sub">'+sub+'</div></div>';}
  document.getElementById('snackKPI').innerHTML=
    _snkKpi('red','รวมปัญหาทั้งหมด',totQty.toLocaleString()+' <small style="font-size:13px;font-weight:600">ชิ้น</small>','มูลค่าเสียหายรวม '+totAmt.toLocaleString()+' บาท')+
    _snkKpi('yellow','มูลค่าเสียหาย','฿'+totAmt.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0}),'เฉลี่ย '+(totQty?Math.round(totAmt/totQty):0)+' บาท/ชิ้น')+
    _snkKpi('blue','เดือนปัญหาสูงสุด',worstMonth.month,worstMonth.total.toLocaleString()+' ชิ้น');

  // Type breakdown mini-cards
  var pct=function(v){return totQty?(v/totQty*100).toFixed(1)+'%':'0%';};
  function _miniCard(color,emoji,label,val){
    return '<div class="card" style="padding:14px 16px;text-align:center;border-top:3px solid '+color+'"><div style="font-size:20px;margin-bottom:4px">'+emoji+'</div><div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px">'+label+'</div><div style="font-size:20px;font-weight:800;color:'+color+'">'+val.toLocaleString()+'</div><div style="font-size:10px;color:var(--text2);margin-top:2px">'+pct(val)+'</div></div>';
  }
  document.getElementById('snackTypeKPI').innerHTML=
    _miniCard('#ef4444','🔥','เสียก่อนหมดอายุ',totExpired)+
    _miniCard('#22c55e','🦠','ขึ้นรา',totMold)+
    _miniCard('#3b82f6','📅','ไม่ยิงวันหมดอายุ',totNodate)+
    _miniCard('#f59e0b','📦','บรรจุภัณฑ์บวม',totPkg)+
    _miniCard('#8b5cf6','🔍','สิ่งแปลกปลอม',totForeign);

  var labels=merged.map(function(r){return r.month;});

  // Monthly stacked bar chart
  if(_snkCharts.monthly) _snkCharts.monthly.destroy();
  _snkCharts.monthly=new Chart(document.getElementById('snackMonthlyChart'),{type:'bar',data:{labels:labels,datasets:[
    {label:'เสียก่อนหมดอายุ',data:merged.map(function(r){return r.expired;}),backgroundColor:'#ef4444'},
    {label:'ขึ้นรา',data:merged.map(function(r){return r.mold;}),backgroundColor:'#22c55e'},
    {label:'ไม่ยิงวันหมดอายุ',data:merged.map(function(r){return r.nodate;}),backgroundColor:'#3b82f6'},
    {label:'บรรจุภัณฑ์บวม/ซีลไม่ดี',data:merged.map(function(r){return r.packaging;}),backgroundColor:'#f59e0b'},
    {label:'สิ่งแปลกปลอม',data:merged.map(function(r){return r.foreign;}),backgroundColor:'#8b5cf6'}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}},scales:{x:{stacked:true},y:{stacked:true,beginAtZero:true}}}});

  // Doughnut chart
  var typeData=[totExpired,totMold,totNodate,totPkg,totForeign];
  var typeLabels=['เสียก่อนหมดอายุ','ขึ้นรา','ไม่ยิงวันหมดอายุ','บรรจุภัณฑ์บวม','สิ่งแปลกปลอม'];
  var typeColors=['#ef4444','#22c55e','#3b82f6','#f59e0b','#8b5cf6'];
  if(_snkCharts.type) _snkCharts.type.destroy();
  _snkCharts.type=new Chart(document.getElementById('snackTypeChart'),{type:'doughnut',data:{labels:typeLabels,datasets:[{data:typeData,backgroundColor:typeColors}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}}}});

  // Channel comparison bar chart
  if(_snkCharts.channel) _snkCharts.channel.destroy();
  var allCh=['Amazon','Booth','Modern Trade','Online'];
  var chColors=['#ea580c','#16a34a','#2563eb','#9333ea'];
  _snkCharts.channel=new Chart(document.getElementById('snackChannelChart'),{type:'bar',data:{labels:labels,datasets:allCh.map(function(c,ci){
    var cd=yearData[c]||[];
    return{label:c,data:cd.map(function(r){return r.total;}),backgroundColor:chColors[ci]};
  })},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}},scales:{y:{beginAtZero:true}}}});

  // Table — use dashboard th/td styles
  var thead='<tr><th style="text-align:left">เดือน</th><th style="text-align:right">เสียก่อนหมดอายุ</th><th style="text-align:right">ขึ้นรา</th><th style="text-align:right">ไม่ยิงวัน</th><th style="text-align:right">บรรจุภัณฑ์</th><th style="text-align:right">แปลกปลอม</th><th style="text-align:right">รวม (ชิ้น)</th><th style="text-align:right">มูลค่า (฿)</th></tr>';
  document.getElementById('snackTHead').innerHTML=thead;

  var tbody='';
  merged.forEach(function(r){
    var op=r.total>0?'':'style="opacity:0.35"';
    tbody+='<tr '+op+'><td style="font-weight:600">'+r.month+'</td><td style="text-align:right;color:#ef4444">'+(r.expired||'–')+'</td><td style="text-align:right;color:#22c55e">'+(r.mold||'–')+'</td><td style="text-align:right;color:#3b82f6">'+(r.nodate||'–')+'</td><td style="text-align:right;color:#f59e0b">'+(r.packaging||'–')+'</td><td style="text-align:right;color:#8b5cf6">'+(r.foreign||'–')+'</td><td style="text-align:right;font-weight:800">'+r.total.toLocaleString()+'</td><td style="text-align:right;color:#b45309">'+r.amt.toLocaleString()+'</td></tr>';
  });
  tbody+='<tr class="tr-total"><td>รวมทั้งปี</td><td style="text-align:right;color:#ef4444">'+totExpired.toLocaleString()+'</td><td style="text-align:right;color:#22c55e">'+totMold.toLocaleString()+'</td><td style="text-align:right;color:#3b82f6">'+totNodate.toLocaleString()+'</td><td style="text-align:right;color:#f59e0b">'+totPkg.toLocaleString()+'</td><td style="text-align:right;color:#8b5cf6">'+totForeign.toLocaleString()+'</td><td style="text-align:right;color:#dc2626;font-size:15px">'+totQty.toLocaleString()+'</td><td style="text-align:right;color:#b45309;font-size:15px">'+totAmt.toLocaleString()+'</td></tr>';
  document.getElementById('snackTBody').innerHTML=tbody;
}

// ============================================================
// TAB SWITCHING
// ============================================================
let builtTabs={overview:true,trend:false,channel:false,customer:false,sales:false,store:false,products:false,cjperf:false,mtperf:false,booth:false,online:false,amazon:false,mt:false,quality:false};
window.dismissWelcome = function() {
  var wl = document.getElementById('welcomeLanding');
  if (wl) wl.style.display = 'none';
  var link = document.querySelector('#sidebarNav .nav-link.active')
    || document.querySelector('#sidebarNav .nav-link');
  if (link && typeof showTab === 'function') showTab(link, 'overview');
};

function showTab(el,name){
  var wl = document.getElementById('welcomeLanding');
  if (wl) wl.style.display = 'none';
  // Hide all sections via inline style (bypasses CSS animation issues)
  document.querySelectorAll('.section').forEach(function(s){
    s.classList.remove('active');
    s.style.display='none';
    s.style.opacity='';
  });
  document.querySelectorAll('.tab').forEach(function(t){t.classList.remove('active');});
  // Show target section directly
  var _sec=document.getElementById('tab-'+name);
  if(_sec){
    _sec.classList.add('active');
    _sec.style.display='block';
    _sec.style.opacity='1';
    void _sec.offsetHeight; // force reflow
  }
  el.classList.add('active');
  var gfb=document.getElementById('globalFilterBar');
  if(gfb){
    var filterRow=gfb.closest('.tb-row-filter')||gfb;
    var _filterTabs={overview:1,booth:1,amazon:1,products:1,cjperf:1};
    filterRow.style.display=(_filterTabs[name])?'':'none';
  }
  if(!builtTabs[name]){builtTabs[name]=true;var init={trend:initTrend,store:initStore,products:initProducts,cjperf:initCJPerf,mtperf:initMTPerf};if(init[name])init[name]();}
  var rerender={overview:renderOverview,channel:renderChannel,customer:renderCustomer,sales:renderSales,
    products:function(){if(_prodTab==='overview')renderProdOverview();else if(_prodTab==='npd')renderProdNPD();},
    cjperf:renderCJPage,mtperf:renderMTPage,mt:renderMTPage,
    booth:function(){renderBooth();renderBoothInfo();},
    online:renderOnline,amazon:renderAmazon,
    ordering:function(){if(typeof renderOrdStaff==='function')renderOrdStaff();},
    quality:renderQualityOverview,
    'sm-expense':function(){if(typeof smInitTab==='function')smInitTab();},
    admin:function(){if(typeof renderAdminStaff==='function')renderAdminStaff();},
    marketing:function(){if(typeof initMarketingTab==='function')initMarketingTab();}};
  if(rerender[name]){try{rerender[name]();}catch(e){console.error('Tab render error ['+name+']:',e);}}
  if(typeof _SUPA_LIVE!=='undefined'&&_SUPA_LIVE.loading&&_SUPA_LIVE._promise&&rerender[name]){
    _SUPA_LIVE._promise.then(function(ok){if(ok&&rerender[name])try{rerender[name]();}catch(e){}});
  }
}

// ============================================================
// OVERVIEW
// ============================================================
function renderOverview(){
  const m=currentMonth;showBanner('Overview',m);
  // Resolve months using _resolveMonths() to support range objects
  const months = _resolveMonths(); // always returns array of month codes
  const isYTD = (m==='YTD');
  const isRange = m && m.range;
  const isSingle = !isYTD && !isRange;

  let tArr,aArr;
  if(isYTD){tArr=MONTHS.map((_,i)=>MONTHLY_TARGET[i]);aArr=MONTHS.map((_,i)=>MONTHLY_ACTUAL[i]);}
  else{tArr=months.map(mo=>{const i=MONTHS_12.indexOf(mo);return MONTHLY_TARGET[i]||0;});
       aArr=months.map(mo=>{const i=MONTHS_12.indexOf(mo);return MONTHLY_ACTUAL[i]||0;});}
  const totT=tArr.reduce((s,v)=>s+(v||0),0),totA=aArr.reduce((s,v)=>s+(v||0),0),diff=totA-totT,ach=totT?totA/totT*100:0;
  const hasData=aArr.some(v=>v>0);
  var _tFn=typeof _t==='function'?_t:function(k){return k;};
  var _isEN=typeof _lang!=='undefined'&&_lang==='en';
  const label=isYTD?'YTD':isRange?months.map(mo=>(_isEN?MONTHS_12[MONTHS_12.indexOf(mo)]:MONTHS_FULL_TH[MONTHS_12.indexOf(mo)])).join('–'):(_isEN?'Month ':'เดือน ')+(_isEN?MONTHS_12[MONTHS_12.indexOf(months[0])]:MONTHS_FULL_TH[MONTHS_12.indexOf(months[0])]);
  var _kpiTarget=_isEN?'Target':'เป้าหมาย';
  var _kpiActual=_isEN?'Actual':'ยอดจริง';
  var _kpiDiff=_isEN?'Difference':'ส่วนต่าง';
  var _kpiAnnual=_isEN?'Annual Target':'เป้าหมายทั้งปี';
  var _kpiAchieved=_isEN?'Achieved':'สำเร็จ';
  var _kpiMillion=_isEN?'M THB':'ล้านบาท';
  var _kpiYearFull=_isEN?'Year '+_CY+' Full':'ปี '+_CY+' ทั้งปี';
  document.getElementById('overviewKPI').innerHTML=`
    <div class="kpi-card blue"><div class="kpi-label">${_kpiTarget} (${label})</div><div class="kpi-value">${fmtM(totT)}</div></div>
    <div class="kpi-card cyan"><div class="kpi-label">${_kpiActual} (${label})</div><div class="kpi-value">${fmtM(totA)}</div><div class="kpi-badge ${ach>=80?'pos':ach>=60?'warn':'neg'}">${ach.toFixed(1)}% ${_kpiAchieved}</div></div>
    <div class="kpi-card red"><div class="kpi-label">${_kpiDiff}</div><div class="kpi-value">${(diff/1e6).toFixed(2)} M</div><div class="kpi-sub">${_kpiMillion}</div></div>
    <div class="kpi-card green"><div class="kpi-label">${_kpiAnnual}</div><div class="kpi-value">${fmtM(MONTHLY_TARGET.reduce((s,v)=>s+(v||0),0))}</div><div class="kpi-sub">${_kpiYearFull}</div></div>`;
  // overviewBar + overviewAch removed (duplicates of trendMain + KPI achievement)
  // Table rows
  const tableMonths = isYTD ? MONTHS.map((mo,i)=>({mo,i})) : months.map(mo=>({mo,i:MONTHS_12.indexOf(mo)}));
  const rows = tableMonths.map(({mo,i})=>{
    if(i<0) return '';
    const t=MONTHLY_TARGET[i]||0,a=MONTHLY_ACTUAL[i]||0,d=a-t,ach=t?a/t*100:0;
    return`<tr><td><strong>${MONTHS_FULL_TH[i]}</strong></td><td style="text-align:right">${fmt(t)}</td><td style="text-align:right">${fmt(a)}</td><td style="text-align:right;color:${d>=0?'#16a34a':'#dc2626'}">${d>=0?'+':''}${fmt(d)}</td><td style="text-align:right"><span class="pill ${d>=0?'green':'red'}">${t?Math.abs(d/t*100).toFixed(0):0}%</span></td><td>${progFill(ach)}</td></tr>`;
  });
  rows.push(`<tr class="tr-total"><td>${isYTD?(_isEN?'Total YTD':'รวม YTD'):(_isEN?'Total':'รวม')}</td><td style="text-align:right">${fmt(totT)}</td><td style="text-align:right">${fmt(totA)}</td><td style="text-align:right;color:#dc2626">${fmt(diff)}</td><td style="text-align:right"><span class="pill red">${totT?Math.abs(diff/totT*100).toFixed(0):0}%</span></td><td>${progFill(ach)}</td></tr>`);
  document.getElementById('overviewTable').innerHTML=rows.join('');
  document.getElementById('overviewTableTitle').textContent=isYTD?(_isEN?'Monthly Table':'ตารางรายเดือน'):(_isEN?'Table — '+label:'ตาราง — '+label);
  const chData=getChannelData(m);
  document.getElementById('overviewChannelTable').innerHTML=CH_NAMES.map(c=>{
    const t=chData[c]?.t||0,a=chData[c]?.a||0,diff=a-t,ach=t?a/t*100:0;
    return`<tr><td><strong>${c}</strong></td><td style="text-align:right">${fmt(t)}</td><td style="text-align:right">${fmt(a)}</td><td style="text-align:right;color:${diff>=0?'#16a34a':'#dc2626'}">${diff>=0?'+':''}${fmt(diff)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td><td>${progFill(ach)}</td></tr>`;
  }).join('');
  // ===== TREND line chart =====
  const lineMonths = _resolveMonths().filter(mo=>MONTHS_12.indexOf(mo)<MONTHS.length);
  const lineLabels = lineMonths.map(mo=>MONTHS_FULL_TH[MONTHS_12.indexOf(mo)]);
  const lineTgt = lineMonths.map(mo=>{const i=MONTHS_12.indexOf(mo);return i>=0?(MONTHLY_TARGET[i]||0)/1e6:0;});
  const lineAct = lineMonths.map(mo=>{const i=MONTHS_12.indexOf(mo);return i>=0&&(MONTHLY_ACTUAL[i]||0)>0?(MONTHLY_ACTUAL[i]||0)/1e6:null;});
  mkChart('overviewLine',{type:'bar',data:{labels:lineLabels,datasets:[{label:'Target',data:lineTgt,backgroundColor:'rgba(79,70,229,.18)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},{label:'Actual',data:lineAct,backgroundColor:'rgba(8,145,178,.7)',borderColor:'#0891b2',borderWidth:2,borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}},x:{grid:{display:false}}}}});

  // ===== PIE/donut chart — สัดส่วนยอดขายแยกตามช่องทาง =====
  const pieChData=getChannelData(currentMonth);
  const pieChNames=CH_NAMES.filter(c=>(pieChData[c]?.a||0)>0);
  const pieChVals=pieChNames.map(c=>pieChData[c]?.a||0);
  const pieChColors=pieChNames.map(c=>CH_COLORS[CH_NAMES.indexOf(c)]);
  const pieChTotal=pieChVals.reduce((s,v)=>s+v,0);
  mkChart('overviewPie',{type:'doughnut',data:{labels:pieChNames,datasets:[{data:pieChVals,backgroundColor:pieChColors,borderWidth:2,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'right',labels:{font:{size:12},padding:12}},tooltip:{callbacks:{label:c=>' '+c.label+': '+(c.raw/pieChTotal*100).toFixed(1)+'% ('+fmtM(c.raw)+')'}}},cutout:'60%'}});

  // ===== CHANNEL STATUS ALERT =====
  const btEl=document.getElementById('ovBelowTarget');
  if(btEl){
    var ytdData=getChannelData('YTD');
    var lastMo=MONTHS[MONTHS.length-1]||'Jan';
    var mthData=CHANNEL_MONTHLY[lastMo]||{};
    var _moTH=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
    var mthLabel=_isEN?lastMo:(_moTH[MONTHS_12.indexOf(lastMo)]||lastMo);
    var fullYearTarget={},ytdTarget={};
    MONTHS_12.forEach(function(mo){
      var mData=CHANNEL_MONTHLY[mo]||{};
      Object.keys(mData).forEach(function(k){
        if(!fullYearTarget[k])fullYearTarget[k]=0;
        fullYearTarget[k]+=(mData[k].t||0);
      });
    });
    MONTHS.forEach(function(mo){
      var mData=CHANNEL_MONTHLY[mo]||{};
      Object.keys(mData).forEach(function(k){
        if(!ytdTarget[k])ytdTarget[k]=0;
        ytdTarget[k]+=(mData[k].t||0);
      });
    });
    function _chStatusBadge(pct){
      var color,bg,text;
      if(pct>=100){color='#16a34a';bg='#16a34a';text=_isEN?'Met':'ผ่านเป้า';}
      else if(pct>=80){color='#d97706';bg='#f59e0b';text=_isEN?'Near':'ใกล้ถึงเป้า';}
      else{color='#dc2626';bg='#dc2626';text=_isEN?'Short':'ขาดเป้า';}
      return {color:color,bg:bg,text:text};
    }
    function _chRow(label,tgt,act,isBig){
      var pct=tgt?(act/tgt*100):0;var s=_chStatusBadge(pct);var diff=act-tgt;
      var pw=Math.min(pct,100);
      var fs=isBig?'font-size:22px;':'font-size:15px;';
      return '<div style="margin-bottom:'+(isBig?'14':'8')+'px">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px">'
        +'<div style="font-size:11px;color:#64748b;font-weight:600">'+label+'</div>'
        +'<div style="display:flex;align-items:center;gap:6px">'
        +'<span style="'+fs+'font-weight:800;color:'+s.color+'">'+pct.toFixed(1)+'%</span>'
        +'<span style="background:'+s.bg+';color:#fff;font-size:9px;font-weight:700;padding:1px 6px;border-radius:8px">'+s.text+'</span>'
        +'</div></div>'
        +'<div style="background:#e2e8f0;border-radius:4px;height:'+(isBig?'8':'5')+'px;margin-bottom:4px;overflow:hidden"><div style="background:'+s.color+';height:100%;border-radius:4px;width:'+pw+'%"></div></div>'
        +'<div style="display:flex;gap:10px;font-size:10px;color:#94a3b8">'
        +'<span>'+(_isEN?'Target':'เป้า')+': '+(tgt/1e6).toFixed(2)+'M</span>'
        +'<span>'+(_isEN?'Actual':'จริง')+': <b style="color:'+s.color+'">'+(act/1e6).toFixed(2)+'M</b></span>'
        +'<span>'+(_isEN?'Gap':'ส่วนต่าง')+': <b style="color:'+(diff>=0?'#16a34a':'#dc2626')+'">'+(diff>=0?'+':'')+fmtM(diff)+'</b></span>'
        +'</div></div>';
    }
    var _btTitle=_isEN?'📊 Channel Performance':'📊 สถานะผลงานแต่ละช่องทาง';
    var chs=CH_NAMES.filter(c=>(fullYearTarget[c]||0)>0);
    if(!chs.length){btEl.innerHTML='';} else {
      btEl.innerHTML='<div class="card" style="border:1px solid #e2e8f0"><div class="card-title" style="color:#1e293b;margin-bottom:10px">'+_btTitle+'</div>'
      +'<div style="display:flex;gap:12px;flex-wrap:wrap">'+chs.map(function(c){
        var fyT=fullYearTarget[c]||0,ytdT=ytdTarget[c]||0,ytdA=ytdData[c]?.a||0;
        var mT=mthData[c]?.t||0,mA=mthData[c]?.a||0;
        var fyPct=fyT?(ytdA/fyT*100):0;
        var fyS=_chStatusBadge(fyPct<50?0:fyPct<75?80:100);
        var cardBg=fyPct>=75?'#f0fdf4':fyPct>=50?'#fffbeb':'#fef2f2';
        var cardBorder=fyPct>=75?'#bbf7d0':fyPct>=50?'#fde68a':'#fecaca';
        return '<div style="flex:1;min-width:240px;background:'+cardBg+';border:1px solid '+cardBorder+';border-radius:12px;padding:16px">'
          +'<div style="font-weight:700;font-size:15px;color:#374151;margin-bottom:12px;border-bottom:1px solid '+cardBorder+';padding-bottom:8px">'+c+'</div>'
          +_chRow((_isEN?'Full Year Target — ':'1. เป้าทั้งปี — ')+(_isEN?'Achieved':'ทำได้'),fyT,ytdA,true)
          +_chRow((_isEN?'Month: ':'2. เดือน ')+mthLabel,mT,mA,false)
          +_chRow((_isEN?'YTD Target (Jan–':'3. เป้า YTD (ม.ค.–')+mthLabel+')',ytdT,ytdA,false)
          +'</div>';
      }).join('')+'</div></div>';
    }
  }

  // Channel Compare (MoM / YoY / YTD)
  var ccBody=document.getElementById('ovChannelCompareBody');
  if(ccBody && typeof CMP!=='undefined' && CMP.channelCompareHTML){
    var moIdx=isYTD?MONTHS.length-1:MONTHS_12.indexOf(months[months.length-1]);
    ccBody.innerHTML=CMP.channelCompareHTML(moIdx);
  }
}

