// CHANNEL
// ============================================================
var _chFilter='all';
function filterChannel(ch,el){
  _chFilter=ch;
  var btns=document.querySelectorAll('#chFilterBar .period-type-btn');
  btns.forEach(function(b){b.classList.remove('active');});
  if(el)el.classList.add('active');
  renderChannel();
}
function renderChannel(){
  const m=currentMonth;showBanner('Channel',m);
  const chData=getChannelData(m),totalAAll=CH_NAMES.reduce((s,c)=>s+(chData[c]?.a||0),0);
  var visNames=_chFilter==='all'?CH_NAMES:[_chFilter];
  var visColors=visNames.map(function(c){return CH_COLORS[CH_NAMES.indexOf(c)];});
  var visColorCls=visNames.map(function(c){return['blue','cyan','yellow','green'][CH_NAMES.indexOf(c)];});
  var totalA=visNames.reduce(function(s,c){return s+(chData[c]?.a||0);},0);
  document.getElementById('chKPI').innerHTML=visNames.map(function(c,i){
    var t=chData[c]?.t||0,a=chData[c]?.a||0,ach=t?a/t*100:0;
    return'<div class="kpi-card '+visColorCls[i]+'"><div class="kpi-label">'+c+'</div><div class="kpi-value sm">'+fmtM(a)+'</div><div class="kpi-sub">Target: '+fmtM(t)+'</div><div class="kpi-badge '+(ach>=80?'pos':ach>=60?'warn':'neg')+'">'+ach.toFixed(1)+'% สำเร็จ</div></div>';
  }).join('');
  mkChart('chBar',{type:'bar',data:{labels:visNames,datasets:[
    {label:'Target',data:visNames.map(function(c){return chData[c]?.t/1e6||0;}),backgroundColor:'rgba(79,70,229,.15)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},
    {label:'Actual',data:visNames.map(function(c){return chData[c]?.a/1e6||0;}),backgroundColor:visColors.map(function(c){return c+'cc';}),borderColor:visColors,borderWidth:2,borderRadius:6},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}}}}});
  mkChart('chPie',{type:'doughnut',data:{labels:visNames,datasets:[{data:visNames.map(function(c){return chData[c]?.a||0;}),backgroundColor:visColors,borderColor:'#fff',borderWidth:3}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'58%',plugins:{legend:{position:'right'},tooltip:{callbacks:{label:function(c){return' '+c.label+': '+(c.raw/totalA*100).toFixed(1)+'% ('+fmtM(c.raw)+')';} }}}}});
  document.getElementById('chTable').innerHTML=visNames.map(function(c){
    var t=chData[c]?.t||0,a=chData[c]?.a||0,diff=a-t,ach=t?a/t*100:0,contrib=totalA?a/totalA*100:0;
    return'<tr><td><strong>'+c+'</strong></td><td style="text-align:right">'+fmt(t)+'</td><td style="text-align:right">'+fmt(a)+'</td><td style="text-align:right;color:'+(diff>=0?'#16a34a':'#dc2626')+'">'+(diff>=0?'+':'')+fmt(diff)+'</td><td style="text-align:right"><span class="pill '+(diff>=0?'green':'red')+'">'+Math.abs(diff/t*100).toFixed(0)+'%</span></td><td style="text-align:right"><span class="pill blue">'+contrib.toFixed(1)+'%</span></td><td>'+progFill(ach)+'</td></tr>';
  }).join('');
  mkChart('chTrend',{type:'line',data:{labels:MONTHS_TH,datasets:visNames.map(function(c,i){return{label:c,data:MONTHS.map(function(mo){return(CHANNEL_MONTHLY[mo]&&CHANNEL_MONTHLY[mo][c])?CHANNEL_MONTHLY[mo][c].a/1e6:0;}),borderColor:visColors[i],backgroundColor:visColors[i]+'22',fill:false,tension:.4,borderWidth:2,pointRadius:4,pointBackgroundColor:visColors[i]};})},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}}}}});
}

// ============================================================
// TREND
// ============================================================
function initTrend(){
  mkChart('trendMain',{type:'bar',data:{labels:MONTHS_FULL_TH,datasets:[
    {label:'Target',data:MONTHLY_TARGET.map(v=>v/1e6),backgroundColor:'rgba(79,70,229,.18)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},
    {label:'Actual',data:MONTHLY_ACTUAL.map(v=>v?v/1e6:null),backgroundColor:'rgba(8,145,178,.7)',borderColor:'#0891b2',borderWidth:2,borderRadius:6},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
  let ct=0,ca=0;const cumTs=[],cumAs=[];
  MONTHLY_TARGET.forEach((t,i)=>{ct+=t;cumTs.push(+(ct/1e6).toFixed(2));if(MONTHLY_ACTUAL[i]){ca+=MONTHLY_ACTUAL[i];cumAs.push(+(ca/1e6).toFixed(2));}else cumAs.push(null);});
  mkChart('trendCum',{type:'line',data:{labels:MONTHS_FULL_TH,datasets:[
    {label:'Cum Target',data:cumTs,borderColor:'#4f46e5',backgroundColor:'rgba(79,70,229,.08)',fill:true,tension:.4,borderWidth:2,pointRadius:3},
    {label:'Cum Actual',data:cumAs,borderColor:'#0891b2',fill:false,tension:.4,borderWidth:3,pointRadius:5,pointBackgroundColor:'#0891b2'},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
  const gaps=MONTHLY_ACTUAL.map((a,i)=>a?(MONTHLY_TARGET[i]-a)/1e6:null);
  mkChart('trendGap',{type:'bar',data:{labels:MONTHS_FULL_TH,datasets:[{label:'Gap',data:gaps,backgroundColor:gaps.map(v=>v==null?'#e2e8f0':v>0?'rgba(220,38,38,.6)':'rgba(22,163,74,.6)'),borderRadius:5}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
  let ctt=0,caa=0;
  document.getElementById('trendTable').innerHTML=MONTHLY_TARGET.map((t,i)=>{
    const a=MONTHLY_ACTUAL[i];ctt+=t;if(a)caa+=a;
    const has=!!a,diff=a-t,ach=a&&t?a/t*100:null;
    const status=!has?`<span class="pill blue">เป้าหมาย</span>`:ach>=80?`<span class="pill green">✓ ผ่าน</span>`:ach>=60?`<span class="pill yellow">⚡ ปาน</span>`:`<span class="pill red">✗ ต่ำ</span>`;
    return`<tr ${i>=6?'style="color:#94a3b8"':''}><td><strong>${MONTHS_FULL_TH[i]}</strong></td><td style="text-align:right">${fmt(t)}</td><td style="text-align:right">${has?fmt(a):'—'}</td><td style="text-align:right;color:${has?(diff>=0?'#16a34a':'#dc2626'):'#94a3b8'}">${has?fmt(diff):'—'}</td><td style="text-align:right">${ach!=null?`<span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span>`:'—'}</td><td style="text-align:right">${fmt(ctt)}</td><td style="text-align:right">${caa?fmt(caa):'—'}</td><td>${status}</td></tr>`;
  }).join('');
  renderDailyTrend();
}

// ============================================================
// CUSTOMER
// ============================================================
var _custMonth='YTD';
function custYearChange(val){ pickAnnual(val); }
function custMonthChange(val){ _custMonth=val; renderCustomer(); }
var _salesMonth='YTD';
function salesYearChange(val){ pickAnnual(val); }
function salesMonthChange(val){ _salesMonth=val; renderSales(); }
function renderCustomer(){
  // Populate year dropdown
  var cyDrop=document.getElementById('custYearDrop');
  if(cyDrop){
    var years=Object.keys(_YEAR_MAP);
    cyDrop.innerHTML=years.map(function(y){return '<option value="'+y+'"'+(parseInt(y)===_CY?' selected':'')+'>ปี '+y+'</option>';}).join('');
  }
  // Populate month dropdown
  var cmDrop=document.getElementById('custMonthDrop');
  if(cmDrop){
    var opts='<option value="YTD"'+(_custMonth==='YTD'?' selected':'')+'>ทั้งหมด (YTD)</option>';
    opts+=MONTHS.map(function(mo,i){return '<option value="'+mo+'"'+(mo===_custMonth?' selected':'')+'>'+(MONTHS_FULL_TH[i]||mo)+'</option>';}).join('');
    cmDrop.innerHTML=opts;
  }
  var m=_custMonth;showBanner('Customer',m);
  const mtData=getMonthData(MT_CUST,m),amzData=getMonthData(AMZ_CUST,m),olData=getMonthData(OL_CUST,m),boothData=getMonthData(BOOTH_DATA,m);
  const all=[...Object.entries(mtData),...Object.entries(amzData),...Object.entries(olData),...Object.entries(boothData)].map(([k,v])=>({name:k,...v})).sort((a,b)=>b.a-a.a);
  const top10=all.filter(e=>e.a>0).slice(0,10),totalA=all.reduce((s,e)=>s+e.a,0);
  mkChart('custBar',{type:'bar',data:{labels:top10.map(e=>e.name),datasets:[{label:'Actual',data:top10.map(e=>e.a),backgroundColor:COLORS12,borderRadius:5}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>(v/1e6).toFixed(1)+'M'},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:10},maxRotation:45,minRotation:0},grid:{display:false}}}}});
  mkChart('custPie',{type:'doughnut',data:{labels:top10.map(e=>e.name),datasets:[{data:top10.map(e=>e.a),backgroundColor:COLORS12,borderColor:'#fff',borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'55%',plugins:{legend:{position:'right',labels:{font:{size:11}}},tooltip:{callbacks:{label:c=>` ${c.label}: ${(c.raw/totalA*100).toFixed(1)}%`}}}}});
  document.getElementById('custMTTable').innerHTML=Object.entries(mtData).sort((a,b)=>b[1].a-a[1].a).map(([name,v],i)=>{
    const ach=v.t?v.a/v.t*100:0;
    return`<tr><td>${rankBadge(i)}</td><td><strong>${name}</strong></td><td style="text-align:right">${fmt(v.t)}</td><td style="text-align:right">${fmt(v.a)}</td><td style="text-align:right;color:${v.a-v.t>=0?'#16a34a':'#dc2626'}">${fmt(v.a-v.t)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td><td>${progFill(ach)}</td></tr>`;
  }).join('');
  document.getElementById('custAmzTable').innerHTML=Object.entries(amzData).sort((a,b)=>b[1].a-a[1].a).map(([name,v])=>{
    const ach=v.t?v.a/v.t*100:0;
    return`<tr><td>${name}</td><td style="text-align:right">${fmt(v.t)}</td><td style="text-align:right">${fmt(v.a)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td></tr>`;
  }).join('');
  document.getElementById('custOlTable').innerHTML=Object.entries(olData).sort((a,b)=>b[1].a-a[1].a).map(([name,v])=>{
    const ach=v.t?v.a/v.t*100:0;
    return`<tr><td>${name}</td><td style="text-align:right">${fmt(v.t)}</td><td style="text-align:right">${fmt(v.a)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td></tr>`;
  }).join('');
  document.getElementById('custBoothTable').innerHTML=Object.entries(boothData).filter(([,v])=>v.a>0).sort((a,b)=>b[1].a-a[1].a).map(([name,v],i)=>{
    const ach=v.t?v.a/v.t*100:0;
    return`<tr><td>${rankBadge(i)}</td><td><strong>${name}</strong></td><td style="text-align:right">${fmt(v.t)}</td><td style="text-align:right">${fmt(v.a)}</td><td style="text-align:right;color:${v.a-v.t>=0?'#16a34a':'#dc2626'}">${fmt(v.a-v.t)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td><td>${progFill(ach)}</td></tr>`;
  }).join('');
}

// ============================================================
// SALES — TOP SECTION
// ============================================================
function renderSales(){
  var syDrop=document.getElementById('salesYearDrop');
  if(syDrop){
    var years=Object.keys(_YEAR_MAP);
    syDrop.innerHTML=years.map(function(y){return '<option value="'+y+'"'+(parseInt(y)===_CY?' selected':'')+'>ปี '+y+'</option>';}).join('');
  }
  var smDrop=document.getElementById('salesMonthDrop');
  if(smDrop){
    var opts='<option value="YTD"'+(_salesMonth==='YTD'?' selected':'')+'>ทั้งหมด (YTD)</option>';
    opts+=MONTHS.map(function(mo,i){return '<option value="'+mo+'"'+(mo===_salesMonth?' selected':'')+'>'+(MONTHS_FULL_TH[i]||mo)+'</option>';}).join('');
    smDrop.innerHTML=opts;
  }
  const m=_salesMonth;
  var _savedMonth=currentMonth;currentMonth=m;
  try{
  showBanner('Sales',m);
  const sorted=getSalesData(m);
  const totalT=sorted.reduce((s,v)=>s+v.target,0),totalA=sorted.reduce((s,v)=>s+v.actual,0),top=sorted[0];
  document.getElementById('salesKPI').innerHTML=`
    <div class="kpi-card blue"><div class="kpi-label">Target รวม</div><div class="kpi-value sm">${fmtM(totalT)}</div><div class="kpi-sub">${m==='YTD'?'YTD '+MONTHS.length+' เดือน':(m&&m.range?MONTHS_FULL_TH[MONTHS_12.indexOf(m.start)]+'–'+MONTHS_FULL_TH[MONTHS_12.indexOf(m.end)]:(MONTH_LABELS[m]||m))}</div></div>
    <div class="kpi-card cyan"><div class="kpi-label">ยอดจริงรวม</div><div class="kpi-value sm">${fmtM(totalA)}</div><div class="kpi-badge ${totalT?achCls(totalA/totalT*100)+'':'blue'}">${totalT?(totalA/totalT*100).toFixed(1)+'%':'-'} achieve</div></div>
    <div class="kpi-card green"><div class="kpi-label">Top Performer</div><div class="kpi-value sm" style="font-size:16px">${top?.name||'—'}</div><div class="kpi-sub">${top?fmtM(top.actual):''}</div></div>
    <div class="kpi-card yellow"><div class="kpi-label">จำนวนพนักงาน</div><div class="kpi-value sm">7 คน</div></div>`;
  const shortNames=sorted.map(s=>s.name.replace(/\s*\(.*?\)/,''));
  mkChart('salesActBar',{type:'bar',data:{labels:shortNames,datasets:[{label:'Actual',data:sorted.map(s=>s.actual/1e6),backgroundColor:COLORS12,borderRadius:6}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:11}},grid:{display:false}}}}});
  const achs=sorted.map(s=>s.target?+(s.actual/s.target*100).toFixed(1):0);
  mkChart('salesAchBar',{type:'bar',data:{labels:shortNames,datasets:[{label:'% Achieve',data:achs,backgroundColor:achs.map(v=>v>=80?'rgba(22,163,74,.7)':v>=60?'rgba(217,119,6,.7)':'rgba(220,38,38,.7)'),borderRadius:6}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>v+'%'},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:11}},grid:{display:false}}}}});
  document.getElementById('salesTable').innerHTML=sorted.map((s,i)=>{
    const diff=s.actual-s.target,ach=s.target?s.actual/s.target*100:0;
    const kpi=ach>=80?`<span class="pill green">✓ ผ่าน</span>`:ach>=60?`<span class="pill yellow">⚡ ปาน</span>`:`<span class="pill red">✗ ต่ำ</span>`;
    return`<tr><td>${rankBadge(i)}</td><td><strong>${s.name}</strong></td><td style="font-size:11px;color:#64748b">${s.zone}</td><td style="text-align:right">${fmt(s.target)}</td><td style="text-align:right">${fmt(s.actual)}</td><td style="text-align:right;color:${diff>=0?'#16a34a':'#dc2626'}">${diff>=0?'+':''}${fmt(diff)}</td><td>${progFill(ach)}</td><td>${kpi}</td></tr>`;
  }).join('');
  var mthHead=document.getElementById('salesMthHead');
  if(mthHead) mthHead.innerHTML='<th>พนักงานขาย</th>'+MONTHS_TH.map(function(t){return'<th style="text-align:right">'+t+'</th>';}).join('')+'<th style="text-align:right">YTD</th><th>Performance</th>';
  const allNames=Object.keys(SALES_MONTHLY);
  document.getElementById('salesMthTable').innerHTML=[
    ...allNames.map(n=>{
      const ytd=MONTHS.reduce((s,mo)=>s+(SALES_MONTHLY[n][mo]||0),0);
      const mCols=MONTHS.map(mo=>`<td style="text-align:right;${mo===m&&m!=='YTD'?'background:#eff6ff;font-weight:700':''}">${fmt(SALES_MONTHLY[n][mo]||0)}</td>`).join('');
      const smv=MONTHS.map(mo=>SALES_MONTHLY[n][mo]||0);
      const sPerf=window.calcPerf(smv);
      return`<tr><td><strong>${n}</strong></td>${mCols}<td style="text-align:right;font-weight:700;color:#4f46e5">${fmt(ytd)}</td><td style="text-align:center">${window.perfBadgeHTML(sPerf)}</td></tr>`;
    }),
    `<tr class="tr-total"><td>รวม</td>${MONTHS.map(mo=>{const s=allNames.reduce((ss,n)=>ss+(SALES_MONTHLY[n][mo]||0),0);return`<td style="text-align:right">${fmt(s)}</td>`;}).join('')}<td style="text-align:right">${fmt(allNames.reduce((s,n)=>s+MONTHS.reduce((ss,mo)=>ss+(SALES_MONTHLY[n][mo]||0),0),0))}</td><td></td></tr>`,
  ].join('');

  // Build person cards
  buildPersonCards(m);
  }finally{ currentMonth=_savedMonth; }
}

// ============================================================
// PERSON CARDS
// ============================================================
function buildPersonCards(m){
  const cards=document.getElementById('personCards');
  const all=Object.keys(SALES_MONTHLY);
  var mos=_resolveMonths();
  var totalAct=0,totalTgt=0;
  all.forEach(function(n){mos.forEach(function(mo){totalAct+=(SALES_MONTHLY[n][mo]||0);totalTgt+=((SALES_MTH_TARGET[n]&&SALES_MTH_TARGET[n][mo])||0);});});
  var totalAch=totalTgt?totalAct/totalTgt*100:0;
  var totalCls=totalAch>=80?'ok':totalAch>=60?'warn':'bad';
  var totalSel=selectedPerson==='__ALL__'?'selected':'';
  var html=`<div class="pcard ${totalSel}" onclick="selectAllPerf()" style="border:2px solid #f97316;background:linear-gradient(135deg,#fff7ed,#ffedd5)">
    <div class="pcard-name" style="color:#c2410c">รวมทุกคน</div>
    <div class="pcard-zone" style="color:#9a3412">ทุกช่องทาง</div>
    <div class="pcard-act" style="color:#ea580c">${fmtM(totalAct)}</div>
    <div class="pcard-tgt" style="font-size:11px;color:#78716c">เป้า ${fmtM(totalTgt)}</div>
    <div class="pcard-ach ${totalCls}">${totalAch.toFixed(1)}% สำเร็จ</div>
  </div>`;
  html+=all.map(name=>{
    var act=0,tgt=0;
    mos.forEach(function(mo){act+=(SALES_MONTHLY[name][mo]||0);tgt+=((SALES_MTH_TARGET[name]&&SALES_MTH_TARGET[name][mo])||0);});
    const ach=tgt?act/tgt*100:0;
    const cls=ach>=80?'ok':ach>=60?'warn':'bad';
    const sel=selectedPerson===name?'selected':'';
    return`<div class="pcard ${sel}" onclick="selectPerson('${name}')">
      <div class="pcard-name">${name}</div>
      <div class="pcard-zone">${SALES_MONTHLY[name].zone}</div>
      <div class="pcard-act">${fmtM(act)}</div>
      <div class="pcard-tgt" style="font-size:11px;color:#78716c">เป้า ${fmtM(tgt)}</div>
      <div class="pcard-ach ${cls}">${ach.toFixed(1)}% สำเร็จ</div>
    </div>`;
  }).join('');
  cards.innerHTML=html;
  buildAllPerfDetail();
  if(selectedPerson==='__ALL__'){
    document.getElementById('salesAllDetail').style.display='block';
    document.getElementById('personDetail').style.display='none';
    setTimeout(_renderAllPerfCharts,50);
  }
}

function _toggleSalesOverview(show){
  var d=show?'':'none';
  ['salesChartsRow','salesRankCard','salesMthCard'].forEach(function(id){var e=document.getElementById(id);if(e)e.style.display=d;});
}

function selectAllPerf(){
  selectedPerson='__ALL__';
  document.querySelectorAll('.pcard').forEach(c=>c.classList.remove('selected'));
  document.querySelector('#personCards .pcard').classList.add('selected');
  document.getElementById('personDetail').style.display='none';
  _toggleSalesOverview(true);
  var el=document.getElementById('salesAllDetail');
  el.style.display='block';
  el.scrollIntoView({behavior:'smooth',block:'start'});
  _renderAllPerfCharts();
}

function selectPerson(name){
  selectedPerson=name;
  document.querySelectorAll('.pcard').forEach(c=>c.classList.remove('selected'));
  const cards=document.getElementById('personCards');
  const allCards=cards.querySelectorAll('.pcard');
  allCards.forEach(c=>{if(c.onclick.toString().includes(`'${name}'`))c.classList.add('selected');});
  document.getElementById('salesAllDetail').style.display='none';
  _toggleSalesOverview(false);
  document.getElementById('personDetail').style.display='block';
  document.getElementById('personDetail').scrollIntoView({behavior:'smooth',block:'start'});
  renderPersonDetail(name);
}

function buildAllPerfDetail(){
  var wrap=document.getElementById('salesAllDetail');
  if(!wrap)return;
  wrap.style.display='none';
  var sorted=getSalesData(_salesMonth);
  var fmtN=function(v){return (v/1e6).toFixed(2)+' M';};
  var pctCls=function(p){return p>=100?'#059669':p>=90?'#16a34a':p>=80?'#ca8a04':p>=70?'#d97706':p>=60?'#ea580c':'#dc2626';};
  var pctBg=function(p){return p>=100?'#ecfdf5':p>=90?'#f0fdf4':p>=80?'#fefce8':p>=70?'#fffbeb':p>=60?'#fff7ed':'#fef2f2';};
  var verdict=function(p){
    if(p>=100)return{t:'ดีเยี่ยม',c:'#059669',bg:'#ecfdf5',i:'🏆'};
    if(p>=90)return{t:'ดี',c:'#16a34a',bg:'#f0fdf4',i:'✅'};
    if(p>=80)return{t:'ปานกลาง',c:'#ca8a04',bg:'#fefce8',i:'📊'};
    if(p>=70)return{t:'พอใช้',c:'#d97706',bg:'#fffbeb',i:'⚡'};
    if(p>=60)return{t:'ไม่ผ่าน (ต้องปรับปรุง)',c:'#ea580c',bg:'#fff7ed',i:'⚠️'};
    return{t:'ไม่ผ่าน (ขั้นรุนแรง)',c:'#dc2626',bg:'#fef2f2',i:'🚨'};
  };
  var chMap={},chOrder=['Modern Trade','Amazon','Booth','Online'];
  sorted.forEach(function(s){
    var ch=s.zone.replace(/\s*\(.*?\)/,'').trim();
    if(ch.indexOf('Amazon')===0)ch='Amazon';
    if(!chMap[ch])chMap[ch]=[];
    chMap[ch].push(s);
  });
  var channels=chOrder.filter(function(c){return chMap[c];});
  Object.keys(chMap).forEach(function(c){if(channels.indexOf(c)<0)channels.push(c);});
  var moTh={Jan:'ม.ค.',Feb:'ก.พ.',Mar:'มี.ค.',Apr:'เม.ย.',May:'พ.ค.',Jun:'มิ.ย.',Jul:'ก.ค.',Aug:'ส.ค.',Sep:'ก.ย.',Oct:'ต.ค.',Nov:'พ.ย.',Dec:'ธ.ค.'};
  var mos=MONTHS;
  var html='';
  channels.forEach(function(ch){
    var staff=chMap[ch];
    var chAct=staff.reduce(function(s,v){return s+v.actual;},0);
    var chTgt=staff.reduce(function(s,v){return s+v.target;},0);
    var chPct=chTgt?(chAct/chTgt*100):0;
    var chId=ch.replace(/[^a-zA-Z0-9]/g,'');
    html+='<div style="background:linear-gradient(135deg,#f0f9ff,#e0f2fe);border-radius:14px;padding:16px 18px;margin-bottom:16px;border:1px solid #bae6fd">';
    html+='<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:12px">';
    html+='<div style="font-size:15px;font-weight:700;color:#0c4a6e">📊 '+ch+'</div>';
    html+='<div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12px">';
    html+='<div style="text-align:center"><div style="color:#64748b;font-size:10px">เป้าหมาย</div><div style="font-weight:700;color:#1e293b">'+fmtN(chTgt)+'</div></div>';
    html+='<div style="text-align:center"><div style="color:#64748b;font-size:10px">ยอดจริง</div><div style="font-weight:700;color:#0369a1">'+fmtN(chAct)+'</div></div>';
    html+='<div style="text-align:center"><div style="color:#64748b;font-size:10px">สำเร็จ</div><div style="font-weight:700;color:'+pctCls(chPct)+'">'+chPct.toFixed(1)+'%</div></div>';
    html+='</div></div>';
    // Staff cards
    html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px">';
    staff.forEach(function(s){
      var diff=s.actual-s.target,ach=s.target?(s.actual/s.target*100):0,barW=Math.min(Math.max(ach,0),100);
      html+='<div style="background:#fff;border-radius:12px;padding:14px;border:1px solid #e2e8f0">';
      html+='<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">';
      html+='<div><div style="font-size:14px;font-weight:700;color:#1e293b">'+s.name+'</div>';
      html+='<div style="font-size:11px;color:#64748b;margin-top:2px">'+s.zone+'</div></div>';
      html+='<div style="background:'+pctBg(ach)+';color:'+pctCls(ach)+';padding:3px 10px;border-radius:20px;font-size:13px;font-weight:700">'+ach.toFixed(1)+'%</div></div>';
      html+='<div style="background:#f1f5f9;border-radius:6px;height:7px;margin-bottom:8px;overflow:hidden">';
      html+='<div style="background:'+pctCls(ach)+';height:100%;border-radius:6px;width:'+barW+'%"></div></div>';
      html+='<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;text-align:center">';
      html+='<div><div style="font-size:10px;color:#94a3b8">เป้าหมาย</div><div style="font-size:13px;font-weight:600;color:#475569">'+fmtN(s.target)+'</div></div>';
      html+='<div><div style="font-size:10px;color:#94a3b8">ยอดจริง</div><div style="font-size:13px;font-weight:600;color:#0369a1">'+fmtN(s.actual)+'</div></div>';
      html+='<div><div style="font-size:10px;color:#94a3b8">ส่วนต่าง</div><div style="font-size:13px;font-weight:600;color:'+(diff>=0?'#22c55e':'#ef4444')+'">'+(diff>=0?'+':'')+fmtN(diff)+'</div></div>';
      html+='</div></div>';
    });
    html+='</div>';
    // Chart + Verdict
    html+='<div style="display:grid;grid-template-columns:2fr 1fr;gap:12px;margin-top:12px">';
    html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0">';
    html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📊 เป้าหมาย vs ยอดจริง</div>';
    html+='<div style="height:220px"><canvas id="apChart_'+chId+'"></canvas></div></div>';
    html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0">';
    html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📋 สรุปผลประเมิน</div>';
    staff.forEach(function(s){
      var ach=s.target?(s.actual/s.target*100):0,vd=verdict(ach);
      html+='<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:'+vd.bg+';border-radius:8px;border-left:3px solid '+vd.c+';margin-bottom:6px">';
      html+='<span style="font-size:16px">'+vd.i+'</span>';
      html+='<div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:600;color:#1e293b">'+s.name+'</div>';
      html+='<div style="font-size:10px;color:#64748b">'+ach.toFixed(1)+'% achieve</div></div>';
      html+='<div style="font-size:11px;font-weight:700;color:'+vd.c+';white-space:nowrap">'+vd.t+'</div></div>';
    });
    html+='</div></div>';
    // Monthly charts per person
    html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0;margin-top:12px">';
    html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📅 เป้าหมาย vs ยอดจริง รายเดือน</div>';
    html+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px">';
    staff.forEach(function(s,idx){
      html+='<div><div style="font-size:12px;font-weight:600;color:#475569;margin-bottom:4px;text-align:center">'+s.name+'</div>';
      html+='<div style="height:180px"><canvas id="apMo_'+chId+'_'+idx+'"></canvas></div></div>';
    });
    html+='</div></div>';
    // Monthly table
    html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0;margin-top:12px;overflow-x:auto">';
    html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📅 ยอดขายรายเดือน</div>';
    html+='<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#f8fafc">';
    html+='<th style="padding:8px 10px;text-align:left;border-bottom:2px solid #e2e8f0;font-weight:600;color:#64748b;position:sticky;left:0;background:#f8fafc">พนักงาน</th>';
    mos.forEach(function(mo){html+='<th style="padding:8px 6px;text-align:right;border-bottom:2px solid #e2e8f0;font-weight:600;color:#64748b;min-width:70px">'+(moTh[mo]||mo)+'</th>';});
    html+='<th style="padding:8px 10px;text-align:right;border-bottom:2px solid #e2e8f0;font-weight:700;color:#1e293b">รวม</th></tr></thead><tbody>';
    staff.forEach(function(s){
      var sm=SALES_MONTHLY[s.name]||{},st=SALES_MTH_TARGET[s.name]||{};
      html+='<tr><td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;font-weight:600;white-space:nowrap;position:sticky;left:0;background:#fff">'+s.name+'</td>';
      mos.forEach(function(mo){var v=sm[mo]||0,t=st[mo]||0,mp=t?(v/t*100):0;
        html+='<td style="padding:8px 6px;text-align:right;border-bottom:1px solid #f1f5f9;color:'+pctCls(mp)+';font-weight:500">'+fmtN(v)+'</td>';});
      html+='<td style="padding:8px 10px;text-align:right;border-bottom:1px solid #f1f5f9;font-weight:700;color:#ea580c">'+fmtN(s.actual)+'</td></tr>';
      html+='<tr style="background:#fafafa"><td style="padding:4px 10px;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8;position:sticky;left:0;background:#fafafa">เป้า</td>';
      mos.forEach(function(mo){html+='<td style="padding:4px 6px;text-align:right;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8">'+fmtN(st[mo]||0)+'</td>';});
      html+='<td style="padding:4px 10px;text-align:right;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-weight:600">'+fmtN(s.target)+'</td></tr>';
    });
    html+='</tbody></table></div>';
    html+='</div>';
  });
  wrap.innerHTML=html;
  wrap._channels=channels;wrap._chMap=chMap;
}

function _renderAllPerfCharts(){
  var wrap=document.getElementById('salesAllDetail');
  if(!wrap||!wrap._chMap)return;
  var channels=wrap._channels,chMap=wrap._chMap;
  var moTh={Jan:'ม.ค.',Feb:'ก.พ.',Mar:'มี.ค.',Apr:'เม.ย.',May:'พ.ค.',Jun:'มิ.ย.',Jul:'ก.ค.',Aug:'ส.ค.',Sep:'ก.ย.',Oct:'ต.ค.',Nov:'พ.ย.',Dec:'ธ.ค.'};
  var mos=MONTHS;
  var moLabels=mos.map(function(m){return moTh[m]||m;});
  var colorFn=function(p){if(p>=100)return'rgba(5,150,105,.7)';if(p>=90)return'rgba(22,163,74,.7)';if(p>=80)return'rgba(202,138,4,.7)';if(p>=70)return'rgba(217,119,6,.7)';if(p>=60)return'rgba(234,88,12,.7)';return'rgba(220,38,38,.7)';};
  channels.forEach(function(ch){
    var staff=chMap[ch],chId=ch.replace(/[^a-zA-Z0-9]/g,'');
    var names=staff.map(function(s){return s.name.replace(/\s*\(.*?\)/,'');});
    var tgts=staff.map(function(s){return s.target/1e6;});
    var acts=staff.map(function(s){return s.actual/1e6;});
    var achC=staff.map(function(s){return colorFn(s.target?(s.actual/s.target*100):0);});
    mkChart('apChart_'+chId,{type:'bar',data:{labels:names,datasets:[
      {label:'เป้าหมาย',data:tgts,backgroundColor:'rgba(79,70,229,.15)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},
      {label:'ยอดจริง',data:acts,backgroundColor:achC,borderColor:achC.map(function(c){return c.replace(/[\d.]+\)$/,'1)');}),borderWidth:2,borderRadius:6}
    ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{font:{size:11}}},tooltip:{callbacks:{label:function(c){return ' '+c.dataset.label+': '+(c.raw).toFixed(2)+' M';}}}},scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:11}},grid:{display:false}}}}});
    staff.forEach(function(s,idx){
      var sm=SALES_MONTHLY[s.name]||{},st=SALES_MTH_TARGET[s.name]||{};
      var mA=mos.map(function(mo){return(sm[mo]||0)/1e6;}),mT=mos.map(function(mo){return(st[mo]||0)/1e6;});
      var mC=mos.map(function(mo){var v=sm[mo]||0,t=st[mo]||0;return colorFn(t?(v/t*100):0);});
      mkChart('apMo_'+chId+'_'+idx,{type:'bar',data:{labels:moLabels,datasets:[
        {label:'เป้าหมาย',data:mT,backgroundColor:'rgba(79,70,229,.12)',borderColor:'#4f46e5',borderWidth:1.5,borderRadius:4},
        {label:'ยอดจริง',data:mA,backgroundColor:mC,borderColor:mC.map(function(c){return c.replace(/[\d.]+\)$/,'1)');}),borderWidth:1.5,borderRadius:4}
      ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{font:{size:10}}},tooltip:{callbacks:{label:function(c){return ' '+c.dataset.label+': '+(c.raw).toFixed(2)+' M';}}}},scales:{y:{ticks:{callback:function(v){return v+'M';},font:{size:10}},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:10}},grid:{display:false}}}}});
    });
  });
}

// ============================================================
// PERSON PERFORMANCE SECTION (inside personDetail)
// ============================================================
function _buildPersonPerfSection(name){
  var wrap=document.getElementById('pdPerfSection');
  if(!wrap)return;
  var fmtN=function(v){return(v/1e6).toFixed(2)+' M';};
  var pctCls=function(p){return p>=100?'#059669':p>=90?'#16a34a':p>=80?'#ca8a04':p>=70?'#d97706':p>=60?'#ea580c':'#dc2626';};
  var pctBg=function(p){return p>=100?'#ecfdf5':p>=90?'#f0fdf4':p>=80?'#fefce8':p>=70?'#fffbeb':p>=60?'#fff7ed':'#fef2f2';};
  var verdict=function(p){
    if(p>=100)return{t:'ดีเยี่ยม',c:'#059669',bg:'#ecfdf5',i:'🏆'};
    if(p>=90)return{t:'ดีมาก',c:'#16a34a',bg:'#f0fdf4',i:'✅'};
    if(p>=80)return{t:'ปานกลาง',c:'#ca8a04',bg:'#fefce8',i:'📊'};
    if(p>=70)return{t:'พอใช้',c:'#d97706',bg:'#fffbeb',i:'⚡'};
    if(p>=60)return{t:'ไม่ผ่าน (ต้องปรับปรุง)',c:'#ea580c',bg:'#fff7ed',i:'⚠️'};
    return{t:'ไม่ผ่าน (ขั้นรุนแรง)',c:'#dc2626',bg:'#fef2f2',i:'🚨'};
  };
  var moTh={Jan:'ม.ค.',Feb:'ก.พ.',Mar:'มี.ค.',Apr:'เม.ย.',May:'พ.ค.',Jun:'มิ.ย.',Jul:'ก.ค.',Aug:'ส.ค.',Sep:'ก.ย.',Oct:'ต.ค.',Nov:'พ.ย.',Dec:'ธ.ค.'};
  var sm=SALES_MONTHLY[name]||{},st=SALES_MTH_TARGET[name]||{};
  var mos=MONTHS;
  var act=0,tgt=0;
  mos.forEach(function(mo){act+=(sm[mo]||0);tgt+=(st[mo]||0);});
  var ach=tgt?(act/tgt*100):0,diff=act-tgt,barW=Math.min(Math.max(ach,0),100);
  var vd=verdict(ach);
  var html='';
  // Staff card + verdict
  html+='<div style="display:grid;grid-template-columns:2fr 1fr;gap:12px;margin-bottom:12px">';
  // Staff card
  html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0">';
  html+='<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">';
  html+='<div><div style="font-size:15px;font-weight:700;color:#1e293b">'+name+'</div>';
  html+='<div style="font-size:12px;color:#64748b;margin-top:2px">'+sm.zone+'</div></div>';
  html+='<div style="background:'+pctBg(ach)+';color:'+pctCls(ach)+';padding:4px 12px;border-radius:20px;font-size:14px;font-weight:700">'+ach.toFixed(1)+'%</div></div>';
  html+='<div style="background:#f1f5f9;border-radius:6px;height:8px;margin-bottom:10px;overflow:hidden">';
  html+='<div style="background:'+pctCls(ach)+';height:100%;border-radius:6px;width:'+barW+'%"></div></div>';
  html+='<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;text-align:center">';
  html+='<div><div style="font-size:10px;color:#94a3b8">เป้าหมาย</div><div style="font-size:14px;font-weight:600;color:#475569">'+fmtN(tgt)+'</div></div>';
  html+='<div><div style="font-size:10px;color:#94a3b8">ยอดจริง</div><div style="font-size:14px;font-weight:600;color:#0369a1">'+fmtN(act)+'</div></div>';
  html+='<div><div style="font-size:10px;color:#94a3b8">ส่วนต่าง</div><div style="font-size:14px;font-weight:600;color:'+(diff>=0?'#22c55e':'#ef4444')+'">'+(diff>=0?'+':'')+fmtN(diff)+'</div></div>';
  html+='</div></div>';
  // Verdict
  html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0;display:flex;flex-direction:column;justify-content:center;align-items:center">';
  html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:12px">📋 สรุปผลประเมิน</div>';
  html+='<div style="font-size:40px;margin-bottom:8px">'+vd.i+'</div>';
  html+='<div style="font-size:18px;font-weight:700;color:'+vd.c+'">'+vd.t+'</div>';
  html+='<div style="font-size:13px;color:#64748b;margin-top:4px">'+ach.toFixed(1)+'% achieve</div>';
  html+='</div></div>';
  // Monthly chart
  html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0;margin-bottom:12px">';
  html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📊 เป้าหมาย vs ยอดจริง รายเดือน</div>';
  html+='<div style="height:220px"><canvas id="pdPerfChart"></canvas></div></div>';
  // Monthly table
  html+='<div style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e2e8f0;overflow-x:auto">';
  html+='<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:8px">📅 ยอดขายรายเดือน</div>';
  html+='<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#f8fafc">';
  html+='<th style="padding:8px 10px;text-align:left;border-bottom:2px solid #e2e8f0;font-weight:600;color:#64748b">พนักงาน</th>';
  mos.forEach(function(mo){html+='<th style="padding:8px 6px;text-align:right;border-bottom:2px solid #e2e8f0;font-weight:600;color:#64748b;min-width:65px">'+(moTh[mo]||mo)+'</th>';});
  html+='<th style="padding:8px 10px;text-align:right;border-bottom:2px solid #e2e8f0;font-weight:700;color:#1e293b">รวม</th></tr></thead><tbody>';
  // Actual row
  html+='<tr><td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;font-weight:600;white-space:nowrap">'+name+'</td>';
  mos.forEach(function(mo){var v=sm[mo]||0,t=st[mo]||0,mp=t?(v/t*100):0;
    html+='<td style="padding:8px 6px;text-align:right;border-bottom:1px solid #f1f5f9;color:'+pctCls(mp)+';font-weight:500">'+fmtN(v)+'</td>';});
  html+='<td style="padding:8px 10px;text-align:right;border-bottom:1px solid #f1f5f9;font-weight:700;color:#ea580c">'+fmtN(act)+'</td></tr>';
  // Target row
  html+='<tr style="background:#fafafa"><td style="padding:4px 10px;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8">เป้า</td>';
  mos.forEach(function(mo){html+='<td style="padding:4px 6px;text-align:right;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8">'+fmtN(st[mo]||0)+'</td>';});
  html+='<td style="padding:4px 10px;text-align:right;border-bottom:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-weight:600">'+fmtN(tgt)+'</td></tr>';
  html+='</tbody></table></div>';
  wrap.innerHTML=html;
}

function _renderPersonPerfChart(name){
  var sm=SALES_MONTHLY[name]||{},st=SALES_MTH_TARGET[name]||{};
  var moTh={Jan:'ม.ค.',Feb:'ก.พ.',Mar:'มี.ค.',Apr:'เม.ย.',May:'พ.ค.',Jun:'มิ.ย.',Jul:'ก.ค.',Aug:'ส.ค.',Sep:'ก.ย.',Oct:'ต.ค.',Nov:'พ.ย.',Dec:'ธ.ค.'};
  var colorFn=function(p){if(p>=100)return'rgba(5,150,105,.7)';if(p>=90)return'rgba(22,163,74,.7)';if(p>=80)return'rgba(202,138,4,.7)';if(p>=70)return'rgba(217,119,6,.7)';if(p>=60)return'rgba(234,88,12,.7)';return'rgba(220,38,38,.7)';};
  var labels=MONTHS.map(function(m){return moTh[m]||m;});
  var mA=MONTHS.map(function(mo){return(sm[mo]||0)/1e6;});
  var mT=MONTHS.map(function(mo){return(st[mo]||0)/1e6;});
  var mC=MONTHS.map(function(mo){var v=sm[mo]||0,t=st[mo]||0;return colorFn(t?(v/t*100):0);});
  mkChart('pdPerfChart',{type:'bar',data:{labels:labels,datasets:[
    {label:'เป้าหมาย',data:mT,backgroundColor:'rgba(79,70,229,.12)',borderColor:'#4f46e5',borderWidth:1.5,borderRadius:5},
    {label:'ยอดจริง',data:mA,backgroundColor:mC,borderColor:mC.map(function(c){return c.replace(/[\d.]+\)$/,'1)');}),borderWidth:1.5,borderRadius:5}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{font:{size:11}}},tooltip:{callbacks:{label:function(c){return ' '+c.dataset.label+': '+(c.raw).toFixed(2)+' M';}}}},scales:{y:{ticks:{callback:function(v){return v+'M';},font:{size:11}},grid:{color:'#f1f5f9'}},x:{ticks:{font:{size:11}},grid:{display:false}}}}});
}

// ============================================================
// PERSON DETAIL
// ============================================================
function renderPersonDetail(name){
  const m=_salesMonth;
  const info=PERSON_CUST_MAP[name];
  var _savedMonth2=currentMonth;currentMonth=m;
  var mos=_resolveMonths();
  var dispAct=0,dispTgt=0;
  mos.forEach(function(mo){dispAct+=(SALES_MONTHLY[name][mo]||0);dispTgt+=((SALES_MTH_TARGET[name]&&SALES_MTH_TARGET[name][mo])||0);});
  const diff=dispAct-dispTgt,pct=dispTgt?dispAct/dispTgt*100:0;

  // Header
  document.getElementById('pdName').textContent=name;
  document.getElementById('pdZone').textContent=SALES_MONTHLY[name].zone+(m!=='YTD'?' · '+MONTH_LABELS[m]:'  · YTD ม.ค.–มิ.ย.');
  document.getElementById('pdTarget').textContent=fmtM(dispTgt);
  document.getElementById('pdActual').textContent=fmtM(dispAct);
  const dEl=document.getElementById('pdDiff');
  dEl.textContent=(diff>=0?'+':'')+fmtM(diff);
  dEl.className='ph-stat-val '+(diff>=0?'pos':'neg');
  const pEl=document.getElementById('pdPct');
  pEl.textContent=pct.toFixed(1)+'%';
  pEl.className='ph-stat-val '+(pct>=80?'pos':pct>=60?'warn':'neg');

  // Person performance section (card + chart + verdict + monthly table)
  _buildPersonPerfSection(name);
  setTimeout(function(){_renderPersonPerfChart(name);},50);

  // Note if no customer breakdown
  const noteEl=document.getElementById('pdNote');
  if(noteEl)noteEl.remove();
  if(info.note){
    const nb=document.createElement('div');nb.id='pdNote';
    nb.className='note-box mb';
    nb.innerHTML=`<div class="note-title">ℹ️ หมายเหตุ</div><p>${info.note}</p>`;
    document.getElementById('personDetail').insertBefore(nb,document.getElementById('personDetail').children[1]);
  }

  // If no customer breakdown
  if(!info.src||info.keys.length===0){
    // Just show monthly trend
    document.querySelector('#personDetail .row.cols2').style.display='none';
    document.getElementById('pdSummaryTitle').closest('.card').style.display='none';
    renderMonthlyTrendOnly(name);
    document.getElementById('pdMiniGrid').innerHTML='<div style="color:var(--muted);font-size:13px;padding:10px">ไม่มีข้อมูลแยกตามลูกค้าสำหรับช่องทางนี้</div>';
    renderPersonMthTable(name,[]);
    currentMonth=_savedMonth2;
    return;
  }
  document.querySelector('#personDetail .row.cols2').style.display='';
  document.getElementById('pdSummaryTitle').closest('.card').style.display='';

  const keys=info.keys;
  const custData=getMonthData(info.src,m);
  const totalA=keys.reduce((s,k)=>s+(custData[k]?.a||0),0);

  // Update titles
  document.getElementById('pdPieTitle').textContent=(m==='YTD'?'YTD':'เดือน '+MONTHS_TH[MONTHS.indexOf(m)])+' — สัดส่วน Actual ตามลูกค้า';
  document.getElementById('pdBarTitle').textContent=(m==='YTD'?'YTD':'เดือน '+MONTHS_TH[MONTHS.indexOf(m)])+' — Budget vs Actual ตามลูกค้า';

  // Pie
  mkChart('pdPie',{type:'doughnut',data:{labels:keys,datasets:[{data:keys.map(k=>custData[k]?.a||0),backgroundColor:CUST_PALETTE,borderColor:'#fff',borderWidth:3}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'60%',plugins:{legend:{position:'right',labels:{font:{size:11}}},tooltip:{callbacks:{label:c=>` ${c.label}: ${fmtM(c.raw)} (${totalA?(c.raw/totalA*100).toFixed(1):'0'}%)`}}}}});

  // Bar budget vs actual
  mkChart('pdBar',{type:'bar',data:{labels:keys,datasets:[
    {label:'Budget',data:keys.map(k=>custData[k]?.t/1e6||0),backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},
    {label:'Actual',data:keys.map(k=>custData[k]?.a/1e6||0),backgroundColor:CUST_PALETTE.map(c=>c+'cc'),borderColor:CUST_PALETTE,borderWidth:2,borderRadius:6},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});

  // Summary table
  document.getElementById('pdSummaryTable').innerHTML=[
    ...keys.map(k=>{
      const t=custData[k]?.t||0,a=custData[k]?.a||0,diff=a-t,ach=t?a/t*100:0,contrib=totalA?a/totalA*100:0;
      return`<tr><td><strong>${k}</strong></td><td style="text-align:right">${fmt(t)}</td><td style="text-align:right">${fmt(a)}</td><td style="text-align:right;color:${diff>=0?'#16a34a':'#dc2626'}">${diff>=0?'+':''}${fmt(diff)}</td><td style="text-align:right"><span class="pill ${achCls(ach)}">${ach.toFixed(1)}%</span></td><td style="text-align:right"><span class="pill blue">${contrib.toFixed(1)}%</span></td><td>${progFill(ach)}</td></tr>`;
    }),
    `<tr class="tr-total"><td>รวม</td><td style="text-align:right">${fmt(keys.reduce((s,k)=>s+(custData[k]?.t||0),0))}</td><td style="text-align:right">${fmt(totalA)}</td><td></td><td></td><td></td><td></td></tr>`,
  ].join('');

  // Trend line (all 6 months per customer)
  mkChart('pdTrend',{type:'line',data:{labels:MONTHS_TH,datasets:keys.map((k,i)=>({
    label:k,data:MONTHS.map(mo=>info.src[mo][k]?.a/1e6||0),
    borderColor:CUST_PALETTE[i],backgroundColor:CUST_PALETTE[i]+'22',fill:false,tension:.4,borderWidth:2,pointRadius:5,pointBackgroundColor:CUST_PALETTE[i]
  }))},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});

  // Mini charts grid (one per month — Budget vs Actual per customer)
  renderMiniCharts(name,keys,info.src);

  // Monthly breakdown table
  renderPersonMthTable(name,keys,info.src);
  currentMonth=_savedMonth2;
}

function renderMonthlyTrendOnly(name){
  const acts=MONTHS.map(mo=>SALES_MONTHLY[name][mo]/1e6);
  const tgts=MONTHS.map(mo=>SALES_MTH_TARGET[name][mo]/1e6);
  mkChart('pdTrend',{type:'bar',data:{labels:MONTHS_TH,datasets:[
    {label:'Target',data:tgts,backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},
    {label:'Actual',data:acts,backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:6},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
  // Pie / bar: just target vs actual for available months
  const dispActs=MONTHS.map(mo=>SALES_MONTHLY[name][mo]);
  mkChart('pdPie',{type:'doughnut',data:{labels:MONTHS_TH,datasets:[{data:dispActs,backgroundColor:COLORS12,borderColor:'#fff',borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'60%',plugins:{legend:{position:'right'}}}});
  mkChart('pdBar',{type:'bar',data:{labels:MONTHS_TH,datasets:[
    {label:'Target',data:tgts,backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:5},
    {label:'Actual',data:acts,backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:5},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
}

function renderMiniCharts(name,keys,src){
  const grid=document.getElementById('pdMiniGrid');
  grid.innerHTML=MONTHS.map((mo,idx)=>`
    <div class="mini-card">
      <div class="mini-card-title">${MONTHS_TH[idx]}</div>
      <div class="mini-chart-wrap"><canvas id="mc_${mo}"></canvas></div>
    </div>`).join('');
  // Short labels for display
  const shortKeys=keys.map(k=>k.length>8?k.substring(0,7)+'…':k);
  MONTHS.forEach(mo=>{
    mkChart('mc_'+mo,{type:'bar',data:{labels:shortKeys,datasets:[
      {label:'Budget',data:keys.map(k=>src[mo][k]?.t/1e6||0),backgroundColor:'rgba(79,70,229,.25)',borderColor:'#4f46e5',borderWidth:1.5,borderRadius:3},
      {label:'Actual',data:keys.map(k=>src[mo][k]?.a/1e6||0),backgroundColor:CUST_PALETTE.map(c=>c+'cc'),borderColor:CUST_PALETTE,borderWidth:1.5,borderRadius:3},
    ]},options:{responsive:true,maintainAspectRatio:false,animation:{duration:300},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>` ${c.dataset.label}: ${c.parsed.y.toFixed(2)}M`}}},
      scales:{x:{ticks:{font:{size:8}},grid:{display:false}},y:{ticks:{font:{size:8},callback:v=>v+'M'},grid:{color:'#f1f5f9'}}}}});
  });
}

function renderPersonMthTable(name,keys,src){
  const head=document.getElementById('pdMthHead');
  const body=document.getElementById('pdMthBody');
  head.innerHTML='<th>ลูกค้า / Metric</th>'+MONTHS_TH.map((m,i)=>`<th style="text-align:right">${m}</th>`).join('')+'<th style="text-align:right">YTD</th><th>Performance</th>';
  if(!keys||keys.length===0){
    body.innerHTML=`<tr><td colspan="${MONTHS.length+2}" style="color:var(--muted);text-align:center">ไม่มีข้อมูลแยกตามลูกค้า</td></tr>`;return;
  }
  body.innerHTML=[
    ...keys.map(k=>{
      const ytd=MONTHS.reduce((s,mo)=>(src[mo][k]?.a||0)+s,0);
      const pmv=MONTHS.map(mo=>src[mo][k]?.a||0);
      const pPerf=window.calcPerf(pmv);
      return`<tr><td><strong>${k}</strong></td>${MONTHS.map(mo=>`<td style="text-align:right">${fmt(src[mo][k]?.a||0)}</td>`).join('')}<td style="text-align:right;font-weight:700;color:#4f46e5">${fmt(ytd)}</td><td style="text-align:center">${window.perfBadgeHTML(pPerf)}</td></tr>
             <tr style="background:#f8fafc"><td style="color:#94a3b8;font-size:11px;padding:4px 14px">└ Budget</td>${MONTHS.map(mo=>`<td style="text-align:right;color:#94a3b8;font-size:11px;padding:4px 14px">${fmt(src[mo][k]?.t||0)}</td>`).join('')}<td style="text-align:right;color:#94a3b8;font-size:11px;padding:4px 14px">${fmt(MONTHS.reduce((s,mo)=>(src[mo][k]?.t||0)+s,0))}</td><td></td></tr>`;
    }),
    `<tr class="tr-total"><td>รวม Actual</td>${MONTHS.map(mo=>`<td style="text-align:right">${fmt(keys.reduce((s,k)=>s+(src[mo][k]?.a||0),0))}</td>`).join('')}<td style="text-align:right">${fmt(keys.reduce((s,k)=>s+MONTHS.reduce((ss,mo)=>ss+(src[mo][k]?.a||0),0),0))}</td><td></td></tr>`,
  ].join('');
}

