function initStore(){
  document.getElementById('storeKpi').innerHTML=`
    <div class="kpi-card blue"><div class="kpi-label">Target สาขาใหม่</div><div class="kpi-value">600</div><div class="kpi-sub">Amazon OR (ตัวอย่าง)</div></div>
    <div class="kpi-card cyan"><div class="kpi-label">ยอดจริงสาขาใหม่</div><div class="kpi-value">101</div><div class="kpi-badge neg">16.8% สำเร็จ</div></div>
    <div class="kpi-card red"><div class="kpi-label">Diff</div><div class="kpi-value">-499</div><div class="kpi-sub">ขาดเป้า 499 สาขา</div></div>
    <div class="kpi-card green"><div class="kpi-label">กรอกข้อมูลอื่นด้านล่าง</div><div class="kpi-value">—</div></div>`;
  document.getElementById('storeBody').innerHTML=storeList.map((s,i)=>
    `<tr><td><strong>${s.name}</strong></td>
    <td style="text-align:center"><input class="store-input" id="st_${i}" type="number" value="${s.targetNew}" min="0"></td>
    <td style="text-align:center"><input class="store-input" id="sa_${i}" type="number" value="${s.actualNew}" min="0"></td>
    <td style="text-align:center"><input class="store-input" id="sl_${i}" type="number" value="${s.lost}" min="0"></td>
    <td id="sd_${i}" style="text-align:right;color:#94a3b8">—</td>
    <td id="sp_${i}" style="text-align:right">—</td>
    <td id="sn_${i}" style="text-align:right;color:#94a3b8">—</td></tr>`).join('');
  calcStore();
}
function calcStore(){
  const vals=storeList.map((s,i)=>({name:s.name,t:+document.getElementById(`st_${i}`)?.value||0,a:+document.getElementById(`sa_${i}`)?.value||0,l:+document.getElementById(`sl_${i}`)?.value||0}));
  vals.forEach((v,i)=>{
    const diff=v.a-v.t,pct=v.t?(diff/v.t*100).toFixed(1)+'%':'—',net=v.a-v.l;
    const d=document.getElementById(`sd_${i}`),p=document.getElementById(`sp_${i}`),n=document.getElementById(`sn_${i}`);
    if(d)d.innerHTML=`<span style="color:${diff>=0?'#16a34a':'#dc2626'}">${diff>=0?'+':''}${diff}</span>`;
    if(p)p.innerHTML=v.t?`<span class="pill ${diff>=0?'green':'red'}">${pct}</span>`:'—';
    if(n)n.innerHTML=`<span style="color:${net>=0?'#16a34a':'#dc2626'}">${net>=0?'+':''}${net}</span>`;
  });
  mkChart('newStoreBar',{type:'bar',data:{labels:vals.map(v=>v.name),datasets:[
    {label:'Target',data:vals.map(v=>v.t),backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:5},
    {label:'Actual',data:vals.map(v=>v.a),backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:5},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{grid:{color:'#f1f5f9'}}}}});
  mkChart('netStoreBar',{type:'bar',data:{labels:vals.map(v=>v.name),datasets:[
    {label:'New',data:vals.map(v=>v.a),backgroundColor:'rgba(22,163,74,.6)',borderColor:'#16a34a',borderWidth:2,borderRadius:5},
    {label:'Lost',data:vals.map(v=>-v.l),backgroundColor:'rgba(220,38,38,.6)',borderColor:'#dc2626',borderWidth:2,borderRadius:5},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:v=>Math.abs(v)},grid:{color:'#f1f5f9'}}}}});
}

