let _prodTab = 'overview';
var _dailyCh='all';
let _prodItems = [];

// ── Product Admin ↔ Display Sync ──
var _PROD_CHANNELS = ['CJ','Big C','Makro','Top','Aeon','The Mall','Amazon','Black Canyon','Online'];

function _persistProducts(){
  var slim = {};
  _PROD_CHANNELS.forEach(function(ch){
    if(!PRODUCTS[ch]) return;
    slim[ch] = PRODUCTS[ch].map(function(p){
      var o = {};
      for(var k in p){ if(k !== 'img') o[k] = p[k]; }
      return o;
    });
  });
  _lsSet('spbiProducts', slim);
}

function _restoreProducts(){
  var saved = _lsGetJSON('spbiProducts', null);
  if(!saved) return;
  _PROD_CHANNELS.forEach(function(ch){
    if(!saved[ch]) return;
    var savedMap = {};
    saved[ch].forEach(function(p){ savedMap[p.code] = p; });
    var existing = PRODUCTS[ch] || [];
    var existMap = {};
    existing.forEach(function(p){ existMap[p.code] = true; });
    saved[ch].forEach(function(p){
      if(!existMap[p.code]){
        existing.push(p);
      } else {
        for(var i=0;i<existing.length;i++){
          if(existing[i].code === p.code){
            var img = existing[i].img;
            for(var k in p){ existing[i][k] = p[k]; }
            if(img) existing[i].img = img;
            break;
          }
        }
      }
    });
    var savedCodes = {};
    saved[ch].forEach(function(p){ savedCodes[p.code] = true; });
    PRODUCTS[ch] = existing.filter(function(p){ return savedCodes[p.code]; });
  });
}

function _countProducts(){
  var active=0, npd=0, disc=0;
  _PROD_CHANNELS.forEach(function(ch){
    (PRODUCTS[ch]||[]).forEach(function(p){
      if(p.status==='discontinued') disc++;
      else { active++; if(p.newMonth) npd++; }
    });
  });
  return {active:active, npd:npd, disc:disc};
}

function _syncProdDisplay(){
  var counts = _countProducts();
  var kpiEl = document.getElementById('prodKPI');
  if(kpiEl){
    var nums = kpiEl.querySelectorAll('[data-prod-kpi]');
    nums.forEach(function(el){
      var k = el.getAttribute('data-prod-kpi');
      if(k==='active') el.textContent = counts.active;
      else if(k==='npd') el.textContent = counts.npd;
      else if(k==='disc') el.textContent = counts.disc;
    });
  }
  if(typeof _prodTab!=='undefined' && _prodTab!=='overview' && _prodTab!=='npd' && _prodTab!=='timeline'){
    renderProdChannel(_prodTab);
  }
}

_restoreProducts();
let _prodCh = '';

// --- IndexedDB helper for product images (replaces localStorage) ---
const _imgDB = (function(){
  const DB_NAME = 'prodImgDB', STORE = 'images';
  let _db = null;
  function open(){
    if(_db) return Promise.resolve(_db);
    return new Promise((resolve, reject)=>{
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = ()=> req.result.createObjectStore(STORE);
      req.onsuccess = ()=>{ _db = req.result; resolve(_db); };
      req.onerror = ()=> reject(req.error);
    });
  }
  return {
    get(key){ return open().then(db=> new Promise((res,rej)=>{
      const tx=db.transaction(STORE,'readonly');
      const r=tx.objectStore(STORE).get(key);
      r.onsuccess=()=>res(r.result||null); r.onerror=()=>res(null);
    })).catch(()=>null); },
    set(key,val){ return open().then(db=> new Promise((res,rej)=>{
      const tx=db.transaction(STORE,'readwrite');
      tx.objectStore(STORE).put(val,key);
      tx.oncomplete=()=>res(); tx.onerror=()=>rej(tx.error);
    })).catch(()=>{}); },
    del(key){ return open().then(db=> new Promise((res,rej)=>{
      const tx=db.transaction(STORE,'readwrite');
      tx.objectStore(STORE).delete(key);
      tx.oncomplete=()=>res(); tx.onerror=()=>res();
    })).catch(()=>{}); },
    getAll(){ return open().then(db=> new Promise((res,rej)=>{
      const tx=db.transaction(STORE,'readonly');
      const store=tx.objectStore(STORE);
      const keys=[],vals=[];
      const cur=store.openCursor();
      cur.onsuccess=()=>{
        const c=cur.result;
        if(c){keys.push(c.key);vals.push(c.value);c.continue();}
        else res(keys.map((k,i)=>({key:k,value:vals[i]})));
      };
      cur.onerror=()=>res([]);
    })).catch(()=>[]); }
  };
})();

function _uploadImgToServer(code, dataUrl){
  return fetch('/api/catalog/upload',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({code:code, dataUrl:dataUrl})
  }).then(function(r){return r.json();})
    .then(function(j){
      if(j.ok) return j.img;
      console.error('[ImgUpload]',j.error); return null;
    }).catch(function(e){ console.error('[ImgUpload]',e); return null; });
}
function _deleteImgFromServer(code){
  return fetch('/api/catalog/delete-image',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({code:code})
  }).then(function(r){return r.json();}).catch(function(){return{ok:false};});
}

async function restoreProductImages(){
  try {
    var lsKeys = [];
    for(var i=0;i<localStorage.length;i++){
      var k=localStorage.key(i);
      if(k&&k.startsWith('prodImg_')) lsKeys.push(k);
    }
    if(lsKeys.length){
      for(var ki=0;ki<lsKeys.length;ki++){
        var val=localStorage.getItem(lsKeys[ki]);
        if(val) await _imgDB.set(lsKeys[ki], val);
        localStorage.removeItem(lsKeys[ki]);
      }
    }
    var all = await _imgDB.getAll();
    for(var ai=0;ai<all.length;ai++){
      var entry=all[ai];
      if(!entry.key.startsWith('prodImg_')) continue;
      var rest = entry.key.slice(8);
      for(var ch of Object.keys(PRODUCTS)){
        if(rest.startsWith(ch+'_')){
          var code = rest.slice(ch.length+1);
          var prod = (PRODUCTS[ch]||[]).find(function(p){return p.code===code;});
          if(prod && !prod.img) prod.img = entry.value;
          break;
        }
      }
    }
  } catch(e){}
  try {
    var ovRes = await fetch('/api/catalog/overrides');
    var ov = await ovRes.json();
    var serverImgs = (ov && ov.images) ? ov.images : {};
    if(Object.keys(serverImgs).length){
      Object.keys(serverImgs).forEach(function(code){
        var imgPath = serverImgs[code];
        Object.keys(PRODUCTS).forEach(function(ch){
          (PRODUCTS[ch]||[]).forEach(function(p){
            if(p.code===code) p.img = imgPath;
          });
        });
      });
    }
    var allIdb = await _imgDB.getAll();
    var migrated = 0;
    for(var mi=0;mi<allIdb.length;mi++){
      var ent=allIdb[mi];
      if(!ent.key.startsWith('prodImg_')||!ent.value) continue;
      if(!ent.value.startsWith('data:')) continue;
      var codeFromKey='';
      var restKey=ent.key.slice(8);
      for(var chk of Object.keys(PRODUCTS)){
        if(restKey.startsWith(chk+'_')){ codeFromKey=restKey.slice(chk.length+1); break; }
      }
      if(!codeFromKey||serverImgs[codeFromKey]) continue;
      var url=await _uploadImgToServer(codeFromKey,ent.value);
      if(url){
        migrated++;
        Object.keys(PRODUCTS).forEach(function(ch){
          (PRODUCTS[ch]||[]).forEach(function(p){if(p.code===codeFromKey) p.img=url;});
        });
      }
    }
    if(migrated) console.log('[ImgMigrate] uploaded',migrated,'images to server');
  } catch(e){ console.error('[ImgRestore]',e); }
}
restoreProductImages();

function restoreRegNums(){
  Object.keys(PRODUCTS).forEach(ch=>{
    (PRODUCTS[ch]||[]).forEach(p=>{
      const fda = localStorage.getItem('prodFda_'+ch+'_'+p.code);
      const halal = localStorage.getItem('prodHalal_'+ch+'_'+p.code);
      if(fda)   p.fda   = fda;
      if(halal) p.halal = halal;
    });
  });
}
restoreRegNums();


// ---- Save product images permanently into the HTML file ----
let _fileHandle = null;

async function saveImagesToFile(silent){
  try {
    if(!_fileHandle||!('createWritable' in _fileHandle)){
      try{ [_fileHandle]=await window.showOpenFilePicker({types:[{description:'HTML',accept:{'text/html':['.html']}}],multiple:false}); }
      catch(e){ if(!silent) showImgChangeToast(); return; }
    }
    const file = await _fileHandle.getFile();
    let html = await file.text();
    const newProducts = {};
    for(const ch of Object.keys(PRODUCTS)){
      newProducts[ch] = [];
      for(const p of (PRODUCTS[ch]||[])){
        const obj = Object.assign({}, p);
        const imgData = await _imgDB.get('prodImg_'+ch+'_'+p.code);
        if(imgData) obj.img = imgData;
        newProducts[ch].push(obj);
      }
    }
    const newBlock = 'const PRODUCTS = ' + JSON.stringify(newProducts) + ';';
    const replaced = html.replace(/const PRODUCTS = \{[\s\S]*?\};/, newBlock);
    if(replaced === html){ alert('ไม่พบ PRODUCTS block'); return; }
    const writable = await _fileHandle.createWritable();
    await writable.write(replaced);
    await writable.close();
    restoreProductImages();
    showImgChangeToast('💾 บันทึกลงไฟล์แล้ว!');
  } catch(err){ console.error(err); if(!silent) alert('เกิดข้อผิดพลาด: '+err.message); }
}

