function selectProdTab(ch){
  _prodTab = ch;
  document.querySelectorAll('.ch-tab-btn').forEach(b=>{
    const bch = b.dataset.ch;
    const color = PROD_CH_COLORS[bch]||'#64748b';
    const grad  = PROD_CH_GRAD[bch];
    if(bch===ch){
      if(grad){ b.style.background=grad; b.style.color='#fff'; b.style.borderColor='transparent'; }
      else     { b.style.background=color; b.style.color='#fff'; b.style.borderColor=color; }
      b.style.boxShadow = '0 4px 14px '+color+'55';
      b.style.transform = 'translateY(-1px)';
    } else {
      b.style.background='white'; b.style.color=color;
      b.style.borderColor=color+'33'; b.style.boxShadow='none'; b.style.transform='none';
    }
  });
  const isChannel = ch!=='overview' && ch!=='npd' && ch!=='timeline';
  document.getElementById('prodFilterBar').style.display = isChannel ? 'block' : 'none';
  if(ch==='overview')      renderProdOverview();
  else if(ch==='npd')      renderProdNPD();
  else if(ch==='timeline') { if(typeof renderProdTimeline==='function') renderProdTimeline(); }
  else                     renderProdChannel(ch);
}

// Map English month code → 0-based index
const MONTH_IDX = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};

function renderProdOverview(){
  var chStats = _PROD_CHANNELS.map(function(ch){
    var items = PRODUCTS[ch]||[];
    var active = items.filter(function(p){ return p.status!=='discontinued'; }).length;
    var npd = items.filter(function(p){ return p.status!=='discontinued' && p.newMonth; }).length;
    var disc = items.filter(function(p){ return p.status==='discontinued'; }).length;
    return {ch:ch, active:active, npd:npd, disc:disc};
  });
  var totActive=0, totNpd=0, totDisc=0;
  chStats.forEach(function(s){ totActive+=s.active; totNpd+=s.npd; totDisc+=s.disc; });

  var mkSimpleTable = function(title, accentColor, colLabel, valFn, totalVal){
    var trows = chStats.map(function(s,i){
      var grad = PROD_CH_GRAD[s.ch]||PROD_CH_COLORS[s.ch]||'#4f46e5';
      var v = valFn(s);
      return '<tr><td style="color:#94a3b8;width:28px">'+(i+1)+'</td>' +
        '<td><span style="font-weight:700;padding:2px 9px;border-radius:12px;font-size:12px;color:#fff;background:'+grad+'">'+s.ch+'</span></td>' +
        '<td style="text-align:center;font-weight:700;color:'+accentColor+'">'+v+'</td></tr>';
    }).join('');
    return '<div class="card" style="overflow-x:auto"><div class="card-title">'+title+'</div>' +
      '<table><thead><tr><th>#</th><th>ช่องทาง</th><th style="text-align:center;background:#eff6ff">'+colLabel+'</th></tr></thead>' +
      '<tbody>'+trows+'<tr style="font-weight:700;background:#eff6ff"><td colspan="2">รวม</td>' +
      '<td style="text-align:center;color:'+accentColor+'">'+totalVal+'</td></tr></tbody></table></div>';
  };

  document.getElementById('prodContent').innerHTML =
    '<div class="row cols3" style="align-items:flex-start;margin-bottom:16px">' +
       mkSimpleTable('📦 สินค้าปัจจุบัน','#4f46e5','ปัจจุบัน',function(s){return s.active;},totActive) +
       mkSimpleTable('🆕 สินค้าใหม่ (NPD)','#16a34a','NPD',function(s){return s.npd;},totNpd) +
       mkSimpleTable('❌ สินค้ายกเลิก','#dc2626','ยกเลิก',function(s){return s.disc;},totDisc) +
    '</div>' +
    '<div class="card mb">' +
      '<div class="card-title">📊 เปรียบเทียบสินค้าแต่ละช่องทาง (ปัจจุบัน / NPD / ยกเลิก)</div>' +
      '<div style="height:260px"><canvas id="prodOvChart"></canvas></div>' +
    '</div>';

  setTimeout(()=>{
    const ctx = document.getElementById('prodOvChart');
    if(!ctx) return;
    if(ctx._ci) ctx._ci.destroy();
    ctx._ci = new Chart(ctx, {
      type:'bar',
      data:{
        labels: chStats.map(function(s){return s.ch;}),
        datasets:[
          {label:'สินค้าปัจจุบัน',
            data: chStats.map(function(s){return s.active;}),
            backgroundColor:'rgba(79,70,229,0.75)', borderColor:'#4f46e5', borderWidth:1, borderRadius:4},
          {label:'สินค้าใหม่ (NPD)',
            data: chStats.map(function(s){return s.npd;}),
            backgroundColor:'rgba(22,163,74,0.75)', borderColor:'#16a34a', borderWidth:1, borderRadius:4},
          {label:'สินค้ายกเลิก',
            data: chStats.map(function(s){return s.disc;}),
            backgroundColor:'rgba(220,38,38,0.75)', borderColor:'#dc2626', borderWidth:1, borderRadius:4},
        ]
      },
      options:{
        responsive:true, maintainAspectRatio:false,
        plugins:{
          legend:{position:'top'},
          tooltip:{callbacks:{label:ctx=>`${ctx.dataset.label}: ${ctx.parsed.y} SKUs`}}
        },
        scales:{
          x:{grid:{display:false}},
          y:{beginAtZero:true, ticks:{stepSize:10},
             title:{display:true,text:'จำนวน SKUs',font:{size:11}}}
        }
      }
    });
  }, 50);
}

let _npdActiveCh = 'All';

function renderProdNPD(){
  const mIdx = (currentMonth==='YTD') ? -1 : (MONTH_IDX[currentMonth]??-1);
  const mLabel = mIdx>=0 ? MONTHS_TH[mIdx] : 'ทั้งปี (YTD)';
  const allChannels = [...new Set(PROD_NPD.map(r=>r.ch).filter(c=>c && c!=='ช่องทาง'))];

  // Channel filter dropdown
  const chOptions = ['All',...allChannels].map(ch=>
    `<option value="${ch}" ${_npdActiveCh===ch?'selected':''}>${ch==='All'?'ทั้งหมด':ch}</option>`
  ).join('');
  const chBtns = `<select id="npdChSelect" onchange="setNPDCh(this.value)"
    style="padding:6px 36px 6px 14px;border-radius:20px;border:1.5px solid var(--accent);
           font-size:13px;font-weight:700;color:var(--accent);background:var(--bg);
           cursor:pointer;outline:none;appearance:none;
           background-image:url('data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 10 6\'><path fill=\'%23ea580c\' d=\'M0 0l5 6 5-6z\'/></svg>');
           background-repeat:no-repeat;background-position:right 12px center;background-size:10px">
    ${chOptions}
  </select>`;

  const channels = _npdActiveCh==='All' ? allChannels : allChannels.filter(c=>c===_npdActiveCh);

  // Summary KPI row
  const totTarget = PROD_NPD.reduce((s,r)=>{
    const m=mIdx>=0?r.monthly[mIdx]:null; return s+(m?m.t:r.tot_t)||0;},0);
  const totActual = PROD_NPD.reduce((s,r)=>{
    const m=mIdx>=0?r.monthly[mIdx]:null; return s+(m?m.a:r.tot_a)||0;},0);
  const totDiff = totActual - totTarget;
  const ach = totTarget>0?(totActual/totTarget*100):0;
  const achColor = ach>=80?'#16a34a':ach>=50?'#d97706':'#dc2626';

  const kpiHtml = `
    <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px">
      <div class="kpi-card blue" style="flex:1;min-width:140px;padding:12px 16px">
        <div class="kpi-label">🎯 Target รวม</div>
        <div class="kpi-value sm" style="font-size:24px">${totTarget}</div>
        <div class="kpi-sub">NPD ทั้งหมด</div>
      </div>
      <div class="kpi-card green" style="flex:1;min-width:140px;padding:12px 16px">
        <div class="kpi-label">✅ ยอดจริงรวม</div>
        <div class="kpi-value sm" style="font-size:24px;color:#16a34a">${totActual}</div>
        <div class="kpi-sub">${mLabel}</div>
      </div>
      <div class="kpi-card ${totDiff>=0?'cyan':'red'}" style="flex:1;min-width:140px;padding:12px 16px">
        <div class="kpi-label">📊 Diff</div>
        <div class="kpi-value sm" style="font-size:24px;color:${totDiff>=0?'#0891b2':'#dc2626'}">${totDiff>=0?'+':''}${totDiff}</div>
        <div class="kpi-sub">เทียบเป้า</div>
      </div>
      <div class="kpi-card yellow" style="flex:1;min-width:140px;padding:12px 16px">
        <div class="kpi-label">📈 Achievement</div>
        <div class="kpi-value sm" style="font-size:24px;color:${achColor}">${ach.toFixed(1)}%</div>
        <div class="kpi-sub">${totTarget>0?'ผ่านเกณฑ์ 80%':'-'}</div>
      </div>
    </div>`;

  // Channel cards
  let cards = '';
  channels.forEach(ch=>{
    const color = PROD_CH_COLORS[ch]||'#4f46e5';
    const grad  = PROD_CH_GRAD[ch]||color;
    const rows  = PROD_NPD.filter(r=>r.ch===ch);
    if(!rows.length) return;

    let chTotT=0, chTotA=0;
    const filteredRows = rows.filter(r=>r.cat && isNaN(r.cat));
    let trows = filteredRows.map(r=>{
      const m = mIdx>=0 ? r.monthly[mIdx] : null;
      const t=m?m.t:r.tot_t, a=m?m.a:r.tot_a, d=m?m.d:r.tot_d;
      const dc = (d||0)>=0 ? '#16a34a' : '#dc2626';
      const ach2 = (t||0)>0?((a||0)/(t||1)*100):0;
      chTotT+=(t||0); chTotA+=(a||0);
      const bar = `<div style="background:#e2e8f0;border-radius:4px;height:6px;width:80px;display:inline-block;vertical-align:middle;margin-right:6px">
        <div style="background:${ach2>=80?'#16a34a':ach2>=50?'#d97706':'#dc2626'};height:6px;border-radius:4px;width:${Math.min(ach2,100)}%"></div></div>`;
      return `<tr>
        <td style="font-weight:600">${r.cat||'—'}</td>
        <td style="text-align:center;font-weight:500">${t||0}</td>
        <td style="text-align:center;font-weight:700">${a||0}</td>
        <td style="text-align:center;color:${dc};font-weight:700">${(d||0)>=0?'+':''}${d||0}</td>
        <td style="text-align:center">${bar}<span style="font-size:11px;color:${dc}">${ach2.toFixed(0)}%</span></td>
      </tr>`;
    }).join('');
    const chDiff=chTotA-chTotT;
    const chAch=chTotT>0?(chTotA/chTotT*100):0;
    const chAchColor=chAch>=80?'#16a34a':chAch>=50?'#d97706':'#dc2626';

    cards += `<div class="card mb" style="overflow:hidden;border:1.5px solid ${color}22">
      <div style="background:${grad};padding:12px 18px;display:flex;align-items:center;justify-content:space-between">
        <div style="color:#fff;font-weight:800;font-size:15px">🆕 ${ch}</div>
        <div style="display:flex;gap:16px">
          <div style="text-align:center">
            <div style="color:rgba(255,255,255,.7);font-size:10px">TARGET</div>
            <div style="color:#fff;font-weight:700;font-size:16px">${chTotT}</div>
          </div>
          <div style="text-align:center">
            <div style="color:rgba(255,255,255,.7);font-size:10px">ACTUAL</div>
            <div style="color:#fff;font-weight:700;font-size:16px">${chTotA}</div>
          </div>
          <div style="text-align:center">
            <div style="color:rgba(255,255,255,.7);font-size:10px">ACHIEVE</div>
            <div style="color:#fff;font-weight:700;font-size:16px">${chAch.toFixed(0)}%</div>
          </div>
        </div>
      </div>
      <div style="padding:0 4px">
      <table style="margin:0"><thead><tr>
        <th>หมวดสินค้า</th>
        <th style="text-align:center;width:80px">Target</th>
        <th style="text-align:center;width:80px">Actual</th>
        <th style="text-align:center;width:70px">Diff</th>
        <th style="text-align:center;width:130px">Progress</th>
      </tr></thead><tbody>${trows}</tbody>
      <tfoot><tr style="background:#f8fafc;font-weight:700">
        <td>รวม</td>
        <td style="text-align:center">${chTotT}</td>
        <td style="text-align:center">${chTotA}</td>
        <td style="text-align:center;color:${chAchColor}">${chDiff>=0?'+':''}${chDiff}</td>
        <td style="text-align:center;color:${chAchColor}">${chAch.toFixed(1)}%</td>
      </tr></tfoot>
      </table>
      </div>
    </div>`;
  });

  document.getElementById('prodContent').innerHTML =
    `<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">
       <span style="font-size:12px;font-weight:700;color:var(--text2)">ช่องทาง:</span>
       ${chBtns}
       <div style="margin-left:auto;font-size:12px;color:var(--muted)">📅 ${mLabel}</div>
     </div>
     ${kpiHtml}${cards}`;
}

function setNPDCh(ch){
  _npdActiveCh = ch;
  renderProdNPD();
}

function renderProdChannel(ch){
  document.getElementById('prodSearch').value='';
  document.getElementById('prodTypeFilter').value='';
  document.getElementById('prodStatusFilter').value='';
  _prodCh = ch;
  _prodItems = (PRODUCTS[ch]||[]).slice().sort(function(a,b){
    var sa = a.status==='discontinued'?1:0, sb = b.status==='discontinued'?1:0;
    return sa - sb;
  });
  _renderProdCards('','','');
}

function filterProdCards(){
  const q = (document.getElementById('prodSearch').value||'').toLowerCase();
  const t = document.getElementById('prodTypeFilter').value||'';
  const st = document.getElementById('prodStatusFilter').value||'';
  _renderProdCards(q,t,st);
}

function _renderProdCards(query, typeFilter, statusFilter){
  const ch = _prodCh;
  const color = PROD_CH_COLORS[ch]||'#4f46e5';
  const grad  = PROD_CH_GRAD[ch]||color;
  const isOnline = ch==='Online';

  let items = _prodItems.filter(p=>{
    if(typeFilter && p.type!==typeFilter) return false;
    if(statusFilter==='new' && !p.newMonth) return false;
    if(statusFilter==='active' && (p.status!=='active')) return false;
    if(statusFilter==='discontinued' && p.status!=='discontinued') return false;
    if(query){ const s=(p.name+' '+p.code+' '+(p.barcode||'')).toLowerCase(); if(!s.includes(query)) return false; }
    return true;
  });

  document.getElementById('prodCardCount').textContent =
    'แสดง '+items.length+' / '+_prodItems.length+' รายการ';

  if(!items.length){
    document.getElementById('prodContent').innerHTML =
      '<div style="text-align:center;color:#94a3b8;padding:60px;font-size:14px">ไม่พบสินค้า</div>';
    return;
  }

  const _cardPastel = [
    {bg:'linear-gradient(135deg,#fef7ed,#fef3c7)',border:'#f59e0b22',accent:'#92400e'},
    {bg:'linear-gradient(135deg,#f0f9ff,#e0f2fe)',border:'#0ea5e922',accent:'#0369a1'},
    {bg:'linear-gradient(135deg,#fdf2f8,#fce7f3)',border:'#ec489922',accent:'#9d174d'},
    {bg:'linear-gradient(135deg,#f0fdf4,#d1fae5)',border:'#10b98122',accent:'#065f46'},
    {bg:'linear-gradient(135deg,#faf5ff,#ede9fe)',border:'#8b5cf622',accent:'#5b21b6'},
    {bg:'linear-gradient(135deg,#fff7ed,#ffedd5)',border:'#f9731622',accent:'#9a3412'},
    {bg:'linear-gradient(135deg,#f0fdfa,#ccfbf1)',border:'#14b8a622',accent:'#115e59'},
    {bg:'linear-gradient(135deg,#fefce8,#fef9c3)',border:'#eab30822',accent:'#713f12'}
  ];
  const cards = items.map((p,i)=>{
    const isDisc = p.status==='discontinued';
    const isNew  = p.newMonth && !isDisc;
    const cp = _cardPastel[i % _cardPastel.length];

    const ribbonColor = isDisc ? 'linear-gradient(135deg,#ef4444,#dc2626)' : isNew ? 'linear-gradient(135deg,#22c55e,#16a34a)' : 'linear-gradient(135deg,#10b981,#059669)';
    const ribbonText  = isDisc ? 'ยกเลิกขาย' : isNew ? '🆕 เข้าใหม่' : '✅ วางจำหน่าย';
    const ribbonHtml  = `<div style="position:absolute;top:14px;right:-20px;background:${ribbonColor};color:#fff;font-size:8px;font-weight:800;padding:3px 24px;transform:rotate(45deg);white-space:nowrap;letter-spacing:.3px;box-shadow:0 2px 6px rgba(0,0,0,.15);text-shadow:0 1px 2px rgba(0,0,0,.2)">${ribbonText}</div>`;

    const rawImg = p.img
      ? `<img src="${p.img}" style="width:100px;height:100px;object-fit:contain;border-radius:12px;filter:drop-shadow(0 3px 8px rgba(0,0,0,.08));background:rgba(255,255,255,.6)">`
      : `<div style="width:100px;height:100px;background:linear-gradient(135deg,rgba(255,255,255,.8),rgba(255,255,255,.4));border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:36px;filter:drop-shadow(0 3px 8px rgba(0,0,0,.06))">🍞</div>`;
    const imgHtml = `<div style="position:relative;overflow:hidden;border-radius:12px;width:100px;height:100px;flex-shrink:0">${rawImg}${ribbonHtml}</div>`;

    const typeIcon = p.type==='Chill'?'❄️':p.type==='Ambient'?'🔥':'';
    const typeColor2 = p.type==='Chill'?'#0891b2':p.type==='Ambient'?'#d97706':'#64748b';
    const typeBg2 = p.type==='Chill'?'linear-gradient(135deg,#e0f7fa,#b2ebf2)':p.type==='Ambient'?'linear-gradient(135deg,#fff8e1,#ffe082)':'linear-gradient(135deg,#f5f5f5,#e0e0e0)';

    const statusBadge = isDisc
      ? `<span style="background:linear-gradient(135deg,#fce4ec,#f8bbd0);color:#c62828;font-size:9px;font-weight:700;padding:3px 10px;border-radius:12px;border:1px solid #c6282820">❌ ยกเลิก${p.discontinuedDate?' '+p.discontinuedDate:''}</span>`
      : isNew
        ? `<span style="background:linear-gradient(135deg,#e8f5e9,#a5d6a7);color:#2e7d32;font-size:9px;font-weight:700;padding:3px 10px;border-radius:12px;border:1px solid #2e7d3220">🆕 ${p.newMonth}</span>`
        : '';

    const cardBg = isDisc ? 'linear-gradient(135deg,#fafafa,#f5f5f5)' : cp.bg;
    const cardBorder2 = isDisc ? '#dc262625' : isNew ? '#16a34a25' : cp.border;
    const cardOpacity = isDisc ? 'opacity:0.75;' : '';

    return `<div onclick="openProdModal(${i})"
      style="background:${cardBg};border:1.5px solid ${cardBorder2};border-radius:18px;overflow:hidden;cursor:pointer;transition:all .2s ease;display:flex;flex-direction:column;${cardOpacity}box-shadow:0 2px 8px rgba(0,0,0,.04)"
      onmouseover="this.style.transform='translateY(-4px) scale(1.02)';this.style.boxShadow='0 12px 32px rgba(0,0,0,.12)'"
      onmouseout="this.style.transform='none';this.style.boxShadow='0 2px 8px rgba(0,0,0,.04)'">
      <div style="background:${isDisc?'linear-gradient(90deg,#ef4444,#f87171)':isNew?'linear-gradient(90deg,#22c55e,#4ade80)':grad};height:4px;border-radius:18px 18px 0 0"></div>
      <div style="padding:14px 12px;display:flex;flex-direction:column;align-items:center;gap:6px;flex:1">
        ${imgHtml}
        <div style="font-size:10px;color:${isDisc?'#94a3b8':cp.accent};font-weight:700;text-align:center;word-break:break-all;letter-spacing:.02em">${p.code||'—'}</div>
        <div style="font-size:13px;font-weight:800;color:${isDisc?'#94a3b8':'#1e293b'};text-align:center;line-height:1.4;min-height:36px">${_stripBrand(p.name)}</div>
        ${statusBadge}
      </div>
    </div>`;
  }).join('');

  document.getElementById('prodContent').innerHTML =
    `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px">${cards}</div>`;
}

let _prodModalIdx = 0;
let _prodModalList = [];

function openProdModal(i){
  _prodModalList = _prodItems;
  _prodModalIdx = i;
  const p = _prodItems[i];
  if(!p) return;
  showProdModal(p, _prodCh);
  updateProdNavBtns();
}

function prodModalPrev(){
  if(_prodModalIdx > 0){ _prodModalIdx--; showProdModal(_prodModalList[_prodModalIdx], _prodCh); updateProdNavBtns(); }
}
function prodModalNext(){
  if(_prodModalIdx < _prodModalList.length-1){ _prodModalIdx++; showProdModal(_prodModalList[_prodModalIdx], _prodCh); updateProdNavBtns(); }
}
function updateProdNavBtns(){
  const prev = document.getElementById('prodNavPrev');
  const next = document.getElementById('prodNavNext');
  const counter = document.getElementById('prodNavCounter');
  if(prev) prev.style.opacity = _prodModalIdx===0 ? '0.3':'1';
  if(next) next.style.opacity = _prodModalIdx===_prodModalList.length-1 ? '0.3':'1';
  if(counter) counter.textContent = (_prodModalIdx+1) + ' / ' + _prodModalList.length;
}
function downloadProdImg(){
  const img = document.getElementById('prodModalImg');
  if(!img || !img.src) return;
  const a = document.createElement('a');
  a.href = img.src;
  const name = (document.getElementById('prodModalName').textContent||'product').replace(/[^a-zA-Z0-9ก-๙]/g,'_');
  a.download = name + '.jpg';
  a.click();
}
function triggerChangeImg(){
  const inp = document.getElementById('changeImgInput');
  if(inp){ inp.value=''; inp.click(); }
}
function handleChangeImg(input){
  const file = input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = function(e){
    const image = new Image();
    image.onload = async function(){
      const MAX=600;
      let w=image.width,h=image.height;
      if(w>MAX||h>MAX){if(w>h){h=Math.round(h*MAX/w);w=MAX;}else{w=Math.round(w*MAX/h);h=MAX;}}
      const canvas=document.createElement('canvas');
      canvas.width=w;canvas.height=h;
      const ctx=canvas.getContext('2d');
      ctx.fillStyle='rgb(254,247,237)';ctx.fillRect(0,0,w,h);
      ctx.drawImage(image,0,0,w,h);
      _removeBg(ctx,w,h);
      const newSrc=canvas.toDataURL('image/jpeg',0.82);
      const p=_prodModalList[_prodModalIdx];
      if(p){
        p.img=newSrc;
        _imgDB.set('prodImg_'+_prodCh+'_'+p.code,newSrc);
        _uploadImgToServer(p.code,newSrc).then(function(url){if(url){p.img=url;var el2=document.getElementById('prodModalImg');if(el2)el2.src=url;}});
      }
      const imgEl=document.getElementById('prodModalImg');
      if(imgEl){imgEl.src=newSrc;imgEl.style.transform='';}
      if(!_fileHandle||!('createWritable' in _fileHandle)){
        showImgChangeToast('📂 กรุณาเลือกไฟล์ spbi.html...');
        try{[_fileHandle]=await window.showOpenFilePicker({types:[{description:'HTML',accept:{'text/html':['.html']}}],multiple:false});}
        catch(e){showImgChangeToast('⚠️ รูปยังไม่ได้บันทึกลงไฟล์');return;}
      }
      await saveImagesToFile(true);
    };
    image.src=e.target.result;
  };
  reader.readAsDataURL(file);
}

function _removeBg(ctx, w, h){
  const imgData = ctx.getImageData(0,0,w,h);
  const d = imgData.data;
  const cr=254, cg=247, cb=237; // cream

  // Sample border pixels to estimate background color
  let sr=0,sg=0,sb=0,n=0;
  const step=Math.max(1,Math.round(Math.min(w,h)/20));
  for(let x=0;x<w;x+=step){ let i=x*4; sr+=d[i];sg+=d[i+1];sb+=d[i+2];n++;
    i=((h-1)*w+x)*4; sr+=d[i];sg+=d[i+1];sb+=d[i+2];n++; }
  for(let y=0;y<h;y+=step){ let i=(y*w)*4; sr+=d[i];sg+=d[i+1];sb+=d[i+2];n++;
    i=(y*w+(w-1))*4; sr+=d[i];sg+=d[i+1];sb+=d[i+2];n++; }
  const bgR=sr/n, bgG=sg/n, bgB=sb/n;
  const TOL=55;

  const mask=new Uint8Array(w*h); // 0=unvisited, 1=bg, 2=fg
  const queue=new Int32Array(w*h);
  let qHead=0, qTail=0;

  function dist(i){ return Math.sqrt((d[i]-bgR)**2+(d[i+1]-bgG)**2+(d[i+2]-bgB)**2); }

  // Seed from all border pixels
  for(let x=0;x<w;x++){
    for(const y of [0,h-1]){
      const p=y*w+x;
      if(!mask[p]&&dist(p*4)<TOL){ mask[p]=1; queue[qTail++]=p; }
    }
  }
  for(let y=1;y<h-1;y++){
    for(const x of [0,w-1]){
      const p=y*w+x;
      if(!mask[p]&&dist(p*4)<TOL){ mask[p]=1; queue[qTail++]=p; }
    }
  }

  // BFS flood fill
  while(qHead<qTail){
    const pos=queue[qHead++];
    const x=pos%w, y=Math.floor(pos/w);
    const nbrs=[pos-1,pos+1,pos-w,pos+w];
    const nok=[x>0,x<w-1,y>0,y<h-1];
    for(let k=0;k<4;k++){
      if(!nok[k]) continue;
      const np=nbrs[k];
      if(mask[np]) continue;
      if(dist(np*4)<TOL){ mask[np]=1; queue[qTail++]=np; }
      else{ mask[np]=2; }
    }
  }

  // Replace background with cream; feather edges
  for(let p=0;p<w*h;p++){
    if(mask[p]===1){
      const i=p*4;
      const t=Math.min(dist(i)/TOL,1);
      d[i]  =Math.round(cr*(1-t)+d[i]*t);
      d[i+1]=Math.round(cg*(1-t)+d[i+1]*t);
      d[i+2]=Math.round(cb*(1-t)+d[i+2]*t);
    }
  }
  ctx.putImageData(imgData,0,0);
}
function rotateProdImg(delta){
  const p = _prodModalList[_prodModalIdx];
  if(!p||!p.img) return;
  const img = new Image();
  img.onload = function(){
    const swap = (delta===90||delta===270);
    const cw = swap ? img.height : img.width;
    const ch = swap ? img.width  : img.height;
    const canvas=document.createElement('canvas');
    canvas.width=cw; canvas.height=ch;
    const ctx=canvas.getContext('2d');
    ctx.fillStyle='rgb(254,247,237)';
    ctx.fillRect(0,0,cw,ch);
    ctx.translate(cw/2, ch/2);
    ctx.rotate(delta*Math.PI/180);
    ctx.drawImage(img, -img.width/2, -img.height/2);
    const newSrc=canvas.toDataURL('image/jpeg',0.82);
    p.img=newSrc;
    _imgDB.set('prodImg_'+_prodCh+'_'+p.code, newSrc);
    _uploadImgToServer(p.code,newSrc).then(function(url){if(url){p.img=url;var el2=document.getElementById('prodModalImg');if(el2)el2.src=url;}});
    const imgEl=document.getElementById('prodModalImg');
    if(imgEl) imgEl.src=newSrc;
    if(_fileHandle) saveImagesToFile(true);
  };
  img.src=p.img;
}

function showImgChangeToast(){
  let t = document.getElementById('imgChangeToast');
  if(!t){
    t = document.createElement('div');
    t.id = 'imgChangeToast';
    t.style.cssText = 'position:fixed;bottom:130px;right:28px;background:#22c55e;color:#fff;padding:10px 18px;border-radius:12px;font-size:13px;font-weight:700;z-index:99999;box-shadow:0 4px 16px rgba(0,0,0,.2);transition:opacity .4s';
    t.textContent = '✓ เปลี่ยนรูปเรียบร้อย';
    document.body.appendChild(t);
  }
  t.style.opacity='1';
  setTimeout(()=>{ t.style.opacity='0'; }, 2500);
}

function _generateProdDesc(p, ch){
  var name = _stripBrand(p.name)||p.name||'';
  var type = p.type||'';
  var weight = p.weight ? p.weight+'g' : '';
  var shelf = p.shelf ? p.shelf+' วัน' : '';
  var gp = p.gp ? Math.round(p.gp*100)+'%' : '';
  var status = p.status==='discontinued' ? 'ยกเลิกขาย' : 'วางจำหน่าย';
  var retail = p.priceRetail ? parseFloat(Number(p.priceRetail).toFixed(2))+' บาท' : '';

  var typeDesc = type==='Chill' ? 'สินค้าแช่เย็น ต้องเก็บรักษาในอุณหภูมิต่ำ' : type==='Ambient' ? 'สินค้าอุณหภูมิปกติ เก็บรักษาที่อุณหภูมิห้อง' : '';

  var catKeywords = {
    'เอแคลร์': 'ขนมเอแคลร์ สอดไส้ครีมนุ่ม เนื้อแป้งเบาฟู อร่อยทุกคำ',
    'พัฟ': 'ขนมพัฟ เนื้อเบาบาง กรอบนอกนุ่มใน รสชาติกลมกล่อม',
    'ครัวซองต์': 'ครัวซองต์ เนื้อแป้งเป็นชั้น หอมเนย อบสดใหม่',
    'ขนมปัง': 'ขนมปังนุ่ม เนื้อละเอียด หอมกรุ่น เหมาะทุกมื้อ',
    'เค้ก': 'เค้กนุ่มชุ่ม เนื้อละเอียด รสชาติเข้มข้น',
    'คุกกี้': 'คุกกี้กรอบ หอมอร่อย เต็มคำ',
    'วาฟเฟิล': 'วาฟเฟิลกรอบนอกนุ่มใน หอมหวาน',
    'โดนัท': 'โดนัทนุ่มฟู เนื้อเนียน หวานพอดี',
    'แซนวิช': 'แซนวิชไส้แน่น สดใหม่ อร่อยพร้อมทาน',
    'ชิฟฟ่อน': 'เค้กชิฟฟ่อนเนื้อนุ่มฟู ละมุนลิ้น',
    'บราวนี่': 'บราวนี่เนื้อหนึบ เข้มข้นรสช็อคโกแลต',
    'มัฟฟิน': 'มัฟฟินนุ่มฟู หอมหวาน เต็มคำ',
    'เวเฟอร์': 'เวเฟอร์กรอบ สอดไส้ครีม อร่อยเพลิน',
    'ปอเปี๊ยะ': 'ปอเปี๊ยะทอดกรอบ ไส้แน่น กินเพลิน',
    'ชิป': 'ขนมชิปกรอบ รสชาติจัดจ้าน',
    'สติ๊ก': 'ขนมสติ๊กกรอบ ทานง่าย พกสะดวก',
    'โรล': 'โรลนุ่ม สอดไส้เต็มๆ อร่อยทุกคำ'
  };

  var catDesc = '';
  for(var kw in catKeywords){
    if(name.indexOf(kw)!==-1){ catDesc = catKeywords[kw]; break; }
  }
  if(!catDesc) catDesc = 'ผลิตภัณฑ์เบเกอรี่คุณภาพจากวรรณวนัช ผลิตด้วยวัตถุดิบคัดสรร';

  var parts = ['<strong>' + name + '</strong> — ' + catDesc];
  if(typeDesc) parts.push(typeDesc);
  if(weight) parts.push('น้ำหนักสุทธิ ' + weight);
  if(shelf) parts.push('อายุสินค้า ' + shelf);
  if(retail) parts.push('ราคาขายปลีก ' + retail);

  var channelNames = {
    'CJ More':'ร้านสะดวกซื้อ CJ More','Big C':'ห้างบิ๊กซี','Makro':'แม็คโคร',
    'Top':'Tops Supermarket','Aeon':'อิออน','The Mall':'เดอะมอลล์',
    'Amazon':'อเมซอน คาเฟ่','Black Canyon':'แบล็คแคนยอน',
    'Booth':'บูธจำหน่ายสินค้า','Online':'ช่องทางออนไลน์'
  };
  parts.push('จำหน่ายผ่าน' + (channelNames[ch]||ch));

  if(p.gp) parts.push('อัตรากำไรขั้นต้น (GP) ' + gp);
  if(status==='ยกเลิกขาย') parts.push('⚠️ สินค้ายกเลิกขายแล้ว');

  return parts.join(' • ');
}

function showProdModal(p, ch){
  const color = PROD_CH_COLORS[ch]||'#4f46e5';
  const grad  = PROD_CH_GRAD[ch]||color;
  const isOnline = ch==='Online';

  document.getElementById('prodModalHeader').style.background = grad;
  document.getElementById('prodModalChBadge').innerHTML =
    `<span style="color:#fff;font-size:16px;font-weight:800;text-shadow:0 1px 4px rgba(0,0,0,.35)">${ch}</span>`;

  // Reset img area
  const rotBtns=`<div style="position:absolute;top:12px;left:12px;display:flex;gap:5px">
    <button onclick="rotateProdImg(-90)" title="หมุนซ้าย" style="background:rgba(0,0,0,.4);border:none;color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center;transition:.15s;backdrop-filter:blur(2px)" onmouseover="this.style.background='rgba(0,0,0,.65)'" onmouseout="this.style.background='rgba(0,0,0,.4)'">↺</button>
    <button onclick="rotateProdImg(90)" title="หมุนขวา" style="background:rgba(0,0,0,.4);border:none;color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center;transition:.15s;backdrop-filter:blur(2px)" onmouseover="this.style.background='rgba(0,0,0,.65)'" onmouseout="this.style.background='rgba(0,0,0,.4)'">↻</button>
  </div>`;
  document.getElementById('prodModalImgArea').innerHTML =
    `<img id="prodModalImg" onclick="openImgZoom(this.src)" style="max-width:300px;max-height:340px;object-fit:contain;border-radius:16px;cursor:zoom-in;transition:transform .2s;filter:drop-shadow(0 6px 20px rgba(0,0,0,.12))" onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='scale(1)'">`
    +`<div style="position:absolute;top:14px;right:14px;background:rgba(0,0,0,.4);color:#fff;font-size:10px;padding:3px 8px;border-radius:20px;pointer-events:none;backdrop-filter:blur(2px)">🔍 คลิกขยาย</div>`
    + rotBtns;
  const imgEl = document.getElementById('prodModalImg');
  if(p.img){ imgEl.src=p.img; }
  else {
    document.getElementById('prodModalImgArea').innerHTML=
      `<div style="font-size:100px;text-align:center;filter:drop-shadow(0 4px 12px rgba(0,0,0,.08))">🍞</div>`;
  }

  document.getElementById('prodModalName').textContent = _stripBrand(p.name)||'—';
  document.getElementById('prodModalCode').innerHTML =
    `รหัส: <strong>${p.code||'—'}</strong> &nbsp;|&nbsp; Barcode: <strong>${p.barcode||'—'}</strong>`;

  // AI product description
  var aiDescEl = document.getElementById('prodModalAiDesc');
  var aiDescText = document.getElementById('prodModalAiDescText');
  if(aiDescEl && aiDescText){
    var desc = _generateProdDesc(p, ch);
    aiDescText.innerHTML = desc;
    aiDescEl.style.display = 'block';
  }

  const typeColor={Chill:'#0891b2',Ambient:'#d97706'};
  const typeBg   ={Chill:'linear-gradient(135deg,#e0f7fa,#b2ebf2)',Ambient:'linear-gradient(135deg,#fff8e1,#ffe082)'};
  const typeBdr  ={Chill:'#0891b233',Ambient:'#d9770633'};
  const isDisc = p.status==='discontinued';
  const isNew  = p.newMonth && !isDisc;
  const statusHtml = isDisc
    ? `<span style="background:linear-gradient(135deg,#fce4ec,#f8bbd0);color:#c62828;font-size:13px;font-weight:700;padding:6px 16px;border-radius:20px;display:inline-flex;align-items:center;gap:5px;border:1px solid #c6282833;box-shadow:0 2px 8px rgba(198,40,40,.1)">❌ ยกเลิก${p.discontinuedDate?' ('+p.discontinuedDate+')':''}</span>`
    : isNew
      ? `<span style="background:linear-gradient(135deg,#e8f5e9,#a5d6a7);color:#2e7d32;font-size:13px;font-weight:700;padding:6px 16px;border-radius:20px;display:inline-flex;align-items:center;gap:5px;border:1px solid #2e7d3233;box-shadow:0 2px 8px rgba(46,125,50,.1)">🆕 เข้าใหม่ เดือน${p.newMonth}</span>`
      : `<span style="background:linear-gradient(135deg,#e3f2fd,#90caf9);color:#1565c0;font-size:13px;font-weight:700;padding:6px 16px;border-radius:20px;display:inline-flex;align-items:center;gap:5px;border:1px solid #1565c033;box-shadow:0 2px 8px rgba(21,101,192,.1)">✅ ขายปัจจุบัน</span>`;
  document.getElementById('prodModalType').innerHTML =
    (p.type ? `<span style="background:${typeBg[p.type]||'linear-gradient(135deg,#f5f5f5,#e0e0e0)'};color:${typeColor[p.type]||'#64748b'};font-size:13px;font-weight:700;padding:6px 18px;border-radius:20px;border:1px solid ${typeBdr[p.type]||'#64748b33'};box-shadow:0 2px 6px rgba(0,0,0,.05)">${p.type==='Chill'?'❄️':'🔥'} ${p.type}</span> ` : '')
    + statusHtml;

  function _fmtPrice(v){ return v!=null ? parseFloat(Number(v).toFixed(2)) : null; }

  // Retail price highlight card
  var retailEl = document.getElementById('prodModalRetailPrice');
  if(retailEl){
    if(p.priceRetail){
      var rp = _fmtPrice(p.priceRetail);
      retailEl.innerHTML = `<div style="background:linear-gradient(135deg,#ff6b35,#f97316,#fb923c);border-radius:16px;padding:16px 20px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 4px 16px rgba(249,115,22,.25)">
        <div style="display:flex;flex-direction:column;gap:2px">
          <div style="font-size:11px;color:rgba(255,255,255,.85);font-weight:600">🏪 ราคาขายหน้าร้าน (In.VAT)</div>
          <div style="font-size:28px;font-weight:900;color:#fff;letter-spacing:-.02em">${rp} <span style="font-size:18px">฿</span></div>
        </div>
        <div style="font-size:40px;opacity:.3">🏷️</div>
      </div>`;
      retailEl.style.display = 'block';
    } else {
      retailEl.style.display = 'none';
    }
  }

  const dets=[];
  const pastel = [
    ['#fef3c7','#92400e'], ['#e0f2fe','#0369a1'], ['#fce7f3','#9d174d'], ['#d1fae5','#065f46'],
    ['#ede9fe','#5b21b6'], ['#fee2e2','#991b1b'], ['#e0f2fe','#0c4a6e'], ['#fef9c3','#713f12'],
    ['#f0fdf4','#14532d'], ['#fff1f2','#881337']
  ];
  if(p.weight!=null)  dets.push(['📦 น้ำหนัก', p.weight+'g']);
  if(p.shelf!=null)   dets.push(['⏱ อายุสินค้า', p.shelf+' วัน']);
  if(p.pcs!=null)     dets.push(['📋 จำนวน/ตะกร้า', p.pcs+' ชิ้น']);
  if(p.gp!=null)      dets.push(['📊 GP%', `<strong style="color:#16a34a">${Math.round(p.gp*100)}%</strong>`]);
  if(p.priceExvat)    dets.push(['🏷 ส่ง Ex.VAT', _fmtPrice(p.priceExvat)+' ฿']);
  if(p.priceIn)       dets.push(['💰 ส่ง In.VAT', `<strong>${_fmtPrice(p.priceIn)} ฿</strong>`]);
  if(p.priceRetailEx) dets.push(['🛒 ปลีก Ex.VAT', _fmtPrice(p.priceRetailEx)+' ฿']);
  if(p.priceRetail)   dets.push(['🛍 ปลีก In.VAT', `<strong style="color:${color}">${_fmtPrice(p.priceRetail)} ฿</strong>`]);
  document.getElementById('prodModalDetails').innerHTML = dets.map(([k,v],i)=>{
    const pc = pastel[i % pastel.length];
    return `<div style="background:linear-gradient(135deg,${pc[0]},${pc[0]}ee);border-radius:14px;padding:10px 14px;display:flex;flex-direction:column;gap:3px;border:1.5px solid ${pc[1]}20;box-shadow:0 2px 8px ${pc[1]}10">
       <div style="font-size:10px;color:${pc[1]}cc;font-weight:600;letter-spacing:.02em">${k}</div>
       <div style="font-size:15px;color:${pc[1]};font-weight:800">${v}</div>
     </div>`;
  }).join('');

  let priceBlock='';
  if(isOnline && p.prices){
    const e = Object.entries(p.prices).filter(([,v])=>v!=null);
    if(e.length) priceBlock=`<div style="font-size:12px;font-weight:700;color:#475569;margin-bottom:8px">ราคาขายออนไลน์</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${e.map(([k,v])=>
        `<div style="background:#fff;border-radius:8px;padding:8px 12px;border:1.5px solid ${color}33">
           <div style="font-size:11px;color:#475569">${k}</div>
           <div style="font-size:16px;font-weight:800;color:${color}">${v} ฿</div>
         </div>`).join('')}</div>`;
  }
  document.getElementById('prodModalPrices').innerHTML = priceBlock;
  document.getElementById('prodModalNote').textContent = p.note ? '* '+p.note : '';

  // อ.ย. and ฮาลาล editable fields
  const _fda   = p.fda   || '';
  const _halal = p.halal || '';
  document.getElementById('prodModalRegNums').innerHTML =
    `<div>
       <div style="font-size:11px;color:#94a3b8;margin-bottom:4px;font-weight:600">เลข อ.ย.</div>
       <div style="display:flex;gap:4px;align-items:center">
         <input id="inputFda" type="text" value="${_fda}"
           placeholder="กรอกเลข อ.ย."
           style="flex:1;border:1.5px solid #e2e8f0;border-radius:8px;padding:5px 8px;font-size:12px;color:#1e293b;outline:none;background:#f8fafc"
           onfocus="this.style.borderColor='${color}'" onblur="this.style.borderColor='#e2e8f0'">
         <button onclick="saveRegNum('fda')"
           style="background:${color};color:#fff;border:none;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap">บันทึก</button>
       </div>
     </div>
     <div>
       <div style="font-size:11px;color:#94a3b8;margin-bottom:4px;font-weight:600">เลขทะเบียนฮาลาล</div>
       <div style="display:flex;gap:4px;align-items:center">
         <input id="inputHalal" type="text" value="${_halal}"
           placeholder="กรอกเลขทะเบียน"
           style="flex:1;border:1.5px solid #e2e8f0;border-radius:8px;padding:5px 8px;font-size:12px;color:#1e293b;outline:none;background:#f8fafc"
           onfocus="this.style.borderColor='${color}'" onblur="this.style.borderColor='#e2e8f0'">
         <button onclick="saveRegNum('halal')"
           style="background:${color};color:#fff;border:none;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap">บันทึก</button>
       </div>
     </div>`;

  document.getElementById('prodModal').style.display='flex';
  document.body.style.overflow='hidden';
}

function closeProdModal(){
  document.getElementById('prodModal').style.display='none';
  document.body.style.overflow='';
}

function openAddProdModal(){
  var modal=document.getElementById('addProdModal');
  if(!modal) return;
  _clearProdForm();
  var chSel=document.getElementById('npCh');
  if(chSel && chSel.options.length===0 && typeof PRODUCTS!=='undefined'){
    Object.keys(PRODUCTS).forEach(function(ch){
      var o=document.createElement('option');o.value=ch;o.textContent=ch;chSel.appendChild(o);
    });
  }
  if(chSel && _prodCh) chSel.value=_prodCh;
  var titleEl=modal.querySelector('[data-prod-title]');
  if(titleEl) titleEl.textContent='➕ เพิ่มสินค้าใหม่';
  var saveBtn=modal.querySelector('[data-prod-save]');
  if(saveBtn) saveBtn.textContent='💾 บันทึก';
  modal.style.display='flex';
  document.body.style.overflow='hidden';
}

function closeAddProdModal(){
  var modal=document.getElementById('addProdModal');
  if(modal){ modal.style.display='none'; modal._editMode=null; }
  _clearProdForm();
  document.body.style.overflow='';
}

function saveNewProduct(){
  var ch=document.getElementById('npCh');
  var code=document.getElementById('npCode');
  var name=document.getElementById('npName');
  if(!ch||!code||!name||!code.value.trim()||!name.value.trim()){
    alert('กรุณากรอกช่องทาง, รหัสสินค้า, และชื่อสินค้า');return;
  }
  if(typeof PRODUCTS==='undefined'){alert('ไม่พบข้อมูล PRODUCTS');return;}
  var chVal=ch.value;
  if(!PRODUCTS[chVal]) PRODUCTS[chVal]=[];
  var modal=document.getElementById('addProdModal');
  var editMode=modal&&modal._editMode;
  var newData={
    code:code.value.trim(), name:name.value.trim(),
    type:(document.getElementById('npType')||{}).value||'Ambient',
    status:(document.getElementById('npStatus')||{}).value||'active',
    barcode:(document.getElementById('npBarcode')||{}).value||'',
    weight:(document.getElementById('npWeight')||{}).value||'',
    shelf:(document.getElementById('npShelf')||{}).value||'',
    gp:parseFloat((document.getElementById('npGp')||{}).value)||null,
    fda:(document.getElementById('npFda')||{}).value||'',
    halal:(document.getElementById('npHalal')||{}).value||'',
    priceExvat:parseFloat((document.getElementById('npPriceExVat')||{}).value)||null,
    priceRetailEx:parseFloat((document.getElementById('npPriceRetailEx')||{}).value)||null,
    priceIn:parseFloat((document.getElementById('npPriceIn')||{}).value)||null,
    priceRetail:parseFloat((document.getElementById('npPriceRetail')||{}).value)||null,
    priceShop:parseFloat((document.getElementById('npPriceShop')||{}).value)||null,
    note:(document.getElementById('npNote')||{}).value||''
  };
  var imgData = modal ? (modal._npImgData||'') : '';
  if(imgData){
    newData.img = imgData;
    _imgDB.set('prodImg_'+chVal+'_'+newData.code, imgData);
    _uploadImgToServer(newData.code,imgData).then(function(url){if(url)newData.img=url;});
  } else {
    newData.img = '';
    _imgDB.del('prodImg_'+chVal+'_'+newData.code);
    _deleteImgFromServer(newData.code);
  }
  if(editMode){
    var oldCh=editMode.ch, oldCode=editMode.code;
    if(oldCh!==chVal){
      PRODUCTS[oldCh]=(PRODUCTS[oldCh]||[]).filter(function(x){return x.code!==oldCode;});
      PRODUCTS[chVal].push(newData);
    } else {
      var arr=PRODUCTS[chVal];
      for(var i=0;i<arr.length;i++){
        if(arr[i].code===oldCode){ arr[i]=newData; break; }
      }
    }
    if(modal) modal._editMode=null;
  } else {
    newData.newMonth='ก.ค.';
    PRODUCTS[chVal].push(newData);
  }
  _clearProdForm();
  closeAddProdModal();
  _persistProducts();
  _syncProdDisplay();
  renderAdminProd();
  alert(editMode?'บันทึกการแก้ไขเรียบร้อย: '+name.value.trim():'เพิ่มสินค้าเรียบร้อย: '+name.value.trim());
}

function handleNpImgChange(input){
  var file = input.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e){
    var image = new Image();
    image.onload = function(){
      var MAX = 600;
      var w = image.width, h = image.height;
      if (w > MAX || h > MAX) { if (w > h) { h = Math.round(h * MAX / w); w = MAX; } else { w = Math.round(w * MAX / h); h = MAX; } }
      var canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      var ctx = canvas.getContext('2d');
      ctx.fillStyle = 'rgb(254,247,237)'; ctx.fillRect(0, 0, w, h);
      ctx.drawImage(image, 0, 0, w, h);
      if (typeof _removeBg === 'function') _removeBg(ctx, w, h);
      var dataUrl = canvas.toDataURL('image/jpeg', 0.82);
      var preview = document.getElementById('npImgPreview');
      if (preview) preview.innerHTML = '<img src="'+dataUrl+'" style="width:100%;height:100%;object-fit:contain">';
      var removeBtn = document.getElementById('npImgRemoveBtn');
      if (removeBtn) removeBtn.style.display = 'inline-block';
      var modal = document.getElementById('addProdModal');
      if (modal) modal._npImgData = dataUrl;
    };
    image.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function removeNpImg(){
  var preview = document.getElementById('npImgPreview');
  if (preview) preview.innerHTML = '<span style="font-size:40px;color:#cbd5e1">📷</span>';
  var removeBtn = document.getElementById('npImgRemoveBtn');
  if (removeBtn) removeBtn.style.display = 'none';
  var modal = document.getElementById('addProdModal');
  if (modal) modal._npImgData = '';
  var input = document.getElementById('npImgFile');
  if (input) input.value = '';
}

function _clearProdForm(){
  var ids=['npCode','npName','npBarcode','npFda','npHalal','npWeight','npShelf','npGp','npPriceExVat','npPriceRetailEx','npPriceIn','npPriceRetail','npPriceShop','npNote'];
  ids.forEach(function(id){ var e=document.getElementById(id); if(e) e.value=''; });
  var t=document.getElementById('npType'); if(t) t.value='Ambient';
  var s=document.getElementById('npStatus'); if(s) s.value='active';
  var modal=document.getElementById('addProdModal');
  if(modal){ modal._editMode=null; modal._npImgData=''; }
  removeNpImg();
}

function deleteCurrentProduct(){
  if(!confirm('ต้องการลบสินค้านี้หรือไม่?')) return;
  var p=_prodModalList&&_prodModalList[_prodModalIdx];
  if(!p){alert('ไม่พบสินค้าที่เลือก');return;}
  var ch=_prodCh;
  if(typeof PRODUCTS!=='undefined' && PRODUCTS[ch]){
    PRODUCTS[ch]=PRODUCTS[ch].filter(function(item){return item.code!==p.code;});
  }
  _persistProducts();
  _syncProdDisplay();
  closeProdModal();
  renderProdChannel(ch);
}

function saveRegNum(field){
  const p   = _prodModalList[_prodModalIdx];
  const ch  = _prodCh;
  if(!p) return;
  const inp = document.getElementById(field==='fda' ? 'inputFda' : 'inputHalal');
  if(!inp) return;
  const val = inp.value.trim();
  p[field] = val;
  try { localStorage.setItem('prod'+field.charAt(0).toUpperCase()+field.slice(1)+'_'+ch+'_'+p.code, val); } catch(e){}
  // Brief flash of input border
  inp.style.borderColor='#22c55e';
  setTimeout(()=>{ inp.style.borderColor='#e2e8f0'; }, 1200);
}


// Keyboard navigation for product modal
document.addEventListener('keydown', function(e){
  const modal = document.getElementById('prodModal');
  if(!modal || modal.style.display==='none') return;
  if(e.key==='ArrowLeft') prodModalPrev();
  else if(e.key==='ArrowRight') prodModalNext();
  else if(e.key==='Escape') closeProdModal();
});


function openImgZoom(src){
  if(!src) return;
  const ov = document.getElementById('imgZoomOverlay');
  document.getElementById('imgZoomImg').src = src;
  ov.style.display = 'flex';
}
function closeImgZoom(){
  document.getElementById('imgZoomOverlay').style.display = 'none';
}
document.addEventListener('keydown', function(e){
  if(e.key==='Escape'){ closeImgZoom(); closeProdModal(); }
});


// ── Period Mode (Year / Month / Day) ────────────────────────
let _periodMode = 'year';
const _DATE_TO_MONTH = {'01':'Jan','02':'Feb','03':'Mar','04':'Apr','05':'May','06':'Jun','07':'Jul','08':'Aug','09':'Sep','10':'Oct','11':'Nov','12':'Dec'};
const _MONTH_TO_IDX  = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
const _MONTH_TO_NUM  = {Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12'};

// Date-range state (used in day mode)
let _rangeStart = 'Jan', _rangeEnd = 'Jun';

// ── Quick period presets ──────────────────────────────────────
// Data available: Jan–May 2026. Today = 2026-06-12.
// Map UI presets to available month ranges — คำนวณจากข้อมูลจริง
function _getLatest(){ return MONTHS.length>0 ? MONTHS[MONTHS.length-1] : 'Jan'; }
function _getPrevLatest(){ var i=MONTHS_12.indexOf(_getLatest()); return i>0?MONTHS_12[i-1]:'Jan'; }

function setQuickPeriod(preset, el){
  document.querySelectorAll('#quickPeriodBtns .period-type-btn').forEach(b=>b.classList.remove('active'));
  if(el) el.classList.add('active');

  const monthTabs = document.getElementById('globalMonthTabs');
  const datePicker = document.getElementById('globalDatePicker');
  if(monthTabs) monthTabs.style.display = 'none';

  switch(preset){
    case 'all':
      if(datePicker) datePicker.style.display = 'none';
      globalSelectMonth('YTD', null);
      break;
    case 'q1': if(datePicker) datePicker.style.display='none'; globalSelectMonth({range:true,start:'Jan',end:'Mar'},null); break;
    case 'q2': if(datePicker) datePicker.style.display='none'; globalSelectMonth({range:true,start:'Apr',end:'Jun'},null); break;
    case 'q3': if(datePicker) datePicker.style.display='none'; globalSelectMonth({range:true,start:'Jul',end:'Sep'},null); break;
    case 'q4': if(datePicker) datePicker.style.display='none'; globalSelectMonth({range:true,start:'Oct',end:'Dec'},null); break;
    case 'annual': if(datePicker) datePicker.style.display='none'; globalSelectMonth('YTD',null); break;
    case 'today':       // current day → latest available month (May)
    case 'thisweek':    // current week → latest month
    case 'thismonth':   // Jun has no data → show latest (May)
      if(datePicker) datePicker.style.display = 'none';
      globalSelectMonth(_getLatest(), null);
      break;
    case 'yesterday':   // yesterday → month before latest
    case 'lastweek':    // last week → month before latest
    case 'lastmonth':   // last complete month = month before latest available
      if(datePicker) datePicker.style.display = 'none';
      globalSelectMonth(_getPrevLatest(), null);
      break;
    case '3months':     // May–Jul
      if(datePicker) datePicker.style.display = 'none';
      globalSelectMonthRange('May','Jul');
      break;
    case 'custom':
      if(datePicker) datePicker.style.display = 'flex';
      onDateRangeChange();
      break;
  }
}

function resetFilters(){
  if(_CY!==2569){
    _CY=2569;
    _applyYear(2569);
    var lab=document.getElementById('annualLabel');
    if(lab) lab.textContent='📅 ปี 2569';
    document.querySelectorAll('#annualMenu .qmenu-item').forEach(function(i){
      i.classList.toggle('active',parseInt(i.dataset.y)===2569);
    });
  }
  var qlab=document.getElementById('quarterLabel');
  if(qlab) qlab.textContent='📆 รายไตรมาส';
  var mlab=document.getElementById('monthLabel');
  if(mlab) mlab.textContent='📅 รายเดือน';
  document.querySelectorAll('#monthMenu .qmenu-item').forEach(function(i){i.classList.remove('active');});
  var allBtn=document.querySelector('#quickPeriodBtns [data-preset="all"]');
  setQuickPeriod('all',allBtn);
}

function setPeriodMode(mode, el){
  _periodMode = mode;
  document.querySelectorAll('.period-type-btn').forEach(b=>{
    b.classList.toggle('active', b.dataset.mode===mode);
  });
  const monthTabs = document.getElementById('globalMonthTabs');
  const datePicker = document.getElementById('globalDatePicker');
  const yearLabel  = document.getElementById('filterYearLabel');

  if(mode==='year'){
    if(monthTabs) monthTabs.style.display = 'none';
    if(datePicker) datePicker.style.display = 'none';
    if(yearLabel) yearLabel.style.display  = 'block';
    globalSelectMonth('YTD', null);
  } else if(mode==='month'){
    if(monthTabs) monthTabs.style.display = 'flex';
    if(datePicker) datePicker.style.display = 'none';
    if(yearLabel) yearLabel.style.display  = 'none';
    var firstTab = monthTabs ? monthTabs.querySelector('.fmtab') : null;
    if(firstTab) globalSelectMonth(firstTab.dataset.m, firstTab);
  } else {
    if(monthTabs) monthTabs.style.display = 'none';
    if(datePicker) datePicker.style.display = 'flex';
    if(yearLabel) yearLabel.style.display  = 'none';
    onDateRangeChange();
  }
}

function onDateRangePreview(){
  const s = document.getElementById('datePickerStart').value;
  const e = document.getElementById('datePickerEnd').value;
  if(!s || !e) return;
  if(e < s){ document.getElementById('datePickerEnd').value = s; return onDateRangePreview(); }
  const mStart = _DATE_TO_MONTH[s.split('-')[1]];
  const mEnd   = _DATE_TO_MONTH[e.split('-')[1]];
  if(!mStart || !mEnd) return;
  const thStart = MONTHS_TH[_MONTH_TO_IDX[mStart]] || mStart;
  const thEnd   = MONTHS_TH[_MONTH_TO_IDX[mEnd]]   || mEnd;
  var label = mStart===mEnd ? thStart : thStart+' – '+thEnd;
  document.getElementById('dateRangeLabel').textContent = '📊 '+label;
}
function onDateRangeChange(){
  const s = document.getElementById('datePickerStart').value;
  const e = document.getElementById('datePickerEnd').value;
  if(!s || !e) return;
  if(e < s){ document.getElementById('datePickerEnd').value = s; return onDateRangeChange(); }
  const mStart = _DATE_TO_MONTH[s.split('-')[1]];
  const mEnd   = _DATE_TO_MONTH[e.split('-')[1]];
  if(!mStart || !mEnd) return;
  _rangeStart = mStart;
  _rangeEnd   = mEnd;
  const thStart = MONTHS_TH[_MONTH_TO_IDX[mStart]] || mStart;
  const thEnd   = MONTHS_TH[_MONTH_TO_IDX[mEnd]]   || mEnd;
  var label = mStart===mEnd ? thStart : thStart+' – '+thEnd;
  document.getElementById('dateRangeLabel').textContent = '📊 '+label;
  globalSelectMonthRange(mStart, mEnd);
}

function globalSelectMonthRange(mStart, mEnd){
  // Store range in currentMonth as special object
  currentMonth = {range:true, start:mStart, end:mEnd};
  _refreshAllTabs();
}

function _refreshAllTabs(){
  renderOverview();
  if(builtTabs.channel)  renderChannel();
  if(builtTabs.customer) renderCustomer();
  if(builtTabs.sales)    renderSales();
  if(selectedPerson && builtTabs.sales) renderPersonDetail(selectedPerson);
  if(builtTabs.products){
    if(_prodTab==='overview') renderProdOverview();
    else if(_prodTab==='npd') renderProdNPD();
  }
  var ds=document.getElementById('ov-daily');
  if(ds&&ds.classList.contains('active')) renderDaily();
  var bthSec=document.getElementById('tab-booth');
  if(bthSec&&bthSec.style.display!=='none') renderBooth();
  var amzSec=document.getElementById('tab-amazon');
  if(amzSec&&amzSec.style.display!=='none') renderAmazon();
  if(builtTabs.cjperf){var cjSec=document.getElementById('tab-cjperf');if(cjSec&&cjSec.style.display!=='none')renderCJPage();}
  var trdTab=document.getElementById('tab-trend');
  if(trdTab&&trdTab.style.display!=='none'){builtTabs.trend=true;if(typeof initTrend==='function')initTrend();}
  var trendSec=document.getElementById('ov-trend');
  if(trendSec&&trendSec.classList.contains('active')&&typeof renderDailyTrend==='function') renderDailyTrend();
  if(typeof renderOvTarget==='function') renderOvTarget();
}


// ════════════════════════════════════════
// CJ PERFORMANCE TAB
// ════════════════════════════════════════
let _cjType='All', _cjCharts={};

function cjSetType(t, el){
  _cjType = t;
  document.querySelectorAll('#cjTypeFilter .fmtab').forEach(b=>b.classList.toggle('active',b===el));
  renderCJPage();
}

function cjFilter(){
  const q=(document.getElementById('cjSearch')||{value:''}).value.toLowerCase();
  return CJ_PRODUCTS.filter(p=>
    (_cjType==='All'||p.type===_cjType) &&
    (!q||p.name.toLowerCase().includes(q)||p.code.includes(q))
  );
}

function initCJPerf(){
  renderCJPage();
}

function renderCJPage(){
  renderCJKPI();
  renderCJCharts();
  renderCJTable();
}

function renderCJKPI(){
  const prods = cjFilter();
  const _cjMonths = _resolveMonths();
  const totB  = prods.reduce((s,p)=>s+_cjMonths.reduce((ss,mo)=>ss+((p.m[mo]||{}).b||0),0),0);
  const totU  = prods.reduce((s,p)=>s+_cjMonths.reduce((ss,mo)=>ss+((p.m[mo]||{}).u||0),0),0);
  const totP  = prods.reduce((s,p)=>s+_cjMonths.reduce((ss,mo)=>ss+((p.m[mo]||{}).p||0),0),0);
  const pct   = totB>0 ? (totP/totB*100) : 0;
  const _pProfit = function(p){return _cjMonths.reduce(function(ss,mo){return ss+((p.m[mo]||{}).p||0);},0);};
  const pos   = prods.filter(p=>_pProfit(p)>0).length;
  const neg   = prods.filter(p=>_pProfit(p)<0).length;

  document.getElementById('cjKPI').innerHTML = `
    <div class="kpi-card blue">
      <div class="kpi-label">💰 Revenue รวม</div>
      <div class="kpi-value sm">${(totB/1e6).toFixed(2)} M</div>
      <div class="kpi-sub">${Math.round(totU).toLocaleString('th-TH')} ชิ้น</div>
    </div>
    <div class="kpi-card ${totP>=0?'green':'red'}">
      <div class="kpi-label">📊 กำไรรวม</div>
      <div class="kpi-value sm">${(totP/1e6).toFixed(2)} M</div>
      <div class="kpi-sub">${pct.toFixed(1)}% Profit Margin</div>
    </div>
    <div class="kpi-card cyan">
      <div class="kpi-label">📦 จำนวนสินค้า</div>
      <div class="kpi-value sm">${prods.length} SKUs</div>
      <div class="kpi-sub">Ambient ${prods.filter(p=>p.type==='Ambient').length} · Chill ${prods.filter(p=>p.type==='Chill').length}</div>
    </div>
    <div class="kpi-card yellow">
      <div class="kpi-label">✅ กำไร / ❌ ขาดทุน</div>
      <div class="kpi-value sm">${pos} / ${neg} SKUs</div>
      <div class="kpi-sub">สินค้ากำไร ${pos} รายการ</div>
    </div>
  `;
}

function destroyCJChart(id){
  if(_cjCharts[id]){_cjCharts[id].destroy();delete _cjCharts[id];}
}

function renderCJCharts(){
  const prods = cjFilter();
  const MNTH = _resolveMonths().filter(function(m){var d=prods[0]&&prods[0].m[m];return d&&d.b>0;});
  const MNTH_TH = MNTH.map(function(m){return MONTHS_TH[MONTHS.indexOf(m)];});

  // Monthly revenue bar
  destroyCJChart('cjMthBar');
  const mthB = MNTH.map(m=>prods.reduce((s,p)=>s+(p.m[m]?.b||0),0)/1e6);
  const mthP = MNTH.map(m=>prods.reduce((s,p)=>s+(p.m[m]?.p||0),0)/1e6);
  _cjCharts['cjMthBar'] = new Chart(document.getElementById('cjMthBar').getContext('2d'),{
    type:'bar',
    data:{labels:MNTH_TH,datasets:[
      {label:'Revenue (M฿)',data:mthB,backgroundColor:'rgba(234,88,12,.8)',borderRadius:5},
      {label:'Profit (M฿)',data:mthP,backgroundColor:'rgba(22,163,74,.7)',borderRadius:5},
    ]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
      scales:{y:{ticks:{callback:v=>v.toFixed(1)+' M'}}}}
  });

  // helper: sum filtered months per product
  const _cjPB = function(p){return MNTH.reduce(function(s,m){return s+((p.m[m]||{}).b||0);},0);};
  const _cjPP = function(p){return MNTH.reduce(function(s,m){return s+((p.m[m]||{}).p||0);},0);};

  // Top 10 products
  destroyCJChart('cjTopBar');
  const top10 = [...prods].sort((a,b)=>_cjPB(b)-_cjPB(a)).slice(0,10);
  _cjCharts['cjTopBar'] = new Chart(document.getElementById('cjTopBar').getContext('2d'),{
    type:'bar',
    data:{
      labels:top10.map(p=>{var n=_stripBrand(p.name);return n.length>20?n.slice(0,20)+'…':n;}),
      datasets:[{label:'Revenue (฿)',data:top10.map(p=>_cjPB(p)),
        backgroundColor:top10.map((_,i)=>`hsl(${20+i*15},80%,55%)`),borderRadius:5}]
    },
    options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false}},
      scales:{x:{ticks:{callback:v=>(v/1e6).toFixed(1)+' M'}}}}
  });

  // Profit pie
  destroyCJChart('cjProfitPie');
  const profPos = prods.filter(p=>_cjPP(p)>0).reduce((s,p)=>s+_cjPP(p),0);
  const profNeg = prods.filter(p=>_cjPP(p)<0).reduce((s,p)=>s+Math.abs(_cjPP(p)),0);
  _cjCharts['cjProfitPie'] = new Chart(document.getElementById('cjProfitPie').getContext('2d'),{
    type:'doughnut',
    data:{labels:['กำไร','ขาดทุน'],
      datasets:[{data:[profPos,profNeg],backgroundColor:['#16a34a','#dc2626'],borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}
  });

  // Type pie
  destroyCJChart('cjTypePie');
  const ambB = prods.filter(p=>p.type==='Ambient').reduce((s,p)=>s+_cjPB(p),0);
  const chillB = prods.filter(p=>p.type==='Chill').reduce((s,p)=>s+_cjPB(p),0);
  _cjCharts['cjTypePie'] = new Chart(document.getElementById('cjTypePie').getContext('2d'),{
    type:'doughnut',
    data:{labels:['Ambient','Chill'],
      datasets:[{data:[ambB,chillB],backgroundColor:['#ea580c','#0891b2'],borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}
  });
}

function renderCJTable(){
  const prods = cjFilter();
  const _tblMths = _resolveMonths();
  const _tblPB = function(p){return _tblMths.reduce(function(s,m){return s+((p.m[m]||{}).b||0);},0);};
  const _tblPU = function(p){return _tblMths.reduce(function(s,m){return s+((p.m[m]||{}).u||0);},0);};
  const _tblPP = function(p){return _tblMths.reduce(function(s,m){return s+((p.m[m]||{}).p||0);},0);};
  const sorted = [...prods].sort((a,b)=>_tblPB(b)-_tblPB(a));
  document.getElementById('cjTableTitle').textContent =
    `รายการสินค้าทั้งหมด (${sorted.length} รายการ)`;

  document.getElementById('cjProdTable').innerHTML = sorted.map((p,i)=>{
    const pb=_tblPB(p), pp=_tblPP(p), pu=_tblPU(p);
    const pct = pb>0?(pp/pb*100):0;
    const profCls = pp>=0?'green':'red';
    const typePill = p.type==='Ambient'
      ? '<span class="pill yellow">🌡 Ambient</span>'
      : '<span class="pill cyan">❄️ Chill</span>';
    return `<tr>
      <td>${i+1}</td>
      <td style="max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${_stripBrand(p.name)}">${_stripBrand(p.name)}</td>
      <td>${typePill}</td>
      <td style="font-size:11px;color:var(--muted)">${p.rmk||'—'}</td>
      <td style="text-align:right">${p.cost.toFixed(2)}</td>
      <td style="text-align:right">${p.price.toFixed(2)}</td>
      <td style="text-align:right;color:${p.pu>=0?'var(--green)':'var(--red)'}">
        ${p.pu>=0?'+':''}${p.pu.toFixed(2)}</td>
      <td style="text-align:right">${Math.round(pu).toLocaleString('th-TH')}</td>
      <td style="text-align:right;font-weight:600">${Math.round(pb).toLocaleString('th-TH')}</td>
      <td style="text-align:right;color:var(--${profCls})">${Math.round(pp).toLocaleString('th-TH')}</td>
      <td>${progFill(Math.abs(pct))} <span style="font-size:10px;color:var(--${profCls})">${pct.toFixed(1)}%</span></td>
      <td style="text-align:center">${(()=>{const mv=_tblMths.map(m=>(p.m[m]||{}).b||0);return perfBadgeHTML(calcPerf(mv));})()}</td>
      <td style="text-align:center" onclick="showSkuPerf('${_stripBrand(p.name).replace(/'/g,"\\'")}',JSON.parse(this.getAttribute('data-m')),'CJ Supermarket')" data-m="${JSON.stringify(p.m||{}).replace(/"/g,'&quot;')}">${perfSearchIcon()}</td>
    </tr>`;
  }).join('');

  // Monthly table
  const _mthsFiltered = _resolveMonths().filter(function(m){return prods.some(function(p){return p.m[m]&&p.m[m].b>0;});});
  document.getElementById('cjMthTable').innerHTML = sorted.map(p=>{
    const mCells = _mthsFiltered.map(m=>`<td style="text-align:right">${p.m[m]?.b?Math.round(p.m[m].b).toLocaleString('th-TH'):'—'}</td>`).join('');
    const mVals = _mthsFiltered.map(m=>(p.m[m]||{}).b||0);
    const perf = calcPerf(mVals);
    return `<tr><td style="max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${_stripBrand(p.name)}">${_stripBrand(p.name)}</td>${mCells}
      <td style="text-align:right;font-weight:700">${Math.round(_tblPB(p)).toLocaleString('th-TH')}</td>
      <td style="text-align:center">${perfBadgeHTML(perf)}</td>
      <td style="text-align:center" onclick="showSkuPerf('${_stripBrand(p.name).replace(/'/g,"\\'")}',JSON.parse(this.getAttribute('data-m')),'CJ Supermarket')" data-m="${JSON.stringify(p.m||{}).replace(/"/g,'&quot;')}">${perfSearchIcon()}</td></tr>`;
  }).join('');
}


