// MT PERFORMANCE TAB
// ════════════════════════════════════════
let _mtCh = 'CJ', _mtType = 'All', _mtRank = 'All', _mtCharts = {};

const MT_CH_LABELS = {CJ:'CJ',BigC:'Big C',MM:'MM Mega',Aeon:'Aeon',Top:'Top',TheMall:'The Mall',Makro:'Makro',Wholegrain:'โฮลเกรน'};
const MT_CH_COLORS = {CJ:'#ea580c',BigC:'#2563eb',MM:'#16a34a',Aeon:'#9333ea',Top:'#dc2626',TheMall:'#d97706',Makro:'#0891b2',Wholegrain:'#65a30d'};
const _MT_CUST_KEY = {CJ:'CJ',BigC:'BIG C',MM:'MM',Aeon:'AEON',Top:'TOP',TheMall:'The Mall',Makro:'MAKRO',Wholegrain:'โฮลเกรน'};
const MT_MONTHS_2026 = ['Jan','Feb','Mar','Apr','May','Jun','Jul'];
const ALL_12_MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function _mtGetYear(){ return (typeof _mtPeriod!=='undefined' && _mtPeriod.year) ? _mtPeriod.year : 2026; }
function _mtAvailableMonths(){
  const yr = _mtGetYear();
  const beYr = yr + 543;
  const d = _YEAR_MAP[beYr];
  if(d && d.MT_CUST){
    const found = new Set();
    ALL_12_MONTHS.forEach(function(mo){
      if(!d.MT_CUST[mo]) return;
      var keys = Object.keys(d.MT_CUST[mo]);
      for(var i=0;i<keys.length;i++){
        if(d.MT_CUST[mo][keys[i]] && d.MT_CUST[mo][keys[i]].a > 0){ found.add(mo); break; }
      }
    });
    if(found.size > 0) return ALL_12_MONTHS.filter(function(m){ return found.has(m); });
  }
  if(yr===2026) return MT_MONTHS_2026;
  return ALL_12_MONTHS;
}
const MT_MONTHS = MT_MONTHS_2026;
const MT_MONTHS_TH = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];

MT_RANK_CRITERIA = {
  'All':     {ap:'≥ 1,000,000',a:'100,000 – 999,999',b:'10,000 – 99,999',c:'0 – 9,999'},
  'CJ':      {ap:'≥ 1,000,000',a:'100,000 – 999,999',b:'10,000 – 99,999',c:'0 – 9,999'},
  'BigC':    {ap:'≥ 100,000',  a:'10,000 – 99,999',  b:'1,000 – 9,999',  c:'0 – 999'},
  'MM':      {ap:'≥ 100',      a:'50 – 99',          b:'30 – 49',        c:'0 – 29'},
  'Aeon':    {ap:'≥ 1,000',    a:'500 – 999',        b:'50 – 499',       c:'0 – 49'},
  'Top':     {ap:'≥ 1,000',    a:'500 – 999',        b:'50 – 499',       c:'0 – 49'},
  'TheMall': {ap:'≥ 5,000',    a:'100 – 499',        b:'50 – 99',        c:'0 – 49'},
  'Makro':   {ap:'≥ 1,000',    a:'500 – 999',        b:'50 – 499',       c:'0 – 49'},
};
function renderRankLegend(){
  const cr = MT_RANK_CRITERIA[_mtCh] || MT_RANK_CRITERIA['All'];
  const ch = _mtCh==='All'?'ทุกช่องทาง':_mtCh;
  const row=(bg,col,lbl,txt)=>`<span style="background:${bg};color:${col};font-weight:800;font-size:12px;padding:2px 10px;border-radius:6px;text-align:center">${lbl}</span><span style="font-size:12px;color:var(--text)">${txt} ชิ้น</span>`;
  document.getElementById('rankLegendContent').innerHTML=`
    <div style="font-size:11px;font-weight:800;color:var(--text);margin-bottom:7px;letter-spacing:.3px">📊 เกณฑ์ Rank — ${ch}</div>
    <div style="display:grid;grid-template-columns:auto 1fr;gap:5px 12px;align-items:center">
      ${row('#dcfce7','#16a34a','A+',cr.ap)}
      ${row('#dbeafe','#2563eb','A',cr.a)}
      ${row('#fef9c3','#d97706','B',cr.b)}
      ${row('#fee2e2','#dc2626','C',cr.c)}
    </div>`;
}
function updateRankTitles(){
  const cr = _mtCh==='All' ? null : (MT_RANK_CRITERIA[_mtCh]||null);
  const map = {rankBtnAp: cr?cr.ap:null, rankBtnA: cr?cr.a:null, rankBtnB: cr?cr.b:null, rankBtnC: cr?cr.c:null};
  Object.entries(map).forEach(([id,val])=>{
    const btn=document.getElementById(id);
    if(!btn) return;
    if(val) btn.setAttribute('title', val+' ชิ้น');
    else btn.removeAttribute('title');
  });
}
function mtSetCh(ch, el){
  _mtCh = ch;
  if(el){document.querySelectorAll('#mtChFilter .fmtab').forEach(b=>b.classList.toggle('active',b===el));}
  const btn=document.getElementById('rankInfoBtn');
  if(btn){btn.classList.toggle('hidden',ch==='All');document.getElementById('rankLegend').classList.add('hidden');}
  updateRankTitles();
  renderMTPage();
}

function mtSelectChannel(ch){
  var stickerDiv=document.getElementById('mt-sticker-cancel');
  var biLayout=document.querySelector('.mt-bi-layout');
  var periodFilter=document.getElementById('mtPeriodFilter');
  if(ch==='StickerCancel'){
    if(biLayout)biLayout.style.display='none';
    if(periodFilter)periodFilter.style.display='none';
    if(stickerDiv){stickerDiv.style.display='block';renderStickerCancel();}
    return;
  }
  if(stickerDiv)stickerDiv.style.display='none';
  if(biLayout)biLayout.style.display='';
  if(periodFilter)periodFilter.style.display='';
  _mtCh = ch;
  updateRankTitles();
  renderMTPage();
}

function mtClickChannel(tabEl, ch){
  document.querySelectorAll('#mtChannelTabs .sub-tab').forEach(function(t){ t.classList.remove('active'); });
  tabEl.classList.add('active');
  mtSelectChannel(ch);
}

