function _contractDaysLeft(iso) {
  if (!iso) return null;
  var today = new Date(); today.setHours(0,0,0,0);
  var exp   = new Date(iso);
  return Math.round((exp - today) / 86400000);
}

function _showContractAlert(expBooths) {
  var modal = document.getElementById('_contractAlertModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = '_contractAlertModal';
    modal.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99999;align-items:center;justify-content:center';
    modal.innerHTML = '<div style="background:#fff;border-radius:20px;padding:32px 28px;max-width:460px;width:92%;box-shadow:0 24px 80px rgba(0,0,0,.3);position:relative">'
      +'<div style="text-align:center;font-size:40px;margin-bottom:6px">🔔</div>'
      +'<div style="text-align:center;font-size:19px;font-weight:800;color:#dc2626;margin-bottom:6px">แจ้งเตือนสัญญาบูธใกล้หมดอายุ!</div>'
      +'<div style="text-align:center;font-size:13px;color:#64748b;margin-bottom:20px">บูธด้านล่างมีสัญญาหมดอายุภายใน 90 วัน</div>'
      +'<div id="_contractAlertBody"></div>'
      +'<button onclick="document.getElementById(\'_contractAlertModal\').style.display=\'none\'" '
        +'style="margin-top:20px;width:100%;padding:11px;border:none;border-radius:12px;background:linear-gradient(135deg,#dc2626,#b91c1c);color:#fff;font-size:14px;font-weight:800;cursor:pointer">ปิด</button>'
      +'</div>';
    document.body.appendChild(modal);
    modal.addEventListener('click', function(e){ if(e.target===modal) modal.style.display='none'; });
  }
  var body = document.getElementById('_contractAlertBody');
  body.innerHTML = expBooths.map(function(b){
    var d = _contractDaysLeft(b.iso);
    var urgency = d <= 7 ? '#dc2626' : d <= 14 ? '#ea580c' : '#d97706';
    var badge = d <= 0 ? 'หมดแล้ว!' : d + ' วัน';
    return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:#fff7ed;border:1.5px solid #fed7aa;border-radius:12px;margin-bottom:10px">'
      +'<div style="font-size:22px">🔔</div>'
      +'<div style="flex:1">'
        +'<div style="font-size:14px;font-weight:800;color:#1e293b">'+b.name+'</div>'
        +'<div style="font-size:12px;color:#64748b;margin-top:2px">สิ้นสุดสัญญา: '+b.label+'</div>'
      +'</div>'
      +'<div style="background:'+urgency+';color:#fff;font-size:12px;font-weight:800;padding:4px 10px;border-radius:20px;white-space:nowrap">'+badge+'</div>'
      +'</div>';
  }).join('');
  modal.style.display = 'flex';
}

function renderBoothInfo() {
  var COLORS = ['#f97316','#0891b2','#10b981','#8b5cf6','#ef4444','#f59e0b','#06b6d4','#ec4899','#a78bfa','#14b8a6','#84cc16'];
  var today = new Date(); today.setHours(0,0,0,0);
  var openList   = BOOTH_INFO.filter(function(b){ return b.status.indexOf('เปิดกิจการอยู่')>=0; });
  var closedList = BOOTH_INFO.filter(function(b){ return b.status.indexOf('เปิดกิจการอยู่')<0; });

  /* Check which open booths expire within 90 days */
  var expiring = openList.reduce(function(acc, b){
    var c = BOOTH_CONTRACT[b.name];
    if (!c || !c.iso) return acc;
    var d = _contractDaysLeft(c.iso);
    if (d !== null && d <= 90) acc.push({name:b.name, iso:c.iso, label:c.label, days:d});
    return acc;
  }, []);

  /* KPI */
  var kpiEl = document.getElementById('bthInfoKPI');
  if(kpiEl) kpiEl.innerHTML = [
    {icon:'🟢',label:'เปิดกิจการ',val:openList.length,col:'#16a34a',bg:'linear-gradient(135deg,#dcfce7,#bbf7d0)'},
    {icon:'🔴',label:'ปิดกิจการ',val:closedList.length,col:'#dc2626',bg:'linear-gradient(135deg,#fee2e2,#fecaca)'},
    {icon:'🏪',label:'บูธทั้งหมด',val:BOOTH_INFO.length,col:'#0891b2',bg:'linear-gradient(135deg,#e0f2fe,#bae6fd)'}
  ].map(function(k){
    return '<div style="background:'+k.bg+';border-radius:16px;padding:20px 24px;display:flex;align-items:center;gap:16px">'
      +'<div style="font-size:36px">'+k.icon+'</div>'
      +'<div><div style="font-size:28px;font-weight:800;color:'+k.col+'">'+k.val+'</div>'
      +'<div style="font-size:13px;font-weight:600;color:#475569">'+k.label+'</div></div></div>';
  }).join('');

  /* Booth cards */
  var grid = document.getElementById('bthCardGrid');
  if(!grid) return;
  var sortedBooths = BOOTH_INFO.slice().sort(function(a,b){
    var ao=a.status.indexOf('เปิดกิจการอยู่')>=0, bo=b.status.indexOf('เปิดกิจการอยู่')>=0;
    return ao===bo?0:ao?-1:1;
  });
  grid.innerHTML = sortedBooths.map(function(b, bi){
    var isOpen  = b.status.indexOf('เปิดกิจการอยู่')>=0;
    var col     = isOpen ? COLORS[bi%COLORS.length] : '#94a3b8';
    var rentFmt = b.rent>0?b.rent.toLocaleString()+' บ./เดือน':'ไม่มีค่าเช่า';

    /* Contract info */
    var cInfo    = BOOTH_CONTRACT[b.name] || {iso:'',label:'-'};
    var daysLeft = _contractDaysLeft(cInfo.iso);
    var isExpiring = (daysLeft !== null && daysLeft <= 90);
    var contractLabel = cInfo.label || '-';
    var contractColor = '#64748b';
    var contractBadge = '';
    if (isExpiring) {
      contractColor = daysLeft <= 7 ? '#dc2626' : daysLeft <= 14 ? '#ea580c' : '#d97706';
      var bLabel = daysLeft <= 0 ? 'หมดแล้ว!' : 'เหลือ '+daysLeft+' วัน';
      contractBadge = '<span style="margin-left:6px;background:'+contractColor+';color:#fff;font-size:10px;font-weight:800;padding:2px 7px;border-radius:10px">'+bLabel+'</span>';
    }

    var rows = [
      {icon:'🏷️',label:'รหัส',val:b.code||'-',full:false},
      {icon:'📂',label:'ประเภท',val:b.type||'-',full:false},
      {icon:'📝',label:'รหัสรับ',val:b.recCode||'-',full:false},
      {icon:'📍',label:'เขต',val:b.zone||'-',full:false},
      {icon:'💰',label:'ค่าเช่า',val:rentFmt,full:false},
      {icon:'📞',label:'เบอร์บูธ',val:b.boothPhone||'-',full:false},
      {icon:'📋',label:'สัญญาบูธ',val:contractLabel,badge:contractBadge||'',full:true}
    ];
    if(b.staffName && b.staffName!=='-') rows.splice(3,0,{icon:'👤',label:'พนักงาน',val:b.staffName+(b.phone&&b.phone!=='-'?' ('+b.phone+')':''),full:true});

    /* Bell badge on card corner */
    var bellBadge = isOpen && isExpiring
      ? '<div style="position:absolute;top:10px;left:10px;z-index:20;background:#dc2626;border-radius:50%;width:28px;height:28px;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(220,38,38,.5);font-size:14px;animation:bellRing 1s ease-in-out infinite alternate">🔔</div>'
      : '';
    var ribbonColor = isOpen ? '#16a34a' : '#dc2626';
    var ribbonText  = isOpen ? 'เปิดอยู่' : 'ปิดแล้ว';
    var ribbon = '<div style="position:absolute;top:14px;right:-22px;width:90px;padding:4px 0;background:'+ribbonColor+';color:#fff;font-size:10px;font-weight:800;text-align:center;transform:rotate(45deg);box-shadow:0 2px 4px rgba(0,0,0,.2);letter-spacing:.5px;z-index:10">'+ribbonText+'</div>';

    var borderStyle = isExpiring ? '2px solid #fca5a5' : '1.5px solid #f1f5f9';

    return '<div class="bth-card" data-open="'+(isOpen?'1':'0')+'" data-idx="'+bi+'" style="background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,.07);border:'+borderStyle+';transition:box-shadow .2s;position:relative;cursor:pointer">'
      +ribbon+bellBadge
      +'<div style="background:'+col+';padding:16px 20px;display:flex;align-items:center;gap:14px">'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:15px;font-weight:800;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+b.name+'</div>'
      +'<div style="font-size:11px;color:rgba(255,255,255,.8);margin-top:2px">'+(isOpen?'🟢 เปิดกิจการอยู่':'🔴 '+b.status)+'</div>'
      +'</div></div>'
      +'<div style="padding:14px 20px;display:grid;grid-template-columns:1fr 1fr;gap:8px 12px">'
      +rows.map(function(r){
        return '<div style="'+(r.full?'grid-column:1/-1;':'')+'">'
          +'<div style="font-size:10px;color:#94a3b8;font-weight:600;text-transform:uppercase;letter-spacing:.5px">'+r.icon+' '+r.label+'</div>'
          +'<div style="font-size:12px;color:#334155;font-weight:600;margin-top:1px">'+r.val+(r.badge||'')+'</div>'
          +'</div>';
      }).join('')
      +'</div>'
      +'<div style="padding:8px 20px 13px;display:flex;justify-content:flex-end;border-top:1px solid #f1f5f9">'
      +'<span style="font-size:11px;color:#94a3b8;display:flex;align-items:center;gap:4px"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="7"/><line x1="16.5" y1="16.5" x2="22" y2="22"/></svg> ดูรายละเอียด</span>'
      +'</div>'
      +'</div>';
  }).join('');
  /* Bind click handlers */
  grid.querySelectorAll('.bth-card').forEach(function(card){
    var ii=parseInt(card.getAttribute('data-idx'),10);
    card.addEventListener('click',function(){openBoothModal(ii);});
  });

  /* Bplus codes grid */
  var cEl = document.getElementById('bthCodesGrid');
  if(cEl) cEl.innerHTML = BPLUS_CODES.map(function(c){
    return '<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0">'
      +'<span style="background:#0891b2;color:#fff;font-size:11px;font-weight:800;padding:2px 8px;border-radius:8px;flex-shrink:0">'+c.code+'</span>'
      +'<span style="font-size:12px;color:#334155;font-weight:600">'+c.name+'</span>'
      +'</div>';
  }).join('');

  /* Show alert popup if any open booth is expiring soon — once per session */
  if (expiring.length > 0 && !window._contractAlertShown) {
    window._contractAlertShown = true;
    setTimeout(function(){ _showContractAlert(expiring); }, 400);
  }
}

function renderBoothDailyAll() {
  var fmtV = function(v){return v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':Math.round(v).toLocaleString();};
  var months = _resolveMonths().filter(function(m){var i=MONTHS.indexOf(m);return i>=0&&MONTHLY_ACTUAL[i]>0;});
  var branches = Object.keys(BOOTH_DATA[months[0]]||{});
  var colors = ['#f97316','#0891b2','#10b981','#8b5cf6','#ef4444','#f59e0b','#06b6d4','#84cc16','#ec4899','#a78bfa','#14b8a6'];
  var kpiHtml = branches.map(function(br,bi){
    var tot=months.reduce(function(s,mo){return s+((BOOTH_DATA[mo]||{})[br]||{a:0}).a;},0);
    var tgt=months.reduce(function(s,mo){return s+((BOOTH_DATA[mo]||{})[br]||{t:0}).t;},0);
    var pct=tgt?(tot/tgt*100).toFixed(1):0;
    return '<div class="kpi-card" style="border-top:3px solid '+colors[bi%colors.length]+'">'
      +'<div class="kpi-label">'+br+'</div>'
      +'<div class="kpi-value" style="font-size:20px;color:'+colors[bi%colors.length]+'">'+fmtV(tot)+'</div>'
      +'<div class="kpi-sub">เป้า '+fmtV(tgt)+'</div>'
      +'<div class="kpi-badge '+(pct>=80?'pos':pct>=60?'warn':'neg')+'">'+pct+'%</div>'
      +'</div>';
  }).join('');
  var kEl=document.getElementById('boothDailyKPI2');
  if(kEl) kEl.innerHTML=kpiHtml;
  var datasets=branches.map(function(br,bi){
    return {label:br,data:months.map(function(mo){return ((BOOTH_DATA[mo]||{})[br]||{a:0}).a;}),backgroundColor:colors[bi%colors.length]+'cc',borderColor:colors[bi%colors.length],borderWidth:1,borderRadius:4};
  });
  var ctx2=document.getElementById('boothDailyChart2');
  if(ctx2){
    if(window._boothDailyChartInst)window._boothDailyChartInst.destroy();
    window._boothDailyChartInst=new Chart(ctx2.getContext('2d'),{type:'bar',data:{labels:months.map(function(m){return MONTHS_TH[MONTHS.indexOf(m)]||m;}),datasets:datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:function(v){return fmtV(v);}}}}}});
  }
  var thead='<thead><tr style="background:#f8fafc;font-size:12px;color:#64748b"><th style="padding:8px 12px;text-align:left">เดือน</th>'+branches.map(function(b){return'<th style="padding:8px 12px;text-align:right">'+b+'</th>';}).join('')+'<th style="padding:8px 12px;text-align:right">รวม</th></tr></thead>';
  var tbody='<tbody>'+months.map(function(mo){
    var vals=branches.map(function(br){return ((BOOTH_DATA[mo]||{})[br]||{a:0}).a;});
    var tot=vals.reduce(function(a,b){return a+b;},0);
    var mi=MONTHS.indexOf(mo);
    return '<tr style="border-bottom:1px solid #f1f5f9"><td style="padding:9px 12px;font-weight:600">'+(MONTHS_TH[mi]||mo)+'</td>'+vals.map(function(v,bi){return'<td style="padding:9px 12px;text-align:right;color:'+colors[bi%colors.length]+';font-weight:600">'+fmtV(v)+'</td>';}).join('')+'<td style="padding:9px 12px;text-align:right;font-weight:700">'+fmtV(tot)+'</td></tr>';
  }).join('')+'</tbody>';
  var tEl=document.getElementById('boothDailyTable2');
  if(tEl) tEl.innerHTML=thead+tbody;
}


var BOOTH_ACCOUNTS = {"ลำพยา 3 (ใหม่)": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ร้านใหม่ (ปตท.คุณาวรรณ)": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "หน้ามอ (ม.เกษตร)": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ลำพยา 3 (เก่า)": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ไทวัสดุ": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "แก้วมณีกาญ": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ลำพยา 2 (ใหม่)": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ธรรมศาลา": "ธนาคารไทยพาณิชย์ / พุฒิสรรค์ แกล้ววิกย์กิจ / 4321496962", "ตลาดดิโอโซน": "ธนาคารไทยพาณิชย์ / พุฒิสรรค์ แกล้ววิกย์กิจ / 4321496962", "ปตท.ราชบุรี": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360", "ศาลายา กม.26": "ธนาคารไทยพาณิชย์ / ภาณุวัชร วัฒนกิจรุ่งโรจน์ / 4047165360"};

function openBoothModal(idx) {
  /* Remove any existing overlay */
  var existing = document.getElementById('_bthOv');
  if (existing) existing.parentNode.removeChild(existing);

  var COLORS = ['#f97316','#0891b2','#10b981','#8b5cf6','#ef4444','#f59e0b','#06b6d4','#ec4899','#a78bfa','#14b8a6','#84cc16'];
  var sorted = BOOTH_INFO.slice().sort(function(a,b){
    var ao=a.status.indexOf('เปิดกิจการอยู่')>=0;
    var bo=b.status.indexOf('เปิดกิจการอยู่')>=0;
    return ao===bo?0:ao?-1:1;
  });
  var b = sorted[idx]; if(!b) return;
  var isOpen = b.status.indexOf('เปิดกิจการอยู่')>=0;
  var col = isOpen ? COLORS[idx % COLORS.length] : '#94a3b8';

  function row(icon, label, val, full) {
    if(!val || val==='-') return '';
    return '<div style="'+(full?'grid-column:1/-1;':'')+'">'
      +'<div style="font-size:10px;color:#94a3b8;font-weight:700;margin-bottom:2px">'+icon+' '+label+'</div>'
      +'<div style="font-size:13px;color:#1e293b;font-weight:600">'+val+'</div>'
      +'</div>';
  }
  var rent = (typeof b.rent==='number'&&b.rent>0)?String(b.rent).replace(/\B(?=(\d{3})+(?!\d))/g,',')+' บาท/เดือน':'-';
  var change = (b.change&&b.change!=='-')?b.change+' บาท':'-';

  var bodyHTML =
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px 18px;padding:20px 24px 24px">'
    +row('🏷','รหัสบูธ',b.code||'')
    +row('📂','ประเภท',b.type||'')
    +row('📝','รหัสบันทึกรับ',b.recCode||'')
    +row('📍','เขตการขาย',b.zone||'')
    +(b.staffName&&b.staffName!=='-'?row('👤','ชื่อพนักงาน',b.staffName,true):'')
    +row('📞','เบอร์พนักงาน',b.phone||'')
    +row('☎','เบอร์บูธ',b.boothPhone||'')
    +row('💰','ค่าเช่า',rent)
    +row('💵','เงินทอน',change)
    +row('🏦','เลขบัญชี',BOOTH_ACCOUNTS[b.name]||b.account||'',true)
    +(function(){
        var c=BOOTH_CONTRACT[b.name]||{iso:'',label:'-'};
        var d=_contractDaysLeft(c.iso);
        var lbl=c.label||'-';
        var badge='';
        if(d!==null&&d<=90){
          var urg=d<=7?'#dc2626':d<=14?'#ea580c':'#d97706';
          badge='<span style="margin-left:6px;background:'+urg+';color:#fff;font-size:10px;font-weight:800;padding:2px 8px;border-radius:10px">'+(d<=0?'หมดแล้ว!':'เหลือ '+d+' วัน')+'</span>';
        }
        return row('📋','สัญญาบูธ',lbl+badge,true);
      })()
    +'</div>';

  var photoHtml = b.photo
    ? '<div style="display:flex;justify-content:center;padding:16px 0 0">'
      +'<img src="'+b.photo+'" style="width:90px;height:90px;border-radius:50%;object-fit:cover;border:3px solid rgba(255,255,255,.6);box-shadow:0 4px 12px rgba(0,0,0,.25)">'
      +'</div>'
    : '';
  var ov = document.createElement('div');
  ov.id = '_bthOv';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML =
    '<div style="background:#fff;border-radius:20px;max-width:520px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.3);overflow:hidden;max-height:90vh;overflow-y:auto">'
    +'<div style="background:'+col+';padding:22px 24px 18px;position:relative">'
    +'<button id="_bthClose" style="position:absolute;top:14px;right:14px;background:rgba(255,255,255,.25);border:none;color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:18px;line-height:1">&#x2715;</button>'
    +photoHtml
    +'<div style="font-size:20px;font-weight:800;color:#fff;padding-right:40px;'+(b.photo?'text-align:center;margin-top:10px;':'')+'">'
    +(b.name||'')+'</div>'
    +'<div style="font-size:12px;color:rgba(255,255,255,.85);margin-top:4px;'+(b.photo?'text-align:center;':'')+'">'
    +(isOpen?'<span style="background:rgba(255,255,255,.25);padding:2px 10px;border-radius:10px">&#x1F7E2; เปิดกิจการอยู่</span>'
            :'<span style="background:rgba(0,0,0,.15);padding:2px 10px;border-radius:10px">&#x1F534; '+(b.status||'')+'</span>')
    +'</div></div>'
    +bodyHTML
    +'</div>';

  document.body.appendChild(ov);
  document.getElementById('_bthClose').onclick = function(){ document.body.removeChild(ov); };
  ov.addEventListener('click', function(e){ if(e.target===ov) document.body.removeChild(ov); });
}
function closeBoothModal() {
  var ov = document.getElementById('_bthOv');
  if(ov) ov.parentNode.removeChild(ov);
}

function renderBooth(){
  var boothData=getMonthData(BOOTH_DATA,currentMonth);
  var entries=Object.entries(boothData).sort(function(a,b){return b[1].a-a[1].a;});
  var totT=entries.reduce(function(s,e){return s+(e[1].t||0);},0),totA=entries.reduce(function(s,e){return s+(e[1].a||0);},0),ach=totT?totA/totT*100:0;
  var fmtM=function(v){return (v/1e6).toFixed(2)+' M';};
  var kEl=document.getElementById('boothKPI');
  if(kEl) kEl.innerHTML='<div class="kpi-card blue"><div class="kpi-label">Target</div><div class="kpi-value sm">'+fmtM(totT)+'</div></div><div class="kpi-card cyan"><div class="kpi-label">Actual</div><div class="kpi-value sm">'+fmtM(totA)+'</div><div class="kpi-badge '+(ach>=80?'pos':ach>=60?'warn':'neg')+'">'+ach.toFixed(1)+'% สำเร็จ</div></div><div class="kpi-card '+(totA>=totT?'green':'red')+'"><div class="kpi-label">% Achievement</div><div class="kpi-value sm">'+ach.toFixed(1)+'%</div></div>';
  var names=entries.map(function(e){return e[0];}),tVals=entries.map(function(e){return (e[1].t||0)/1e6;}),aVals=entries.map(function(e){return (e[1].a||0)/1e6;});
  mkChart('boothBar',{type:'bar',data:{labels:names.map(function(n){return n.length>10?n.slice(0,10)+'…':n;}),datasets:[{label:'Target',data:tVals,backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},{label:'Actual',data:aVals,backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}},x:{grid:{display:false},ticks:{maxRotation:30}}}}});
  var achVals=entries.map(function(e){return e[1].t?+(e[1].a/e[1].t*100).toFixed(1):0;});
  mkChart('boothAch',{type:'bar',data:{labels:names.map(function(n){return n.length>10?n.slice(0,10)+'…':n;}),datasets:[{label:'%',data:achVals,backgroundColor:achVals.map(function(v){return v>=80?'rgba(22,163,74,.7)':v>=60?'rgba(217,119,6,.7)':'rgba(220,38,38,.7)';}),borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:function(v){return v+'%';}},suggestedMax:120,grid:{color:'#f1f5f9'}},x:{grid:{display:false},ticks:{maxRotation:30}}}}});
  var bt=document.getElementById('boothTable');
  if(bt) bt.innerHTML=entries.map(function(e){var n=e[0],v=e[1],pct=v.t?v.a/v.t*100:0,col=pct>=80?'#16a34a':pct>=60?'#d97706':'#dc2626',bar=Math.min(pct,100);return'<tr style="border-bottom:1px solid #f1f5f9"><td style="padding:7px 10px;font-weight:600">'+n+'</td><td style="padding:7px 10px;text-align:right">'+fmtM(v.t||0)+'</td><td style="padding:7px 10px;text-align:right;color:#0891b2;font-weight:600">'+fmtM(v.a||0)+'</td><td style="padding:7px 10px;text-align:right;color:'+((v.a||0)>=(v.t||0)?'#16a34a':'#dc2626')+'">'+fmtM((v.a||0)-(v.t||0))+'</td><td style="padding:7px 10px;text-align:right;font-weight:700;color:'+col+'">'+pct.toFixed(1)+'%</td><td style="padding:7px 10px"><div style="background:#e2e8f0;border-radius:4px;height:8px"><div style="width:'+bar+'%;background:'+col+';height:8px;border-radius:4px"></div></div></td></tr>';}).join('');
}
function _renderChannel(chName,kpiId,barId,tableId){
  var months=_resolveMonths(),fmtM=function(v){return (v/1e6).toFixed(2)+' M';};
  var totT=0,totA=0;
  var rows=months.map(function(mo){var i=MONTHS.indexOf(mo);if(i<0)return null;var d=(CHANNEL_MONTHLY[mo]||{})[chName]||{t:0,a:0};totT+=d.t||0;totA+=d.a||0;return{label:MONTHS_TH[i],t:d.t||0,a:d.a||0};}).filter(Boolean);
  var ach=totT?totA/totT*100:0;
  var kEl=document.getElementById(kpiId);
  if(kEl) kEl.innerHTML='<div class="kpi-card blue"><div class="kpi-label">Target</div><div class="kpi-value sm">'+fmtM(totT)+'</div></div><div class="kpi-card cyan"><div class="kpi-label">Actual</div><div class="kpi-value sm">'+fmtM(totA)+'</div><div class="kpi-badge '+(ach>=80?'pos':ach>=60?'warn':'neg')+'">'+ach.toFixed(1)+'% สำเร็จ</div></div><div class="kpi-card '+(totA>=totT?'green':'red')+'"><div class="kpi-label">% Achievement</div><div class="kpi-value sm">'+ach.toFixed(1)+'%</div></div>';
  mkChart(barId,{type:'bar',data:{labels:rows.map(function(r){return r.label;}),datasets:[{label:'Target',data:rows.map(function(r){return r.t/1e6;}),backgroundColor:'rgba(79,70,229,.2)',borderColor:'#4f46e5',borderWidth:2,borderRadius:6},{label:'Actual',data:rows.map(function(r){return r.a/1e6;}),backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}},x:{grid:{display:false}}}}});
  var tb=document.getElementById(tableId);
  if(tb) tb.innerHTML=rows.map(function(r){var pct=r.t?r.a/r.t*100:0,col=pct>=80?'#16a34a':pct>=60?'#d97706':'#dc2626',bar=Math.min(pct,100);return'<tr style="border-bottom:1px solid #f1f5f9"><td style="padding:7px 10px;font-weight:600">'+r.label+'</td><td style="padding:7px 10px;text-align:right">'+fmtM(r.t)+'</td><td style="padding:7px 10px;text-align:right;color:#0891b2;font-weight:600">'+fmtM(r.a)+'</td><td style="padding:7px 10px;text-align:right;color:'+(r.a>=r.t?'#16a34a':'#dc2626')+'">'+fmtM(r.a-r.t)+'</td><td style="padding:7px 10px;text-align:right;font-weight:700;color:'+col+'">'+pct.toFixed(1)+'%</td><td style="padding:7px 10px"><div style="background:#e2e8f0;border-radius:4px;height:8px"><div style="width:'+bar+'%;background:'+col+';height:8px;border-radius:4px"></div></div></td></tr>';}).join('');
}
