function handleDataUpload(input,category){
  var files=input.files;
  if(!files||files.length===0) return;
  var lbl={
    ads:'ADS & Campaign',influencer:'อินฟลูเอนเซอร์',shipping:'ค่าขนส่ง',
    cod:'COD','return':'สินค้าตีกลับ',claim:'ออเดอร์ส่งเคลม',
    cancel:'ออเดอร์ยกเลิก',supply:'วัสดุสิ้นเปลือง',cost:'ต้นทุนขายสินค้า',
    'budget-actual':'เป้า vs จริง','channel-monthly':'ยอดขายรายช่อง','sales-staff':'ยอดขายพนักงาน'
  }[category]||category;
  var sp=document.getElementById('upload-status-'+category);
  if(sp) sp.innerHTML='<span style="color:#2563eb;font-weight:700">⏳ กำลังอ่านไฟล์...</span>';
  var file=files[0];
  var reader=new FileReader();
  reader.onload=function(e){
    try{
      var data=new Uint8Array(e.target.result);
      var wb=XLSX.read(data,{type:'array'});
      var sheets=wb.SheetNames;
      var allRows=[];
      var sheetPreviews=[];
      sheets.forEach(function(sn){
        var ws=wb.Sheets[sn];
        var json=XLSX.utils.sheet_to_json(ws,{defval:''});
        if(json.length>0){
          allRows=allRows.concat(json.map(function(r){r._sheet=sn;return r;}));
          sheetPreviews.push({name:sn,rows:json.length,cols:Object.keys(json[0]).length});
        }
      });
      if(allRows.length===0){
        if(sp) sp.innerHTML='<span style="color:#dc2626;font-weight:700">❌ ไม่พบข้อมูลในไฟล์</span>';
        return;
      }
      var storageKey='upload_'+category;
      try{localStorage.setItem(storageKey,JSON.stringify({ts:Date.now(),file:file.name,category:category,label:lbl,data:allRows}));}catch(ex){}
      var previewHtml='<div style="margin-top:8px;padding:10px;background:#f0fdf4;border:1px solid #86efac;border-radius:8px;font-size:11px">';
      previewHtml+='<div style="font-weight:800;color:#15803d;margin-bottom:6px">✅ อ่านสำเร็จ: '+file.name+'</div>';
      previewHtml+='<div style="color:#374151;margin-bottom:6px">พบ '+sheets.length+' sheet, '+allRows.length+' แถว</div>';
      sheetPreviews.forEach(function(s){previewHtml+='<span style="display:inline-block;background:#dcfce7;padding:2px 8px;border-radius:4px;margin:2px;font-size:10px">'+s.name+' ('+s.rows+' แถว, '+s.cols+' คอลัมน์)</span>';});
      var sampleKeys=Object.keys(allRows[0]).filter(function(k){return k!=='_sheet';});
      if(sampleKeys.length>0){
        previewHtml+='<div style="overflow-x:auto;margin-top:8px"><table style="border-collapse:collapse;font-size:10px;width:100%"><tr>';
        sampleKeys.forEach(function(k){previewHtml+='<th style="border:1px solid #d1d5db;padding:3px 6px;background:#e5e7eb;white-space:nowrap">'+k+'</th>';});
        previewHtml+='</tr>';
        var preview=allRows.slice(0,5);
        preview.forEach(function(row){
          previewHtml+='<tr>';
          sampleKeys.forEach(function(k){previewHtml+='<td style="border:1px solid #d1d5db;padding:3px 6px;white-space:nowrap">'+(row[k]!=null?row[k]:'')+'</td>';});
          previewHtml+='</tr>';
        });
        if(allRows.length>5) previewHtml+='<tr><td colspan="'+sampleKeys.length+'" style="border:1px solid #d1d5db;padding:3px 6px;color:#6b7280;text-align:center">... อีก '+(allRows.length-5)+' แถว</td></tr>';
        previewHtml+='</table></div>';
      }
      previewHtml+='<div style="color:#6b7280;margin-top:6px;font-size:10px">💾 บันทึกไว้ใน localStorage แล้ว (key: '+storageKey+')</div>';
      previewHtml+='</div>';
      if(sp) sp.innerHTML=previewHtml;
      if(category==='bank-income') _applyBankIncome(allRows, sp, previewHtml);
    }catch(err){
      console.error('Upload parse error:',err);
      if(sp) sp.innerHTML='<span style="color:#dc2626;font-weight:700">❌ อ่านไฟล์ผิดพลาด: '+err.message+'</span>';
    }
  };
  reader.readAsArrayBuffer(file);
  input.value='';
}

function _applyBankIncome(rows, sp, prevHtml){
  var _thToEnMap={'ม.ค.':'Jan','ก.พ.':'Feb','มี.ค.':'Mar','เม.ย.':'Apr','พ.ค.':'May','มิ.ย.':'Jun','ก.ค.':'Jul','ส.ค.':'Aug','ก.ย.':'Sep','ต.ค.':'Oct','พ.ย.':'Nov','ธ.ค.':'Dec'};
  var thToEn={}; Object.keys(_TH_MO_MAP).forEach(function(k){var c=_TH_MO_MAP[k];if(c&&_thToEnMap[c]) thToEn[k]=_thToEnMap[c];});
  var colMonth=null,colPlatform=null,colAmount=null;
  if(rows.length===0) return;
  var keys=Object.keys(rows[0]).filter(function(k){return k!=='_sheet';});
  keys.forEach(function(k){
    var kl=k.trim().toLowerCase();
    if(!colMonth&&(kl.indexOf('เดือน')>=0||kl==='month')) colMonth=k;
    if(!colPlatform&&(kl.indexOf('แพลตฟอร์ม')>=0||kl.indexOf('platform')>=0||kl.indexOf('ช่องทาง')>=0)) colPlatform=k;
    if(!colAmount&&(kl.indexOf('เข้าบัญชี')>=0||kl.indexOf('ยอด')>=0||kl.indexOf('revenue')>=0||kl.indexOf('amount')>=0||kl.indexOf('income')>=0)) colAmount=k;
  });
  if(!colMonth||!colAmount){
    if(sp) sp.innerHTML=prevHtml+'<div style="margin-top:6px;padding:8px;background:#fef2f2;border:1px solid #fca5a5;border-radius:6px;font-size:11px;color:#dc2626;font-weight:700">⚠️ ไม่พบคอลัมน์ "เดือน" หรือ "ยอดเงินเข้าบัญชี" — กรุณาตรวจหัวคอลัมน์ในไฟล์</div>';
    return;
  }
  var byMonth={};
  var updated=0;
  rows.forEach(function(r){
    var rawMo=String(r[colMonth]||'').trim().toLowerCase();
    var mo=thToEn[rawMo];
    if(!mo) return;
    var amt=parseFloat(String(r[colAmount]||'0').replace(/,/g,''));
    if(isNaN(amt)) amt=0;
    if(!byMonth[mo]) byMonth[mo]=0;
    byMonth[mo]+=amt;
    updated++;
  });
  if(updated===0){
    if(sp) sp.innerHTML=prevHtml+'<div style="margin-top:6px;padding:8px;background:#fef2f2;border:1px solid #fca5a5;border-radius:6px;font-size:11px;color:#dc2626;font-weight:700">⚠️ ไม่สามารถแปลงข้อมูลเดือนได้ — กรุณาตรวจค่าในคอลัมน์ "เดือน"</div>';
    return;
  }
  var d=_YEAR_MAP[_CY];
  if(!d) return;
  var ch=d.CHANNEL_MONTHLY;
  if(!ch) { d.CHANNEL_MONTHLY={}; ch=d.CHANNEL_MONTHLY; }
  var monthsUpdated=[];
  Object.keys(byMonth).forEach(function(mo){
    if(!ch[mo]) ch[mo]={};
    if(!ch[mo]['Online']) ch[mo]['Online']={t:0,a:0};
    ch[mo]['Online'].a=Math.round(byMonth[mo]);
    monthsUpdated.push(mo);
  });
  _applyYear(_CY);
  _buildSalesData(d);
  try{ renderOverview(); }catch(e){ console.error('re-render error:',e); }
  var fmtNum=function(n){return n.toLocaleString('th-TH');};
  var resultHtml='<div style="margin-top:6px;padding:8px;background:#eff6ff;border:1px solid #93c5fd;border-radius:6px;font-size:11px">';
  resultHtml+='<div style="font-weight:800;color:#1d4ed8;margin-bottom:4px">✅ อัพเดท Dashboard สำเร็จ!</div>';
  resultHtml+='<div style="color:#374151">อัพเดทยอด Online '+monthsUpdated.length+' เดือน: '+monthsUpdated.join(', ')+'</div>';
  monthsUpdated.forEach(function(mo){
    resultHtml+='<div style="color:#6b7280;padding-left:8px">• '+mo+': ฿'+fmtNum(byMonth[mo])+'</div>';
  });
  resultHtml+='</div>';
  if(sp) sp.innerHTML=prevHtml+resultHtml;
}

