var CASH_MONTHS_TH=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
var CASH_CH_KEYS=['tiktok','shopee','lazada','online','nadrub','line'];
var CASH_CH_LABELS=['Tiktok','Shopee','Lazada','ลูกค้าออนไลน์','นัดรับเปิดบิล','LINE'];
var CASH_CH_COLORS=['rgba(239,68,68,.75)','rgba(234,88,12,.75)','rgba(217,119,6,.75)','rgba(22,163,74,.75)','rgba(59,130,246,.75)','rgba(168,85,247,.75)'];

function renderCash67(){
  var fmtM=function(v){return v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':Math.round(v).toLocaleString();};
  var fmtB=function(v){return Math.round(v).toLocaleString();};
  var CASH_DATA=_getCashMap()[_cashYear]||{};
  var yearLabel='ปี '+_cashYear;
  var CASH_MONTHS_ACTIVE=CASH_MONTHS_TH.filter(function(m){return CASH_DATA[m];});
  var mos=CASH_MONTHS_ACTIVE;
  // Sync selects
  var _cys=document.getElementById('cashYearSel');if(_cys)_cys.value=_cashYear;
  var _cms=document.getElementById('cashMonthSel');
  if(_cms){
    var _avail=CASH_MONTHS_ACTIVE;
    _cms.innerHTML='<option value="">ทั้งหมด</option>'+_avail.map(function(m){return'<option value="'+m+'">'+m+'</option>';}).join('');
    if(_cashMo&&_avail.indexOf(_cashMo)<0)_cashMo='';
    _cms.value=_cashMo;
  }
  if(_cashMo) mos=mos.filter(function(m){return m===_cashMo;});

  // Totals
  var totGross=mos.reduce(function(s,m){return s+(CASH_DATA[m]?CASH_DATA[m].gross:0);},0);
  var totNet=mos.reduce(function(s,m){return s+(CASH_DATA[m]?CASH_DATA[m].net:0);},0);
  var totExp=totGross-totNet;
  var netPct=totGross?totNet/totGross*100:0;

  // KPI cards
  var kpis=[
    {label:'รายรับรวม (Gross)',val:fmtB(totGross),color:'#0891b2',icon:'💰'},
    {label:'ยอดสุทธิ (Net)',val:fmtB(totNet),color:'#16a34a',icon:'✅'},
    {label:'ค่าใช้จ่ายรวม',val:fmtB(totExp),color:'#dc2626',icon:'💸'},
    {label:'% ยอดสุทธิ',val:netPct.toFixed(1)+'%',color:'#7c3aed',icon:'📊'}
  ];
  var kEl=document.getElementById('cashKPI');
  if(kEl) kEl.innerHTML=kpis.map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');

  // Bar chart: Gross vs Net
  var grossVals=mos.map(function(m){return CASH_DATA[m]?CASH_DATA[m].gross:0;});
  var netVals=mos.map(function(m){return CASH_DATA[m]?CASH_DATA[m].net:0;});
  mkChart('cashBar',{type:'bar',data:{labels:mos,datasets:[
    {label:'ยอดรวมรับ (Gross)',data:grossVals.map(function(v){return Math.round(v/1e3)/1e3;}),backgroundColor:'rgba(8,145,178,.35)',borderColor:'#0891b2',borderWidth:2,borderRadius:6},
    {label:'ยอดสุทธิ (Net)',data:netVals.map(function(v){return Math.round(v/1e3)/1e3;}),backgroundColor:'rgba(22,163,74,.6)',borderColor:'#16a34a',borderWidth:2,borderRadius:6}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}},x:{grid:{display:false}}}}});

  // Table
  var tb=document.getElementById('cashTable');
  if(tb) tb.innerHTML=mos.map(function(m){
    var d=CASH_DATA[m]||{gross:0,net:0};
    var exp=d.gross-d.net;
    var pct=d.gross?d.net/d.gross*100:0;
    return'<tr style="border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:7px 10px;font-weight:600">'+m+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#0891b2;font-weight:600">'+fmtB(d.gross)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#16a34a;font-weight:700">'+fmtB(d.net)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#dc2626">'+fmtB(exp)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#7c3aed;font-weight:700">'+pct.toFixed(1)+'%</td>'+
    '</tr>';
  }).join('');

  // Channel bar chart
  mkChart('cashChannelBar',{type:'bar',data:{labels:mos,datasets:CASH_CH_KEYS.map(function(k,ki){
    return{label:CASH_CH_LABELS[ki],data:mos.map(function(m){return CASH_DATA[m]?Math.round((CASH_DATA[m].channels[k]||0)/1e3)/1e3:0;}),backgroundColor:CASH_CH_COLORS[ki],borderRadius:4};
  })},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{x:{stacked:true,grid:{display:false}},y:{stacked:true,ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}}}}});

  // Channel pie YTD
  var ytdCh=CASH_CH_KEYS.map(function(k){return mos.reduce(function(s,m){return s+(CASH_DATA[m]?CASH_DATA[m].channels[k]||0:0);},0);});
  var ytdTotal=ytdCh.reduce(function(s,v){return s+v;},0);
  mkChart('cashChannelPie',{type:'doughnut',data:{labels:CASH_CH_LABELS,datasets:[{data:ytdCh,backgroundColor:CASH_CH_COLORS,borderColor:'#fff',borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'55%',plugins:{legend:{position:'right',labels:{font:{size:11}}},
      tooltip:{callbacks:{label:function(c){return' '+c.label+': '+(ytdTotal?c.raw/ytdTotal*100:0).toFixed(1)+'%';}}}}}});

  // Channel detail table header + body
  var chHdr=document.getElementById('cashChHeader');
  if(chHdr) chHdr.innerHTML='<th style="padding:8px 12px;text-align:left">ช่องทาง</th>'+
    mos.map(function(m){return'<th style="padding:8px 12px;text-align:right">'+m+'</th>';}).join('')+
    '<th style="padding:8px 12px;text-align:right">YTD รวม</th>'+
    '<th style="padding:8px 12px;text-align:right">สัดส่วน</th>';
  var chTb=document.getElementById('cashChTable');
  if(chTb) chTb.innerHTML=CASH_CH_KEYS.map(function(k,ki){
    var rowYTD=ytdCh[ki];
    var pct=ytdTotal?rowYTD/ytdTotal*100:0;
    return'<tr style="border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:10px 12px;font-weight:700;color:'+CASH_CH_COLORS[ki].replace('rgba(','#').split(',')[0]+'">'+CASH_CH_LABELS[ki]+'</td>'+
      mos.map(function(m){return'<td style="padding:10px 12px;text-align:right">'+(CASH_DATA[m]?Math.round(CASH_DATA[m].channels[k]||0).toLocaleString():'-')+'</td>';}).join('')+
      '<td style="padding:10px 12px;text-align:right;font-weight:700">'+Math.round(rowYTD).toLocaleString()+'</td>'+
      '<td style="padding:10px 12px;text-align:right;color:#64748b">'+pct.toFixed(1)+'%</td>'+
    '</tr>';
  }).join('');
}

// ── เปรียบเทียบ view ──
function renderCompare67(){
  var fmtB=function(v){return Math.round(v).toLocaleString();};
  _cashYear=_olYear;
  var CASH_DATA=_getCashMap()[_olYear]||{};
  var yearLabel='ปี '+_olYear;
  var CASH_MONTHS_ACTIVE=CASH_MONTHS_TH.filter(function(m){return CASH_DATA[m];});
  var mos=_olMo&&CASH_MONTHS_ACTIVE.indexOf(_olMo)>=0?[_olMo]:CASH_MONTHS_ACTIVE;
  // Map TH months to the existing MONTHS_TH for order data
  var TH_TO_EN={'ม.ค.':'Jan','ก.พ.':'Feb','มี.ค.':'Mar','เม.ย.':'Apr','พ.ค.':'May','มิ.ย.':'Jun','ก.ค.':'Jul','ส.ค.':'Aug','ก.ย.':'Sep','ต.ค.':'Oct','พ.ย.':'Nov','ธ.ค.':'Dec'};

  // Get actual (order) per month from CHANNEL_MONTHLY
  var orderVals=mos.map(function(m){var en=TH_TO_EN[m];if(!en)return 0;var d=(CHANNEL_MONTHLY[en]||{})['Online']||{};return d.a||0;});
  var cashGross=mos.map(function(m){return CASH_DATA[m]?CASH_DATA[m].gross:0;});
  var cashNet=mos.map(function(m){return CASH_DATA[m]?CASH_DATA[m].net:0;});

  // KPI totals
  var totOrder=orderVals.reduce(function(s,v){return s+v;},0);
  var totGross=cashGross.reduce(function(s,v){return s+v;},0);
  var totNet=cashNet.reduce(function(s,v){return s+v;},0);
  var diff=totOrder-totNet;

  var kpis=[
    {label:'ยอด เปิดออเดอร์ YTD',val:(totOrder/1e6).toFixed(2)+'M',color:'#0891b2',icon:'📊'},
    {label:'เงินเข้าบัญชี Gross YTD',val:(totGross/1e6).toFixed(2)+'M',color:'#7c3aed',icon:'💰'},
    {label:'เงินเข้าบัญชี Net YTD',val:(totNet/1e6).toFixed(2)+'M',color:'#16a34a',icon:'✅'},
    {label:'ส่วนต่าง (Actual-Net)',val:(diff/1e6).toFixed(2)+'M',color:diff>=0?'#d97706':'#dc2626',icon:'⚖️'}
  ];
  var _ct=document.getElementById('compareBarTitle');if(_ct)_ct.textContent='⚖️ เปรียบเทียบยอดขาย: แบบเปิดออเดอร์ vs แบบเงินเข้าบัญชี '+yearLabel;
  var kEl=document.getElementById('compareKPI');
  if(kEl) kEl.innerHTML=kpis.map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');

  // Grouped bar chart
  mkChart('compareBar',{type:'bar',data:{labels:mos,datasets:[
    {label:'เปิดออเดอร์ (Actual)',data:orderVals.map(function(v){return Math.round(v/1e3)/1e3;}),backgroundColor:'rgba(8,145,178,.6)',borderColor:'#0891b2',borderWidth:2,borderRadius:6},
    {label:'เงินเข้าบัญชี (Gross)',data:cashGross.map(function(v){return Math.round(v/1e3)/1e3;}),backgroundColor:'rgba(124,58,237,.35)',borderColor:'#7c3aed',borderWidth:2,borderRadius:6},
    {label:'เงินเข้าบัญชี (Net)',data:cashNet.map(function(v){return Math.round(v/1e3)/1e3;}),backgroundColor:'rgba(22,163,74,.6)',borderColor:'#16a34a',borderWidth:2,borderRadius:6}
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{y:{ticks:{callback:function(v){return v+'M';}},grid:{color:'#f1f5f9'}},x:{grid:{display:false}}}}});

  // Table
  var tb=document.getElementById('compareTable');
  if(tb) tb.innerHTML=mos.map(function(m,i){
    var ord=orderVals[i],gr=cashGross[i],net=cashNet[i],d=ord-net;
    return'<tr style="border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:7px 10px;font-weight:600">'+m+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#0891b2;font-weight:600">'+fmtB(ord)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#7c3aed">'+fmtB(gr)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#16a34a;font-weight:700">'+fmtB(net)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;font-weight:700;color:'+(d>=0?'#d97706':'#dc2626')+'">'+fmtB(d)+'</td>'+
    '</tr>';
  }).join('');
}

