// ── ADS filter state ──
var _adsSelMonths=ADS_MONTHS.slice(),_adsRangeStart=ADS_MONTHS[0],_adsRangeEnd=ADS_MONTHS[ADS_MONTHS.length-1];
var _adsSelPlats=ADS_PLATFORMS.slice();
var _adsYear=2569,_adsMo='',_adsPlat='';

function adsResetFilters(){
  _adsSelMonths=ADS_MONTHS.slice();
  _adsRangeStart=ADS_MONTHS[0];
  _adsRangeEnd=ADS_MONTHS[ADS_MONTHS.length-1];
  _adsSelPlats=ADS_PLATFORMS.slice();
  renderAds();
}
function adsSetRange(start,end){
  var si=ADS_MONTHS.indexOf(start),ei=ADS_MONTHS.indexOf(end);
  if(si<0)si=0; if(ei<0)ei=ADS_MONTHS.length-1;
  if(si>ei){var tmp=si;si=ei;ei=tmp;}
  _adsRangeStart=ADS_MONTHS[si];
  _adsRangeEnd=ADS_MONTHS[ei];
  _adsSelMonths=ADS_MONTHS.slice(si,ei+1);
  renderAds();
}
function adsToggleMonth(mo){
  var i=_adsSelMonths.indexOf(mo);
  if(i>=0){if(_adsSelMonths.length>1)_adsSelMonths.splice(i,1);}
  else _adsSelMonths.push(mo);
  _adsSelMonths.sort(function(a,b){return ADS_MONTHS.indexOf(a)-ADS_MONTHS.indexOf(b);});
  renderAds();
}
function adsTogglePlat(p){
  var i=_adsSelPlats.indexOf(p);
  if(i>=0){if(_adsSelPlats.length>1)_adsSelPlats.splice(i,1);}
  else _adsSelPlats.push(p);
  renderAds();
}

function switchAdsInner(id, btn) {
  var sections = document.querySelectorAll('.ads-inner-section');
  for (var i = 0; i < sections.length; i++) sections[i].style.display = 'none';
  var target = document.getElementById(id);
  if (target) target.style.display = '';
  var btns = document.querySelectorAll('.ads-inner-tab');
  for (var j = 0; j < btns.length; j++) {
    btns[j].style.background = '#fff';
    btns[j].style.color = btns[j].style.borderColor;
    btns[j].classList.remove('ads-inner-active');
  }
  if (btn) {
    btn.style.background = btn.style.borderColor;
    btn.style.color = '#fff';
    btn.classList.add('ads-inner-active');
  }
  if (id === 'ads-entry') renderAdsDailyTable();
}

