function renderAds(){
  var fmt=function(v){return v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(1)+'K':Math.round(v).toLocaleString();};
  var fmtB=function(v){return Math.round(v).toLocaleString();};
  var fmtPct=function(v){return v.toFixed(2)+'%';};

  // Year routing via _getAdsMap()
  var _adsEntry=_getAdsMap()[_adsYear]||_getAdsMap()[_latestYear(_getAdsMap())]||{data:{},mo:[],moTh:[]};
  var ADS_DATA_CUR=_adsEntry.data,ADS_MO_CUR=_adsEntry.mo,ADS_MO_TH_CUR=_adsEntry.moTh;
  // Merge daily-entered data — only add months NOT already in hardcoded data
  var _dailyAgg = _getAdsDailyAggregated(_adsYear);
  var _dailyMoKeys = Object.keys(_dailyAgg);
  if (_dailyMoKeys.length) {
    var merged = {};
    Object.keys(ADS_DATA_CUR).forEach(function(k){ merged[k] = ADS_DATA_CUR[k]; });
    _dailyMoKeys.forEach(function(mo){ if(!ADS_DATA_CUR[mo]) merged[mo] = _dailyAgg[mo]; });
    ADS_DATA_CUR = merged;
    var allMoKeys = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var allMoTh = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
    var mergedKeys = Object.keys(merged);
    var newMo = [], newMoTh = [];
    allMoKeys.forEach(function(k,i){ if (mergedKeys.indexOf(k) >= 0) { newMo.push(k); newMoTh.push(allMoTh[i]); } });
    ADS_MO_CUR = newMo; ADS_MO_TH_CUR = newMoTh;
  }
  ADS_MONTHS=ADS_MO_CUR; ADS_MONTHS_TH=ADS_MO_TH_CUR;
  // Update month dropdown options for selected year
  var _aMS=document.getElementById('adsMonthSel');
  if(_aMS){
    if(_adsMo&&ADS_MO_TH_CUR.indexOf(_adsMo)<0)_adsMo='';
    _aMS.innerHTML='<option value="">ทั้งหมด</option>'+ADS_MO_TH_CUR.map(function(m){return'<option value="'+m+'">'+m+'</option>';}).join('');
    _aMS.value=_adsMo;
  }
  var _aPS=document.getElementById('adsPlatSel');if(_aPS)_aPS.value=_adsPlat;
  // Compute selMo and selPl from new globals
  var selMo,selPl;
  if(_adsMo){
    var _mi=ADS_MONTHS_TH.indexOf(_adsMo);
    selMo=_mi>=0?[ADS_MONTHS[_mi]]:ADS_MONTHS.slice();
  } else { selMo=ADS_MONTHS.slice(); }
  selPl=_adsPlat?[_adsPlat]:ADS_PLATFORMS.slice();
  _adsSelMonths=selMo; _adsSelPlats=selPl;

  // ── Compute totals for selected months & platforms ──
  // KPI: total sales = sum of selected platforms' sales across selected months
  var ytdSales=0,ytdAd=0;
  selMo.forEach(function(mo){
    selPl.forEach(function(p){
      ytdSales+=ADS_DATA_CUR[mo][p].sales;
      ytdAd+=ADS_DATA_CUR[mo][p].ad;
    });
  });
  var ytdPct=ytdSales?ytdAd/ytdSales*100:0;
  var ytdRoas=ytdAd?ytdSales/ytdAd:0;

  var periodLabel=selMo.length===ADS_MONTHS.length?'YTD 2569':selMo.map(function(mo){return ADS_MONTHS_TH[ADS_MONTHS.indexOf(mo)];}).join(', ');
  var platLabel=selPl.length===ADS_PLATFORMS.length?'ทุกแพลตฟอร์ม':selPl.join(', ');

  // Platform totals (filtered months)
  var platYtdSales=selPl.map(function(p){return selMo.reduce(function(s,mo){return s+ADS_DATA_CUR[mo][p].sales;},0);});
  var platYtdAd=selPl.map(function(p){return selMo.reduce(function(s,mo){return s+ADS_DATA_CUR[mo][p].ad;},0);});

  // KPI cards
  document.getElementById('adsKPI').innerHTML=[
    {label:'ยอดขายรวม (ADS)',val:fmt(ytdSales),sub:periodLabel+' · '+platLabel,color:'#4f46e5',icon:'💰'},
    {label:'ค่าแอดรวม',val:fmt(ytdAd),sub:periodLabel+' · '+platLabel,color:'#dc2626',icon:'📢'},
    {label:'เฉลี่ย % ค่าแอด',val:fmtPct(ytdPct),sub:'ต่อยอดขาย',color:ytdPct<=15?'#16a34a':ytdPct<=20?'#d97706':'#dc2626',icon:'📊'},
    {label:'ROAS เฉลี่ย',val:ytdRoas.toFixed(2)+'x',sub:'Return on Ad Spend',color:'#0891b2',icon:'🚀'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.6rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
      '<div style="font-size:11px;color:#94a3b8;margin-top:4px">'+k.sub+'</div>'+
    '</div>';
  }).join('');

  var moLabels=selMo.map(function(mo){return ADS_MONTHS_TH[ADS_MONTHS.indexOf(mo)];});

  // Chart 1: Combo — monthly total (sum of selected platforms) + ad%
  var trendSales=selMo.map(function(mo){return selPl.reduce(function(s,p){return s+ADS_DATA_CUR[mo][p].sales;},0);});
  var trendAd=selMo.map(function(mo){return selPl.reduce(function(s,p){return s+ADS_DATA_CUR[mo][p].ad;},0);});
  var trendPct=selMo.map(function(mo,i){return trendSales[i]?+(trendAd[i]/trendSales[i]*100).toFixed(2):0;});

  mkChart('adsTrendChart',{type:'bar',data:{
    labels:moLabels,
    datasets:[
      {type:'bar',label:'ยอดขาย (บาท)',data:trendSales,backgroundColor:'rgba(79,70,229,.55)',borderRadius:6,yAxisID:'y'},
      {type:'bar',label:'ค่าแอด (บาท)',data:trendAd,backgroundColor:'rgba(220,38,38,.55)',borderRadius:6,yAxisID:'y'},
      {type:'line',label:'% ค่าแอด',data:trendPct,borderColor:'#f59e0b',backgroundColor:'transparent',tension:.4,pointRadius:5,pointBackgroundColor:'#f59e0b',yAxisID:'y2'},
    ]
  },options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index'},plugins:{legend:{position:'top'}},
    scales:{y:{ticks:{callback:function(v){return v>=1e6?(v/1e6).toFixed(1)+'M':v+'K';}},grid:{color:'#f1f5f9'},title:{display:true,text:'บาท'}},
      y2:{position:'right',min:0,max:35,ticks:{callback:function(v){return v+'%';}},grid:{display:false},title:{display:true,text:'% ค่าแอด'}}}}});

  // Chart 2: Platform Sales grouped bar (selected platforms × selected months)
  var selPlColors=selPl.map(function(p){return ADS_PLAT_BG[ADS_PLATFORMS.indexOf(p)];});
  mkChart('adsSalesChart',{type:'bar',data:{labels:moLabels,datasets:selPl.map(function(p,pi){
    return{label:p,data:selMo.map(function(mo){return ADS_DATA_CUR[mo][p].sales;}),backgroundColor:selPlColors[pi],borderRadius:4};
  })},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'}}}}});

  // Chart 3: Platform Ad Spend grouped bar
  mkChart('adsSpendChart',{type:'bar',data:{labels:moLabels,datasets:selPl.map(function(p,pi){
    return{label:p,data:selMo.map(function(mo){return ADS_DATA_CUR[mo][p].ad;}),backgroundColor:selPlColors[pi],borderRadius:4};
  })},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'}}}}});

  // Chart 4: Ad% line chart per selected platform
  var selPlColors2=selPl.map(function(p){return ADS_PLAT_COLORS[ADS_PLATFORMS.indexOf(p)];});
  mkChart('adsPctChart',{type:'line',data:{labels:moLabels,datasets:selPl.map(function(p,pi){
    return{label:p,data:selMo.map(function(mo){return+ADS_DATA_CUR[mo][p].pct.toFixed(2);}),borderColor:selPlColors2[pi],backgroundColor:'transparent',tension:.4,pointRadius:4,pointBackgroundColor:selPlColors2[pi]};
  })},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},
    scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v+'%';}},grid:{color:'#f1f5f9'}}}}});

  // Chart 5: Pie — sales share by selected platform
  mkChart('adsPieChart',{type:'doughnut',data:{labels:selPl,datasets:[{data:platYtdSales,backgroundColor:selPlColors,borderColor:'#fff',borderWidth:2}]},
    options:{responsive:true,maintainAspectRatio:false,cutout:'55%',plugins:{legend:{position:'right',labels:{font:{size:12}}},
      tooltip:{callbacks:{label:function(c){return' '+c.label+': '+fmtPct(ytdSales?c.raw/ytdSales*100:0);}}}}}} );

  // Platform summary cards
  document.getElementById('adsPlatCards').innerHTML=selPl.map(function(p,pi){
    var s=platYtdSales[pi],a=platYtdAd[pi],pct=s?a/s*100:0,roas=a?s/a:0;
    var c=selPlColors2[pi];
    return'<div class="card" style="flex:1;min-width:200px;border-top:4px solid '+c+'">'+
      '<div style="font-size:18px;font-weight:800;color:'+c+';margin-bottom:8px">'+p+'</div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:12px">'+
        '<div><div style="color:#94a3b8">ยอดขาย</div><div style="font-weight:700;color:#1e293b">'+fmt(s)+'</div></div>'+
        '<div><div style="color:#94a3b8">ค่าแอด</div><div style="font-weight:700;color:#dc2626">'+fmt(a)+'</div></div>'+
        '<div><div style="color:#94a3b8">% ค่าแอด</div><div style="font-weight:700;color:'+(pct<=15?'#16a34a':pct<=20?'#d97706':'#dc2626')+'">'+fmtPct(pct)+'</div></div>'+
        '<div><div style="color:#94a3b8">ROAS</div><div style="font-weight:700;color:#0891b2">'+roas.toFixed(2)+'x</div></div>'+
      '</div>'+
    '</div>';
  }).join('');

  // Monthly detail table (only selected platforms shown as columns)
  var thead='<thead><tr style="background:#f8fafc;font-size:11px;color:#64748b">'+
    '<th style="padding:8px 10px;text-align:left">เดือน</th>'+
    ['รวม'].concat(selPl).map(function(p){
      return'<th style="padding:8px 10px;text-align:right;border-left:1px solid #e2e8f0" colspan="3">'+p+'</th>';
    }).join('')+
  '</tr><tr style="background:#f8fafc;font-size:10px;color:#94a3b8">'+
    '<th></th>'+
    ['รวม'].concat(selPl).map(function(){
      return'<th style="padding:4px 8px;text-align:right;border-left:1px solid #e2e8f0">ยอดขาย</th>'+
             '<th style="padding:4px 8px;text-align:right">ค่าแอด</th>'+
             '<th style="padding:4px 8px;text-align:right">%</th>';
    }).join('')+
  '</tr></thead>';

  var tbody='<tbody>'+selMo.map(function(mo){
    var mi=ADS_MONTHS.indexOf(mo);
    var d=ADS_DATA_CUR[mo];
    // row total = sum of selected platforms
    var rowS=selPl.reduce(function(s,p){return s+d[p].sales;},0);
    var rowA=selPl.reduce(function(s,p){return s+d[p].ad;},0);
    var rowP=rowS?rowA/rowS*100:0;
    var totCell='<td style="padding:8px 10px;text-align:right;border-left:1px solid #e2e8f0;background:#f8fafc;font-weight:700;color:#1e293b">'+fmtB(rowS)+'</td>'+
                '<td style="padding:8px 10px;text-align:right;background:#f8fafc;font-weight:700;color:#dc2626">'+fmtB(rowA)+'</td>'+
                '<td style="padding:8px 10px;text-align:right;background:#f8fafc;font-weight:700;color:'+(rowP<=15?'#16a34a':rowP<=20?'#d97706':'#dc2626')+'">'+fmtPct(rowP)+'</td>';
    var platCells=selPl.map(function(p,pi){
      var obj=d[p];var c=selPlColors2[pi];
      return'<td style="padding:8px 10px;text-align:right;border-left:1px solid #e2e8f0;font-weight:500;color:'+c+'">'+fmtB(obj.sales)+'</td>'+
             '<td style="padding:8px 10px;text-align:right;color:#dc2626">'+fmtB(obj.ad)+'</td>'+
             '<td style="padding:8px 10px;text-align:right;color:'+(obj.pct<=15?'#16a34a':obj.pct<=20?'#d97706':'#dc2626')+'">'+fmtPct(obj.pct)+'</td>';
    }).join('');
    return'<tr style="border-bottom:1px solid #f1f5f9"><td style="padding:8px 10px;font-weight:700">'+ADS_MONTHS_TH[mi]+'</td>'+totCell+platCells+'</tr>';
  }).join('');

  // Totals row
  var totCols=['sum'].concat(selPl).map(function(p,pi){
    var ts,ta;
    if(pi===0){ts=selMo.reduce(function(s,mo){return s+selPl.reduce(function(ss,pp){return ss+ADS_DATA_CUR[mo][pp].sales;},0);},0);
              ta=selMo.reduce(function(s,mo){return s+selPl.reduce(function(ss,pp){return ss+ADS_DATA_CUR[mo][pp].ad;},0);},0);}
    else{ts=selMo.reduce(function(s,mo){return s+ADS_DATA_CUR[mo][p].sales;},0);
         ta=selMo.reduce(function(s,mo){return s+ADS_DATA_CUR[mo][p].ad;},0);}
    var tp=ts?ta/ts*100:0;
    var bg=pi===0?'#f8fafc':'#fff';
    return'<td style="padding:8px 10px;text-align:right;border-left:1px solid #e2e8f0;background:'+bg+';font-weight:700">'+fmtB(ts)+'</td>'+
           '<td style="padding:8px 10px;text-align:right;background:'+bg+';font-weight:700;color:#dc2626">'+fmtB(ta)+'</td>'+
           '<td style="padding:8px 10px;text-align:right;background:'+bg+';font-weight:700;color:'+(tp<=15?'#16a34a':tp<=20?'#d97706':'#dc2626')+'">'+fmtPct(tp)+'</td>';
  }).join('');
  tbody+='<tr style="background:#f8fafc;border-top:2px solid #e2e8f0;font-weight:700"><td style="padding:8px 10px">รวม</td>'+totCols+'</tr></tbody>';

  document.getElementById('adsTable').innerHTML=thead+tbody;
}

// ============================================================
// ADS DAILY — ฟอร์มกรอกข้อมูลยิง ADS รายวัน
// localStorage key: adsDailyData
// ============================================================
var _adsDailyData = null;
var _adsDailyMonthFilter = '';
var _adsDailyYearFilter = 2569;

function _getAdsDailyData() {
  if (!_adsDailyData) {
    try { _adsDailyData = JSON.parse(localStorage.getItem('adsDailyData') || 'null'); } catch(e) {}
    if (!_adsDailyData) _adsDailyData = [];
  }
  return _adsDailyData;
}
function _saveAdsDailyData() {
  _lsSet('adsDailyData',_getAdsDailyData());
}
function _adsDailyId() { return 'AD' + Date.now().toString(36) + Math.random().toString(36).substr(2,4); }

var _ADS_PLAT_KEYS = ['Tiktok','Facebook','Lazada','Shopee'];

function _adsOpenDailyForm(editIdx) {
  var rows = _getAdsDailyData();
  var isEdit = typeof editIdx === 'number';
  var d = isEdit ? rows[editIdx] : {
    id: _adsDailyId(), date: '', year: 2569,
    Tiktok: {sales:0,ad:0}, Facebook: {sales:0,ad:0},
    Lazada: {sales:0,ad:0}, Shopee: {sales:0,ad:0}
  };

  var body = _custField('วันที่', 'ad_date', 'date', d.date, {required:true})
    + _custField('ปี (พ.ศ.)', 'ad_year', 'select', String(d.year), {options:['2567','2568','2569']});

  var platMeta = {
    Tiktok:  {color:'#ef4444', bg:'#fef2f2', border:'#fecaca', icon:'🎵'},
    Facebook:{color:'#3b82f6', bg:'#eff6ff', border:'#bfdbfe', icon:'📘'},
    Lazada:  {color:'#f59e0b', bg:'#fffbeb', border:'#fde68a', icon:'🛒'},
    Shopee:  {color:'#f97316', bg:'#fff7ed', border:'#fed7aa', icon:'🟠'}
  };

  _ADS_PLAT_KEYS.forEach(function(plat) {
    var m = platMeta[plat];
    var pData = d[plat] || {sales:0,ad:0};
    body += '<div style="grid-column:1/-1;background:'+m.bg+';border:1.5px solid '+m.border+';border-radius:10px;padding:14px 16px;margin-bottom:4px">';
    body += '<div style="font-size:14px;font-weight:700;color:'+m.color+';margin-bottom:10px">'+m.icon+' '+plat+'</div>';
    body += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px">';
    body += _custField('ยอดขาย (฿)', 'ad_'+plat+'_sales', 'number', pData.sales, {placeholder:'0.00'});
    body += _custField('ค่าแอด (฿)', 'ad_'+plat+'_ad', 'number', pData.ad, {placeholder:'0.00'});
    body += '</div></div>';
  });

  _custOpenModal((isEdit ? '✏️ แก้ไข' : '➕ เพิ่ม') + ' ข้อมูลยิง ADS รายวัน', body, function() {
    var dateVal = document.getElementById('ad_date').value;
    if (!dateVal) { alert('กรุณาเลือกวันที่'); return; }
    var yearVal = parseInt(document.getElementById('ad_year').value);

    var obj = { id: d.id, date: dateVal, year: yearVal };
    _ADS_PLAT_KEYS.forEach(function(plat) {
      var s = parseFloat(document.getElementById('ad_'+plat+'_sales').value) || 0;
      var a = parseFloat(document.getElementById('ad_'+plat+'_ad').value) || 0;
      obj[plat] = { sales: s, ad: a, pct: s ? (a/s*100) : 0 };
    });
    obj.totalSales = _ADS_PLAT_KEYS.reduce(function(sum,p){ return sum + obj[p].sales; }, 0);
    obj.totalAd = _ADS_PLAT_KEYS.reduce(function(sum,p){ return sum + obj[p].ad; }, 0);
    obj.totalPct = obj.totalSales ? (obj.totalAd / obj.totalSales * 100) : 0;

    if (isEdit) { rows[editIdx] = obj; }
    else { rows.push(obj); }
    _saveAdsDailyData();
    document.getElementById('custFormOverlay').remove();
    renderAdsDailyTable();
    renderAds();
  }, '#3b82f6');
}

function _adsDeleteDaily(idx) {
  var rows = _getAdsDailyData();
  if (!confirm('ลบข้อมูล ADS วันที่ ' + rows[idx].date + ' ?')) return;
  rows.splice(idx, 1);
  _saveAdsDailyData();
  renderAdsDailyTable();
  renderAds();
}

function _adsDailyCSV() {
  var rows = _getAdsDailyData();
  if (!rows.length) { alert('ไม่มีข้อมูลสำหรับดาวน์โหลด'); return; }
  var headers = ['วันที่','ปี','TikTok ยอดขาย','TikTok ค่าแอด','TikTok %','Facebook ยอดขาย','Facebook ค่าแอด','Facebook %','Lazada ยอดขาย','Lazada ค่าแอด','Lazada %','Shopee ยอดขาย','Shopee ค่าแอด','Shopee %','รวมยอดขาย','รวมค่าแอด','รวม%'];
  var csvRows = rows.map(function(d) {
    var r = [d.date, d.year];
    _ADS_PLAT_KEYS.forEach(function(p) {
      r.push(d[p].sales, d[p].ad, d[p].pct ? d[p].pct.toFixed(2) : '0');
    });
    r.push(d.totalSales||0, d.totalAd||0, d.totalPct ? d.totalPct.toFixed(2) : '0');
    return r;
  });
  _custExportCSV(csvRows, headers, 'ads_daily_' + new Date().toISOString().slice(0,10) + '.csv');
}

function _adsDailySetMonthFilter(mo) { _adsDailyMonthFilter = mo; renderAdsDailyTable(); }
function _adsDailySetYearFilter(yr) { _adsDailyYearFilter = yr; renderAdsDailyTable(); }

function renderAdsDailyTable() {
  var el = document.getElementById('adsDailySection');
  if (!el) return;
  var rows = _getAdsDailyData();
  var accent = '#3b82f6';

  var filtered = rows.filter(function(d) {
    if (d.year !== _adsDailyYearFilter) return false;
    if (_adsDailyMonthFilter) {
      var m = new Date(d.date).getMonth();
      var moIdx = _normMonthIdx(_adsDailyMonthFilter);
      if (m !== moIdx) return false;
    }
    return true;
  }).sort(function(a,b){ return a.date.localeCompare(b.date); });

  var h = '';

  // Year + Month filter
  h += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center">';
  h += '<select onchange="_adsDailySetYearFilter(parseInt(this.value))" style="padding:5px 10px;border-radius:8px;border:1.5px solid '+accent+';font-size:12px;font-weight:700;color:'+accent+'">';
  _yearsFromRows(_getAdsDailyData(),{2567:1,2568:1,2569:1}).forEach(function(y) {
    h += '<option value="'+y+'"'+(y===_adsDailyYearFilter?' selected':'')+'>ปี '+y+'</option>';
  });
  h += '</select>';
  h += '<select onchange="_adsDailySetMonthFilter(this.value)" style="padding:5px 10px;border-radius:8px;border:1.5px solid '+accent+';font-size:12px;font-weight:700;color:'+accent+'">';
  h += '<option value="">ทุกเดือน</option>';
  ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'].forEach(function(m) {
    h += '<option value="'+m+'"'+(m===_adsDailyMonthFilter?' selected':'')+'>'+m+'</option>';
  });
  h += '</select>';
  h += '</div>';

  // Toolbar
  h += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap">';
  h += '<button onclick="_adsOpenDailyForm()" style="padding:8px 18px;border:none;border-radius:8px;background:'+accent+';color:#fff;cursor:pointer;font-size:14px;font-weight:600">➕ เพิ่มข้อมูล ADS</button>';
  h += '<button onclick="_adsDailyCSV()" style="padding:8px 18px;border:1px solid #d1d5db;border-radius:8px;background:#fff;cursor:pointer;font-size:14px;color:#374151">⬇️ ดาวน์โหลด CSV</button>';
  h += '</div>';

  if (!filtered.length) {
    h += '<div style="text-align:center;padding:60px 20px;color:#94a3b8">';
    h += '<div style="font-size:48px;margin-bottom:12px">📢</div>';
    h += '<div style="font-size:16px;font-weight:600;margin-bottom:4px">ยังไม่มีข้อมูล ADS รายวัน</div>';
    h += '<div style="font-size:13px">กดปุ่ม ➕ ด้านบนเพื่อเพิ่มข้อมูล</div></div>';
  } else {
    // Summary
    var tSales = filtered.reduce(function(s,d){return s+(d.totalSales||0);},0);
    var tAd = filtered.reduce(function(s,d){return s+(d.totalAd||0);},0);
    var tPct = tSales ? (tAd/tSales*100) : 0;
    h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px;margin-bottom:16px">';
    h += '<div style="background:#eff6ff;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">จำนวนวัน</div><div style="font-size:1.3rem;font-weight:800;color:#3b82f6">'+filtered.length+'</div></div>';
    h += '<div style="background:#f0fdf4;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">ยอดขายรวม</div><div style="font-size:1.3rem;font-weight:800;color:#16a34a">'+Math.round(tSales).toLocaleString()+'</div></div>';
    h += '<div style="background:#fef2f2;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">ค่าแอดรวม</div><div style="font-size:1.3rem;font-weight:800;color:#dc2626">'+Math.round(tAd).toLocaleString()+'</div></div>';
    h += '<div style="background:#fefce8;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">% ค่าแอด</div><div style="font-size:1.3rem;font-weight:800;color:#d97706">'+tPct.toFixed(2)+'%</div></div>';
    h += '</div>';

    // Table matching the image format
    var platColors = {Tiktok:'#ef4444',Facebook:'#3b82f6',Lazada:'#f59e0b',Shopee:'#f97316'};
    h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11.5px">';
    // Header row 1: platform groups
    h += '<thead><tr style="background:#1e293b;color:#fff;font-size:11px">';
    h += '<th rowspan="2" style="padding:8px 6px;border:1px solid #334155;min-width:80px">วันที่</th>';
    _ADS_PLAT_KEYS.forEach(function(p) {
      h += '<th colspan="3" style="padding:8px 6px;border:1px solid #334155;text-align:center;background:'+platColors[p]+'cc">'+p+'</th>';
    });
    h += '<th colspan="2" style="padding:8px 6px;border:1px solid #334155;text-align:center;background:#475569">รวมค่าแอดทุกวัน</th>';
    h += '<th rowspan="2" style="padding:8px 6px;border:1px solid #334155;min-width:50px">จัดการ</th>';
    h += '</tr>';
    // Header row 2: sub columns
    h += '<tr style="background:#334155;color:#e2e8f0;font-size:10px">';
    _ADS_PLAT_KEYS.forEach(function() {
      h += '<th style="padding:4px 6px;border:1px solid #475569;text-align:right">ยอดขาย</th>';
      h += '<th style="padding:4px 6px;border:1px solid #475569;text-align:right">ค่าแอด</th>';
      h += '<th style="padding:4px 6px;border:1px solid #475569;text-align:right">%</th>';
    });
    h += '<th style="padding:4px 6px;border:1px solid #475569;text-align:right">รวมค่าแอดทุกวัน</th>';
    h += '<th style="padding:4px 6px;border:1px solid #475569;text-align:right">%</th>';
    h += '</tr></thead>';

    h += '<tbody>';
    filtered.forEach(function(d, i) {
      var realIdx = rows.indexOf(d);
      var rw = i%2===0?'#fff':'#f8fafc';
      h += '<tr style="background:'+rw+';border-bottom:1px solid #e2e8f0">';
      h += '<td style="padding:6px 8px;font-weight:600;white-space:nowrap;border-right:1px solid #e2e8f0">'+d.date+'</td>';
      _ADS_PLAT_KEYS.forEach(function(p) {
        var pd = d[p]||{sales:0,ad:0,pct:0};
        var pctColor = pd.pct<=15?'#16a34a':pd.pct<=20?'#d97706':'#dc2626';
        h += '<td style="padding:6px 6px;text-align:right;color:'+platColors[p]+'">'+(pd.sales?Math.round(pd.sales).toLocaleString():'–')+'</td>';
        h += '<td style="padding:6px 6px;text-align:right;color:#dc2626">'+(pd.ad?Math.round(pd.ad).toLocaleString():'–')+'</td>';
        h += '<td style="padding:6px 6px;text-align:right;color:'+pctColor+';border-right:1px solid #e2e8f0">'+(pd.pct?pd.pct.toFixed(1)+'%':'–')+'</td>';
      });
      var totPctColor = (d.totalPct||0)<=15?'#16a34a':(d.totalPct||0)<=20?'#d97706':'#dc2626';
      h += '<td style="padding:6px 6px;text-align:right;font-weight:700">'+(d.totalAd?Math.round(d.totalAd).toLocaleString():'–')+'</td>';
      h += '<td style="padding:6px 6px;text-align:right;font-weight:700;color:'+totPctColor+';border-right:1px solid #e2e8f0">'+(d.totalPct?d.totalPct.toFixed(1)+'%':'–')+'</td>';
      h += '<td style="padding:6px 4px;text-align:center;white-space:nowrap">';
      h += '<button onclick="_adsOpenDailyForm('+realIdx+')" style="padding:3px 8px;border:none;border-radius:4px;background:#3b82f6;color:#fff;cursor:pointer;font-size:10px">✏️</button> ';
      h += '<button onclick="_adsDeleteDaily('+realIdx+')" style="padding:3px 8px;border:none;border-radius:4px;background:#ef4444;color:#fff;cursor:pointer;font-size:10px">🗑️</button>';
      h += '</td></tr>';
    });

    // Totals row
    h += '<tr style="background:#f1f5f9;border-top:2px solid #1e293b;font-weight:700">';
    h += '<td style="padding:8px;font-weight:800">Total</td>';
    _ADS_PLAT_KEYS.forEach(function(p) {
      var ps = filtered.reduce(function(s,d){return s+((d[p]||{}).sales||0);},0);
      var pa = filtered.reduce(function(s,d){return s+((d[p]||{}).ad||0);},0);
      var pp = ps ? (pa/ps*100) : 0;
      h += '<td style="padding:6px;text-align:right;color:'+platColors[p]+'">'+Math.round(ps).toLocaleString()+'</td>';
      h += '<td style="padding:6px;text-align:right;color:#dc2626">'+Math.round(pa).toLocaleString()+'</td>';
      h += '<td style="padding:6px;text-align:right;border-right:1px solid #e2e8f0">'+pp.toFixed(1)+'%</td>';
    });
    h += '<td style="padding:6px;text-align:right;font-weight:800">'+Math.round(tAd).toLocaleString()+' บาท</td>';
    h += '<td style="padding:6px;text-align:right;font-weight:800;color:'+(tPct<=15?'#16a34a':tPct<=20?'#d97706':'#dc2626')+'">'+tPct.toFixed(1)+'%</td>';
    h += '<td></td></tr>';
    h += '</tbody></table></div>';
  }

  el.innerHTML = h;
}

// Admin panel: ADS data view
function renderAdminAds() {
  var el = document.getElementById('adminAdsBody');
  if (!el) return;
  var rows = _getAdsDailyData();
  if (!rows.length) {
    el.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8"><div style="font-size:40px;margin-bottom:8px">📢</div><div>ยังไม่มีข้อมูล ADS รายวัน — ไปกรอกได้ที่หน้า Online > ADS & Campaign</div></div>';
    return;
  }
  var h = '<div style="margin:16px 0;font-size:14px;color:#475569">รายการข้อมูล ADS รายวันทั้งหมด: <b>'+rows.length+'</b> รายการ</div>';
  h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:12px">';
  h += '<thead><tr style="background:#f8fafc"><th style="padding:8px;border:1px solid #e2e8f0">#</th><th style="padding:8px;border:1px solid #e2e8f0">วันที่</th><th style="padding:8px;border:1px solid #e2e8f0">ปี</th>';
  _ADS_PLAT_KEYS.forEach(function(p) {
    h += '<th style="padding:8px;border:1px solid #e2e8f0">'+p+' ยอดขาย</th><th style="padding:8px;border:1px solid #e2e8f0">'+p+' ค่าแอด</th>';
  });
  h += '<th style="padding:8px;border:1px solid #e2e8f0">รวมค่าแอด</th><th style="padding:8px;border:1px solid #e2e8f0">จัดการ</th></tr></thead><tbody>';
  rows.forEach(function(d,i) {
    h += '<tr><td style="padding:6px;border:1px solid #e2e8f0;text-align:center">'+(i+1)+'</td>';
    h += '<td style="padding:6px;border:1px solid #e2e8f0">'+d.date+'</td>';
    h += '<td style="padding:6px;border:1px solid #e2e8f0;text-align:center">'+d.year+'</td>';
    _ADS_PLAT_KEYS.forEach(function(p) {
      var pd = d[p]||{sales:0,ad:0};
      h += '<td style="padding:6px;border:1px solid #e2e8f0;text-align:right">'+Math.round(pd.sales).toLocaleString()+'</td>';
      h += '<td style="padding:6px;border:1px solid #e2e8f0;text-align:right;color:#dc2626">'+Math.round(pd.ad).toLocaleString()+'</td>';
    });
    h += '<td style="padding:6px;border:1px solid #e2e8f0;text-align:right;font-weight:700">'+Math.round(d.totalAd||0).toLocaleString()+'</td>';
    h += '<td style="padding:6px;border:1px solid #e2e8f0;text-align:center">';
    h += '<button onclick="_adsOpenDailyForm('+i+')" style="padding:3px 10px;border:none;border-radius:4px;background:#3b82f6;color:#fff;cursor:pointer;font-size:11px;margin-right:4px">✏️</button>';
    h += '<button onclick="_adsDeleteDaily('+i+');renderAdminAds()" style="padding:3px 10px;border:none;border-radius:4px;background:#ef4444;color:#fff;cursor:pointer;font-size:11px">🗑️</button>';
    h += '</td></tr>';
  });
  h += '</tbody></table></div>';
  el.innerHTML = h;
}

// Aggregate daily data into monthly summaries for renderAds integration
function _getAdsDailyAggregated(year) {
  var rows = _getAdsDailyData().filter(function(d){ return d.year === year; });
  var moKeys = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var result = {};
  rows.forEach(function(d) {
    var m = new Date(d.date).getMonth();
    var moKey = moKeys[m];
    if (!result[moKey]) {
      result[moKey] = {};
      _ADS_PLAT_KEYS.forEach(function(p){ result[moKey][p] = {sales:0,ad:0}; });
      result[moKey].total = {sales:0,ad:0};
    }
    _ADS_PLAT_KEYS.forEach(function(p) {
      var pd = d[p]||{sales:0,ad:0};
      result[moKey][p].sales += pd.sales;
      result[moKey][p].ad += pd.ad;
      result[moKey].total.sales += pd.sales;
      result[moKey].total.ad += pd.ad;
    });
  });
  Object.keys(result).forEach(function(mo) {
    _ADS_PLAT_KEYS.forEach(function(p) {
      result[mo][p].pct = result[mo][p].sales ? (result[mo][p].ad / result[mo][p].sales * 100) : 0;
    });
    result[mo].total.pct = result[mo].total.sales ? (result[mo].total.ad / result[mo].total.sales * 100) : 0;
  });
  return result;
}

// ── Influencer ──────────────────────────────────────────────
var _influYear=2569;
function renderInfluencer(yr){
  if(yr!==undefined) _influYear=yr;
  var yr=_influYear;
  var fmt=function(v){return v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(1)+'K':Math.round(v).toLocaleString();};
  var data=INFLU_DATA[yr]||[];

  // Year/month selects sync
  var _iYS=document.getElementById('influYearSel');if(_iYS)_iYS.value=String(yr);
  var _avInMo=[...new Set(data.map(function(d){return d.month;}))].sort(function(a,b){return _normMonthIdx(a)-_normMonthIdx(b);});
  var _iMS=document.getElementById('influMonthSel');
  if(_iMS){_iMS.innerHTML='<option value="">ทั้งหมด</option>'+_avInMo.map(function(m){return'<option value="'+m+'"'+(_influMo===m?' selected':'')+'>'+m+'</option>';}).join('');}
  if(_influMo) data=data.filter(function(d){return d.month===_influMo;});

  // Totals
  var totalFee=data.reduce(function(s,d){return s+d.fee;},0);
  var avgFee=data.length?totalFee/data.length:0;

  // Platform breakdown
  var platMap={};
  data.forEach(function(d){
    var p=d.platform.split('/')[0].trim();
    platMap[p]=(platMap[p]||0)+1;
  });
  var topPlat=Object.keys(platMap).sort(function(a,b){return platMap[b]-platMap[a];})[0]||'–';

  // Monthly breakdown
  var moOrder=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var moFee={},moCount={};
  moOrder.forEach(function(m){moFee[m]=0;moCount[m]=0;});
  data.forEach(function(d){if(moFee[d.month]!==undefined){moFee[d.month]+=d.fee;moCount[d.month]++;}});
  var activeMo=moOrder.filter(function(m){return moFee[m]>0||moCount[m]>0;});

  // KPI
  document.getElementById('influKPI').innerHTML=[
    {label:'จำนวนอินฟลูเอนเซอร์',val:data.length+' คน',sub:'ปี '+yr,color:'#4f46e5',icon:'👥'},
    {label:'ค่าจ้างรวม',val:fmt(totalFee)+' บาท',sub:'ปี '+yr,color:'#dc2626',icon:'💰'},
    {label:'เฉลี่ยต่อคน',val:fmt(avgFee)+' บาท',sub:'ต่อ 1 อินฟลู',color:'#d97706',icon:'📊'},
    {label:'แพลตฟอร์มหลัก',val:topPlat,sub:(platMap[topPlat]||0)+' คน',color:'#0891b2',icon:'📱'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.5rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
      '<div style="font-size:11px;color:#94a3b8;margin-top:4px">'+k.sub+'</div></div>';
  }).join('');

  // Pie: platform
  var platKeys=Object.keys(platMap);
  var platColors=['#ef4444','#3b82f6','#f59e0b','#10b981','#8b5cf6','#f97316'];
  if(data.length===0){
    document.getElementById('influPlatPie').getContext('2d').clearRect(0,0,400,300);
    if(window._charts&&window._charts['influPlatPie']){window._charts['influPlatPie'].destroy();delete window._charts['influPlatPie'];}
  } else {
    mkChart('influPlatPie',{type:'doughnut',data:{labels:platKeys,datasets:[{data:platKeys.map(function(p){return platMap[p];}),backgroundColor:platColors.slice(0,platKeys.length),borderColor:'#fff',borderWidth:2}]},
      options:{responsive:true,maintainAspectRatio:false,cutout:'55%',plugins:{legend:{position:'right',labels:{font:{size:12}}},
        tooltip:{callbacks:{label:function(c){return' '+c.label+': '+c.raw+' คน';}}}}}});
  }

  // Bar: monthly fee
  var barColors=activeMo.map(function(){return'rgba(79,70,229,.7)';});
  if(data.length===0||activeMo.length===0){
    if(window._charts&&window._charts['influMonthBar']){window._charts['influMonthBar'].destroy();delete window._charts['influMonthBar'];}
  } else {
    mkChart('influMonthBar',{type:'bar',data:{labels:activeMo,datasets:[{label:'ค่าจ้าง (บาท)',data:activeMo.map(function(m){return moFee[m];}),backgroundColor:barColors,borderRadius:6}]},
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},
        scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'}}}}});
  }

  // Year comparison bar
  var yrFees=INFLU_YEARS.map(function(y){return(INFLU_DATA[y]||[]).reduce(function(s,d){return s+d.fee;},0);});
  var yrCounts=INFLU_YEARS.map(function(y){return(INFLU_DATA[y]||[]).length;});
  mkChart('influYearBar',{type:'bar',data:{labels:INFLU_YEAR_LABELS,datasets:[
    {label:'ค่าจ้างรวม (บาท)',data:yrFees,backgroundColor:INFLU_YEARS.map(function(y){return y===yr?'rgba(79,70,229,.85)':'rgba(79,70,229,.3)';}),borderRadius:8,yAxisID:'y'},
    {type:'line',label:'จำนวน (คน)',data:yrCounts,borderColor:'#f59e0b',backgroundColor:'transparent',tension:.4,pointRadius:6,pointBackgroundColor:'#f59e0b',yAxisID:'y2'},
  ]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index'},plugins:{legend:{position:'top'}},
    scales:{y:{ticks:{callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'},title:{display:true,text:'บาท'}},
      y2:{position:'right',min:0,ticks:{callback:function(v){return v+' คน';}},grid:{display:false}}}}});

  // Table
  document.getElementById('influTableTitle').textContent='📋 รายชื่ออินฟลูเอนเซอร์ ปี '+yr+' ('+data.length+' คน)';
  if(data.length===0){
    document.getElementById('influTable').innerHTML='<tr><td style="padding:20px;text-align:center;color:#94a3b8">ไม่มีข้อมูล</td></tr>';
    return;
  }
  var hStyle='padding:9px 12px;text-align:left;font-size:11px;font-weight:700;color:#64748b;background:#f8fafc;border-bottom:2px solid #e2e8f0;white-space:nowrap';
  var thead='<thead><tr>'+
    ['#','ชื่อ–นามสกุล','ชื่อเพจ / Account','แพลตฟอร์ม','เดือน','ค่าจ้าง','ยอดวิว','สถานะ'].map(function(h){return'<th style="'+hStyle+'">'+h+'</th>';}).join('')+
  '</tr></thead>';
  var tbody='<tbody>'+data.map(function(d,i){
    var platColor=d.platform.toLowerCase().indexOf('tiktok')>=0?'#ef4444':d.platform.toLowerCase().indexOf('facebook')>=0?'#3b82f6':'#10b981';
    var feeColor=d.fee>=10000?'#dc2626':d.fee>=3000?'#d97706':'#16a34a';
    var rw=i%2===0?'#fff':'#f8fafc';
    return'<tr style="background:'+rw+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:8px 12px;color:#94a3b8;font-size:12px">'+(i+1)+'</td>'+
      '<td style="padding:8px 12px;font-weight:600;color:#1e293b">'+d.name+'</td>'+
      '<td style="padding:8px 12px;color:#4f46e5;font-size:12px">'+d.page+'</td>'+
      '<td style="padding:8px 12px"><span style="background:'+platColor+'22;color:'+platColor+';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700">'+d.platform+'</span></td>'+
      '<td style="padding:8px 12px;font-size:12px;color:#64748b">'+d.month+'</td>'+
      '<td style="padding:8px 12px;font-weight:700;color:'+feeColor+';text-align:right">'+(d.fee?d.fee.toLocaleString():'-')+'</td>'+
      '<td style="padding:8px 12px;font-size:12px;color:#475569;text-align:right">'+d.views+'</td>'+
      '<td style="padding:8px 12px"><span style="background:#dcfce7;color:#16a34a;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600">'+d.status+'</span></td>'+
    '</tr>';
  }).join('')+'</tbody>';
  document.getElementById('influTable').innerHTML=thead+tbody;
}

