var _olView='order'; // 'order'|'cash'|'compare'
var _olYear=2569,_olMo=''; // shared year/month filter for all 3 views
// aliases kept for backward compat
var _orderMo='',_cashYear=2569,_cashMo='';
var _shipYear=2569,_shipMo='';
var _shipRecYear=2569,_shipRecMo='ม.ค.',_shipRecPage=0;
var _shipRecPageSize=50;
function renderShipRecords(){
  var moOrder=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var fmtN=function(v){return v?v.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}):'-';};
  var yrSel=document.getElementById('shipRecYearSel');
  yrSel.innerHTML=_sortedNumKeys(SHIP_RECORDS).map(function(y){
    return'<option value="'+y+'"'+(y===_shipRecYear?' selected':'')+'>ปี '+y+'</option>';
  }).join('');
  var yrRec=SHIP_RECORDS[String(_shipRecYear)]||{};
  var availMo=moOrder.filter(function(m){return yrRec[m]&&yrRec[m].length>0;});
  if(availMo.indexOf(_shipRecMo)<0)_shipRecMo=availMo[0]||'ม.ค.';
  var moSel=document.getElementById('shipRecMonthSel');
  moSel.innerHTML=availMo.map(function(m){
    return'<option value="'+m+'"'+(m===_shipRecMo?' selected':'')+'>'+m+'</option>';
  }).join('');
  var q=(document.getElementById('shipRecSearch').value||'').toLowerCase().trim();
  var allRows=yrRec[_shipRecMo]||[];
  var rows=q?allRows.filter(function(r){
    return(r[1]||'').toLowerCase().indexOf(q)>=0||(r[4]||'').toLowerCase().indexOf(q)>=0||(r[5]||'').toLowerCase().indexOf(q)>=0;
  }):allRows;
  var total=rows.length;
  var pages=Math.max(1,Math.ceil(total/_shipRecPageSize));
  if(_shipRecPage>=pages)_shipRecPage=0;
  var start=_shipRecPage*_shipRecPageSize;
  var slice=rows.slice(start,start+_shipRecPageSize);
  var infoTxt=q?'ผลการค้นหา "<b>'+q+'</b>" : '+(start+1)+'–'+Math.min(start+_shipRecPageSize,total)+' จาก <b>'+total.toLocaleString()+'</b> รายการ':'แสดง '+(total?start+1:0)+'–'+Math.min(start+_shipRecPageSize,total)+' จาก <b>'+total.toLocaleString()+'</b> รายการ เดือน '+_shipRecMo+' ปี '+_shipRecYear;
  document.getElementById('shipRecInfo').innerHTML=infoTxt;
  document.getElementById('shipRecTable').innerHTML=slice.map(function(r,i){
    var bg=(start+i)%2===0?'#fff':'#f8fafc';
    return'<tr style="background:'+bg+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:6px 10px;color:#94a3b8">'+(start+i+1)+'</td>'+
      '<td style="padding:6px 10px;font-weight:600;white-space:nowrap">'+_shipRecMo+'</td>'+
      '<td style="padding:6px 10px;color:#1e293b">'+r[1]+'</td>'+
      '<td style="padding:6px 10px;font-family:monospace;font-size:11px;color:#4f46e5">'+r[4]+'</td>'+
      '<td style="padding:6px 10px"><span style="background:#e0f2fe;color:#0369a1;padding:2px 7px;border-radius:8px;font-size:10px;font-weight:700">'+r[5]+'</span></td>'+
      '<td style="padding:6px 10px;text-align:right;color:#d97706">'+fmtN(r[6])+'</td>'+
      '<td style="padding:6px 10px;text-align:right;color:#4f46e5;font-weight:600">'+fmtN(r[7])+'</td>'+
      '<td style="padding:6px 10px;text-align:right;color:#dc2626;font-weight:600">'+fmtN(r[8])+'</td>'+
      '<td style="padding:6px 10px;color:#64748b;font-size:11px;min-width:260px">'+r[9]+'</td>'+
    '</tr>';
  }).join('');
  var pagerBtns='';
  if(pages>1){
    if(_shipRecPage>0)pagerBtns+='<button onclick="_shipRecPage='+(_shipRecPage-1)+';renderShipRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;font-size:12px">◀</button>';
    var lo=Math.max(0,_shipRecPage-2),hi=Math.min(pages-1,_shipRecPage+2);
    for(var pg=lo;pg<=hi;pg++){var ac=pg===_shipRecPage;pagerBtns+='<button onclick="_shipRecPage='+pg+';renderShipRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid '+(ac?'#0891b2':'#e2e8f0')+';background:'+(ac?'#0891b2':'#fff')+';color:'+(ac?'#fff':'#1e293b')+';font-weight:'+(ac?'700':'400')+';cursor:pointer;font-size:12px">'+(pg+1)+'</button>';}
    if(_shipRecPage<pages-1)pagerBtns+='<button onclick="_shipRecPage='+(_shipRecPage+1)+';renderShipRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;font-size:12px">▶</button>';
  }
  document.getElementById('shipRecPager').innerHTML=pagerBtns;
}
function renderShipping(yr){
  if(yr!==undefined)_shipYear=yr;
  var data=SHIPPING_DATA[_shipYear]||[];
  var fmtB=function(v){return v.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});};
  var _sYS=document.getElementById('shipYearSel');if(_sYS)_sYS.value=String(_shipYear);
  var _avShMo=data.map(function(r){return r.mo;});
  var _sMS=document.getElementById('shipMonthSel');
  if(_sMS){_sMS.innerHTML='<option value="">ทั้งหมด</option>'+_avShMo.map(function(m){return'<option value="'+m+'"'+(_shipMo===m?' selected':'')+'>'+m+'</option>';}).join('');}
  var filtData=_shipMo?data.filter(function(r){return r.mo===_shipMo;}):data;
  var data=filtData;
  var totParcels=data.reduce(function(s,r){return s+r.parcels;},0);
  var totFreight=data.reduce(function(s,r){return s+r.freight;},0);
  var totTotal=data.reduce(function(s,r){return s+r.total;},0);
  var avgPerParcel=totParcels?totTotal/totParcels:0;
  document.getElementById('shippingKPI').innerHTML=[
    {label:'พัสดุรวมทั้งปี',val:totParcels.toLocaleString()+' ชิ้น',color:'#0891b2',icon:'📦'},
    {label:'ค่าขนส่งรวม',val:fmtB(totFreight)+' บาท',color:'#4f46e5',icon:'💰'},
    {label:'Total Charge รวม',val:fmtB(totTotal)+' บาท',color:'#dc2626',icon:'🧾'},
    {label:'ค่าเฉลี่ย/ชิ้น',val:avgPerParcel.toFixed(2)+' บาท',color:'#16a34a',icon:'📊'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');
  document.getElementById('shippingTableTitle').textContent='📋 สรุปรายเดือน ปี '+_shipYear;
  var labels=data.map(function(r){return r.mo;});
  mkChart('shippingParcelChart',{type:'bar',data:{labels:labels,datasets:[{label:'พัสดุรวม',data:data.map(function(r){return r.parcels;}),backgroundColor:'rgba(8,145,178,.65)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'}}}}});
  mkChart('shippingCostChart',{type:'bar',data:{labels:labels,datasets:[{label:'ค่าขนส่ง',data:data.map(function(r){return r.freight;}),backgroundColor:'rgba(79,70,229,.65)',borderRadius:6},{label:'Total Charge',data:data.map(function(r){return r.total;}),backgroundColor:'rgba(220,38,38,.4)',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{x:{grid:{display:false}},y:{ticks:{callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},grid:{color:'#f1f5f9'}}}}});
  var ytdParc=0,ytdFreight=0,ytdTotal=0;
  var rows=data.map(function(r,i){
    ytdParc+=r.parcels;ytdFreight+=r.freight;ytdTotal+=r.total;
    var avg=r.parcels?r.total/r.parcels:0;
    var bg=i%2===0?'#fff':'#f8fafc';
    return'<tr style="background:'+bg+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:8px 12px;font-weight:600">'+r.mo+'</td>'+
      '<td style="padding:8px 12px;text-align:right">'+r.parcels.toLocaleString()+'</td>'+
      '<td style="padding:8px 12px;text-align:right;color:#64748b">'+r.cod_parcels.toLocaleString()+'</td>'+
      '<td style="padding:8px 12px;text-align:right">-</td>'+
      '<td style="padding:8px 12px;text-align:right;color:#4f46e5;font-weight:600">'+fmtB(r.freight)+'</td>'+
      '<td style="padding:8px 12px;text-align:right;color:#dc2626;font-weight:600">'+fmtB(r.total)+'</td>'+
      '<td style="padding:8px 12px;text-align:right;color:#16a34a">'+avg.toFixed(2)+'</td>'+
    '</tr>';
  }).join('');
  rows+='<tr style="background:#e2e8f0;font-weight:800;font-size:13px;border-top:2px solid #cbd5e1">'+
    '<td style="padding:8px 12px">รวม</td>'+
    '<td style="padding:8px 12px;text-align:right">'+ytdParc.toLocaleString()+'</td>'+
    '<td style="padding:8px 12px;text-align:right;color:#64748b">-</td>'+
    '<td style="padding:8px 12px;text-align:right">-</td>'+
    '<td style="padding:8px 12px;text-align:right;color:#4f46e5;font-weight:800">'+fmtB(ytdFreight)+'</td>'+
    '<td style="padding:8px 12px;text-align:right;color:#dc2626;font-weight:800">'+fmtB(ytdTotal)+'</td>'+
    '<td style="padding:8px 12px;text-align:right;color:#16a34a">'+(ytdParc?ytdTotal/ytdParc:0).toFixed(2)+'</td>'+
  '</tr>';
  document.getElementById('shippingTableBody').innerHTML=rows;
  var _shipYrs=_sortedNumKeys(SHIP_RECORDS);
  if(!window._shipCmpYears){window._shipCmpYears={};_shipYrs.forEach(function(y){window._shipCmpYears[y]=true;});}
  var allSel=_shipYrs.every(function(y){return window._shipCmpYears[y];});
  document.getElementById('shipCmpModeBtns').innerHTML=
    '<button onclick="window._shipCmpYears=null;renderShipping()" style="padding:5px 14px;border-radius:20px;border:1.5px solid '+(allSel?'#0891b2':'#e2e8f0')+';background:'+(allSel?'#0891b2':'#f8fafc')+';color:'+(allSel?'#fff':'#64748b')+';font-size:12px;font-weight:600;cursor:pointer">ทั้งหมด</button>'+
    _shipYrs.map(function(y){var on=window._shipCmpYears[y];return'<button onclick="window._shipCmpYears['+y+']=!window._shipCmpYears['+y+'];renderShipping()" style="padding:5px 14px;border-radius:20px;border:1.5px solid '+(on?'#0891b2':'#e2e8f0')+';background:'+(on?'#0891b2':'#f8fafc')+';color:'+(on?'#fff':'#64748b')+';font-size:12px;font-weight:600;cursor:pointer">ปี '+y+'</button>';}).join('');
  var allYears=_shipYrs.filter(function(y){return window._shipCmpYears[y];});
  if(allYears.length===0){var _ly=_shipYrs[_shipYrs.length-1]||2569;allYears=[_ly];window._shipCmpYears[_ly]=true;}
  var yrColors=['#0891b2','#7c3aed','#dc2626'];
  var ths='padding:8px 10px;text-align:center;color:#fff;font-weight:700;font-size:12px;border-right:1px solid rgba(255,255,255,.2)';
  var subThs='padding:6px 10px;text-align:center;color:#fff;font-weight:600;font-size:11px;border-right:1px solid rgba(255,255,255,.2)';
  var thMo='padding:8px 12px;text-align:left;color:#fff;font-weight:700;font-size:12px';
  var headRow='<tr><th style="'+thMo+';background:#334155" rowspan="2">เดือน</th>'+
    allYears.map(function(y,yi){var col=yrColors[yi];return'<th style="'+ths+';background:'+col+'" colspan="2">ปี '+y+'</th>';}).join('')+'</tr>'+
    '<tr>'+allYears.map(function(y,yi){var col=yrColors[yi];return'<th style="'+subThs+';background:'+col+'cc">📦 จำนวนกล่อง</th><th style="'+subThs+';background:'+col+'99">💰 ค่าขนส่ง (บาท)</th>';}).join('')+'</tr>';
  document.getElementById('shippingAllHead').innerHTML=headRow;
  var moOrder=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var bodyRows=[];var yrTotals=allYears.map(function(){return{parcels:0,freight:0};});
  moOrder.forEach(function(mo,mi){
    var cells='';var hasAny=false;
    allYears.forEach(function(y,yi){
      var yd=(SHIPPING_DATA[y]||[]).filter(function(r){return r.mo===mo;});
      if(yd.length)hasAny=true;
      var tp=yd.reduce(function(s,r){return s+r.parcels;},0);
      var tf=yd.reduce(function(s,r){return s+r.freight;},0);
      yrTotals[yi].parcels+=tp;yrTotals[yi].freight+=tf;
      var col=yrColors[yi];
      cells+='<td style="padding:8px 10px;text-align:right;color:'+col+';font-weight:600;border-right:1px solid #e2e8f0">'+(tp?tp.toLocaleString():'-')+'</td><td style="padding:8px 10px;text-align:right;color:#475569;border-right:1px solid #e2e8f0">'+(tf?fmtB(tf):'-')+'</td>';
    });
    if(hasAny){var rbg=mi%2===0?'#fff':'#f8fafc';bodyRows.push('<tr style="background:'+rbg+';border-bottom:1px solid #f1f5f9"><td style="padding:8px 12px;font-weight:600;color:#1e293b">'+mo+'</td>'+cells+'</tr>');}
  });
  var totalCells=allYears.map(function(y,yi){var tp=yrTotals[yi].parcels;var tf=yrTotals[yi].freight;var col=yrColors[yi];return'<td style="padding:8px 10px;text-align:right;color:'+col+';font-weight:800;border-right:1px solid #cbd5e1">'+tp.toLocaleString()+'</td><td style="padding:8px 10px;text-align:right;color:#dc2626;font-weight:800;border-right:1px solid #e2e8f0">'+fmtB(tf)+'</td>';}).join('');
  bodyRows.push('<tr style="background:#e2e8f0;font-weight:800;border-top:2px solid #cbd5e1"><td style="padding:8px 10px;font-weight:800;color:#1e293b">รวม</td>'+totalCells+'</tr>');
  document.getElementById('shippingAllBody').innerHTML=bodyRows.join('');
  _shipRecYear=_shipYear;_shipRecPage=0;renderShipRecords();
}
