    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px">'
    + _custField('จำนวนพัสดุที่ COD (ชิ้น)', 'sh_cod_parcels', 'number', d.cod_parcels, {placeholder:'0'})
    + _custField('จำนวนที่สั่งซื้อ', 'sh_orders', 'number', d.orders, {placeholder:'0'})
