    + _custField('รวมค่าทิ้งที่ละ (฿)', 'sh_per_item_fee', 'number', d.per_item_fee, {placeholder:'0.00'})
    + '</div></div>'
    + '<div style="grid-column:1/-1;background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:10px;padding:14px 16px;margin-bottom:4px">'
    + '<div style="font-size:14px;font-weight:700;color:#16a34a;margin-bottom:10px">💰 ค่าขนส่ง</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px">'
    + _custField('รวมค่าพัสดุ (฿)', 'sh_shipping_cost', 'number', d.shipping_cost, {placeholder:'0.00'})
    + _custField('Total Charge (฿)', 'sh_total_charge', 'number', d.total_charge, {placeholder:'0.00'})
