  h += '<div style="margin-left:auto;display:flex;gap:8px;flex-wrap:wrap;align-items:center">';
  h += '<select onchange="_shipItemSetYearFilter(parseInt(this.value))" style="padding:5px 10px;border-radius:8px;border:1.5px solid '+accent+';font-size:12px;font-weight:700;color:'+accent+'">';
