    var totCodFee = filtered.reduce(function(s,d){return s+(d.total_cod_fee||0);},0);
    var totVat = filtered.reduce(function(s,d){return s+(d.cod_vat7||0);},0);

    h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-bottom:16px">';
