var _retYear=2569,_retMo='',_retPlat='',_retPage=0,_retPageSize=50,_retDateFrom='',_retDateTo='';
var PLAT_COLORS={'Lazada':'#f97316','Shopee':'#f43f5e','TikTok':'#000','Facebook':'#4f46e5'};
function _getReturnMap(){return{2567:{sum:RETURN_SUMMARY,rec:RETURN_RECORDS,prd:RETURN_PRODUCTS},2568:{sum:RETURN_SUMMARY_68,rec:RETURN_RECORDS_68,prd:RETURN_PRODUCTS_68},2569:{sum:RETURN_SUMMARY_69,rec:RETURN_RECORDS_69,prd:RETURN_PRODUCTS_69}};}
function renderReturn(yr,mo){
  if(yr!==undefined&&yr!==null)_retYear=yr;
  var _RETURN_MAP=_getReturnMap();
  var _rm=_RETURN_MAP[_retYear]||_RETURN_MAP[_latestYear(_RETURN_MAP)]||{};
  var RET_SUM=_rm.sum||{};
  var RET_REC=_rm.rec||{};
  var RET_PRD=_rm.prd||[];
  var moOrder=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var fmtB=function(v){return(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});};
  // mo: null=auto last month, ''=ทั้งหมด, 'ม.ค.'=specific
  if(mo!==undefined&&mo!==null)_retMo=mo;
  else if(mo===null){var avail=moOrder.filter(function(m){return RET_SUM[m];});_retMo=avail[avail.length-1]||'ม.ค.';}
  // Year select
  var yrSel=document.getElementById('returnYearSel');
  if(yrSel)yrSel.innerHTML=_sortedNumKeys(_RETURN_MAP).map(function(y){return'<option value="'+y+'"'+(y===_retYear?' selected':'')+'>ปี '+y+'</option>';}).join('');
  var yrSel2=document.getElementById('retYearSel2');
  if(yrSel2)yrSel2.value=String(_retYear);
  // Month select (top)
  var availMo=moOrder.filter(function(m){return RET_SUM[m];});
  var mTopSel=document.getElementById('returnMonthTopSel');
  if(mTopSel)mTopSel.innerHTML='<option value=""'+(_retMo===''?' selected':'')+'>ทั้งหมด</option>'+
    availMo.map(function(m){return'<option value="'+m+'"'+(m===_retMo?' selected':'')+'>'+m+'</option>';}).join('');
  // Build plats: single month or aggregate all
  var plats=[];
  if(_retMo===''){
    var platMap={};
    availMo.forEach(function(m){
      ((RET_SUM[m]||{}).platforms||[]).forEach(function(p){
        if(!platMap[p.platform])platMap[p.platform]={platform:p.platform,reject_qty:0,reject_amt:0,nocontact_qty:0,nocontact_amt:0,dup_qty:0,dup_amt:0,late_qty:0,late_amt:0,ants_qty:0,ants_amt:0};
        var t=platMap[p.platform];
        t.reject_qty+=p.reject_qty;t.reject_amt+=p.reject_amt;
        t.nocontact_qty+=p.nocontact_qty;t.nocontact_amt+=p.nocontact_amt;
        t.dup_qty+=p.dup_qty;t.dup_amt+=p.dup_amt;
        t.late_qty+=p.late_qty;t.late_amt+=p.late_amt;
        t.ants_qty+=(p.ants_qty||0);t.ants_amt+=(p.ants_amt||0);
      });
    });
    plats=Object.values(platMap);
  }else{
    plats=((RET_SUM[_retMo]||{}).platforms)||[];
  }
  // KPI
  var yrQty=Object.values(RET_SUM).reduce(function(s,x){return s+(x.total_qty||0);},0);
  var yrAmt=Object.values(RET_SUM).reduce(function(s,x){return s+(x.total_amt||0);},0);
  var dispQty=_retMo===''?yrQty:((RET_SUM[_retMo]||{}).total_qty||0);
  var dispAmt=_retMo===''?yrAmt:((RET_SUM[_retMo]||{}).total_amt||0);
  var dispLabel=_retMo===''?('ตีกลับทั้งหมด ปี '+_retYear):('ตีกลับ '+_retMo+' ปี '+_retYear);
  var dispLabel2=_retMo===''?'ยอดเสียหายรวมทั้งปี':'ยอดเสียหายเดือนนี้';
  document.getElementById('returnKPI').innerHTML=[
    {label:dispLabel,val:dispQty.toLocaleString()+' ออเดอร์',color:'#dc2626',icon:'📦'},
    {label:dispLabel2,val:fmtB(dispAmt)+' บาท',color:'#d97706',icon:'💸'},
    {label:'ตีกลับรวมทั้งปี',val:yrQty.toLocaleString()+' ออเดอร์',color:'#7c3aed',icon:'📊'},
    {label:'ยอดเสียหายรวมทั้งปี',val:fmtB(yrAmt)+' บาท',color:'#475569',icon:'🧾'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.3rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');
  // Chart (always all months)
  var labels=moOrder.filter(function(m){return RET_SUM[m];});
  var qtyData=labels.map(function(m){return(RET_SUM[m]||{}).total_qty||0;});
  var amtData=labels.map(function(m){return(RET_SUM[m]||{}).total_amt||0;});
  mkChart('returnChart',{type:'bar',data:{labels:labels,datasets:[
    {label:'จำนวนออเดอร์',data:qtyData,backgroundColor:'rgba(220,38,38,.7)',borderRadius:5,yAxisID:'y'},
    {label:'ยอด (บาท)',data:amtData,backgroundColor:'rgba(217,119,6,.4)',borderRadius:5,yAxisID:'y1'},
  ]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}},scales:{
    x:{grid:{display:false}},
    y:{position:'left',grid:{color:'#f1f5f9'},ticks:{callback:function(v){return v;}}},
    y1:{position:'right',grid:{display:false},ticks:{callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}}},
  }}});
  // Platform table
  var tableTitle=_retMo===''?('📋 รายละเอียดทั้งปี '+_retYear+' แยกแพลตฟอร์ม'):('📋 รายละเอียด '+_retMo+' แยกแพลตฟอร์ม');
  document.getElementById('returnTableTitle').textContent=tableTitle;
  var totPlatAmt=plats.reduce(function(s,p){return s+p.reject_amt+p.nocontact_amt+p.dup_amt+p.late_amt+(p.ants_amt||0);},0);
  document.getElementById('returnMonthBody').innerHTML=plats.map(function(p,i){
    var bg=i%2===0?'#fff':'#f8fafc';
    var total_amt=p.reject_amt+p.nocontact_amt+p.dup_amt+p.late_amt+(p.ants_amt||0);
    var col=PLAT_COLORS[p.platform]||'#64748b';
    return'<tr style="background:'+bg+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:8px 12px"><span style="background:'+col+';color:#fff;padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700">'+p.platform+'</span></td>'+
      '<td style="padding:8px 10px;text-align:center">'+p.reject_qty+'</td>'+
      '<td style="padding:8px 10px;text-align:center">'+p.nocontact_qty+'</td>'+
      '<td style="padding:8px 10px;text-align:center">'+p.dup_qty+'</td>'+
      '<td style="padding:8px 10px;text-align:center">'+p.late_qty+'</td>'+
      '<td style="padding:8px 10px;text-align:center">'+(p.ants_qty||0)+'</td>'+
      '<td style="padding:8px 10px;text-align:right;color:#dc2626;font-weight:600">'+fmtB(total_amt)+'</td>'+
    '</tr>';
  }).join('')+
  '<tr style="background:#e2e8f0;font-weight:800;border-top:2px solid #cbd5e1">'+
    '<td style="padding:8px 12px">รวม</td>'+
    '<td style="padding:8px 10px;text-align:center">'+plats.reduce(function(s,p){return s+p.reject_qty;},0)+'</td>'+
    '<td style="padding:8px 10px;text-align:center">'+plats.reduce(function(s,p){return s+p.nocontact_qty;},0)+'</td>'+
    '<td style="padding:8px 10px;text-align:center">'+plats.reduce(function(s,p){return s+p.dup_qty;},0)+'</td>'+
    '<td style="padding:8px 10px;text-align:center">'+plats.reduce(function(s,p){return s+p.late_qty;},0)+'</td>'+
    '<td style="padding:8px 10px;text-align:center">'+plats.reduce(function(s,p){return s+(p.ants_qty||0);},0)+'</td>'+
    '<td style="padding:8px 10px;text-align:right;color:#dc2626;font-weight:800">'+fmtB(totPlatAmt)+'</td>'+
  '</tr>';
  // Products table
  document.getElementById('returnProductBody').innerHTML=RET_PRD.map(function(p,i){
    var bg=i%2===0?'#fff':'#f8fafc';
    return'<tr style="background:'+bg+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:7px 10px;text-align:center;color:#94a3b8">'+(i+1)+'</td>'+
      '<td style="padding:7px 12px;font-weight:600;color:#1e293b">'+p.name+'</td>'+
      '<td style="padding:7px 10px;text-align:right;font-weight:600">'+p.total.toLocaleString()+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#64748b">'+p.cost.toFixed(2)+'</td>'+
      '<td style="padding:7px 10px;text-align:right;color:#dc2626;font-weight:700">'+p.amt.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
    '</tr>';
  }).join('');
  renderReturnRecords();
}
function renderReturnRecords(){
  var moOrder=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var fmtB=function(v){return(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});};
  var RET_REC2=(_getReturnMap()[_retYear]||{}).rec||{};
  var moSel=document.getElementById('retMonthSel');
  var availMo=moOrder.filter(function(m){return RET_REC2[m]&&RET_REC2[m].length>0;});
  moSel.innerHTML='<option value=""'+(''===_retMo?' selected':'')+'>ทั้งหมด</option>'+
    availMo.map(function(m){return'<option value="'+m+'"'+(m===_retMo?' selected':'')+'>'+m+'</option>';}).join('');
  var baseRows=[];
  if(_retMo===''){
    availMo.forEach(function(m){
      (RET_REC2[m]||[]).forEach(function(r){
        if(r[4]&&r[4]!=='-'||r[5]>0)baseRows.push([r[0],r[1],r[2],r[3],r[4],r[5],r[6],m]);
      });
    });
  }else{
    (RET_REC2[_retMo]||[]).forEach(function(r){baseRows.push([r[0],r[1],r[2],r[3],r[4],r[5],r[6],_retMo]);});
  }
  var q=(document.getElementById('retSearch').value||'').toLowerCase().trim();
  var plat=document.getElementById('retPlatSel').value;
  var moMap={'ม.ค.':1,'ก.พ.':2,'มี.ค.':3,'เม.ย.':4,'พ.ค.':5,'มิ.ย.':6,'ก.ค.':7,'ส.ค.':8,'ก.ย.':9,'ต.ค.':10,'พ.ย.':11,'ธ.ค.':12};
  var ceYr=_retYear-543;
  var dfrom=_retDateFrom?new Date(_retDateFrom):null;
  var dto=_retDateTo?new Date(_retDateTo+'T23:59:59'):null;
  var rows=baseRows.filter(function(r){
    if(plat&&r[1]!==plat)return false;
    if(q&&(r[3]||'').toLowerCase().indexOf(q)<0&&(r[4]||'').toLowerCase().indexOf(q)<0&&(r[6]||'').toLowerCase().indexOf(q)<0)return false;
    if((dfrom||dto)&&r[0]){
      var moNum=moMap[r[7]]||1;
      var rDate=new Date(ceYr,moNum-1,parseInt(r[0]));
      if(dfrom&&rDate<dfrom)return false;
      if(dto&&rDate>dto)return false;
    }
    return true;
  });
  var total=rows.length;
  var pages=Math.max(1,Math.ceil(total/_retPageSize));
  if(_retPage>=pages)_retPage=0;
  var start=_retPage*_retPageSize;
  var slice=rows.slice(start,start+_retPageSize);
  document.getElementById('retInfo').innerHTML='แสดง '+(total?start+1:0)+'-'+Math.min(start+_retPageSize,total)+' จาก <b>'+total.toLocaleString()+'</b> รายการ';
  var REASON_COLOR={'ปฏิเสธ , ยกเลิก':'#dc2626','ติดต่อไม่ได้ , ไม่รับโทรศัพท์':'#d97706','ส่งของไปซ้ำ':'#7c3aed','เกินเวลานัดส่งพัสดุ':'#0891b2'};
  document.getElementById('retTable').innerHTML=slice.map(function(r,i){
    var bg=(start+i)%2===0?'#fff':'#f8fafc';
    var col=PLAT_COLORS[r[1]]||'#64748b';
    var rcol=REASON_COLOR[r[6]]||'#475569';
    var mo7=r[7]||_retMo;var dayStr=r[0]?r[0]+' '+mo7:mo7;
    return'<tr style="background:'+bg+';border-bottom:1px solid #f1f5f9">'+
      '<td style="padding:6px 10px;color:#94a3b8;text-align:center">'+(start+i+1)+'</td>'+
      '<td style="padding:6px 10px;text-align:center;font-weight:600;white-space:nowrap">'+dayStr+'</td>'+
      '<td style="padding:6px 10px;text-align:center"><span style="background:'+col+';color:#fff;padding:2px 7px;border-radius:8px;font-size:10px;font-weight:700">'+r[1]+'</span></td>'+
      '<td style="padding:6px 10px;color:#1e293b">'+r[4]+'</td>'+
      '<td style="padding:6px 10px;font-family:monospace;font-size:10px;color:#4f46e5">'+r[3]+'</td>'+
      '<td style="padding:6px 10px;text-align:right;color:#dc2626;font-weight:700">'+fmtB(r[5])+'</td>'+
      '<td style="padding:6px 10px;font-size:10px;color:'+rcol+';font-weight:600">'+r[6]+'</td>'+
    '</tr>';
  }).join('');
  var pagerBtns='';
  if(pages>1){
    if(_retPage>0)pagerBtns+='<button onclick="_retPage='+(_retPage-1)+';renderReturnRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;font-size:12px">◀</button>';
    var lo=Math.max(0,_retPage-2),hi=Math.min(pages-1,_retPage+2);
    for(var pg=lo;pg<=hi;pg++){var ac=pg===_retPage;pagerBtns+='<button onclick="_retPage='+pg+';renderReturnRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid '+(ac?'#dc2626':'#e2e8f0')+';background:'+(ac?'#dc2626':'#fff')+';color:'+(ac?'#fff':'#1e293b')+';font-weight:'+(ac?'700':'400')+';cursor:pointer;font-size:12px">'+(pg+1)+'</button>';}
    if(_retPage<pages-1)pagerBtns+='<button onclick="_retPage='+(_retPage+1)+';renderReturnRecords()" style="padding:5px 12px;border-radius:8px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;font-size:12px">▶</button>';
  }
  document.getElementById('retPager').innerHTML=pagerBtns;
}

