var _claimYear=2569,_claimMo='',_claimPage=0,_claimPageSize=50,_claimSearch='';
var _claimDateFrom='',_claimDateTo='';
var _cancelYear=2569,_cancelMo='',_cancelPage=0,_cancelPageSize=50,_cancelSearch='';
var _cancelDateFrom='',_cancelDateTo='';
var _claimChart=null,_cancelChart=null;

var CLAIM_MONTHS=["ม.ค.","ก.พ.","มี.ค.","เม.ย.","พ.ค.","มิ.ย.","ก.ค.","ส.ค.","ก.ย.","ต.ค.","พ.ย.","ธ.ค."];

function renderClaim(){
  var yrStr=String(_claimYear);
  var sumData=CLAIM_SUMMARY[yrStr]||{};
  var availMo=CLAIM_MONTHS.filter(function(m){return sumData[m];});

  // Sync selects
  var yrSel=document.getElementById('claimYearSel');
  if(yrSel)yrSel.value=yrStr;
  var _cYS2=document.getElementById('claimYearSel2');if(_cYS2)_cYS2.value=yrStr;
  var moSel=document.getElementById('claimMonthSel');
  if(moSel){
    moSel.innerHTML='<option value="">ทั้งหมด</option>'+CLAIM_MONTHS.map(function(m){return'<option value="'+m+'"'+(_claimMo===m?' selected':'')+'>'+m+'</option>';}).join('');
  }
  var _cMS2=document.getElementById('claimMonthSel2');if(_cMS2){_cMS2.innerHTML='<option value="">ทั้งหมด</option>'+CLAIM_MONTHS.map(function(m){return'<option value="'+m+'"'+(_claimMo===m?' selected':'')+'>'+m+'</option>';}).join('');}

  // KPI
  var selMo=_claimMo&&sumData[_claimMo]?sumData[_claimMo]:null;
  var totQty=0,totCost=0;
  availMo.forEach(function(m){totQty+=(sumData[m].claim_qty||0);totCost+=(sumData[m].claim_cost||0);});
  var moQty=selMo?selMo.claim_qty:totQty;
  var moCost=selMo?selMo.claim_cost:totCost;
  var label=_claimMo||'ทั้งปี';
  var kpiEl=document.getElementById('claimKPI');
  if(kpiEl)kpiEl.innerHTML=[
    {label:'จำนวนเคลม ('+label+')',val:moQty.toLocaleString()+' รายการ',color:'#7c3aed',icon:'📋'},
    {label:'ค่าขนส่ง ('+label+')',val:moCost.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+' บาท',color:'#059669',icon:'💸'},
    {label:'จำนวนเคลมทั้งปี',val:totQty.toLocaleString()+' รายการ',color:'#1e40af',icon:'📦'},
    {label:'ค่าขนส่งทั้งปี',val:totCost.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+' บาท',color:'#d97706',icon:'💰'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');

  // Chart
  var labels=availMo;
  var vals=labels.map(function(m){return(sumData[m]||{}).claim_qty||0;});
  var costs=labels.map(function(m){return(sumData[m]||{}).claim_cost||0;});
  var ctx=document.getElementById('claimChart');
  if(ctx){
    if(_claimChart){_claimChart.destroy();_claimChart=null;}
    _claimChart=new Chart(ctx.getContext('2d'),{type:'bar',data:{labels:labels,datasets:[
      {label:'จำนวนเคลม (รายการ)',data:vals,backgroundColor:'rgba(124,58,237,0.7)',yAxisID:'y'},
      {label:'ค่าขนส่ง (บาท)',data:costs,backgroundColor:'rgba(251,146,60,0.6)',type:'bar',yAxisID:'y2'}
    ]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index'},plugins:{legend:{position:'top'}},scales:{
      y:{beginAtZero:true,title:{display:true,text:'รายการ'}},
      y2:{beginAtZero:true,position:'right',title:{display:true,text:'บาท'},grid:{drawOnChartArea:false}}
    }}});
  }
  renderClaimRecords();
}

function renderClaimRecords(){
  var yrStr=String(_claimYear);
  var recData=CLAIM_RECORDS[yrStr]||{};
  var q=(document.getElementById('claimSearch')||{}).value||'';
  q=q.toLowerCase().trim();

  var rows=[];
  if(_claimMo&&recData[_claimMo]){
    recData[_claimMo].forEach(function(r){rows.push([r,_claimMo]);});
  } else {
    CLAIM_MONTHS.forEach(function(m){(recData[m]||[]).forEach(function(r){rows.push([r,m]);});});
  }
  if(q){rows=rows.filter(function(item){var r=item[0];return(r[1]||'').toLowerCase().includes(q)||(r[2]||'').toLowerCase().includes(q);});}
  var _TH_C={"ม.ค.":1,"ก.พ.":2,"มี.ค.":3,"เม.ย.":4,"พ.ค.":5,"มิ.ย.":6,"ก.ค.":7,"ส.ค.":8,"ก.ย.":9,"ต.ค.":10,"พ.ย.":11,"ธ.ค.":12};
  var _ceC=_claimYear-543,_dfC=_claimDateFrom?new Date(_claimDateFrom):null,_dtC=_claimDateTo?new Date(_claimDateTo+'T23:59:59'):null;
  if(_dfC||_dtC){rows=rows.filter(function(item){var r=item[0],mo=item[1];
    var d=new Date(_ceC,(_TH_C[mo]||1)-1,parseInt(r[0])||1);
    return(!_dfC||d>=_dfC)&&(!_dtC||d<=_dtC);});}

  var total=rows.length,ps=_claimPageSize,page=_claimPage;
  var maxPage=Math.max(0,Math.ceil(total/ps)-1);
  if(page>maxPage)page=_claimPage=maxPage;
  var slice=rows.slice(page*ps,(page+1)*ps);

  var tbody=document.getElementById('claimTable');
  if(tbody)tbody.innerHTML=slice.map(function(item,i){
    var r=item[0],mo=item[1];
    var bg=i%2===0?'':'background:#faf5ff';
    return'<tr style="'+bg+'">'+
      '<td style="padding:6px 10px;text-align:center;color:#94a3b8">'+(page*ps+i+1)+'</td>'+
      '<td style="padding:6px 10px;font-family:monospace;font-size:11px">'+r[1]+'</td>'+
      '<td style="padding:6px 10px">'+r[2]+'</td>'+
      '<td style="padding:6px 10px">'+r[3]+'</td>'+
      '<td style="padding:6px 10px;text-align:center">'+mo+'</td>'+
      '<td style="padding:6px 10px;text-align:center">'+r[0]+'</td>'+
      '<td style="padding:6px 10px;font-size:11px;color:#7c3aed">'+r[4]+'</td>'+
    '</tr>';
  }).join('');

  // Pager
  var pager=document.getElementById('claimPager');
  if(pager){
    var btns='';
    var totalPages=Math.ceil(total/ps);
    btns+='<span style="color:#64748b;font-size:12px;align-self:center">'+total.toLocaleString()+' รายการ</span>';
    if(totalPages>1){
      btns+='<button onclick="_claimPage=Math.max(0,_claimPage-1);renderClaimRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">◀</button>';
      var start=Math.max(0,page-2),end=Math.min(totalPages-1,start+4);
      for(var p=start;p<=end;p++){
        var active=p===page;
        btns+='<button onclick="_claimPage='+p+';renderClaimRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid '+(active?'#7c3aed':'#e2e8f0')+';background:'+(active?'#7c3aed':'#fff')+';color:'+(active?'#fff':'#1e293b')+';cursor:pointer">'+(p+1)+'</button>';
      }
      btns+='<button onclick="_claimPage=Math.min(Math.ceil('+total+'/'+ps+')-1,_claimPage+1);renderClaimRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">▶</button>';
    }
    pager.innerHTML=btns;
  }
}

function renderCancel(){
  var yrStr=String(_cancelYear);
  var sumData=CLAIM_SUMMARY[yrStr]||{};
  var availMo=CLAIM_MONTHS.filter(function(m){return sumData[m];});

  // Sync selects
  var yrSel=document.getElementById('cancelYearSel');
  if(yrSel)yrSel.value=yrStr;
  var _xYS2=document.getElementById('cancelYearSel2');if(_xYS2)_xYS2.value=yrStr;
  var moSel=document.getElementById('cancelMonthSel');
  if(moSel){
    moSel.innerHTML='<option value="">ทั้งหมด</option>'+CLAIM_MONTHS.map(function(m){return'<option value="'+m+'"'+(_cancelMo===m?' selected':'')+'>'+m+'</option>';}).join('');
  }
  var _xMS2=document.getElementById('cancelMonthSel2');if(_xMS2){_xMS2.innerHTML='<option value="">ทั้งหมด</option>'+CLAIM_MONTHS.map(function(m){return'<option value="'+m+'"'+(_cancelMo===m?' selected':'')+'>'+m+'</option>';}).join('');}

  // KPI
  var selMo=_cancelMo&&sumData[_cancelMo]?sumData[_cancelMo]:null;
  var totQty=0,totAmt=0;
  availMo.forEach(function(m){totQty+=(sumData[m].cancel_qty||0);totAmt+=(sumData[m].cancel_amt||0);});
  var moQty=selMo?selMo.cancel_qty:totQty;
  var moAmt=selMo?selMo.cancel_amt:totAmt;
  var label=_cancelMo||'ทั้งปี';
  var kpiEl=document.getElementById('cancelKPI');
  if(kpiEl)kpiEl.innerHTML=[
    {label:'จำนวนยกเลิก ('+label+')',val:moQty.toLocaleString()+' รายการ',color:'#dc2626',icon:'❌'},
    {label:'ยอดขาย ('+label+')',val:moAmt.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+' บาท',color:'#059669',icon:'💸'},
    {label:'จำนวนยกเลิกทั้งปี',val:totQty.toLocaleString()+' รายการ',color:'#1e40af',icon:'📦'},
    {label:'ยอดขายทั้งปี',val:totAmt.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+' บาท',color:'#d97706',icon:'💰'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');

  // Chart
  var labels=availMo;
  var vals=labels.map(function(m){return(sumData[m]||{}).cancel_qty||0;});
  var amts=labels.map(function(m){return(sumData[m]||{}).cancel_amt||0;});
  var ctx=document.getElementById('cancelChart');
  if(ctx){
    if(_cancelChart){_cancelChart.destroy();_cancelChart=null;}
    _cancelChart=new Chart(ctx.getContext('2d'),{type:'bar',data:{labels:labels,datasets:[
      {label:'จำนวนยกเลิก (รายการ)',data:vals,backgroundColor:'rgba(220,38,38,0.7)',yAxisID:'y'},
      {label:'ยอดขาย (บาท)',data:amts,backgroundColor:'rgba(251,146,60,0.5)',type:'bar',yAxisID:'y2'}
    ]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index'},plugins:{legend:{position:'top'}},scales:{
      y:{beginAtZero:true,title:{display:true,text:'รายการ'}},
      y2:{beginAtZero:true,position:'right',title:{display:true,text:'บาท'},grid:{drawOnChartArea:false}}
    }}});
  }
  renderCancelRecords();
}

function renderCancelRecords(){
  var yrStr=String(_cancelYear);
  var recData=CANCEL_RECORDS[yrStr]||{};
  var q=(document.getElementById('cancelSearch')||{}).value||'';
  q=q.toLowerCase().trim();

  var rows=[];
  if(_cancelMo&&recData[_cancelMo]){
    recData[_cancelMo].forEach(function(r){rows.push([r,_cancelMo]);});
  } else {
    CLAIM_MONTHS.forEach(function(m){(recData[m]||[]).forEach(function(r){rows.push([r,m]);});});
  }
  if(q){rows=rows.filter(function(item){var r=item[0];return(r[1]||'').toLowerCase().includes(q)||(r[2]||'').toLowerCase().includes(q);});}
  var _TH_X={"ม.ค.":1,"ก.พ.":2,"มี.ค.":3,"เม.ย.":4,"พ.ค.":5,"มิ.ย.":6,"ก.ค.":7,"ส.ค.":8,"ก.ย.":9,"ต.ค.":10,"พ.ย.":11,"ธ.ค.":12};
  var _ceX=_cancelYear-543,_dfX=_cancelDateFrom?new Date(_cancelDateFrom):null,_dtX=_cancelDateTo?new Date(_cancelDateTo+'T23:59:59'):null;
  if(_dfX||_dtX){rows=rows.filter(function(item){var r=item[0],mo=item[1];
    var d=new Date(_ceX,(_TH_X[mo]||1)-1,parseInt(r[0])||1);
    return(!_dfX||d>=_dfX)&&(!_dtX||d<=_dtX);});}

  var total=rows.length,ps=_cancelPageSize,page=_cancelPage;
  var maxPage=Math.max(0,Math.ceil(total/ps)-1);
  if(page>maxPage)page=_cancelPage=maxPage;
  var slice=rows.slice(page*ps,(page+1)*ps);

  var tbody=document.getElementById('cancelTable');
  if(tbody)tbody.innerHTML=slice.map(function(item,i){
    var r=item[0],mo=item[1];
    var bg=i%2===0?'':'background:#fff1f2';
    return'<tr style="'+bg+'">'+
      '<td style="padding:6px 10px;text-align:center;color:#94a3b8">'+(page*ps+i+1)+'</td>'+
      '<td style="padding:6px 10px;font-family:monospace;font-size:11px">'+r[1]+'</td>'+
      '<td style="padding:6px 10px">'+r[2]+'</td>'+
      '<td style="padding:6px 10px">'+r[3]+'</td>'+
      '<td style="padding:6px 10px;text-align:center">'+mo+'</td>'+
      '<td style="padding:6px 10px;text-align:center">'+r[0]+'</td>'+
      '<td style="padding:6px 10px;text-align:right;color:#dc2626;font-weight:700">'+(r[4]?r[4].toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}):'')+'</td>'+
      '<td style="padding:6px 10px;font-size:11px;color:#64748b">'+r[5]+'</td>'+
    '</tr>';
  }).join('');

  // Pager
  var pager=document.getElementById('cancelPager');
  if(pager){
    var btns='';
    var totalPages=Math.ceil(total/ps);
    btns+='<span style="color:#64748b;font-size:12px;align-self:center">'+total.toLocaleString()+' รายการ</span>';
    if(totalPages>1){
      btns+='<button onclick="_cancelPage=Math.max(0,_cancelPage-1);renderCancelRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">◀</button>';
      var start=Math.max(0,page-2),end=Math.min(totalPages-1,start+4);
      for(var p=start;p<=end;p++){
        var active=p===page;
        btns+='<button onclick="_cancelPage='+p+';renderCancelRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid '+(active?'#dc2626':'#e2e8f0')+';background:'+(active?'#dc2626':'#fff')+';color:'+(active?'#fff':'#1e293b')+';cursor:pointer">'+(p+1)+'</button>';
      }
      btns+='<button onclick="_cancelPage=Math.min(Math.ceil('+total+'/'+ps+')-1,_cancelPage+1);renderCancelRecords()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">▶</button>';
    }
    pager.innerHTML=btns;
  }
}


