var _supplyYear=2569,_supplyMo='',_supplyProdPage=0,_supplyProdPageSize=50;
var _supplyChart=null;
var SUPPLY_MONTHS=["ม.ค.","ก.พ.","มี.ค.","เม.ย.","พ.ค.","มิ.ย.","ก.ค.","ส.ค.","ก.ย.","ต.ค.","พ.ย.","ธ.ค."];

function renderSupply(){
  var yrStr=String(_supplyYear);
  var sumData=SUPPLY_SUMMARY[yrStr]||{};
  var availMo=SUPPLY_MONTHS.filter(function(m){return sumData[m]&&(sumData[m].qty>0||sumData[m].amt>0);});

  // Sync year select
  var yrSel=document.getElementById('supplyYearSel');
  if(yrSel)yrSel.value=yrStr;
  var _sYS2=document.getElementById('supplyYearSel2');if(_sYS2)_sYS2.value=yrStr;
  // Sync month select
  var moSel=document.getElementById('supplyMonthSel');
  if(moSel){
    moSel.innerHTML='<option value="">ทั้งหมด</option>'+
      SUPPLY_MONTHS.map(function(m){return'<option value="'+m+'"'+(_supplyMo===m?' selected':'')+'>'+m+'</option>';}).join('');
  }
  var _sMS2=document.getElementById('supplyMonthSel2');if(_sMS2){_sMS2.innerHTML='<option value="">ทั้งหมด</option>'+SUPPLY_MONTHS.map(function(m){return'<option value="'+m+'"'+(_supplyMo===m?' selected':'')+'>'+m+'</option>';}).join('');}

  // KPI
  var totQty=0,totAmt=0;
  availMo.forEach(function(m){totQty+=(sumData[m].qty||0);totAmt+=sumData[m].amt||0;});
  var moData=_supplyMo&&sumData[_supplyMo]?sumData[_supplyMo]:null;
  var moQty=moData?moData.qty:totQty;
  var moAmt=moData?moData.amt:totAmt;
  var prods=SUPPLY_PRODUCTS[yrStr]||[];
  var label=_supplyMo||'ทั้งปี';
  var kpiEl=document.getElementById('supplyKPI');
  if(kpiEl)kpiEl.innerHTML=[
    {label:'ยอดเบิก ('+label+')',val:moQty.toLocaleString()+' ชิ้น',color:'#059669',icon:'🧾'},
    {label:'มูลค่า ('+label+')',val:moAmt.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' บาท',color:'#4f46e5',icon:'💸'},
    {label:'ยอดเบิกทั้งปี',val:totQty.toLocaleString()+' ชิ้น',color:'#1e40af',icon:'📦'},
    {label:'มูลค่าทั้งปี',val:totAmt.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' บาท',color:'#d97706',icon:'💰'},
  ].map(function(k){
    return'<div class="card" style="border-top:4px solid '+k.color+';padding:16px 18px">'+
      '<div style="font-size:22px;margin-bottom:6px">'+k.icon+'</div>'+
      '<div style="font-size:12px;color:#64748b;font-weight:600;margin-bottom:4px">'+k.label+'</div>'+
      '<div style="font-size:1.4rem;font-weight:800;color:'+k.color+'">'+k.val+'</div>'+
    '</div>';
  }).join('');

  // Chart
  var labels=availMo;
  var qtyVals=labels.map(function(m){return(sumData[m]||{}).qty||0;});
  var amtVals=labels.map(function(m){return(sumData[m]||{}).amt||0;});
  var ctx=document.getElementById('supplyChart');
  if(ctx){
    if(_supplyChart){_supplyChart.destroy();_supplyChart=null;}
    _supplyChart=new Chart(ctx.getContext('2d'),{type:'bar',data:{labels:labels,datasets:[
      {label:'จำนวนเบิก (ชิ้น)',data:qtyVals,backgroundColor:'rgba(5,150,105,0.7)',yAxisID:'y'},
      {label:'มูลค่า (บาท)',data:amtVals,backgroundColor:'rgba(251,146,60,0.6)',type:'bar',yAxisID:'y2'}
    ]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index'},plugins:{legend:{position:'top'}},scales:{
      y:{beginAtZero:true,title:{display:true,text:'ชิ้น'}},
      y2:{beginAtZero:true,position:'right',title:{display:true,text:'บาท'},grid:{drawOnChartArea:false}}
    }}});
  }
  renderSupplyProducts();
}

function renderSupplyProducts(){
  var yrStr=String(_supplyYear);
  var prods=SUPPLY_PRODUCTS[yrStr]||[];
  var q=(document.getElementById('supplySearch')||{}).value||'';
  q=q.toLowerCase().trim();

  // Filter by month
  var filtered=prods.map(function(p){
    var qty,amt;
    if(_supplyMo){
      var md=p.months&&p.months[_supplyMo]?p.months[_supplyMo]:{qty:0,amt:0};
      qty=md.qty;amt=md.amt;
    } else {
      qty=p.total_qty;amt=p.total_amt;
    }
    return {code:p.code,name:p.name,unit:p.unit,cost:p.cost,qty:qty,amt:amt};
  }).filter(function(p){return p.qty>0||p.amt>0;});

  // Search
  if(q){filtered=filtered.filter(function(p){return(p.code||'').toLowerCase().includes(q)||(p.name||'').toLowerCase().includes(q);});}

  var total=filtered.length,ps=_supplyProdPageSize,page=_supplyProdPage;
  var maxPage=Math.max(0,Math.ceil(total/ps)-1);
  if(page>maxPage)page=_supplyProdPage=maxPage;
  var slice=filtered.slice(page*ps,(page+1)*ps);

  var tbody=document.getElementById('supplyProdTable');
  if(tbody)tbody.innerHTML=slice.map(function(p,i){
    var bg=i%2===0?'':'background:#f0fdf4';
    return'<tr style="'+bg+'">'+
      '<td style="padding:6px 10px;font-family:monospace;font-size:11px;color:#059669">'+p.code+'</td>'+
      '<td style="padding:6px 10px">'+p.name+'</td>'+
      '<td style="padding:6px 10px;text-align:center;color:#64748b">'+p.unit+'</td>'+
      '<td style="padding:6px 10px;text-align:right">'+p.cost.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
      '<td style="padding:6px 10px;text-align:right;font-weight:700;color:#059669">'+p.qty.toLocaleString()+'</td>'+
      '<td style="padding:6px 10px;text-align:right;font-weight:700;color:#1e40af">'+p.amt.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
    '</tr>';
  }).join('');

  var pager=document.getElementById('supplyProdPager');
  if(pager){
    var btns='<span style="color:#64748b;font-size:12px;align-self:center">'+total.toLocaleString()+' รายการ</span>';
    var totalPages=Math.ceil(total/ps);
    if(totalPages>1){
      btns+='<button onclick="_supplyProdPage=Math.max(0,_supplyProdPage-1);renderSupplyProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">◀</button>';
      var start=Math.max(0,page-2),end=Math.min(totalPages-1,start+4);
      for(var p2=start;p2<=end;p2++){
        var active=p2===page;
        btns+='<button onclick="_supplyProdPage='+p2+';renderSupplyProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid '+(active?'#059669':'#e2e8f0')+';background:'+(active?'#059669':'#fff')+';color:'+(active?'#fff':'#1e293b')+';cursor:pointer">'+(p2+1)+'</button>';
      }
      btns+='<button onclick="_supplyProdPage=Math.min('+maxPage+',_supplyProdPage+1);renderSupplyProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">▶</button>';
    }
    pager.innerHTML=btns;
  }
}


/* ===== Supply Entry Form (กรอกรายการเบิกวัสดุสิ้นเปลือง แบบตาราง) ===== */
var _supplyEntryYear = 2569;
var _supplyEntryMonth = (function(){ var m = new Date().getMonth(); return ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][m]; })();
var _supplyEntryCache = null;

function _getSupplyEntryData() {
  if (_supplyEntryCache) return _supplyEntryCache;
  try { _supplyEntryCache = JSON.parse(localStorage.getItem('supplyEntryData')) || {}; }
  catch(e) { _supplyEntryCache = {}; }
  return _supplyEntryCache;
}
function _saveSupplyEntry(data) {
  _supplyEntryCache = data;
  _lsSet('supplyEntryData',data);
}

function _getSupplyProductList() {
  var yrStr = String(_supplyEntryYear);
  var prods = (typeof SUPPLY_PRODUCTS !== 'undefined' && SUPPLY_PRODUCTS[yrStr]) ? SUPPLY_PRODUCTS[yrStr] : [];
  if (!prods.length) {
    var keys = Object.keys(SUPPLY_PRODUCTS || {});
    for (var k = keys.length - 1; k >= 0; k--) {
      if (SUPPLY_PRODUCTS[keys[k]] && SUPPLY_PRODUCTS[keys[k]].length) {
        prods = SUPPLY_PRODUCTS[keys[k]]; break;
      }
    }
  }
  return prods;
}

function _supplyEntrySetYear(yr) { _supplyEntryYear = yr; renderSupplyEntryForm(); }
function _supplyEntrySetMonth(mo) { _supplyEntryMonth = mo; renderSupplyEntryForm(); }

function _supplyEntrySave() {
  if (!_supplyEntryMonth) { alert('กรุณาเลือกเดือนก่อนบันทึก'); return; }
  var prods = _getSupplyProductList();
  var data = _getSupplyEntryData();
  var key = _supplyEntryYear + '_' + _supplyEntryMonth;
  var entries = [];
  prods.forEach(function(p, i) {
    var inp = document.getElementById('se_qty_' + i);
    var qty = inp ? (parseFloat(inp.value) || 0) : 0;
    entries.push({ code: p.code, qty: qty, amt: qty * (p.cost || 0) });
  });
  data[key] = { year: _supplyEntryYear, month: _supplyEntryMonth, items: entries, saved_at: new Date().toISOString() };
  _saveSupplyEntry(data);
  alert('บันทึกข้อมูลเบิกวัสดุสิ้นเปลือง เดือน ' + _supplyEntryMonth + ' ปี ' + _supplyEntryYear + ' เรียบร้อย!');
  renderSupplyEntryForm();
}

function _supplyEntryCalcRow(idx) {
  var prods = _getSupplyProductList();
  var p = prods[idx];
  if (!p) return;
  var inp = document.getElementById('se_qty_' + idx);
  var amtEl = document.getElementById('se_amt_' + idx);
  if (inp && amtEl) {
    var qty = parseFloat(inp.value) || 0;
    var amt = qty * (p.cost || 0);
    amtEl.textContent = amt.toLocaleString('th-TH', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  }
  _supplyEntryUpdateTotal();
}

function _supplyEntryUpdateTotal() {
  var prods = _getSupplyProductList();
  var totQty = 0, totAmt = 0;
  prods.forEach(function(p, i) {
    var inp = document.getElementById('se_qty_' + i);
    var qty = inp ? (parseFloat(inp.value) || 0) : 0;
    totQty += qty;
    totAmt += qty * (p.cost || 0);
  });
  var tqEl = document.getElementById('se_totQty');
  var taEl = document.getElementById('se_totAmt');
  if (tqEl) tqEl.textContent = totQty.toLocaleString();
  if (taEl) taEl.textContent = totAmt.toLocaleString('th-TH', {minimumFractionDigits: 2, maximumFractionDigits: 2});
}

function _supplyEntryCSV() {
  if (!_supplyEntryMonth) { alert('กรุณาเลือกเดือนก่อน'); return; }
  var prods = _getSupplyProductList();
  var data = _getSupplyEntryData();
  var key = _supplyEntryYear + '_' + _supplyEntryMonth;
  var saved = data[key] ? data[key].items : [];
  var csv = '﻿"ลำดับ","รหัสสินค้า","ชื่อสินค้า","หน่วย","ราคาต้นทุน","ยอดเบิก","เป็นเงิน"\n';
  prods.forEach(function(p, i) {
    var s = saved[i] || {};
    var qty = s.qty || 0;
    csv += (i+1)+',"'+p.code+'","'+p.name+'","'+p.unit+'",'+p.cost+','+qty+','+(qty*p.cost)+'\n';
  });
  var blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a'); a.href = url; a.download = 'supply_entry_'+_supplyEntryYear+'_'+_supplyEntryMonth+'.csv'; a.click();
  URL.revokeObjectURL(url);
}

function _supplyEntryOpenPaste() {
  var html = '<div id="supplyPasteModal" style="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.45);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px">';
  html += '<div style="background:#fff;border-radius:16px;padding:24px;max-width:700px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3)">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div style="font-size:1.1rem;font-weight:800;color:#059669">📋 วางข้อมูลจาก Excel</div>';
  html += '<button onclick="document.getElementById(\'supplyPasteModal\').remove()" style="border:none;background:none;font-size:22px;cursor:pointer;color:#94a3b8">✕</button></div>';
  html += '<div style="font-size:12px;color:#64748b;margin-bottom:10px">คัดลอกคอลัมน์ <b>รหัสสินค้า</b> กับ <b>ยอดเบิก</b> จาก Excel แล้ววาง<br>รูปแบบ: รหัสสินค้า [TAB] ยอดเบิก (แต่ละรายการ 1 บรรทัด)</div>';
  html += '<textarea id="supplyPasteArea" style="width:100%;height:160px;border:1.5px solid #e2e8f0;border-radius:8px;padding:10px;font-size:12px;font-family:monospace;box-sizing:border-box;resize:vertical" placeholder="02-BB111\t500\n02-BB116\t820\n..."></textarea>';
  html += '<div style="display:flex;gap:10px;margin-top:14px">';
  html += '<button onclick="_supplyPasteApply()" style="flex:1;padding:10px;border:none;border-radius:8px;background:#059669;color:#fff;font-weight:700;font-size:14px;cursor:pointer">✅ ใส่ลงตาราง</button>';
  html += '<button onclick="document.getElementById(\'supplyPasteModal\').remove()" style="flex:1;padding:10px;border:1.5px solid #e2e8f0;border-radius:8px;background:#fff;color:#64748b;font-weight:600;font-size:14px;cursor:pointer">ยกเลิก</button>';
  html += '</div></div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

function _supplyPasteApply() {
  var area = document.getElementById('supplyPasteArea');
  if (!area) return;
  var lines = area.value.split('\n').filter(function(l) { return l.trim(); });
  var prods = _getSupplyProductList();
  var codeMap = {};
  prods.forEach(function(p, i) { codeMap[p.code.toLowerCase()] = i; });
  var matched = 0;
  lines.forEach(function(line) {
    var cols = line.split('\t');
    if (cols.length < 2) return;
    var code = cols[0].trim().toLowerCase();
    var qty = parseFloat(String(cols[1]).replace(/,/g, '')) || 0;
    if (codeMap[code] !== undefined && qty > 0) {
      var inp = document.getElementById('se_qty_' + codeMap[code]);
      if (inp) { inp.value = qty; _supplyEntryCalcRow(codeMap[code]); matched++; }
    }
  });
  var modal = document.getElementById('supplyPasteModal');
  if (modal) modal.remove();
  alert('ใส่ข้อมูลลงตาราง ' + matched + ' รายการ');
}

function _supplyEntryClearAll() {
  if (!confirm('ล้างยอดเบิกทั้งหมดในตาราง?')) return;
  var prods = _getSupplyProductList();
  prods.forEach(function(p, i) {
    var inp = document.getElementById('se_qty_' + i);
    if (inp) inp.value = '';
    var amtEl = document.getElementById('se_amt_' + i);
    if (amtEl) amtEl.textContent = '0.00';
  });
  _supplyEntryUpdateTotal();
}

function _supplyEntryDeleteMonth() {
  if (!_supplyEntryMonth) return;
  if (!confirm('ลบข้อมูลเบิกวัสดุ เดือน ' + _supplyEntryMonth + ' ปี ' + _supplyEntryYear + '?')) return;
  var data = _getSupplyEntryData();
  var key = _supplyEntryYear + '_' + _supplyEntryMonth;
  delete data[key];
  _saveSupplyEntry(data);
  renderSupplyEntryForm();
}

function renderSupplyEntryForm() {
  var el = document.getElementById('supplyEntrySection');
  if (!el) return;
  var accent = '#059669';
  var fmtN = function(v) { return (v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}); };
  var prods = _getSupplyProductList();
  var data = _getSupplyEntryData();
  var key = _supplyEntryYear + '_' + _supplyEntryMonth;
  var saved = (_supplyEntryMonth && data[key]) ? data[key].items : [];
  var savedMap = {};
  saved.forEach(function(s) { if (s.code) savedMap[s.code] = s; });

  var months = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var savedKeys = Object.keys(data).filter(function(k) { return k.startsWith(_supplyEntryYear + '_'); });
  var savedMonths = savedKeys.map(function(k) { return k.split('_')[1]; });

  var h = '<div class="card mt">';
  h += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap">';
  h += '<div class="card-title" style="margin:0">📋 รายการเบิกวัสดุสิ้นเปลือง</div>';
  h += '<div style="margin-left:auto;display:flex;gap:8px;flex-wrap:wrap;align-items:center">';
  h += '<select onchange="_supplyEntrySetYear(parseInt(this.value))" style="padding:5px 10px;border-radius:8px;border:1.5px solid '+accent+';font-size:12px;font-weight:700;color:'+accent+'">';
  _sortedNumKeys(SUPPLY_PRODUCTS).forEach(function(y) {
    h += '<option value="'+y+'"'+(y===_supplyEntryYear?' selected':'')+'>ปี '+y+'</option>';
  });
  h += '</select>';
  h += '<select onchange="_supplyEntrySetMonth(this.value)" style="padding:6px 12px;border-radius:8px;border:1.5px solid '+accent+';font-size:13px;font-weight:700;color:'+accent+';background:#fff">';
  h += '<option value="">-- เลือกเดือน --</option>';
  months.forEach(function(m) {
    var hasSaved = savedMonths.indexOf(m) >= 0;
    h += '<option value="'+m+'"'+(m===_supplyEntryMonth?' selected':'')+'>'+m+(hasSaved?' ✅':'')+'</option>';
  });
  h += '</select>';
  h += '</div></div>';

  if (!_supplyEntryMonth) {
    h += '<div style="text-align:center;padding:60px 20px;color:#94a3b8">';
    h += '<div style="font-size:48px;margin-bottom:12px">📦</div>';
    h += '<div style="font-size:16px;font-weight:600;margin-bottom:8px">เลือกเดือนที่ต้องการกรอกข้อมูล</div>';
    h += '<div style="font-size:13px">เลือกเดือนจากดรอปดาวน์ด้านบน เดือนที่มีข้อมูลแล้วจะแสดง ✅</div></div>';
    if (savedKeys.length) {
      h += '<div style="margin-top:16px;font-size:13px;color:#64748b"><b>เดือนที่กรอกแล้ว:</b> ' + savedMonths.join(', ') + '</div>';
    }
    h += '</div>';
    el.innerHTML = h;
    return;
  }

  var hasSavedData = data[key] && data[key].items && data[key].items.length > 0;
  h += '<div style="display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap;align-items:center">';
  h += '<button onclick="_supplyEntrySave()" style="padding:8px 20px;border:none;border-radius:8px;background:'+accent+';color:#fff;cursor:pointer;font-size:14px;font-weight:700">💾 บันทึก '+_supplyEntryMonth+'</button>';
  h += '<button onclick="_supplyEntryOpenPaste()" style="padding:8px 18px;border:none;border-radius:8px;background:#2563eb;color:#fff;cursor:pointer;font-size:14px;font-weight:600">📋 วางจาก Excel</button>';
  h += '<button onclick="_supplyEntryCSV()" style="padding:8px 18px;border:1px solid #d1d5db;border-radius:8px;background:#fff;cursor:pointer;font-size:14px;color:#374151">⬇️ CSV</button>';
  h += '<button onclick="_supplyEntryClearAll()" style="padding:8px 18px;border:1px solid #fca5a5;border-radius:8px;background:#fff;cursor:pointer;font-size:14px;color:#dc2626">🗑️ ล้างทั้งหมด</button>';
  if (hasSavedData) {
    h += '<button onclick="_supplyEntryDeleteMonth()" style="padding:8px 18px;border:1px solid #dc2626;border-radius:8px;background:#dc2626;color:#fff;cursor:pointer;font-size:14px;font-weight:600">❌ ลบเดือนนี้</button>';
  }
  if (hasSavedData) {
    h += '<div style="margin-left:auto;font-size:11px;color:#16a34a;font-weight:600">✅ บันทึกแล้ว</div>';
  }
  h += '</div>';

  h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;margin-bottom:14px">';
  h += '<div style="background:#ecfdf5;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">จำนวนรายการ</div><div style="font-size:1.3rem;font-weight:800;color:#059669">'+prods.length+'</div></div>';
  h += '<div style="background:#eff6ff;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">ยอดเบิกรวม (ชิ้น)</div><div style="font-size:1.3rem;font-weight:800;color:#3b82f6" id="se_totQty">0</div></div>';
  h += '<div style="background:#fff7ed;border-radius:8px;padding:12px 14px;text-align:center"><div style="font-size:11px;color:#64748b;font-weight:600">มูลค่ารวม (บาท)</div><div style="font-size:1.3rem;font-weight:800;color:#f97316" id="se_totAmt">0.00</div></div>';
  h += '</div>';

  h += '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:12px">';
  h += '<thead><tr style="background:#1e293b;color:#fff;font-size:10.5px">';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:center;width:36px">ลำดับ</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:left">รหัสสินค้า</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:left">ชื่อสินค้า</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:center;width:50px">หน่วย</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:right;width:80px">ราคาต้นทุน</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:center;width:100px;background:#059669">ยอดเบิก</th>';
  h += '<th style="padding:8px 6px;border:1px solid #334155;text-align:right;width:110px;background:#f97316">เป็นเงิน (บาท)</th>';
  h += '</tr></thead><tbody>';

  prods.forEach(function(p, i) {
    var s = savedMap[p.code] || {};
    var qty = s.qty || '';
    var amt = (s.qty || 0) * (p.cost || 0);
    var bg = i % 2 === 0 ? '#fff' : '#f8fafc';
    h += '<tr style="background:'+bg+'">';
    h += '<td style="padding:5px 6px;border:1px solid #e2e8f0;text-align:center;color:#94a3b8;font-size:10px">'+(i+1)+'</td>';
    h += '<td style="padding:5px 6px;border:1px solid #e2e8f0;font-weight:600;font-size:11px;color:#3b82f6">'+p.code+'</td>';
    h += '<td style="padding:5px 6px;border:1px solid #e2e8f0;font-size:11px">'+p.name+'</td>';
    h += '<td style="padding:5px 6px;border:1px solid #e2e8f0;text-align:center;font-size:11px;color:#64748b">'+p.unit+'</td>';
    h += '<td style="padding:5px 6px;border:1px solid #e2e8f0;text-align:right;font-size:11px">'+fmtN(p.cost)+'</td>';
    h += '<td style="padding:3px 4px;border:1px solid #e2e8f0;text-align:center;background:#ecfdf5">';
    h += '<input id="se_qty_'+i+'" type="number" min="0" value="'+(qty||'')+'" oninput="_supplyEntryCalcRow('+i+')" style="width:80px;padding:5px 6px;border:1.5px solid #d1d5db;border-radius:6px;font-size:13px;text-align:right;font-weight:600" placeholder="0" /></td>';
    h += '<td style="padding:5px 8px;border:1px solid #e2e8f0;text-align:right;font-weight:700;color:#f97316;font-size:12px" id="se_amt_'+i+'">'+fmtN(amt)+'</td>';
    h += '</tr>';
  });

  h += '</tbody>';
  h += '<tfoot><tr style="background:#f1f5f9;font-weight:800">';
  h += '<td colspan="5" style="padding:8px 10px;border:1px solid #e2e8f0;text-align:right;font-size:12px">รวมทั้งหมด</td>';
  h += '<td style="padding:8px 10px;border:1px solid #e2e8f0;text-align:center;font-size:13px;color:#059669" id="se_totQtyFoot">0</td>';
  h += '<td style="padding:8px 10px;border:1px solid #e2e8f0;text-align:right;font-size:13px;color:#f97316" id="se_totAmtFoot">0.00</td>';
  h += '</tr></tfoot>';
  h += '</table></div>';

  h += '<div style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap">';
  h += '<button onclick="_supplyEntrySave()" style="padding:10px 28px;border:none;border-radius:8px;background:'+accent+';color:#fff;cursor:pointer;font-size:15px;font-weight:700">💾 บันทึกข้อมูลเดือน '+_supplyEntryMonth+'</button>';
  h += '</div>';

  h += '</div>';
  el.innerHTML = h;
  _supplyEntryUpdateTotal();
}

// ─── ต้นทุนขายสินค้า state & render ───────────────────────────────────────
var _costMo='',_costView='prod',_costProdPage=0,_costYear=2569;
var _costFromYear=2568,_costFromMo='ม.ค.',_costToYear=2569,_costToMo='ก.ค.';
var _costMode='yr',_costYrSingle=2569;
var _costSingleMo=null; // {yr,mo} or null = all months
var _COST_MONTHS_69=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.'];
var _COST_MONTHS_68=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
var _COST_ALL_MONTHS={2568:['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'],
  2569:['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.']};
var _COST_LABELS=['ต้นทุนสินค้า','ต้นทุนค่ากล่องพัสดุ','ต้นทุนค่าบับเบิ้ล + เทปใส',
  'ต้นทุนค่าแรงพนักงานที่เกี่ยวข้อง','ต้นทุนค่าขนส่ง (COD) , (ปณ.)',
  'ต้นทุนค่ากระตุ้นยอดขาย (ยิง ADS)','ต้นทุนค่าจ้างอินฟลูเรนเซอร์',
  'ต้นทุนเบิกสินค้าไลฟ์สด','ค่าโทรศัพท์ที่เกี่ยวข้องในแผนกออนไลน์','วัสดุสิ้นเปลืองใช้จัดฉาก'];
var _COST_KEYS=['prod','box','bubble','labor','ship','ads','influ','live','phone','supply'];
var _COST_ICONS=['🛒','📦','🫧','👷','🚚','📢','🤳','🎬','📱','🧹'];
var _COST_SKIP_LABELS={'ต้นทุน Outsource':1,'วัสดุสิ้นเปลือง':1,'ต้นทุนค่าแรงผลิต':1,'วัสดุสิ้นเปลืองใช้จัดฉาก':1,'ค่าเบิกของจัดฉากไลฟ์สด':1};
var _COST_ICON_MAP={'ต้นทุนสินค้า':'🛒','ต้นทุนค่ากล่องพัสดุ':'📦','ต้นทุนค่าบับเบิ้ล + เทปใส':'🫧',
  'ต้นทุนค่าแรงพนักงานที่เกี่ยวข้อง':'👷','ต้นทุนค่าขนส่ง (COD) , (ปณ.)':'🚚',
  'ต้นทุนค่ากระตุ้นยอดขาย (ยิง ADS)':'📢','ต้นทุนค่าจ้างอินฟลูเรนเซอร์':'🤳',
  'ต้นทุนเบิกสินค้าไลฟ์สด':'🎬','ค่าโทรศัพท์ที่เกี่ยวข้องในแผนกออนไลน์':'📱',
  'วัสดุสิ้นเปลืองใช้จัดฉาก':'🧹','ต้นทุนค่าใช้จ่ายแพลตฟอร์ม':'🏪','ต้นทุนค่าแคมเปญ':'🎯',
  'ต้นทุน Outsource':'🔧','ค่าเบิกของจัดฉากไลฟ์สด':'🎥','วัสดุสิ้นเปลือง':'🧹'};
function setCostMode(m){
  _costMode=m;
  if(m!=='yr') _costSingleMo=null; // reset month tab when switching mode
  ['yr','mo','day'].forEach(function(n){
    var btn=document.getElementById('costMode-'+n);
    var div=document.getElementById('costFilter-'+n);
    var on=(n===m);
    if(btn){btn.style.background=on?'#7c3aed':'#fff';btn.style.color=on?'#fff':'#7c3aed';}
    if(div) div.style.display=on?'flex':'none';
  });
  renderCostMonthTabs();
  renderCost();
}
function applyDayFilter(){
  // Convert CE dates to BE year+month pairs for _costFromYear/Mo/ToYear/Mo
  var fd=document.getElementById('costFromDate');
  var td=document.getElementById('costToDate');
  if(!fd||!td) return;
  var fv=fd.value,tv=td.value; // "YYYY-MM-DD" CE
  if(!fv||!tv) return;
  var fp=fv.split('-'),tp=tv.split('-');
  var TH_MO=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  _costFromYear=parseInt(fp[0])+543;
  _costFromMo=TH_MO[parseInt(fp[1])-1]||'ม.ค.';
  _costToYear=parseInt(tp[0])+543;
  _costToMo=TH_MO[parseInt(tp[1])-1]||'ธ.ค.';
  renderCost();
}
function resetCostFilter(){
  _costMode='yr';_costYrSingle=2569;
  _costFromYear=2568;_costFromMo='ม.ค.';_costToYear=2569;_costToMo='ก.ค.';
  var el;
  if(el=document.getElementById('costYrSingle')) el.value=2569;
  if(el=document.getElementById('costFromYrSel')) el.value=2568;
  if(el=document.getElementById('costFromMoSel')) el.value='ม.ค.';
  if(el=document.getElementById('costToYrSel')) el.value=2569;
  if(el=document.getElementById('costFromDate')) el.value='2025-01-01';
  if(el=document.getElementById('costToDate')) el.value='2026-07-31';
  _costSingleMo=null;
  var ab=document.getElementById('costApplyBtn');if(ab)ab.style.display='none';
  setCostMode('yr');
  updateCostFilter();
}
function renderCostMonthTabs(){
  var row=document.getElementById('costMonthTabRow');
  if(!row) return;
  if(_costMode!=='yr'){row.style.display='none';return;}
  var yrs=_costYrSingle===0?[2568,2569]:[_costYrSingle];
  var months=[];
  yrs.forEach(function(yr){
    (_COST_ALL_MONTHS[yr]||[]).forEach(function(mo){
      months.push({yr:yr,mo:mo,label:mo+"'"+(yr===2568?'68':'69')});
    });
  });
  if(months.length===0){row.style.display='none';return;}
  row.style.display='flex';
  var BG_ON='#7c3aed',BG_OFF='#fff',C_ON='#fff',C_OFF='#7c3aed';
  var BSTYLE='padding:4px 12px;border-radius:20px;border:1.5px solid #7c3aed;font-size:11px;font-weight:700;cursor:pointer;';
  var allActive=_costSingleMo===null;
  var html='<span style="font-size:11px;color:#7c3aed;font-weight:600">📆 เดือน:</span>'+
    '<button onclick="setCostMonthTab(null)" style="'+BSTYLE+'background:'+(allActive?BG_ON:BG_OFF)+';color:'+(allActive?C_ON:C_OFF)+'">ทั้งหมด</button>';
  months.forEach(function(m){
    var active=_costSingleMo&&_costSingleMo.yr===m.yr&&_costSingleMo.mo===m.mo;
    html+='<button onclick="setCostMonthTab({yr:'+m.yr+',mo:\''+m.mo+'\'})" style="'+BSTYLE+'background:'+(active?BG_ON:BG_OFF)+';color:'+(active?C_ON:C_OFF)+'">'+m.label+'</button>';
  });
  row.innerHTML=html;
}
function setCostMonthTab(mo){
  _costSingleMo=mo;
  renderCostMonthTabs();
  renderCost();
}
function showCostApply(){
  var btn=document.getElementById('costApplyBtn');
  if(btn){btn.style.display='inline-block';}
}
function applyCostFilter(){
  if(_costMode==='day') applyDayFilter();
  else renderCost();
  var btn=document.getElementById('costApplyBtn');
  if(btn) btn.style.display='none';
}
function updateCostFilterOnly(){
  // Rebuild month selectors without rendering (used when year changes)
  var fromMos=_COST_ALL_MONTHS[_costFromYear]||[];
  var fsel=document.getElementById('costFromMoSel');
  if(fsel){
    fsel.innerHTML='<option value="all">ทั้งหมด</option>'+fromMos.map(function(m){return'<option value="'+m+'">'+m+'</option>';}).join('');
    if(_costFromMo!=='all'&&fromMos.indexOf(_costFromMo)<0) _costFromMo='all';
    fsel.value=_costFromMo;
  }
  showCostApply();
}
function updateCostFilter(){
  // Rebuild month selectors for รายเดือน mode
  var fromMos=_COST_ALL_MONTHS[_costFromYear]||[];
  var fsel=document.getElementById('costFromMoSel');
  if(fsel){
    fsel.innerHTML='<option value="all">ทั้งหมด</option>'+fromMos.map(function(m){return'<option value="'+m+'">'+m+'</option>';}).join('');
    if(_costFromMo!=='all'&&fromMos.indexOf(_costFromMo)<0) _costFromMo='all';
    fsel.value=_costFromMo;
  }
  var lbl=document.getElementById('costRangeLabel');
  var months=_getCostMonths();
  if(lbl) lbl.textContent=months.length+' เดือน';
  renderCost();
}
function switchCostView(v){
  _costView=v;
  ['prod','exp'].forEach(function(n){
    var el=document.getElementById('costv-'+n);
    if(el) el.style.display=(n===v?'':'none');
    var btn=document.getElementById('cost-btn-'+n);
    if(btn){btn.style.background=n===v?'#7c3aed':'#fff';btn.style.color=n===v?'#fff':'#7c3aed';}
  });
  // Show sub-toggle only when รวมค่าใช้จ่าย is active
  var wrap=document.getElementById('cexp-toggle-wrap');
  if(wrap) wrap.style.display=(v==='exp'?'flex':'none');
  if(v==='prod') renderCostProducts();
  else renderCostExpenses();
}
function renderCost(){
  renderCostMonthTabs();
  var months=_getCostMonths();
  var lbl=document.getElementById('costRangeLabel');
  if(lbl) lbl.textContent=months.length+' เดือน';
  if(_costView==='prod') renderCostProducts();
  else renderCostExpenses();
}
function _getCostItemsForYrMo(yr,mo){
  var cMap=_getAmzCostMap();
  var src=cMap[yr];
  if(!src) return [];
  var d=src[mo]; if(!d) return [];
  if(d.items) return d.items.map(function(it){return{label:it[0],val:it[1]};});
  return _COST_KEYS.map(function(k,i){return{label:_COST_LABELS[i],val:d[k]||0};});
}
// Legacy alias for backward compat
function _getCostItems(mo){ return _getCostItemsForYrMo(_costYear,mo); }
function _getCostMonths(){
  // Returns [{yr,mo,label}] based on current mode
  var result=[];
  var moBase=_COST_MONTHS_68;
  if(_costMode==='yr'){
    // รายปี: all months of selected year (or both years)
    var yrs=_costYrSingle===0?[2568,2569]:[_costYrSingle];
    yrs.forEach(function(yr){
      (_COST_ALL_MONTHS[yr]||[]).forEach(function(mo){
        result.push({yr:yr,mo:mo,label:mo+(yr===2568?"'68":"'69")});
      });
    });
    // Filter by selected month tab
    if(_costSingleMo){
      result=result.filter(function(x){return x.yr===_costSingleMo.yr&&x.mo===_costSingleMo.mo;});
    }
  } else {
    // รายเดือน: all months of year if 'all', else single month
    if(_costFromMo==='all'){
      (_COST_ALL_MONTHS[_costFromYear]||[]).forEach(function(mo){
        result.push({yr:_costFromYear,mo:mo,label:mo+(_costFromYear===2568?"'68":"'69")});
      });
    } else {
      var fromIdx=moBase.indexOf(_costFromMo);
      var toIdx=moBase.indexOf(_costToMo);
      [2568,2569].forEach(function(yr){
        (_COST_ALL_MONTHS[yr]||[]).forEach(function(mo){
          var mi=moBase.indexOf(mo);
          var afterFrom=yr>_costFromYear||(yr===_costFromYear&&mi>=fromIdx);
          var beforeTo=yr<_costToYear||(yr===_costToYear&&mi<=toIdx);
          if(afterFrom&&beforeTo) result.push({yr:yr,mo:mo,label:mo+(yr===2568?"'68":"'69")});
        });
      });
    }
  }
  return result;
}
function renderCostProducts(){
  var mos=_getCostMonths();  // [{yr,mo,label}]
  // Aggregate products across selected months (cross-year)
  var map={};
  mos.forEach(function(item){
    var PROD=(_getAmzProdMap()[item.yr])||{};
    var ps=PROD[item.mo]||[];
    ps.forEach(function(p){
      var key=p[0]+'_'+p[1];
      if(!map[key]) map[key]={code:p[0],name:p[1],price:p[2],unit:p[4],qty:0,cost:0};
      map[key].qty+=p[3];
      map[key].cost=Math.round((map[key].cost+p[5])*100)/100;
    });
  });
  var all=Object.values(map).sort(function(a,b){return b.cost-a.cost;});
  // Search
  var q=((document.getElementById('costProdSearch')||{}).value||'').toLowerCase().trim();
  if(q) all=all.filter(function(p){return String(p.code).includes(q)||p.name.toLowerCase().includes(q);});
  var total=all.length,ps=25,page=_costProdPage;
  var maxPage=Math.max(0,Math.ceil(total/ps)-1);
  if(page>maxPage) page=_costProdPage=maxPage;
  var slice=all.slice(page*ps,(page+1)*ps);
  var cnt=document.getElementById('costProdCount');
  if(cnt) cnt.textContent=total.toLocaleString()+' รายการ';
  var tbody=document.getElementById('costProdTable');
  if(tbody) tbody.innerHTML=slice.map(function(p,i){
    var bg=i%2===0?'':'background:#faf5ff';
    return'<tr style="'+bg+'">'+
      '<td style="padding:6px 12px;font-family:monospace;font-size:11px;color:#7c3aed">'+p.code+'</td>'+
      '<td style="padding:6px 12px">'+p.name+'</td>'+
      '<td style="padding:6px 12px;text-align:center;color:#64748b">'+p.unit+'</td>'+
      '<td style="padding:6px 12px;text-align:right">'+p.price.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
      '<td style="padding:6px 12px;text-align:right;font-weight:700;color:#7c3aed">'+p.qty.toLocaleString()+'</td>'+
      '<td style="padding:6px 12px;text-align:right;font-weight:700;color:#1e40af">'+p.cost.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
    '</tr>';
  }).join('');
  var pager=document.getElementById('costProdPager');
  if(pager){
    var btns='';
    var totalPages=Math.ceil(total/ps);
    if(totalPages>1){
      btns+='<button onclick="_costProdPage=Math.max(0,_costProdPage-1);renderCostProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">◀</button>';
      var start=Math.max(0,page-2),end=Math.min(totalPages-1,start+4);
      for(var p2=start;p2<=end;p2++){
        var active=p2===page;
        btns+='<button onclick="_costProdPage='+p2+';renderCostProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid '+(active?'#7c3aed':'#e2e8f0')+';background:'+(active?'#7c3aed':'#fff')+';color:'+(active?'#fff':'#1e293b')+';cursor:pointer">'+(p2+1)+'</button>';
      }
      btns+='<button onclick="_costProdPage=Math.min('+(totalPages-1)+',_costProdPage+1);renderCostProducts()" style="padding:4px 10px;border-radius:6px;border:1px solid #e2e8f0;cursor:pointer">▶</button>';
    }
    pager.innerHTML=btns;
  }
}
function renderCostExpenses(){
  var mos=_getCostMonths();  // [{yr,mo,label}]
  // Aggregate generic items across months (cross-year)
  var labelMap={};
  var grandTotal=0;
  mos.forEach(function(item){
    var items=_getCostItemsForYrMo(item.yr,item.mo);
    items.forEach(function(it){
      var lbl=(it.label||'').trim();
      if(_COST_SKIP_LABELS[lbl]) return;
      if(!labelMap[lbl]) labelMap[lbl]=0;
      labelMap[lbl]=Math.round((labelMap[lbl]+it.val)*100)/100;
    });
    var _cSrc=(_getAmzCostMap()[item.yr])||{};
    var d=_cSrc[item.mo];if(d) grandTotal=Math.round((grandTotal+d.total)*100)/100;
  });
  var aggItems=Object.keys(labelMap).map(function(lbl){
    return{label:lbl,val:labelMap[lbl],icon:_COST_ICON_MAP[lbl]||'💼'};
  }).sort(function(a,b){return b.val-a.val;});
  // KPI cards
  var kpiDiv=document.getElementById('costExpKPI');
  if(kpiDiv){
    var months=_getCostMonths();var yearLabel=months.length>0?(months[0].label+' – '+months[months.length-1].label):'–';
    var totalCard='<div style="grid-column:1/-1;background:linear-gradient(135deg,#7c3aed,#a855f7);border-radius:12px;padding:14px 18px;color:#fff;display:flex;align-items:center;gap:12px">'+
      '<span style="font-size:28px">💰</span>'+
      '<div><div style="font-size:11px;opacity:.85">ต้นทุนรวมทั้งหมด '+yearLabel+'</div>'+
      '<div style="font-size:22px;font-weight:800">฿'+grandTotal.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</div></div></div>';
    var cards=aggItems.map(function(it){
      var pct=grandTotal>0?((it.val/grandTotal)*100).toFixed(1):'0.0';
      return'<div style="background:#fff;border-radius:10px;padding:12px 14px;border:1px solid #e2e8f0;border-left:4px solid #7c3aed">'+
        '<div style="font-size:16px">'+it.icon+'</div>'+
        '<div style="font-size:10px;color:#64748b;margin:4px 0">'+it.label+'</div>'+
        '<div style="font-size:15px;font-weight:800;color:#7c3aed">฿'+it.val.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+'</div>'+
        '<div style="font-size:10px;color:#94a3b8">'+pct+'% ของต้นทุนรวม</div>'+
      '</div>';
    }).join('');
    kpiDiv.innerHTML=totalCard+cards;
  }
  // Bar chart
  mkChart('costExpBar',{type:'bar',data:{labels:aggItems.map(function(it){
    var l=it.label.replace('ต้นทุน','').replace('ค่า','').trim();return l.length>10?l.substr(0,10)+'…':l;}),
    datasets:[{label:'ต้นทุน (บาท)',data:aggItems.map(function(it){return it.val;}),
    backgroundColor:'rgba(124,58,237,0.75)',borderColor:'#7c3aed',borderWidth:1.5,borderRadius:5}]},
    options:{responsive:true,plugins:{legend:{display:false},
      tooltip:{callbacks:{label:function(ctx){return'฿'+ctx.parsed.y.toLocaleString('th-TH',{minimumFractionDigits:2});}}}},
      scales:{y:{ticks:{callback:function(v){return'฿'+(v>=1000000?(v/1000000).toFixed(1)+'M':v>=1000?(v/1000).toFixed(0)+'K':v);}}}}}});
  // Table
  var tbody=document.getElementById('costExpTable');
  if(tbody){
    tbody.innerHTML=aggItems.map(function(r,i){
      var bg=i%2===0?'':'background:#faf5ff';
      var pct=grandTotal>0?((r.val/grandTotal)*100).toFixed(1):'0.0';
      return'<tr style="'+bg+'">'+
        '<td style="padding:7px 12px;text-align:center">'+r.icon+'</td>'+
        '<td style="padding:7px 12px;font-weight:600">'+r.label+'</td>'+
        '<td style="padding:7px 12px;text-align:right;font-weight:700;color:#7c3aed">฿'+r.val.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
        '<td style="padding:7px 12px;text-align:right;color:#64748b">'+pct+'%</td>'+
      '</tr>';
    }).join('')+
    '<tr style="background:#7c3aed;color:#fff;font-weight:800">'+
      '<td style="padding:8px 12px;text-align:center">💰</td>'+
      '<td style="padding:8px 12px">รวมทั้งหมด</td>'+
      '<td style="padding:8px 12px;text-align:right">฿'+grandTotal.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td>'+
      '<td style="padding:8px 12px;text-align:right">100%</td>'+
    '</tr>';
  }
}
var _costExpView='sum';
var _costCmpGroupBy='mo';
function setCmpGroupBy(g){
  _costCmpGroupBy=g;
  ['mo','yr'].forEach(function(n){
    var btn=document.getElementById('cmpGrp-'+n);
    if(btn){btn.style.background=n===g?'#a855f7':'#fff';btn.style.color=n===g?'#fff':'#a855f7';}
  });
  renderCostCompare();
}
function switchCostExpView(v){
  _costExpView=v;
  ['sum','cmp'].forEach(function(n){
    var el=document.getElementById('cexpv-'+n);
    if(el) el.style.display=(n===v?'':'none');
    var btn=document.getElementById('cexp-btn-'+n);
    if(btn){btn.style.background=n===v?'#a855f7':'#fff';btn.style.color=n===v?'#fff':'#a855f7';}
  });
  if(v==='cmp') renderCostCompare();
}
function renderCostCompare(){
  // Use date range months
  var CMS_OBJ_ALL=_getCostMonths();  // [{yr,mo,label}]
  // ── Build X-axis based on groupBy mode ──
  var CMS, CMS_OBJ;
  if(_costCmpGroupBy==='yr'){
    // Group by year: create virtual items per year
    var yrSet={};
    CMS_OBJ_ALL.forEach(function(x){yrSet[x.yr]=true;});
    var yrs=Object.keys(yrSet).sort();
    CMS=yrs.map(function(y){return'ปี '+y;});
    // Build virtual CMS_OBJ with yr-level labels for matrix key
    CMS_OBJ=yrs.map(function(y){return{yr:parseInt(y),mo:null,label:'ปี '+y};});
  } else {
    CMS_OBJ=CMS_OBJ_ALL;
    CMS=CMS_OBJ.map(function(x){return x.label;});
  }
  // Collect all unique cost labels in order of first appearance
  var labelOrder=[],labelSet={};
  CMS_OBJ_ALL.forEach(function(item){
    _getCostItemsForYrMo(item.yr,item.mo).forEach(function(it){
      var lbl=(it.label||'').trim();
      if(lbl&&!labelSet[lbl]&&!_COST_SKIP_LABELS[lbl]){labelSet[lbl]=true;labelOrder.push(lbl);}
    });
  });
  // Build data matrix: costLabel -> {xLabel: val}
  var matrix={};
  labelOrder.forEach(function(lbl){matrix[lbl]={};});
  var moTotals={};
  if(_costCmpGroupBy==='yr'){
    // Sum all months per year
    CMS_OBJ_ALL.forEach(function(item){
      var xLbl='ปี '+item.yr;
      if(!moTotals[xLbl]) moTotals[xLbl]=0;
      _getCostItemsForYrMo(item.yr,item.mo).forEach(function(it){
        var lbl=(it.label||'').trim();
        if(!matrix[lbl]) matrix[lbl]={};
        matrix[lbl][xLbl]=Math.round(((matrix[lbl][xLbl]||0)+it.val)*100)/100;
        moTotals[xLbl]=Math.round((moTotals[xLbl]+it.val)*100)/100;
      });
    });
  } else {
    CMS_OBJ.forEach(function(item){
      var xLbl=item.label;
      moTotals[xLbl]=0;
      _getCostItemsForYrMo(item.yr,item.mo).forEach(function(it){
        var lbl=(it.label||'').trim();
        if(!matrix[lbl]) matrix[lbl]={};
        matrix[lbl][xLbl]=(matrix[lbl][xLbl]||0)+it.val;
        moTotals[xLbl]=Math.round((moTotals[xLbl]+it.val)*100)/100;
      });
    });
  }
  // Row totals
  var rowTotals={};
  labelOrder.forEach(function(lbl){
    rowTotals[lbl]=CMS.reduce(function(s,x){return Math.round((s+(matrix[lbl][x]||0))*100)/100;},0);
  });
  var grandTotal=CMS.reduce(function(s,x){return Math.round((s+moTotals[x])*100)/100;},0);

  // ── Stacked bar chart ──
  var palette=['#7c3aed','#a78bfa','#f59e0b','#10b981','#ef4444','#3b82f6','#f97316','#06b6d4','#84cc16','#ec4899','#8b5cf6','#14b8a6','#f43f5e','#6366f1'];
  var datasets=labelOrder.map(function(lbl,i){
    return{label:lbl,data:CMS.map(function(x){return matrix[lbl][x]||0;}),
      backgroundColor:palette[i%palette.length],borderRadius:2};
  });
  mkChart('costCmpBar',{type:'bar',data:{labels:CMS,datasets:datasets},
    options:{responsive:true,plugins:{legend:{position:'bottom',labels:{font:{size:10},boxWidth:12}},
      tooltip:{mode:'index',callbacks:{label:function(ctx){return ctx.dataset.label.replace('ต้นทุน','').trim()+': ฿'+ctx.parsed.y.toLocaleString('th-TH',{minimumFractionDigits:0});}}}},
      scales:{x:{stacked:true},y:{stacked:true,ticks:{callback:function(v){return'฿'+(v>=1000000?(v/1000000).toFixed(1)+'M':v>=1000?(v/1000).toFixed(0)+'K':v);}}}}}});

  // ── Pivot table ──
  var rowMax={};
  labelOrder.forEach(function(lbl){
    rowMax[lbl]=Math.max.apply(null,CMS.map(function(x){return matrix[lbl][x]||0;}));
  });
  function heatBg(val,max){
    if(!max||!val) return '';
    var t=val/max;
    var r=Math.round(124+t*(220-124));
    var g=Math.round(58+t*(20-58));
    var b=Math.round(237+t*(60-237));
    return'background:rgba('+r+','+g+','+b+','+(0.08+t*0.25)+')';
  }
  var th='<th style="padding:7px 10px;text-align:left;background:#7c3aed;color:#fff;white-space:nowrap;position:sticky;left:0">รายการต้นทุน</th>'+
    CMS.map(function(x){return'<th style="padding:7px 10px;text-align:right;background:#7c3aed;color:#fff;white-space:nowrap;min-width:90px">'+x+'</th>';}).join('')+
    '<th style="padding:7px 10px;text-align:right;background:#581c87;color:#fff;white-space:nowrap">รวม</th>';
  var filteredLabels=labelOrder.filter(function(lbl){return rowTotals[lbl]>0;});
  var rows2=filteredLabels.map(function(lbl,i){
    var bg=i%2===0?'':'background:#faf5ff';
    var cells=CMS.map(function(x){
      var v=matrix[lbl][x]||0;
      var heat=heatBg(v,rowMax[lbl]);
      return'<td style="padding:6px 10px;text-align:right;font-size:12px;'+heat+'">'+
        (v?'฿'+v.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0}):'–')+'</td>';
    }).join('');
    return'<tr style="'+bg+'">'+
      '<td style="padding:6px 10px;font-weight:600;font-size:12px;white-space:nowrap;position:sticky;left:0;background:'+(i%2===0?'#fff':'#faf5ff')+'">'+
        (_COST_ICON_MAP[lbl]||'💼')+' '+lbl+'</td>'+
      cells+
      '<td style="padding:6px 10px;text-align:right;font-weight:700;color:#7c3aed;font-size:12px;white-space:nowrap">฿'+rowTotals[lbl].toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+'</td>'+
    '</tr>';
  }).join('');
  var footCells=CMS.map(function(x){
    return'<td style="padding:7px 10px;text-align:right;font-weight:800;white-space:nowrap">฿'+moTotals[x].toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+'</td>';
  }).join('');
  var cmpDiv=document.getElementById('costCmpTable');
  if(cmpDiv) cmpDiv.innerHTML='<table style="width:100%;border-collapse:collapse;font-size:12px">'+
    '<thead><tr>'+th+'</tr></thead><tbody>'+rows2+'</tbody>'+
    '<tfoot><tr style="background:#7c3aed;color:#fff"><td style="padding:7px 10px;font-weight:800;position:sticky;left:0;background:#7c3aed">💰 รวมทั้งหมด</td>'+
    footCells+'<td style="padding:7px 10px;text-align:right;font-weight:800;background:#581c87">฿'+grandTotal.toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+'</td></tr></tfoot></table>';

  // ── Mini charts per category ──
  var miniDiv=document.getElementById('costCmpMini');
  if(miniDiv){
    var miniPalette=['#7c3aed','#a78bfa','#f59e0b','#10b981','#ef4444','#3b82f6','#f97316','#06b6d4','#84cc16','#ec4899','#8b5cf6','#14b8a6','#f43f5e','#6366f1','#d97706'];
    miniDiv.innerHTML=filteredLabels.map(function(lbl,i){
      return'<div style="background:#fff;border-radius:12px;padding:14px;border:1px solid #e2e8f0">'+
        '<div style="font-size:12px;font-weight:700;color:#1e293b;margin-bottom:8px">'+
          (_COST_ICON_MAP[lbl]||'💼')+' '+lbl+
        '</div>'+
        '<canvas id="costMini_'+i+'" height="120"></canvas>'+
        '<div style="margin-top:6px;text-align:right;font-size:11px;color:#7c3aed;font-weight:700">'+
          'รวม: ฿'+rowTotals[lbl].toLocaleString('th-TH',{minimumFractionDigits:0,maximumFractionDigits:0})+
        '</div>'+
      '</div>';
    }).join('');
    // Render each mini chart after DOM is updated
    setTimeout(function(){
      filteredLabels.forEach(function(lbl,i){
        var vals=CMS.map(function(x){return matrix[lbl][x]||0;});
        var clr=miniPalette[i%miniPalette.length];
        var bg=clr.replace('#','');
        var r=parseInt(bg.substring(0,2),16);
        var g=parseInt(bg.substring(2,4),16);
        var b=parseInt(bg.substring(4,6),16);
        mkChart('costMini_'+i,{type:'bar',
          data:{labels:CMS,datasets:[{label:lbl,data:vals,
            backgroundColor:'rgba('+r+','+g+','+b+',.65)',
            borderColor:clr,borderWidth:1.5,borderRadius:4}]},
          options:{responsive:true,plugins:{legend:{display:false},
            tooltip:{callbacks:{label:function(ctx){return'฿'+ctx.parsed.y.toLocaleString('th-TH',{minimumFractionDigits:0});}}}},
            scales:{x:{ticks:{font:{size:10}}},
              y:{ticks:{font:{size:10},callback:function(v){
                return v>=1000000?(v/1000000).toFixed(1)+'M':v>=1000?(v/1000).toFixed(0)+'K':v;
              }}}}}});
      });
    },50);
  }
}


// ─── รายการขายสินค้า (Product Ranking) ───────────────────────────────────
var _prYear=2569,_prMo='',_prRankFilter='all',_prPage=0;
var _prMode='yr',_prFromYear=2568,_prFromMo='ม.ค.',_prToYear=2569,_prToMo='ก.ค.';
var _PR_MONTHS_69=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.'];
var _PR_MONTHS_68=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
var _TOP10_COLORS=['#dc2626','#ea580c','#f97316','#f59e0b','#eab308','#84cc16','#22c55e','#10b981','#06b6d4','#0891b2'];

function setPrMode(m){
  _prMode=m;
  ['yr','mo','day'].forEach(function(x){
    var btn=document.getElementById('prMode-'+x);
    if(btn) btn.style.background=x===m?'#0891b2':'#fff',btn.style.color=x===m?'#fff':'#0891b2';
    var div=document.getElementById('prFilter-'+x);
    if(div) div.style.display=x===m?'flex':'none';
  });
  // sync selects
  if(m==='yr'){
    var s=document.getElementById('prYrSel'); if(s) s.value=_prYear;
  }
  if(m==='mo') updatePrMoFilter();
  if(m==='day') applyPrDayFilter();
  var lbl=document.getElementById('prRangeLabel');
  if(lbl){var ms=_getPrMonths(); lbl.textContent=ms.length+' เดือน';}
  renderProdRank();
}
function updatePrFilter(){
  renderProdRank();
}
function updatePrMoFilter(){
  var CMS=_prYear===2569?_PR_MONTHS_69:_PR_MONTHS_68;
  var sel=document.getElementById('prMoSel');
  if(sel){
    sel.innerHTML='<option value="">ทั้งหมด</option>'+CMS.map(function(m){return'<option value="'+m+'">'+m+'</option>';}).join('');
    if(_prMo&&CMS.indexOf(_prMo)<0) _prMo='';
    sel.value=_prMo;
  }
  var ysel=document.getElementById('prYrSelMo'); if(ysel) ysel.value=_prYear;
  renderProdRank();
}
function applyPrDayFilter(){
  var TH_MO=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var fd=document.getElementById('prFromDate').value;
  var td=document.getElementById('prToDate').value;
  if(fd){var p=fd.split('-');_prFromYear=parseInt(p[0])+543;_prFromMo=TH_MO[parseInt(p[1])-1];}
  if(td){var p=td.split('-');_prToYear=parseInt(p[0])+543;_prToMo=TH_MO[parseInt(p[1])-1];}
  var lbl=document.getElementById('prRangeLabel');
  if(lbl){var ms=_getPrMonths(); lbl.textContent=ms.length+' เดือน';}
  renderProdRank();
}
function resetPrFilter(){
  _prMode='yr';_prYear=2569;_prMo='';_prRankFilter='all';_prPage=0;
  _prFromYear=2568;_prFromMo='ม.ค.';_prToYear=2569;_prToMo='ก.ค.';
  setPrMode('yr');
  var ysel=document.getElementById('prYrSel'); if(ysel) ysel.value=2569;
  var fd=document.getElementById('prFromDate'); if(fd) fd.value='2025-01-01';
  var td=document.getElementById('prToDate'); if(td) td.value='2026-07-31';
  document.querySelectorAll('.pr-rank-btn').forEach(function(b){
    b.style.background=b.dataset.rank==='all'?'#0891b2':'#fff';
    b.style.color=b.dataset.rank==='all'?'#fff':'#0891b2';
  });
  renderProdRank();
}
function _getPrMonths(){
  // Returns [{yr,mo}] based on current filter mode
  var TH_MO=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var _COST_ALL_MONTHS={2568:['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'],2569:['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.']};
  if(_prMode==='yr'){
    // Single year
    var CMS=_prYear===2569?_PR_MONTHS_69:_PR_MONTHS_68;
    return CMS.map(function(m){return {yr:_prYear,mo:m};});
  } else {
    // Range (mo or day mode)
    var fromYr=_prMode==='day'?_prFromYear:parseInt((document.getElementById('prYrSelMo')||{value:2568}).value)||_prFromYear;
    var fromMo=_prMode==='day'?_prFromMo:(_prMo||'ม.ค.');
    // For 'mo' mode: from = year+first month of selection; show all months in year if no month selected
    if(_prMode==='mo'){
      var yr2=parseInt((document.getElementById('prYrSelMo')||{value:_prYear}).value)||_prYear;
      var CMS2=yr2===2569?_PR_MONTHS_69:_PR_MONTHS_68;
      if(_prMo) return [{yr:yr2,mo:_prMo}];
      return CMS2.map(function(m){return{yr:yr2,mo:m};});
    }
    // day mode: cross-year range
    var result=[];
    var fyIdx=_COST_ALL_MONTHS[_prFromYear]?_COST_ALL_MONTHS[_prFromYear].indexOf(_prFromMo):-1;
    var tyIdx=_COST_ALL_MONTHS[_prToYear]?_COST_ALL_MONTHS[_prToYear].indexOf(_prToMo):-1;
    [2568,2569].forEach(function(yr){
      var mlist=_COST_ALL_MONTHS[yr]||[];
      mlist.forEach(function(mo,mi){
        var after=(yr>_prFromYear)||(yr===_prFromYear&&mi>=fyIdx);
        var before=(yr<_prToYear)||(yr===_prToYear&&mi<=tyIdx);
        if(after&&before) result.push({yr:yr,mo:mo});
      });
    });
    return result;
  }
}
function setPrRankFilter(r){
  _prRankFilter=r;_prPage=0;
  ['all','Aplus','A','B','C'].forEach(function(n){
    var btn=document.getElementById('prRank-'+n);
    var active=(n===r||(n==='Aplus'&&r==='A+'));
    if(!btn) return;
    var colors={'all':'#0891b2','Aplus':'#dc2626','A':'#f59e0b','B':'#22c55e','C':'#94a3b8'};
    var c=colors[n]||'#0891b2';
    btn.style.background=active?c:'#fff';
    btn.style.color=active?'#fff':c;
  });
  renderProdRank();
}
function _getPrProducts(){
  var mos=_getPrMonths();
  var map={};
  mos.forEach(function(item){
    var yr=item.yr,mo=item.mo;
    var PROD=(_getAmzProdMap()[yr])||{};
    (PROD[mo]||[]).forEach(function(p){
      var key=String(p[0])+'_'+p[1];
      if(!map[key]) map[key]={code:p[0],name:p[1],price:p[2],unit:p[4],qty:0,cost:0};
      map[key].qty+=p[3];
      map[key].cost=Math.round((map[key].cost+p[5])*100)/100;
    });
  });
  // Sort by cost desc, assign rank
  var all=Object.values(map).filter(function(p){return p.qty>0||p.cost>0;})
    .sort(function(a,b){return b.cost-a.cost;});
  var total=all.reduce(function(s,p){return s+p.cost;},0);
  var n=all.length;
  all.forEach(function(p,i){
    p.pct=total>0?((p.cost/total)*100).toFixed(1):'0.0';
    p.rank=i<3?'A+':(i<Math.round(n*0.25)?'A':(i<Math.round(n*0.6)?'B':'C'));
    p.rankNo=i+1;
  });
  return{products:all,total:total};
}
var _olPPMonthShowBaht = true;
function renderProdRank(){
  var el = document.getElementById('prContent');
  if(!el) return;

  var TH_MO = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  var MONTHS_EN = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  var mos = _getPrMonths();
  var map = {};
  mos.forEach(function(item){
    var yr = item.yr, mo = item.mo;
    var PROD = (_getAmzProdMap()[yr])||{};
    var moIdx = TH_MO.indexOf(mo);
    var moKey = moIdx>=0 ? MONTHS_EN[moIdx] : mo;
    (PROD[mo]||[]).forEach(function(p){
      var key = String(p[0])+'_'+p[1];
      if(!map[key]) map[key] = {code:p[0], name:p[1], price:p[2], unit:p[4], qty:0, cost:0, monthly:{}};
      map[key].qty += p[3];
      map[key].cost = Math.round((map[key].cost + p[5])*100)/100;
      if(!map[key].monthly[moKey]) map[key].monthly[moKey] = {b:0, q:0};
      map[key].monthly[moKey].b += p[5];
      map[key].monthly[moKey].q += p[3];
    });
  });

  var all = Object.values(map).filter(function(p){return p.qty>0||p.cost>0;})
    .sort(function(a,b){return b.cost - a.cost;});
  var totalRev = all.reduce(function(s,p){return s+p.cost;},0);
  var totalQty = all.reduce(function(s,p){return s+p.qty;},0);
  var n = all.length;
  all.forEach(function(p,i){
    p.pct = totalRev>0 ? ((p.cost/totalRev)*100).toFixed(1) : '0.0';
    p.rank = i<3 ? 'A+' : (i<Math.round(n*0.25) ? 'A' : (i<Math.round(n*0.6) ? 'B' : 'C'));
    p.rankNo = i+1;
  });

  var aplusCount = all.filter(function(p){return p.rank==='A+';}).length;

  var activeMonths = [];
  all.forEach(function(p){
    if(p.monthly){Object.keys(p.monthly).forEach(function(mk){if(activeMonths.indexOf(mk)===-1)activeMonths.push(mk);});}
  });
  activeMonths.sort(function(a,b){return MONTHS_EN.indexOf(a)-MONTHS_EN.indexOf(b);});

  var OL_PP_CATS = [
    {key:'cake',  label:'เค้ก',      icon:'🎂', clr:'#e11d48', match:function(nm){return nm.indexOf('เค้ก')!==-1||nm.indexOf('เบาหวิว')!==-1||nm.indexOf('ชิฟฟ่อน')!==-1||nm.indexOf('ชิฟฟอน')!==-1||nm.indexOf('ลาวา')!==-1||nm.indexOf('ซอฟท์')!==-1;}},
    {key:'bread', label:'ขนมปัง',    icon:'🍞', clr:'#d97706', match:function(nm){return nm.indexOf('ขนมปัง')!==-1||nm.indexOf('แซนวิช')!==-1||nm.indexOf('แซนด์วิช')!==-1||nm.indexOf('ปัง')!==-1||nm.indexOf('โฮลวีท')!==-1;}},
    {key:'piah',  label:'เปี๊ยะ',    icon:'🥟', clr:'#7c3aed', match:function(nm){return nm.indexOf('เปี๊ยะ')!==-1;}},
    {key:'cream', label:'ครีมฮอร์น', icon:'🥐', clr:'#0891b2', match:function(nm){return nm.indexOf('ครีมฮอร์น')!==-1||nm.indexOf('เอแคลร์')!==-1||nm.indexOf('เครปโรล')!==-1;}},
    {key:'snack', label:'ขนม',       icon:'🧁', clr:'#16a34a', match:function(nm){return nm.indexOf('ทาร์ต')!==-1||nm.indexOf('คอนเฟล็ก')!==-1||nm.indexOf('คัพเค้ก')!==-1||nm.indexOf('ปังสังขยา')!==-1;}}
  ];
  function _olGetCat(name){for(var i=0;i<OL_PP_CATS.length;i++){if(OL_PP_CATS[i].match(name))return OL_PP_CATS[i].key;}return 'other';}
  var catCounts = {};
  OL_PP_CATS.forEach(function(c){catCounts[c.key]=[];});
  catCounts.other = [];
  all.forEach(function(p){var cat=_olGetCat(p.name);catCounts[cat].push(p);});

  var catLabels = [], catValues = [], catColors = [];
  OL_PP_CATS.forEach(function(c){
    var items = catCounts[c.key];
    if(items.length>0){
      catLabels.push(c.label);
      catValues.push(items.reduce(function(s,d){return s+d.cost;},0));
      catColors.push(c.clr);
    }
  });
  if(catCounts.other.length>0){
    catLabels.push('อื่นๆ');
    catValues.push(catCounts.other.reduce(function(s,d){return s+d.cost;},0));
    catColors.push('#94a3b8');
  }

  var fmtB = function(v){if(v>=1e6)return(v/1e6).toFixed(2)+' M';if(v>=1e3)return(v/1e3).toFixed(1)+' K';return Math.round(v).toLocaleString();};
  var fmtQ = function(v){return Math.round(v).toLocaleString('th-TH');};

  var html = '';

  // KPI cards
  html += '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px">';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;text-align:center;padding:16px"><div style="font-size:11px;color:#64748b">จำนวน SKU</div><div style="font-size:22px;font-weight:800;color:#4f46e5">'+all.length+'</div></div>';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;text-align:center;padding:16px"><div style="font-size:11px;color:#64748b">ยอดขายรวม (บาท)</div><div style="font-size:22px;font-weight:800;color:#16a34a">'+fmtB(totalRev)+'</div></div>';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;text-align:center;padding:16px"><div style="font-size:11px;color:#64748b">จำนวนชิ้นรวม</div><div style="font-size:22px;font-weight:800;color:#0891b2">'+fmtQ(totalQty)+'</div></div>';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;text-align:center;padding:16px"><div style="font-size:11px;color:#64748b">สินค้า A+</div><div style="font-size:22px;font-weight:800;color:#d97706">'+aplusCount+'</div></div>';
  html += '</div>';

  // Charts: Top 10 + Category doughnut
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px">';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:16px 20px"><div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:12px">📊 Top 10 สินค้าขายดี (บาท)</div>';
  html += '<div style="position:relative;height:300px"><canvas id="olPPTop10Chart"></canvas></div></div>';
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:16px 20px"><div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:12px">📊 สัดส่วนตามหมวดสินค้า</div>';
  html += '<div style="position:relative;height:300px"><canvas id="olPPCatChart"></canvas></div></div>';
  html += '</div>';

  // Category summary cards
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:16px">';
  OL_PP_CATS.forEach(function(c){
    var items = catCounts[c.key];
    var catTotal = items.reduce(function(s,d){return s+d.cost;},0);
    html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:14px;text-align:center;border-left:4px solid '+c.clr+'">'
      +'<div style="font-size:18px">'+c.icon+'</div>'
      +'<div style="font-size:12px;font-weight:700;color:'+c.clr+';margin:4px 0">'+c.label+'</div>'
      +'<div style="font-size:16px;font-weight:800;color:#1e293b">'+items.length+' SKU</div>'
      +'<div style="font-size:11px;color:#64748b">฿'+fmtB(catTotal)+'</div></div>';
  });
  var otherItems = catCounts.other;
  var otherTotal = otherItems.reduce(function(s,d){return s+d.cost;},0);
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:14px;text-align:center;border-left:4px solid #94a3b8">'
    +'<div style="font-size:18px">📦</div>'
    +'<div style="font-size:12px;font-weight:700;color:#94a3b8;margin:4px 0">อื่นๆ</div>'
    +'<div style="font-size:16px;font-weight:800;color:#1e293b">'+otherItems.length+' SKU</div>'
    +'<div style="font-size:11px;color:#64748b">฿'+fmtB(otherTotal)+'</div></div>';
  html += '</div>';

  // Full product table with filters
  html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:16px 20px;margin-bottom:16px">';
  html += '<div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:12px">📋 ตารางผลงานสินค้า</div>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;align-items:center">';
  html += '<select id="olPPFilterRank" onchange="_olPPFilterTable()" style="padding:6px 12px;border-radius:8px;border:1px solid #e2e8f0;font-size:13px;background:#fff;color:#1e293b">';
  html += '<option value="all">Rank: ทั้งหมด</option><option value="A+">A+</option><option value="A">A</option><option value="B">B</option><option value="C">C</option></select>';
  html += '<input id="olPPSearch" oninput="_olPPFilterTable()" placeholder="🔍 ค้นหาสินค้า..." style="padding:6px 12px;border-radius:8px;border:1px solid #e2e8f0;font-size:13px;flex:1;min-width:180px;background:#fff;color:#1e293b">';
  html += '</div>';

  html += '<div style="overflow-x:auto"><table id="olPPProdTable" style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f8fafc">';
  html += '<th style="padding:8px;text-align:center;font-size:11px;text-transform:uppercase;color:#64748b">NO</th>';
  html += '<th style="padding:8px;text-align:left;font-size:11px;text-transform:uppercase;color:#64748b">ชื่อสินค้า</th>';
  html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b">ราคา/ชิ้น</th>';
  html += '<th style="padding:8px;text-align:center;font-size:11px;text-transform:uppercase;color:#64748b">RANK</th>';
  html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b">รวมชิ้น</th>';
  html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b">รวมบาท</th>';
  html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b">%REVENUE</th>';
  html += '<th style="padding:8px;text-align:center;font-size:11px;text-transform:uppercase;color:#64748b">Performance</th>';
  html += '<th style="padding:8px;text-align:center;font-size:11px;text-transform:uppercase;color:#64748b">กราฟ</th>';
  html += '</tr></thead><tbody>';

  window._olPPAllData = all;
  window._olPPActiveMonths = activeMonths;
  window._olPPMonthsEN = MONTHS_EN;
  window._olPPMonthsTH = TH_MO;

  all.forEach(function(p,i){
    var pct = totalRev>0 ? ((p.cost/totalRev)*100) : 0;
    var rankColor = p.rank==='A+'?'#dc2626':p.rank==='A'?'#ea580c':p.rank==='B'?'#d97706':'#94a3b8';
    var bg = i%2 ? 'background:rgba(0,0,0,.02)' : '';
    var mv = activeMonths.map(function(mk){return p.monthly[mk]?p.monthly[mk].b:0;});
    var pf = window.calcPerf(mv);
    html += '<tr style="'+bg+'" data-rank="'+p.rank+'" data-name="'+(p.name||'').toLowerCase()+'">';
    html += '<td style="padding:6px 8px;text-align:center;color:#64748b">'+(i+1)+'</td>';
    html += '<td style="padding:6px 8px;font-weight:600;max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="'+p.name+'">'+p.name+'</td>';
    html += '<td style="padding:6px 8px;text-align:right;font-weight:600">'+p.price.toFixed(2)+'</td>';
    html += '<td style="padding:6px 8px;text-align:center"><span style="display:inline-block;padding:2px 10px;border-radius:10px;font-size:11px;font-weight:800;color:#fff;background:'+rankColor+'">'+p.rank+'</span></td>';
    html += '<td style="padding:6px 8px;text-align:right;font-weight:600">'+fmtQ(p.qty)+'</td>';
    html += '<td style="padding:6px 8px;text-align:right;font-weight:600">'+fmtB(p.cost)+'</td>';
    html += '<td style="padding:6px 8px;text-align:right;color:#64748b">'+pct.toFixed(1)+'%</td>';
    html += '<td style="padding:6px 8px;text-align:center">'+window.perfBadgeHTML(pf)+'</td>';
    html += '<td style="padding:6px 8px;text-align:center"><button onclick="_olPPShowChart('+i+')" style="background:none;border:none;cursor:pointer;font-size:16px" title="ดูกราฟรายเดือน">🔍</button></td>';
    html += '</tr>';
  });
  html += '</tbody></table></div></div>';

  // Monthly breakdown table
  if(activeMonths.length>0){
    html += '<div style="background:#fff;border-radius:12px;border:1px solid #e2e8f0;padding:16px 20px;margin-bottom:16px">';
    html += '<div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:12px">📅 ยอดขายรายเดือน</div>';
    html += '<div style="display:flex;gap:8px;margin-bottom:10px">';
    html += '<button id="olPPMonthUnit" onclick="_olPPToggleMonthUnit()" style="padding:4px 14px;border-radius:8px;border:1px solid #e2e8f0;font-size:12px;cursor:pointer;background:#fff;color:#1e293b">แสดง: บาท</button>';
    html += '</div>';
    html += '<div style="overflow-x:auto"><table id="olPPMonthTable" style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#f8fafc">';
    html += '<th style="padding:8px;text-align:left;font-size:11px;text-transform:uppercase;color:#64748b;position:sticky;left:0;background:#f8fafc;z-index:2">ชื่อสินค้า</th>';
    activeMonths.forEach(function(mk){
      var idx = MONTHS_EN.indexOf(mk);
      html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b">'+(idx>=0?TH_MO[idx]:mk)+'</th>';
    });
    html += '<th style="padding:8px;text-align:right;font-size:11px;text-transform:uppercase;color:#64748b;font-weight:800">ยอดรวม</th>';
    html += '<th style="padding:8px;text-align:center;font-size:11px;text-transform:uppercase;color:#64748b">Performance</th>';
    html += '</tr></thead><tbody>';

    all.forEach(function(p,i){
      var bg = i%2 ? 'background:rgba(0,0,0,.02)' : '';
      var mv2 = activeMonths.map(function(mk){return p.monthly[mk]?p.monthly[mk].b:0;});
      var pf2 = window.calcPerf(mv2);
      html += '<tr style="'+bg+'">';
      html += '<td style="padding:6px 8px;text-align:left;position:sticky;left:0;background:'+(i%2?'#fafafa':'#fff')+';z-index:1;max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:600" title="'+p.name+'">'+p.name+'</td>';
      activeMonths.forEach(function(mk){
        var md = p.monthly[mk]||null;
        html += '<td style="padding:6px 8px;text-align:right" data-b="'+(md?md.b:0)+'" data-q="'+(md?md.q:0)+'">'+(md?fmtB(md.b):'—')+'</td>';
      });
      html += '<td style="padding:6px 8px;text-align:right;font-weight:700">'+fmtB(p.cost)+'</td>';
      html += '<td style="padding:6px 8px;text-align:center">'+window.perfBadgeHTML(pf2)+'</td>';
      html += '</tr>';
    });

    html += '<tr style="font-weight:800;background:#f1f5f9">';
    html += '<td style="padding:6px 8px;text-align:left;position:sticky;left:0;background:#f1f5f9;z-index:1">รวมทั้งหมด</td>';
    activeMonths.forEach(function(mk){
      var sumB = 0;
      all.forEach(function(p){if(p.monthly[mk])sumB+=p.monthly[mk].b;});
      html += '<td style="padding:6px 8px;text-align:right">'+fmtB(sumB)+'</td>';
    });
    html += '<td style="padding:6px 8px;text-align:right">'+fmtB(totalRev)+'</td>';
    html += '<td></td>';
    html += '</tr>';
    html += '</tbody></table></div></div>';
  }

  el.innerHTML = html;
  _olPPMonthShowBaht = true;

  setTimeout(function(){
    var top10 = all.slice(0,10);
    mkChart('olPPTop10Chart',{type:'bar',
      data:{labels:top10.map(function(p){var nm=p.name;return nm.length>25?nm.substr(0,25)+'…':nm;}),
        datasets:[{data:top10.map(function(p){return p.cost;}),backgroundColor:_TOP10_COLORS.slice(0,top10.length),borderRadius:4,barThickness:20}]},
      options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{callbacks:{label:function(ctx){
          var p=top10[ctx.dataIndex];
          return['฿'+Math.round(ctx.raw).toLocaleString('th-TH'),'ชิ้น: '+fmtQ(p.qty),'สัดส่วน: '+p.pct+'%'];
        }}}},
        scales:{x:{ticks:{callback:function(v){return v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':v;}},beginAtZero:true,grid:{color:'rgba(0,0,0,0.05)'}},
          y:{grid:{display:false},ticks:{font:{size:11}}}}}
    });
    mkChart('olPPCatChart',{type:'doughnut',
      data:{labels:catLabels,datasets:[{data:catValues,backgroundColor:catColors,borderWidth:2}]},
      options:{responsive:true,maintainAspectRatio:false,
        plugins:{legend:{position:'bottom',labels:{font:{size:11}}},
          tooltip:{callbacks:{label:function(ctx){
            var v=ctx.raw;var t=catValues.reduce(function(a,b){return a+b;},0);
            return ctx.label+': ฿'+fmtB(v)+' ('+(t>0?(v/t*100).toFixed(1):0)+'%)';
          }}}}}
    });
  },100);
}

window._olPPFilterTable = function(){
  var rankF = document.getElementById('olPPFilterRank');
  var searchF = document.getElementById('olPPSearch');
  var rv = rankF?rankF.value:'all';
  var sv = searchF?(searchF.value||'').toLowerCase():'';
  var tbl = document.getElementById('olPPProdTable');
  if(!tbl) return;
  var rows = tbl.querySelectorAll('tbody tr');
  rows.forEach(function(row){
    var r = row.getAttribute('data-rank')||'';
    var n = row.getAttribute('data-name')||'';
    var show = (rv==='all'||r===rv) && (!sv||n.indexOf(sv)!==-1);
    row.style.display = show?'':'none';
  });
};

window._olPPToggleMonthUnit = function(){
  var btn = document.getElementById('olPPMonthUnit');
  var tbl = document.getElementById('olPPMonthTable');
  if(!btn||!tbl) return;
  _olPPMonthShowBaht = !_olPPMonthShowBaht;
  btn.textContent = _olPPMonthShowBaht ? 'แสดง: บาท' : 'แสดง: ชิ้น';
  var fmtB2 = function(v){if(v>=1e6)return(v/1e6).toFixed(2)+' M';if(v>=1e3)return(v/1e3).toFixed(1)+' K';return Math.round(v).toLocaleString();};
  var fmtQ2 = function(v){return Math.round(v).toLocaleString('th-TH');};
  var cells = tbl.querySelectorAll('tbody td[data-b]');
  cells.forEach(function(td){
    var b = parseFloat(td.getAttribute('data-b'))||0;
    var q = parseFloat(td.getAttribute('data-q'))||0;
    if(b===0&&q===0){td.textContent='—';return;}
    td.textContent = _olPPMonthShowBaht ? fmtB2(b) : fmtQ2(q);
  });
};

window._olPPShowChart = function(idx){
  var all = window._olPPAllData;
  var aMo = window._olPPActiveMonths;
  var MEN = window._olPPMonthsEN;
  var MTH = window._olPPMonthsTH;
  if(!all||!all[idx]) return;
  var p = all[idx];
  var labels = aMo.map(function(mk){var ii=MEN.indexOf(mk);return ii>=0?MTH[ii]:mk;});
  var dataB = aMo.map(function(mk){return p.monthly[mk]?p.monthly[mk].b:0;});
  var dataQ = aMo.map(function(mk){return p.monthly[mk]?p.monthly[mk].q:0;});
  var fmtB3 = function(v){if(v>=1e6)return(v/1e6).toFixed(2)+' M';if(v>=1e3)return(v/1e3).toFixed(1)+' K';return Math.round(v).toLocaleString();};

  var old = document.getElementById('olPPChartModal');
  if(old) old.remove();

  var overlay = document.createElement('div');
  overlay.id = 'olPPChartModal';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:center;justify-content:center';
  overlay.onclick = function(e){if(e.target===overlay){overlay.remove();}};

  var rankColor = p.rank==='A+'?'#dc2626':p.rank==='A'?'#ea580c':p.rank==='B'?'#d97706':'#94a3b8';
  var totalB = dataB.reduce(function(s,v){return s+v;},0);
  var totalQ = dataQ.reduce(function(s,v){return s+v;},0);

  var box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:16px;padding:24px;width:90%;max-width:700px;max-height:90vh;overflow-y:auto;position:relative';
  box.innerHTML = '<button onclick="document.getElementById(\'olPPChartModal\').remove()" style="position:absolute;top:12px;right:16px;background:none;border:none;font-size:22px;cursor:pointer;color:#64748b">✕</button>'
    +'<div style="font-size:16px;font-weight:800;color:#0f172a;margin-bottom:4px">📊 '+p.name+'</div>'
    +'<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px;font-size:12px;color:#64748b">'
    +'<span>Rank: <span style="display:inline-block;padding:1px 8px;border-radius:8px;font-weight:800;color:#fff;background:'+rankColor+';font-size:11px">'+p.rank+'</span></span>'
    +'<span>ราคา: ฿'+p.price.toFixed(2)+'</span>'
    +'<span>รวมบาท: <b style="color:#16a34a">฿'+fmtB3(totalB)+'</b></span>'
    +'<span>รวมชิ้น: <b style="color:#0891b2">'+totalQ.toLocaleString('th-TH')+'</b></span>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:12px">'
    +'<button id="olPPModalBaht" onclick="_olPPModalToggle(\'b\')" style="padding:4px 14px;border-radius:8px;border:1px solid #7c3aed;background:#7c3aed;color:#fff;font-size:12px;cursor:pointer;font-weight:700">บาท</button>'
    +'<button id="olPPModalQty" onclick="_olPPModalToggle(\'q\')" style="padding:4px 14px;border-radius:8px;border:1px solid #e2e8f0;background:#fff;color:#1e293b;font-size:12px;cursor:pointer;font-weight:700">ชิ้น</button>'
    +'</div>'
    +'<div style="position:relative;height:280px"><canvas id="olPPModalChart"></canvas></div>'
    +'<div id="olPPModalTable" style="margin-top:16px;overflow-x:auto"></div>';
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  window._olPPModalData = {labels:labels, b:dataB, q:dataQ, name:p.name};
  window._olPPModalMode = 'b';
  _olPPModalRender();
};

window._olPPModalToggle = function(mode){
  window._olPPModalMode = mode;
  var btnB = document.getElementById('olPPModalBaht');
  var btnQ = document.getElementById('olPPModalQty');
  if(btnB){btnB.style.background = mode==='b'?'#7c3aed':'#fff'; btnB.style.color = mode==='b'?'#fff':'#1e293b'; btnB.style.borderColor = mode==='b'?'#7c3aed':'#e2e8f0';}
  if(btnQ){btnQ.style.background = mode==='q'?'#7c3aed':'#fff'; btnQ.style.color = mode==='q'?'#fff':'#1e293b'; btnQ.style.borderColor = mode==='q'?'#7c3aed':'#e2e8f0';}
  _olPPModalRender();
};

function _olPPModalRender(){
  var d = window._olPPModalData;
  var mode = window._olPPModalMode;
  if(!d) return;
  var vals = mode==='b' ? d.b : d.q;
  var unit = mode==='b' ? 'บาท' : 'ชิ้น';
  var color = mode==='b' ? '#7c3aed' : '#0891b2';
  var fmtV = function(v){if(mode==='b'){if(v>=1e6)return(v/1e6).toFixed(2)+' M';if(v>=1e3)return(v/1e3).toFixed(1)+' K';return Math.round(v).toLocaleString();}return Math.round(v).toLocaleString('th-TH');};

  mkChart('olPPModalChart',{type:'line',
    data:{labels:d.labels,datasets:[{label:unit,data:vals,borderColor:color,backgroundColor:color+'22',fill:true,tension:0.3,pointRadius:5,pointBackgroundColor:color,borderWidth:2.5}]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false},tooltip:{callbacks:{label:function(ctx){return fmtV(ctx.raw)+' '+unit;}}}},
      scales:{y:{beginAtZero:true,ticks:{callback:function(v){return fmtV(v);}}},x:{grid:{display:false}}}}
  });

  var tbl = '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#f8fafc">';
  tbl += '<th style="padding:6px 8px;text-align:left;color:#64748b">เดือน</th>';
  tbl += '<th style="padding:6px 8px;text-align:right;color:#64748b">'+unit+'</th>';
  tbl += '<th style="padding:6px 8px;text-align:right;color:#64748b">เปลี่ยนแปลง</th>';
  tbl += '</tr></thead><tbody>';
  vals.forEach(function(v,i){
    var prev = i>0 ? vals[i-1] : 0;
    var diff = i>0 ? v - prev : 0;
    var pctChg = (i>0 && prev>0) ? ((diff/prev)*100).toFixed(1) : '—';
    var chgColor = diff>0?'#16a34a':diff<0?'#dc2626':'#64748b';
    var arrow = diff>0?'▲':diff<0?'▼':'—';
    var bg = i%2?'background:rgba(0,0,0,.02)':'';
    tbl += '<tr style="'+bg+'"><td style="padding:5px 8px;font-weight:600">'+d.labels[i]+'</td>';
    tbl += '<td style="padding:5px 8px;text-align:right;font-weight:600">'+fmtV(v)+'</td>';
    tbl += '<td style="padding:5px 8px;text-align:right;color:'+chgColor+';font-weight:600">'+(i>0?(arrow+' '+pctChg+'%'):'—')+'</td>';
    tbl += '</tr>';
  });
  tbl += '</tbody></table>';
  var tblEl = document.getElementById('olPPModalTable');
  if(tblEl) tblEl.innerHTML = tbl;
}

