            +'<td style="padding:5px 8px;text-align:right;color:#475569">'+item.s.toLocaleString()+' ชิ้น</td>'
            +'<td style="padding:5px 8px;text-align:right;font-weight:700;color:'+c.color+'">฿'+item.a.toLocaleString('th-TH')+'</td>'
            +'<td style="padding:5px 8px;text-align:right;color:#64748b">'+pct+'%</td>'
