// PIN guard for exports (hashed)
const EXPORT_PIN_HASH = 'a]3f9#b2e1';
let _pinOk = false;
async function _hashPin(pin){
  var enc = new TextEncoder();
  var buf = await crypto.subtle.digest('SHA-256', enc.encode(pin));
  return Array.from(new Uint8Array(buf)).map(function(b){return b.toString(16).padStart(2,'0')}).join('');
}
async function _checkPin(){
  if(_pinOk) return true;
  var p = prompt('กรุณาใส่ PIN เพื่อส่งออกข้อมูล:');
  if(p === null) return false;
  var h = await _hashPin(p);
  if(h === 'ee28deeee58fc612d5cab19233ba24abe3802de5c56962fa88ebef9c3cdfa4b9'){ _pinOk = true; return true; }
  alert('PIN ไม่ถูกต้อง');
  return false;
}
async function guardedExportPrint(){ if(await _checkPin()) exportPrint(); }
async function guardedExportImage(){ if(await _checkPin()) exportImage(); }
async function guardedExportExcel(){ if(await _checkPin()) exportExcel(); }
async function guardedExportPDF(){ if(await _checkPin()) exportPDF(); }

