// ---- helper: ดึงข้อมูลพนักงานพร้อม overrides จาก localStorage ----
function _getAdminStaffList(){
  var base = (typeof SM_STAFF_DB !== 'undefined') ? SM_STAFF_DB.slice() : [];
  var overrides = [];
  try { overrides = JSON.parse(localStorage.getItem('adminStaffOverrides') || '[]'); } catch(e){}
  // merge: override ตาม empId, ถ้าไม่มีใน base ให้เพิ่มท้าย
  var map = {};
  base.forEach(function(s){ map[s.empId] = s; });
  overrides.forEach(function(o){
    if(o._deleted) { delete map[o.empId]; return; }
    if(map[o.empId]){
      // merge fields
      var keys = Object.keys(o);
      keys.forEach(function(k){ if(k !== '_added') map[o.empId][k] = o[k]; });
    } else {
      map[o.empId] = o;
    }
  });
  var result = [];
  Object.keys(map).forEach(function(k){ result.push(map[k]); });
  return result;
}

function _saveAdminStaffOverride(staffObj, deleted){
  var overrides = [];
  try { overrides = JSON.parse(localStorage.getItem('adminStaffOverrides') || '[]'); } catch(e){}
  // หา index เดิม
  var idx = -1;
  overrides.forEach(function(o,i){ if(o.empId === staffObj.empId) idx = i; });
  var entry = {};
  var keys = Object.keys(staffObj);
  keys.forEach(function(k){ entry[k] = staffObj[k]; });
  if(deleted) entry._deleted = true;
  if(idx >= 0) overrides[idx] = entry;
  else overrides.push(entry);
  _lsSet('adminStaffOverrides',overrides);
}

function renderAdminStaff(){
  var el=document.getElementById('adminStaffTable');
  if(!el)return;
  var deptColors = { 'Modern Trade':'#f97316', 'Amazon':'#8b5cf6', 'Booth':'#10b981', 'Ordering Center':'#3b82f6', 'Online':'#ec4899' };
  var staff = _getAdminStaffList();
  var bg=['#fff','#f8fafc'];
  var rows = staff.map(function(s,i){
    var color = deptColors[s.dept] || '#64748b';
    return '<tr style="background:'+bg[i%2]+'">'
      +'<td style="padding:6px 10px;font-size:12px;color:#64748b">'+(i+1)+'</td>'
      +'<td style="padding:6px 10px;font-size:12px;font-family:monospace;color:#64748b">'+s.empId+'</td>'
      +'<td style="padding:6px 10px;font-size:12px;font-weight:600">'+s.name+'</td>'
      +'<td style="padding:6px 10px;font-size:12px;font-weight:700;color:#1e293b">'+s.nick+'</td>'
      +'<td style="padding:6px 10px;font-size:11px;color:#475569">'+s.positionTh+'</td>'
      +'<td style="padding:6px 10px;font-size:11px"><span style="background:#f1f5f9;padding:2px 6px;border-radius:10px">'+s.level+'</span></td>'
      +'<td style="padding:6px 10px;font-size:11px;font-weight:600;color:'+color+'">'+s.dept+'</td>'
      +'<td style="padding:6px 10px;font-size:11px;color:#475569">'+(s.phone||'-')+'</td>'
      +'<td style="padding:6px 10px;font-size:11px;color:#2563eb">'+(s.emailCo||'-')+'</td>'
      +'<td style="padding:6px 10px;text-align:center;white-space:nowrap">'
      +'<button onclick="adminEditStaff(\''+s.empId+'\')" style="background:none;border:none;cursor:pointer;font-size:14px" title="แก้ไข">✏️</button>'
      +'<button onclick="adminDeleteStaff(\''+s.empId+'\')" style="background:none;border:none;cursor:pointer;font-size:14px;margin-left:4px" title="ลบ">🗑️</button>'
      +'</td></tr>';
  });
  el.innerHTML='<table style="width:100%;border-collapse:collapse;min-width:900px"><thead><tr style="background:#1e293b;color:#fff">'
    +'<th style="padding:8px 10px">#</th>'
    +'<th style="padding:8px 10px">รหัส</th>'
    +'<th style="padding:8px 10px">ชื่อ-นามสกุล</th>'
    +'<th style="padding:8px 10px">ชื่อเล่น</th>'
    +'<th style="padding:8px 10px">ตำแหน่ง</th>'
    +'<th style="padding:8px 10px">ระดับ</th>'
    +'<th style="padding:8px 10px">แผนก</th>'
    +'<th style="padding:8px 10px">เบอร์โทร</th>'
    +'<th style="padding:8px 10px">Email บริษัท</th>'
    +'<th style="padding:8px 10px;text-align:center">Actions</th>'
    +'</tr></thead><tbody>'+rows.join('')+'</tbody></table>';
  var note = document.getElementById('adminStaffNote');
  if(note) note.textContent = 'พนักงานทั้งหมด: ' + staff.length + ' คน';
}

function _openStaffForm(staffObj){
  var isEdit = !!staffObj;
  var s = staffObj || {empId:'',name:'',nick:'',positionTh:'',positionEn:'',level:'เจ้าหน้าที่',dept:'Modern Trade',deptTh:'',branch:'',phone:'',birthday:'',startDate:'',age:'',emailCo:'',emailPersonal:''};
  var levels = ['ผู้อำนวยการ','ผู้จัดการ','หัวหน้าแผนก','หัวหน้างาน','เจ้าหน้าที่','พนักงาน'];
  var depts = ['Modern Trade','Amazon','Booth','Ordering Center','Online'];
  var deptThMap = {'Modern Trade':'โมเดิร์นเทรด','Amazon':'อเมซอน','Booth':'บูธ','Ordering Center':'ออเดอริ่งเซ็นเตอร์','Online':'ออนไลน์'};
  var branches = ['','CJ','Big C','Top','Makro','MM','Aeon','The Mall','OR','COCO','RM','ร้านของฝาก','ลูกค้าทั่วไป','Black Canyon','เขต BKK 1 (ปทุมธานี)','เขต BKK 2 (นนทบุรี)','เขต BKK 3 (สมุทรปราการ)','ลำพยา 3 (ใหม่)','ร้านใหม่ (ปตท.คุณาวรรณ)','หน้ามอ (ม.เกษตร)','ลำพยา 3 (เก่า)','ไทวัสดุ','แก้วมณีกาญ','ลำพยา 2 (ใหม่)','ธรรมศาลา','ตลาดดิโอโซน','ปตท.ราชบุรี','ศาลายา กม.26','ลาดหลุมแก้ว','วัดเขาทำเทียม','วัดใหม่สุปดิษฐาราม','ศิลปากร','วันดอนขนาก'];
  var positionsTh = ['','ผู้อำนวยการฝ่ายขาย - การตลาด','ผู้จัดการฝ่ายขาย – การตลาด','ผู้ช่วยผู้จัดการฝ่ายขาย – การตลาด','ผู้จัดการการตลาด','หัวหน้าแผนกการตลาด','หัวหน้างานการตลาด','เจ้าหน้าที่ขายอเมซอน','นักวิเคราะห์ยอดขาย','ผู้ช่วยผู้จัดการโมเดิร์นเทรด','หัวหน้าแผนกโมเดิร์นเทรด','หัวหน้างานโมเดิร์นเทรด','เจ้าหน้าที่โมเดริน์เทรด','ผู้ช่วยผู้จัดการอเมซอน','หัวหน้าแผนกอเมซอน','หัวหน้างานอเมซอน','เจ้าหน้าที่ขายอเมซอน','เจ้าหน้าที่สนับสนุนฝ่ายขาย','พนักงานขายบูธสินค้า','หัวหน้าแผนกธุรการขาย','หัวหน้างานธุรการขาย','เจ้าหน้าที่ธุรการขาย','ผู้ช่วยผู้จัดการอเมซอน','หัวหน้าแผนกออนไลน์','หัวหน้างานออนไลน์','เจ้าหน้าที่ธุรการออนไลน์','เจ้าหน้าที่ไลฟ์สดออนไลน์'];

  function makeField(label, id, type, value, opts){
    opts = opts || {};
    var inp = '';
    if(type === 'select'){
      inp = '<select id="'+id+'" style="width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px">';
      (opts.options||[]).forEach(function(o){ inp += '<option value="'+o+'"'+(o===value?' selected':'')+'>'+o+'</option>'; });
      inp += '</select>';
    } else if(type === 'date'){
      inp = '<input type="date" id="'+id+'" value="'+(value||'')+'" style="width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px">';
    } else {
      var ro = opts.readonly ? ' readonly style="width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;background:#f1f5f9;color:#64748b"' : ' style="width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px"';
      inp = '<input type="'+(type||'text')+'" id="'+id+'" value="'+String(value||'').replace(/"/g,'&quot;')+'"'+ro+(opts.placeholder?' placeholder="'+opts.placeholder+'"':'')+'>';
    }
    return '<div style="margin-bottom:10px"><label style="display:block;font-size:12px;font-weight:600;color:#374151;margin-bottom:4px">'+label+(opts.required?' <span style="color:#ef4444">*</span>':'')+'</label>'+inp+'</div>';
  }

  var overlay = document.createElement('div');
  overlay.id = 'staffFormOverlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.innerHTML = '<div style="background:#fff;border-radius:12px;width:100%;max-width:720px;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3)">'
    +'<div style="padding:20px 24px 16px;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:#fff;border-radius:12px 12px 0 0;z-index:1">'
    +'<h3 style="margin:0;font-size:18px;color:#1e293b">'+(isEdit?'✏️ แก้ไขข้อมูลพนักงาน':'➕ เพิ่มพนักงานใหม่')+'</h3>'
    +'<button onclick="document.getElementById(\'staffFormOverlay\').remove()" style="background:none;border:none;font-size:22px;cursor:pointer;color:#94a3b8;padding:4px">✕</button>'
    +'</div>'
    +'<div style="padding:20px 24px">'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:0 16px">'
    + makeField('รหัสพนักงาน','sf_empId','text',s.empId,{required:true, readonly:isEdit, placeholder:'เช่น 64070068'})
    + makeField('ชื่อ-นามสกุล','sf_name','text',s.name,{required:true, placeholder:'เช่น นางสาวปาล์ม บุญกุศล'})
    + makeField('ชื่อเล่น','sf_nick','text',s.nick,{required:true, placeholder:'เช่น ปาล์ม'})
    + makeField('ตำแหน่ง (TH)','sf_positionTh','select',s.positionTh,{options:positionsTh})
    + makeField('ตำแหน่ง (EN)','sf_positionEn','text',s.positionEn,{placeholder:'เช่น Sales Director'})
    + makeField('ระดับ','sf_level','select',s.level,{options:levels})
    + makeField('แผนก (EN)','sf_dept','select',s.dept,{options:depts})
    + makeField('แผนก (TH)','sf_deptTh','text',s.deptTh||deptThMap[s.dept]||'',{placeholder:'เช่น โมเดิร์นเทรด'})
    + makeField('สาขา / ความรับผิดชอบ','sf_branch','select',s.branch,{options:branches})
    + makeField('เบอร์โทร','sf_phone','tel',s.phone,{placeholder:'เช่น 092-1234567'})
    + makeField('วันเกิด','sf_birthday','date',s.birthday)
    + makeField('วันเริ่มงาน','sf_startDate','date',s.startDate)
    + makeField('อายุ (ปี)','sf_age','number',s.age,{placeholder:'เช่น 28'})
    + makeField('Email บริษัท','sf_emailCo','email',s.emailCo,{placeholder:'เช่น palm@wanwanach.com'})
    +'</div>'
    + makeField('Email ส่วนตัว','sf_emailPersonal','email',s.emailPersonal,{placeholder:'เช่น palm.b@gmail.com'})
    +'</div>'
    +'<div style="padding:16px 24px 20px;border-top:1px solid #e5e7eb;display:flex;gap:10px;justify-content:flex-end;position:sticky;bottom:0;background:#fff;border-radius:0 0 12px 12px">'
    +'<button onclick="document.getElementById(\'staffFormOverlay\').remove()" style="padding:10px 24px;border:1px solid #d1d5db;border-radius:8px;background:#fff;cursor:pointer;font-size:14px;color:#374151">ยกเลิก</button>'
    +'<button id="sfSaveBtn" style="padding:10px 24px;border:none;border-radius:8px;background:#f97316;color:#fff;cursor:pointer;font-size:14px;font-weight:600">'+(isEdit?'💾 บันทึก':'➕ เพิ่มพนักงาน')+'</button>'
    +'</div></div>';
  document.body.appendChild(overlay);

  var deptSelect = document.getElementById('sf_dept');
  if(deptSelect){
    deptSelect.addEventListener('change', function(){
      var deptThInput = document.getElementById('sf_deptTh');
      if(deptThInput) deptThInput.value = deptThMap[this.value] || '';
    });
  }

  document.getElementById('sfSaveBtn').addEventListener('click', function(){
    var empId = document.getElementById('sf_empId').value.trim();
    var name = document.getElementById('sf_name').value.trim();
    var nick = document.getElementById('sf_nick').value.trim();
    if(!empId){ alert('กรุณากรอกรหัสพนักงาน'); document.getElementById('sf_empId').focus(); return; }
    if(!name){ alert('กรุณากรอกชื่อ-นามสกุล'); document.getElementById('sf_name').focus(); return; }
    if(!nick){ alert('กรุณากรอกชื่อเล่น'); document.getElementById('sf_nick').focus(); return; }
    if(!isEdit){
      var existing = _getAdminStaffList();
      var dup = false;
      existing.forEach(function(x){ if(x.empId === empId) dup = true; });
      if(dup){ alert('รหัสพนักงาน "' + empId + '" ซ้ำ!'); return; }
    }
    var data = {
      empId: empId,
      name: name,
      nick: nick,
      positionTh: document.getElementById('sf_positionTh').value.trim(),
      positionEn: document.getElementById('sf_positionEn').value.trim(),
      level: document.getElementById('sf_level').value,
      dept: document.getElementById('sf_dept').value,
      deptTh: document.getElementById('sf_deptTh').value.trim(),
      branch: document.getElementById('sf_branch').value.trim(),
      phone: document.getElementById('sf_phone').value.trim(),
      birthday: document.getElementById('sf_birthday').value,
      startDate: document.getElementById('sf_startDate').value,
      age: document.getElementById('sf_age').value.trim(),
      emailCo: document.getElementById('sf_emailCo').value.trim(),
      emailPersonal: document.getElementById('sf_emailPersonal').value.trim()
    };
    if(!isEdit) data._added = true;
    _saveAdminStaffOverride(data, false);
    document.getElementById('staffFormOverlay').remove();
    renderAdminStaff();
    if (typeof _smRefreshStaffData === 'function') _smRefreshStaffData();
  });

  overlay.addEventListener('click', function(e){ if(e.target === overlay) overlay.remove(); });
  setTimeout(function(){ document.getElementById(isEdit?'sf_name':'sf_empId').focus(); }, 100);
}

function adminEditStaff(empId){
  var staff = _getAdminStaffList();
  var s = null;
  staff.forEach(function(x){ if(x.empId === empId) s = x; });
  if(!s){ alert('ไม่พบข้อมูลพนักงาน'); return; }
  _openStaffForm(s);
}

function adminDeleteStaff(empId){
  var staff = _getAdminStaffList();
  var s = null;
  staff.forEach(function(x){ if(x.empId === empId) s = x; });
  if(!s) return;
  if(!confirm('ลบพนักงาน "' + s.name + ' (' + s.nick + ')" ?')) return;
  _saveAdminStaffOverride(s, true);
  renderAdminStaff();
}

function renderAdminProd(){
  var sel=document.getElementById('adminProdChannel');
  var el=document.getElementById('adminProdTable');
  if(!sel||!el)return;
  if(sel.options.length===0){
    var oAll=document.createElement('option');
    oAll.value='__all__'; oAll.textContent='ทุกช่องทาง';
    sel.appendChild(oAll);
    var channels=Object.keys(PRODUCTS);
    channels.forEach(function(ch){
      var o=document.createElement('option');
      o.value=ch; o.textContent=ch;
      sel.appendChild(o);
    });
  }
  var ch=sel.value;
  var items=[];
  if(ch==='__all__'){
    Object.keys(PRODUCTS).forEach(function(c){
      (PRODUCTS[c]||[]).forEach(function(p){
        items.push({_ch:c, p:p});
      });
    });
  } else {
    (PRODUCTS[ch]||[]).forEach(function(p){ items.push({_ch:ch, p:p}); });
  }
  var showCh = ch==='__all__';
  var bg=['#fff','#f8fafc'];
  var td='padding:5px 8px;font-size:11px;white-space:nowrap';
  var rows=items.map(function(item,i){
    var p=item.p; var pCh=item._ch;
    var st=p.status||'active';
    var stBg=st==='active'?'#dcfce7':st==='discontinued'?'#fee2e2':'#dbeafe';
    var stColor=st==='active'?'#16a34a':st==='discontinued'?'#dc2626':'#1d4ed8';
    var stLabel=st==='active'?'Active':st==='discontinued'?'ยกเลิก':'ใหม่';
    if(p.newMonth&&st==='active'){stBg='#dbeafe';stColor='#1d4ed8';stLabel='ใหม่';}
    var fda=p.fda||localStorage.getItem('prodFda_'+pCh+'_'+p.code)||'';
    var halal=p.halal||localStorage.getItem('prodHalal_'+pCh+'_'+p.code)||'';
    var r='<tr style="background:'+bg[i%2]+'">';
    r+='<td style="'+td+';color:#94a3b8;text-align:center">'+(i+1)+'</td>';
    if(showCh) r+='<td style="'+td+';font-weight:600;color:#f97316">'+pCh+'</td>';
    r+='<td style="'+td+';font-family:monospace;color:#64748b">'+(p.code||'-')+'</td>';
    r+='<td style="'+td+'">'+(p.barcode||'-')+'</td>';
    r+='<td style="'+td+';font-weight:600;max-width:200px;overflow:hidden;text-overflow:ellipsis">'+(p.name||'-')+'</td>';
    var prodImg=p.img||'';
    if(prodImg){
      r+='<td style="'+td+';text-align:center"><img src="'+prodImg+'" style="width:50px;height:50px;object-fit:cover;border-radius:6px;cursor:pointer" onclick="openImgZoom(this.src)"></td>';
    } else {
      r+='<td style="'+td+';text-align:center;color:#cbd5e1;font-size:10px">ไม่มีรูป</td>';
    }
    r+='<td style="'+td+';color:#475569;font-size:10px">'+(fda||'-')+'</td>';
    r+='<td style="'+td+';color:#475569;font-size:10px">'+(halal||'-')+'</td>';
    r+='<td style="'+td+'">'+(p.type||'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.weight||'-')+'</td>';
    r+='<td style="'+td+';text-align:center">'+(p.shelf?p.shelf+' วัน':'-')+'</td>';
    r+='<td style="'+td+';text-align:center"><span style="background:'+stBg+';color:'+stColor+';padding:1px 6px;border-radius:4px;font-size:10px;font-weight:600">'+stLabel+'</span></td>';
    r+='<td style="'+td+';text-align:right">'+(p.gp!=null?p.gp+'%':'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.priceExvat!=null?p.priceExvat.toLocaleString():'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.priceRetailEx!=null?p.priceRetailEx.toLocaleString():'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.priceIn!=null?p.priceIn.toLocaleString():'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.priceRetail!=null?p.priceRetail.toLocaleString():'-')+'</td>';
    r+='<td style="'+td+';text-align:right">'+(p.priceShop!=null?p.priceShop.toLocaleString():'-')+'</td>';
    r+='<td style="'+td+';color:#64748b;max-width:120px;overflow:hidden;text-overflow:ellipsis">'+(p.note||'-')+'</td>';
    r+='<td style="'+td+';text-align:center">';
    r+='<button onclick="adminEditProd(\''+pCh+'\',\''+p.code+'\')" style="background:none;border:none;cursor:pointer;font-size:13px" title="แก้ไข">✏️</button>';
    r+='<button onclick="adminDelProd(\''+pCh+'\',\''+p.code+'\')" style="background:none;border:none;cursor:pointer;font-size:13px;margin-left:2px" title="ลบ">🗑️</button>';
    r+='</td></tr>';
    return r;
  });
  var th='padding:6px 8px;font-size:11px;white-space:nowrap';
  var hdr='<tr style="background:#1e293b;color:#fff">';
  hdr+='<th style="'+th+'">#</th>';
  if(showCh) hdr+='<th style="'+th+'">ช่องทาง</th>';
  hdr+='<th style="'+th+'">รหัส</th>';
  hdr+='<th style="'+th+'">บาร์โค้ด</th>';
  hdr+='<th style="'+th+'">ชื่อสินค้า</th>';
  hdr+='<th style="'+th+';text-align:center">รูปสินค้า</th>';
  hdr+='<th style="'+th+'">เลข อ.ย.</th>';
  hdr+='<th style="'+th+'">ฮาลาล</th>';
  hdr+='<th style="'+th+'">ประเภท</th>';
  hdr+='<th style="'+th+';text-align:right">น้ำหนัก</th>';
  hdr+='<th style="'+th+';text-align:center">อายุ</th>';
  hdr+='<th style="'+th+';text-align:center">สถานะ</th>';
  hdr+='<th style="'+th+';text-align:right">GP%</th>';
  hdr+='<th style="'+th+';text-align:right">ส่ง Ex.</th>';
  hdr+='<th style="'+th+';text-align:right">ปลีก Ex.</th>';
  hdr+='<th style="'+th+';text-align:right">ส่ง In.</th>';
  hdr+='<th style="'+th+';text-align:right">ปลีก In.</th>';
  hdr+='<th style="'+th+';text-align:right">หน้าร้าน</th>';
  hdr+='<th style="'+th+'">หมายเหตุ</th>';
  hdr+='<th style="'+th+';text-align:center">Actions</th>';
  hdr+='</tr>';
  el.innerHTML='<table style="width:100%;border-collapse:collapse;min-width:1400px"><thead>'+hdr+'</thead><tbody>'+rows.join('')+'</tbody></table>';
  var totalActive=items.filter(function(x){return(x.p.status||'active')==='active';}).length;
  var totalDisc=items.filter(function(x){return x.p.status==='discontinued';}).length;
  var note=document.getElementById('adminProdNote');
  if(note) note.textContent=(ch==='__all__'?'ทุกช่องทาง':ch)+': '+items.length+' รายการ (Active: '+totalActive+', ยกเลิก: '+totalDisc+')';
}

function adminEditProd(ch, code){
  var items=PRODUCTS[ch]||[];
  var p=null;
  items.forEach(function(x){ if(x.code===code) p=x; });
  if(!p){ alert('ไม่พบสินค้า'); return; }
  var fda=p.fda||localStorage.getItem('prodFda_'+ch+'_'+p.code)||'';
  var halal=p.halal||localStorage.getItem('prodHalal_'+ch+'_'+p.code)||'';
  var modal=document.getElementById('addProdModal');
  if(!modal) return;
  var chSel=document.getElementById('npCh');
  if(chSel && chSel.options.length===0){
    Object.keys(PRODUCTS).forEach(function(c){
      var o=document.createElement('option'); o.value=c; o.textContent=c; chSel.appendChild(o);
    });
  }
  if(chSel) chSel.value=ch;
  var setVal=function(id,v){ var e=document.getElementById(id); if(e) e.value=v||''; };
  setVal('npCode',p.code);
  setVal('npName',p.name);
  setVal('npBarcode',p.barcode);
  setVal('npFda',fda);
  setVal('npHalal',halal);
  setVal('npType',p.type||'Ambient');
  setVal('npWeight',p.weight);
  setVal('npShelf',p.shelf);
  setVal('npStatus',p.status||'active');
  setVal('npGp',p.gp);
  setVal('npPriceExVat',p.priceExvat);
  setVal('npPriceRetailEx',p.priceRetailEx);
  setVal('npPriceIn',p.priceIn);
  setVal('npPriceRetail',p.priceRetail);
  setVal('npPriceShop',p.priceShop);
  setVal('npNote',p.note);
  var titleEl=modal.querySelector('[data-prod-title]');
  if(titleEl) titleEl.textContent='✏️ แก้ไขสินค้า: '+p.name;
  var saveBtn=modal.querySelector('[data-prod-save]');
  if(saveBtn) saveBtn.textContent='💾 บันทึกการแก้ไข';
  // Show existing product image
  var preview = document.getElementById('npImgPreview');
  var removeBtn = document.getElementById('npImgRemoveBtn');
  var existingImg = p.img || '';
  if (preview) {
    if (existingImg) {
      preview.innerHTML = '<img src="'+existingImg+'" style="width:100%;height:100%;object-fit:contain">';
      if (removeBtn) removeBtn.style.display = 'inline-block';
    } else {
      preview.innerHTML = '<span style="font-size:40px;color:#cbd5e1">📷</span>';
      if (removeBtn) removeBtn.style.display = 'none';
    }
  }
  modal._npImgData = existingImg || '';

  modal.style.display='flex';
  document.body.style.overflow='hidden';
  modal._editMode={ch:ch, code:code};
}

function adminDelProd(ch, code){
  var items=PRODUCTS[ch]||[];
  var p=null;
  items.forEach(function(x){ if(x.code===code) p=x; });
  if(!p) return;
  if(!confirm('ลบสินค้า "'+p.name+'" ('+code+') จาก '+ch+' ?')) return;
  PRODUCTS[ch]=items.filter(function(x){ return x.code!==code; });
  _persistProducts();
  _syncProdDisplay();
  renderAdminProd();
}

function renderAdminSales(){
  var sel=document.getElementById('adminSalesYear');
  var el=document.getElementById('adminSalesTable');
  if(!sel||!el)return;
  if(sel.options.length===0){
    var o=document.createElement('option');
    o.value=String(_CY-543); o.textContent=String(_CY-543);
    sel.appendChild(o);
  }
  var channels=['Modern Trade','Amazon & Souvenir','Booth','Online'];
  var months=['Jan','Feb','Mar','Apr','May','Jun','Jul'];
  var monthsTh=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.'];
  var bg=['#fff','#f8fafc'];
  var grandT=0,grandA=0;
  var rows=channels.map(function(ch,ci){
    var totT=0,totA=0;
    var cells=months.map(function(m){
      var cm=CHANNEL_MONTHLY[m];
      var d=cm&&cm[ch]?cm[ch]:{t:0,a:0};
      totT+=d.t||0; totA+=d.a||0;
      var t=(d.t||0)/1e6, a=(d.a||0)/1e6;
      return '<td style="padding:6px 8px;font-size:11px;text-align:right;line-height:1.4">'
        +'<div style="color:#64748b">T: '+t.toFixed(1)+'</div>'
        +'<div style="font-weight:600;color:'+(a>=t?'#16a34a':'#dc2626')+'">A: '+a.toFixed(1)+'</div></td>';
    });
    grandT+=totT; grandA+=totA;
    var pct=totT?(totA/totT*100):0;
    var pctColor=pct>=80?'#16a34a':pct>=60?'#b45309':'#dc2626';
    return '<tr style="background:'+bg[ci%2]+'">'
      +'<td style="padding:6px 12px;font-size:12px;font-weight:700">'+ch+'</td>'
      +cells.join('')
      +'<td style="padding:6px 8px;font-size:11px;text-align:right;font-weight:700">'+(totA/1e6).toFixed(1)+'M</td>'
      +'<td style="padding:6px 8px;text-align:center"><span style="color:'+pctColor+';font-weight:700;font-size:11px">'+pct.toFixed(1)+'%</span></td>'
      +'</tr>';
  });
  var gPct=grandT?(grandA/grandT*100):0;
  rows.push('<tr style="background:#f1f5f9;font-weight:700">'
    +'<td style="padding:6px 12px;font-size:12px">รวม</td>'
    +months.map(function(m){
      var cm=CHANNEL_MONTHLY[m];var tAll=0,aAll=0;
      channels.forEach(function(ch){var d=cm&&cm[ch]?cm[ch]:{t:0,a:0};tAll+=d.t||0;aAll+=d.a||0;});
      return '<td style="padding:6px 8px;font-size:11px;text-align:right">'+(aAll/1e6).toFixed(1)+'</td>';
    }).join('')
    +'<td style="padding:6px 8px;font-size:11px;text-align:right">'+(grandA/1e6).toFixed(1)+'M</td>'
    +'<td style="padding:6px 8px;text-align:center;font-size:11px">'+gPct.toFixed(1)+'%</td></tr>');

  el.innerHTML='<table><thead><tr style="background:#1e293b;color:#fff">'
    +'<th style="padding:8px 12px">ช่องทาง</th>'
    +monthsTh.map(function(m){return '<th style="padding:8px 8px;text-align:right;font-size:11px">'+m+'</th>';}).join('')
    +'<th style="padding:8px 8px;text-align:right">Total</th>'
    +'<th style="padding:8px 8px;text-align:center">%</th>'
    +'</tr></thead><tbody>'+rows.join('')+'</tbody></table>';
}

