    +'<input id="roleFormEmail" type="email" value="'+u.email+'" placeholder="user@wanwanach.com" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:8px;font-size:13px;box-sizing:border-box"></div>'
    +'<div><label style="font-size:12px;font-weight:600;color:#475569;display:block;margin-bottom:4px">ชื่อ *</label>'
    +'<input id="roleFormName" type="text" value="'+u.name+'" placeholder="ชื่อผู้ใช้" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:8px;font-size:13px;box-sizing:border-box"></div>'
    +'<div style="display:flex;gap:12px"><div style="flex:1"><label style="font-size:12px;font-weight:600;color:#475569;display:block;margin-bottom:4px">Role *</label>'
    +'<select id="roleFormRole" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:8px;font-size:13px">'
    +'<option value="admin"'+(u.role==='admin'?' selected':'')+'>admin — ผู้ดูแลระบบ</option>'
    +'<option value="manager"'+(u.role==='manager'?' selected':'')+'>manager — ผู้จัดการ</option>'
    +'<option value="leader"'+(u.role==='leader'?' selected':'')+'>leader — หัวหน้างาน</option>'
    +'<option value="sales"'+(u.role==='sales'?' selected':'')+'>sales — ฝ่ายขาย</option>'
    +'<option value="officer"'+(u.role==='officer'?' selected':'')+'>officer — เจ้าหน้าที่</option>'
    +'<option value="viewer"'+(u.role==='viewer'?' selected':'')+'>viewer — ดูอย่างเดียว</option>'
