    +'<div style="flex:1"><label style="font-size:12px;font-weight:600;color:#475569;display:block;margin-bottom:4px">สถานะ</label>'
    +'<select id="roleFormActive" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:8px;font-size:13px">'
    +'<option value="1"'+(u.active?' selected':'')+'>Active</option>'
    +'<option value="0"'+(!u.active?' selected':'')+'>Inactive</option>'
    +'</select></div></div>'
    +'<div><label style="font-size:12px;font-weight:600;color:#475569;display:block;margin-bottom:6px">สิทธิ์เข้าถึงเมนู</label>'
    +'<div style="display:flex;justify-content:flex-end;margin-bottom:6px"><button onclick="_rolesToggleAll(true)" style="background:none;border:none;color:#f97316;font-size:11px;cursor:pointer;font-weight:600;padding:2px 6px">เลือกทั้งหมด</button>'
    +'<button onclick="_rolesToggleAll(false)" style="background:none;border:none;color:#64748b;font-size:11px;cursor:pointer;font-weight:600;padding:2px 6px">ล้าง</button></div>'
