// ===== ศูนย์เอกสาร — shared document manager =====

var _DOC_DB_NAME = 'wwn_doc_center';
var _DOC_DB_VER = 1;
var _docDB = null;
var _docCache = {};

function _docOpenDB() {
  return new Promise(function(resolve, reject) {
    if (_docDB) return resolve(_docDB);
    var req = indexedDB.open(_DOC_DB_NAME, _DOC_DB_VER);
    req.onupgradeneeded = function(e) {
      var db = e.target.result;
      if (!db.objectStoreNames.contains('docs')) {
        db.createObjectStore('docs', { keyPath: 'id' });
      }
    };
    req.onsuccess = function(e) { _docDB = e.target.result; resolve(_docDB); };
    req.onerror = function(e) { reject(e); };
  });
}

function _docGetAll(category) {
  return _docCache[category] || [];
}

function _docLoadCategory(category) {
  return _docOpenDB().then(function(db) {
    return new Promise(function(resolve) {
      var tx = db.transaction('docs', 'readonly');
      var store = tx.objectStore('docs');
      var all = [];
      store.openCursor().onsuccess = function(e) {
        var cursor = e.target.result;
        if (cursor) {
          if (cursor.value.category === category) all.push(cursor.value);
          cursor.continue();
        } else {
          all.sort(function(a, b) { return (b.createdAt || '').localeCompare(a.createdAt || ''); });
          _docCache[category] = all;
          resolve(all);
        }
      };
    });
  });
}

function _docSave(category, doc) {
  return _docOpenDB().then(function(db) {
    return new Promise(function(resolve) {
      var tx = db.transaction('docs', 'readwrite');
      tx.objectStore('docs').put(doc);
      tx.oncomplete = function() { resolve(); };
    });
  });
}

function _docAdd(category, doc) {
  doc.id = Date.now() + '_' + Math.random().toString(36).substr(2, 5);
  doc.createdAt = new Date().toISOString().slice(0, 10);
  doc.category = category;
  return _docSave(category, doc).then(function() {
    if (!_docCache[category]) _docCache[category] = [];
    _docCache[category].unshift(doc);
    return doc;
  });
}

function _docDelete(category, id) {
  return _docOpenDB().then(function(db) {
    return new Promise(function(resolve) {
      var tx = db.transaction('docs', 'readwrite');
      tx.objectStore('docs').delete(id);
      tx.oncomplete = function() {
        _docCache[category] = (_docCache[category] || []).filter(function(d) { return d.id !== id; });
        resolve();
      };
    });
  });
}

function _docDownload(docId) {
  _docOpenDB().then(function(db) {
    var tx = db.transaction('docs', 'readonly');
    var req = tx.objectStore('docs').get(docId);
    req.onsuccess = function(e) {
      var doc = e.target.result;
      if (!doc || !doc.data) { alert('ไม่พบไฟล์'); return; }
      var a = document.createElement('a');
      a.href = doc.data;
      a.download = doc.filename || 'document';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    };
  });
}

function _docPreviewById(docId) {
  _docOpenDB().then(function(db) {
    var tx = db.transaction('docs', 'readonly');
    var req = tx.objectStore('docs').get(docId);
    req.onsuccess = function(e) {
      var doc = e.target.result;
      if (doc && doc.data && /^data:image\//i.test(doc.data)) {
        _docPreviewImage(doc.data);
      }
    };
  });
}

function _docRenderList(category, docs, renderFn) {
  if (!docs.length) {
    return '<div style="text-align:center;padding:40px;color:#94a3b8;font-size:14px">'
      + '<div style="font-size:48px;margin-bottom:12px">📂</div>'
      + 'ยังไม่มีเอกสาร — กด <strong>"+ เพิ่มเอกสาร"</strong> เพื่อเริ่มต้น</div>';
  }
  var h = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px">';
  docs.forEach(function(doc) {
    var ext = (doc.filename || '').split('.').pop().toUpperCase() || 'FILE';
    var extColor = ext === 'PDF' ? '#ef4444' : ext === 'DOCX' || ext === 'DOC' ? '#2563eb' : ext === 'XLSX' || ext === 'XLS' ? '#16a34a' : ext === 'PNG' || ext === 'JPG' || ext === 'JPEG' ? '#8b5cf6' : '#64748b';
    var isImage = doc.isImage;
    h += '<div style="background:var(--card-bg,#fff);border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;position:relative;transition:box-shadow .2s" onmouseover="this.style.boxShadow=\'0 4px 16px rgba(0,0,0,.1)\'" onmouseout="this.style.boxShadow=\'\'">';
    if (isImage) {
      h += '<div id="docThumb_' + doc.id + '" style="width:100%;aspect-ratio:16/10;overflow:hidden;background:#f8fafc;cursor:pointer;position:relative" onclick="_docPreviewById(\'' + doc.id + '\')">';
      h += '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#94a3b8;font-size:13px">Loading...</div>';
      h += '<div style="position:absolute;top:8px;right:8px;background:rgba(0,0,0,.5);color:#fff;font-size:10px;font-weight:700;padding:3px 8px;border-radius:6px">🔍 คลิกดูเต็ม</div>';
      h += '</div>';
    }
    h += '<div style="padding:14px 18px 16px">';
    h += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">';
    h += '<div style="background:' + extColor + '15;color:' + extColor + ';font-size:11px;font-weight:800;padding:5px 8px;border-radius:8px;min-width:36px;text-align:center">' + ext + '</div>';
    h += '<div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:700;color:var(--text,#1e293b);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + (doc.name || doc.filename) + '</div>';
    if (doc.note) h += '<div style="font-size:11px;color:#94a3b8;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + doc.note + '</div>';
    h += '</div></div>';
    if (doc.channel) {
      var chLabel = doc.channel;
      (_DOC_CONTRACT_CHANNELS || []).forEach(function(c) { if (c.key === doc.channel) chLabel = c.label; });
      h += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">';
      h += '<span style="background:#eff6ff;color:#1e40af;font-size:10px;font-weight:700;padding:3px 8px;border-radius:6px">' + chLabel + '</span>';
      h += '<button onclick="event.stopPropagation();_docEditChannel(\'' + doc.id + '\',\'' + renderFn + '\')" style="background:none;border:none;color:#94a3b8;font-size:10px;cursor:pointer;padding:2px 4px" title="เปลี่ยนช่องทาง">✏️</button>';
      h += '</div>';
    }
    h += '<div style="display:flex;align-items:center;justify-content:space-between;font-size:11px;color:#94a3b8">';
    h += '<span>📅 ' + (doc.createdAt || '-') + '</span>';
    h += '<div style="display:flex;gap:6px">';
    if (doc.hasFile) {
      h += '<button onclick="event.stopPropagation();_docDownload(\'' + doc.id + '\')" style="background:#3b82f6;color:#fff;border:none;padding:5px 12px;border-radius:8px;font-size:11px;font-weight:600;cursor:pointer">⬇ ดาวน์โหลด</button>';
    }
    h += '<button onclick="event.stopPropagation();if(confirm(\'ลบเอกสารนี้?\')){_docDelete(\'' + category + '\',\'' + doc.id + '\').then(function(){' + renderFn + '()})}" style="background:#fee2e2;color:#ef4444;border:none;padding:5px 10px;border-radius:8px;font-size:11px;font-weight:600;cursor:pointer">✕</button>';
    h += '</div></div></div></div>';
  });
  h += '</div>';
  return h;
}

function _docLoadThumbnails(docs) {
  docs.forEach(function(doc) {
    if (!doc.isImage) return;
    var el = document.getElementById('docThumb_' + doc.id);
    if (!el) return;
    _docOpenDB().then(function(db) {
      var tx = db.transaction('docs', 'readonly');
      var req = tx.objectStore('docs').get(doc.id);
      req.onsuccess = function(e) {
        var full = e.target.result;
        if (full && full.data) {
          var img = document.createElement('img');
          img.src = full.data;
          img.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block';
          img.alt = doc.name || '';
          el.firstChild.replaceWith(img);
        }
      };
    });
  });
}

function _docRenderUploadForm(category, renderFn, extraFields) {
  var formId = 'docForm_' + category.replace(/[^a-zA-Z0-9]/g,'_');
  var h = '<div id="' + formId + '_wrap" style="display:none;background:var(--card-bg,#fff);border:2px dashed #3b82f6;border-radius:16px;padding:24px;margin-bottom:20px">';
  h += '<div style="font-size:15px;font-weight:700;color:#3b82f6;margin-bottom:14px">📎 เพิ่มเอกสารใหม่</div>';
  h += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">';
  h += '<div><label style="font-size:12px;font-weight:600;color:var(--text-sub,#64748b)">ชื่อเอกสาร</label>';
  h += '<input id="' + formId + '_name" type="text" placeholder="ระบุชื่อเอกสาร..." style="width:100%;padding:8px 12px;border:1px solid #e2e8f0;border-radius:8px;font-size:13px;margin-top:4px;box-sizing:border-box"></div>';
  h += '<div><label style="font-size:12px;font-weight:600;color:var(--text-sub,#64748b)">หมายเหตุ</label>';
  h += '<input id="' + formId + '_note" type="text" placeholder="รายละเอียดเพิ่มเติม..." style="width:100%;padding:8px 12px;border:1px solid #e2e8f0;border-radius:8px;font-size:13px;margin-top:4px;box-sizing:border-box"></div>';
  h += '</div>';
  if (extraFields) h += extraFields(formId);
  h += '<div style="margin-bottom:14px"><label style="font-size:12px;font-weight:600;color:var(--text-sub,#64748b)">เลือกไฟล์</label>';
  h += '<input id="' + formId + '_file" type="file" style="display:block;margin-top:4px;font-size:13px" accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.gif,.ppt,.pptx,.txt,.csv"></div>';
  h += '<div style="display:flex;gap:8px">';
  h += '<button onclick="_docHandleUpload(\'' + category + '\',\'' + formId + '\',\'' + renderFn + '\')" style="background:#3b82f6;color:#fff;border:none;padding:8px 20px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">💾 บันทึก</button>';
  h += '<button onclick="document.getElementById(\'' + formId + '_wrap\').style.display=\'none\'" style="background:#f1f5f9;color:#64748b;border:none;padding:8px 20px;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer">ยกเลิก</button>';
  h += '</div></div>';
  return h;
}

window._docHandleUpload = function(category, formId, renderFn) {
  var nameEl = document.getElementById(formId + '_name');
  var noteEl = document.getElementById(formId + '_note');
  var fileEl = document.getElementById(formId + '_file');
  var channelEl = document.getElementById(formId + '_channel');

  if (!fileEl.files.length && !nameEl.value.trim()) {
    alert('กรุณาระบุชื่อเอกสารหรือเลือกไฟล์');
    return;
  }

  var doc = {
    name: nameEl.value.trim(),
    note: noteEl.value.trim()
  };
  if (channelEl) doc.channel = channelEl.value;

  if (fileEl.files.length) {
    var file = fileEl.files[0];
    if (file.size > 50 * 1024 * 1024) {
      alert('ไฟล์ใหญ่เกิน 50 MB — กรุณาเลือกไฟล์ที่เล็กกว่า');
      return;
    }
    doc.filename = file.name;
    doc.fileSize = file.size;
    doc.hasFile = true;
    doc.isImage = /^image\//i.test(file.type);
    if (!doc.name) doc.name = file.name;
    var reader = new FileReader();
    reader.onload = function(e) {
      doc.data = e.target.result;
      _docAdd(category, doc).then(function() {
        if (window[renderFn]) window[renderFn]();
      });
    };
    reader.readAsDataURL(file);
  } else {
    doc.filename = doc.name;
    doc.hasFile = false;
    _docAdd(category, doc).then(function() {
      if (window[renderFn]) window[renderFn]();
    });
  }
};

window._docPreviewImage = function(src) {
  var overlay = document.getElementById('docImgOverlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'docImgOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.85);display:flex;align-items:center;justify-content:center;cursor:zoom-out;padding:20px;box-sizing:border-box';
    overlay.onclick = function() { overlay.style.display = 'none'; };
    overlay.innerHTML = '<img style="max-width:95%;max-height:95%;object-fit:contain;border-radius:12px;box-shadow:0 8px 40px rgba(0,0,0,.5)">'
      + '<div style="position:absolute;top:16px;right:20px;color:#fff;font-size:28px;cursor:pointer;font-weight:700;text-shadow:0 2px 8px rgba(0,0,0,.5)">✕</div>';
    document.body.appendChild(overlay);
  }
  overlay.querySelector('img').src = src;
  overlay.style.display = 'flex';
};

window._docEditChannel = function(docId, renderFn) {
  var chLabels = {};
  _DOC_CONTRACT_CHANNELS.forEach(function(ch) { if (ch.key !== 'all') chLabels[ch.key] = ch.label; });
  var opts = Object.keys(chLabels).map(function(k) { return k + ' = ' + chLabels[k]; }).join('\n');
  var newCh = prompt('เลือกช่องทางใหม่:\n' + opts + '\n\nพิมพ์ชื่อช่องทาง (เช่น BigC, AEON, TOP, Makro, TheMall, MM, Amazon, BlackCanyon):');
  if (!newCh || !chLabels[newCh]) { if (newCh) alert('ไม่พบช่องทาง "' + newCh + '"'); return; }
  _docOpenDB().then(function(db) {
    var tx = db.transaction('docs', 'readwrite');
    var req = tx.objectStore('docs').get(docId);
    req.onsuccess = function(e) {
      var doc = e.target.result;
      if (!doc) return;
      doc.channel = newCh;
      tx.objectStore('docs').put(doc);
      tx.oncomplete = function() {
        _docCache = {};
        if (window[renderFn]) window[renderFn]();
      };
    };
  });
};

function _docToggleForm(category) {
  var formId = 'docForm_' + category.replace(/[^a-zA-Z0-9]/g,'_');
  var wrap = document.getElementById(formId + '_wrap');
  if (wrap) wrap.style.display = wrap.style.display === 'none' ? 'block' : 'none';
}

